import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSection";

/**
 * Test fetching section detail for a discussion board as an authenticated member.
 *
 * This test validates the ability to create a new section and then access its full details as a standard member. The test confirms that all section metadata is retrievable and correct, including name, description, channel linkage, and timestamps. It checks basic permission for standard users (assuming connection is authenticated) and also tests error handling for not-found cases.
 *
 * Steps:
 * 1. Create a new discussion board section under a random channel ID
 * 2. Retrieve the section by its returned ID using the getById endpoint
 * 3. Assert that all data fields in the response match what was created (name, description, channel, timestamps, etc.)
 * 4. Attempt to fetch a non-existent section and confirm an error is thrown (e.g., for a random UUID not matching any section)
 */
export async function test_api_discussionBoard_test_get_section_detail_as_authenticated_user(connection: api.IConnection) {
  // 1. Create a new section under a random parent channel (simulate valid UUID)
  const createInput: IDiscussionBoardSection.ICreate = {
    discussionboard_channel_id: typia.random<string & tags.Format<"uuid">>(),
    name: `Section-${RandomGenerator.alphaNumeric(8)}`,
    description: RandomGenerator.paragraph()(),
  };
  const createdSection: IDiscussionBoardSection = await api.functional.discussionBoard.sections.post(connection, { body: createInput });
  typia.assert(createdSection);

  // 2. Retrieve the section by ID
  const fetchedSection: IDiscussionBoardSection = await api.functional.discussionBoard.sections.getById(connection, { id: createdSection.id });
  typia.assert(fetchedSection);
  // 3. Assert all returned data matches created fields
  TestValidator.equals("id matches")(fetchedSection.id)(createdSection.id);
  TestValidator.equals("channel linkage matches")(fetchedSection.discussionboard_channel_id)(createInput.discussionboard_channel_id);
  TestValidator.equals("name matches")(fetchedSection.name)(createInput.name);
  TestValidator.equals("description matches")(fetchedSection.description ?? null)(createInput.description ?? null);
  TestValidator.predicate("has created_at timestamp")(typeof fetchedSection.created_at === "string");
  TestValidator.predicate("has updated_at timestamp")(typeof fetchedSection.updated_at === "string");

  // 4. Request a non-existent section ID
  await TestValidator.error("not found for missing section")(
    () => api.functional.discussionBoard.sections.getById(connection, { id: typia.random<string & tags.Format<"uuid">>() }),
  );
}

