import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";

/**
 * Test attempting to delete a channel that was already soft-deleted.
 *
 * This test verifies that when an attempt is made to delete (soft-delete) a channel that has already been soft-deleted, the API correctly prevents a double-deletion and returns an appropriate error. This ensures data integrity and avoids inconsistent state for discussion board channels.
 *
 * Steps:
 * 1. Create a new channel
 * 2. Soft-delete (erase) the channel
 * 3. Attempt to soft-delete the same channel a second time, expecting an error to be returned.
 */
export async function test_api_discussionBoard_channels_test_soft_delete_channel_already_deleted_handling(
  connection: api.IConnection,
) {
  // 1. Create a new channel
  const channel = await api.functional.discussionBoard.channels.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()()
    } satisfies IDiscussionBoardChannel.ICreate
  });
  typia.assert(channel);

  // 2. Soft-delete (erase) the channel
  const erased = await api.functional.discussionBoard.channels.eraseById(connection, {
    id: channel.id
  });
  typia.assert(erased);
  TestValidator.equals("deleted_at set")(
    typeof erased.deleted_at === "string" && erased.deleted_at !== null
  )(true);

  // 3. Attempt to soft-delete the channel again (should fail)
  await TestValidator.error("Deleting already soft-deleted channel should fail")(
    async () => {
      await api.functional.discussionBoard.channels.eraseById(connection, {
        id: channel.id
      });
    }
  );
}

