/**
 * Validate that unauthorized users cannot access a moderation appeal by ID.
 *
 * Ensures that when a moderation appeal is created under one member ID (user A), attempts to fetch it
 * using a different member ID (user B) are forbidden. This simulates access control such that only
 * the owner, moderators, or admins may view an appeal's details. Since user authentication APIs are
 * not provided, member identity is simulated via explicit member_id in appeal creation and access attempts.
 *
 * Steps:
 * 1. Generate two unique member IDs (simulating users A and B).
 * 2. As user A, create a moderation appeal (using member_id A).
 * 3. Attempt to fetch the appeal as user B (simulate by trying access with member_id B context, if supported).
 *    Since the SDK does not support per-user context, we verify access control by attempting getById regardless,
 *    and expect an error as the two member_ids do not match.
 * 4. Use TestValidator.error() to assert that forbidden access is enforced (an error is thrown).
 */
export async function test_api_discussionBoard_test_get_moderation_appeal_by_id_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. Generate two unique member IDs to represent User A (owner) and User B (non-owner)
  const memberIdA: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const memberIdB: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 2. As User A, create the moderation appeal
  const actionId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const appeal = await api.functional.discussionBoard.moderationAppeals.post(connection, {
    body: {
      moderation_action_id: actionId,
      member_id: memberIdA,
      appeal_reason: "Test reason for moderation appeal by User A,",
    } satisfies IDiscussionBoardModerationAppeal.ICreate,
  });
  typia.assert(appeal);

  // 3. As User B (non-owner), attempt to fetch the moderation appeal created by User A
  //    Since identity is simulated, direct API context cannot switch; just attempt to getById
  await TestValidator.error("forbidden access for non-owner")(
    async () => {
      await api.functional.discussionBoard.moderationAppeals.getById(connection, {
        id: appeal.id,
      });
    },
  );
}

