 *
 * Steps:
 * 1. Attempt to create a moderation action with a missing 'action_type'. Assert that an error is thrown.
 * 2. Attempt to create a moderation action with a missing 'action_reason'. Assert that an error is thrown.
 * 3. Attempt to create a moderation action with a missing 'affected_member_id'. Assert that an error is thrown.
 * 4. Optionally, repeat with all three fields missing to confirm error robustness.
 */
export async function test_api_discussionBoard_test_create_moderation_action_with_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Missing 'action_type'
  await TestValidator.error("missing action_type should fail")(async () => {
    await api.functional.discussionBoard.moderationActions.post(connection, {
      body: {
        affected_member_id: typia.random<string & tags.Format<"uuid">>(),
        action_reason: "Audit required action reason.",
        // action_type intentionally omitted
      } as any, // This is required ONLY because TypeScript will not let us omit a required non-nullable field; runtime error is still checked.
    });
  });

  // 2. Missing 'action_reason'
  await TestValidator.error("missing action_reason should fail")(async () => {
    await api.functional.discussionBoard.moderationActions.post(connection, {
      body: {
        affected_member_id: typia.random<string & tags.Format<"uuid">>(),
        action_type: "warn",
        // action_reason intentionally omitted
      } as any,
    });
  });

  // 3. Missing 'affected_member_id'
  await TestValidator.error("missing affected_member_id should fail")(async () => {
    await api.functional.discussionBoard.moderationActions.post(connection, {
      body: {
        action_type: "suspend",
        action_reason: "Moderation action test.",
        // affected_member_id intentionally omitted
      } as any,
    });
  });

  // 4. All required fields missing
  await TestValidator.error("all required fields missing should fail")(async () => {
    await api.functional.discussionBoard.moderationActions.post(connection, {
      body: {
        // completely empty body
      } as any,
    });
  });
}

