import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDeleteConfirmation } from "@ORGANIZATION/PROJECT-api/lib/structures/IDeleteConfirmation";

/**
 * E2E test for admin board deletion (DiscussionBoard).
 *
 * This test verifies two main flows:
 *  a) Happy path – An admin creates a board, deletes it with the API, and confirms that:
 *     - The DELETE call returns a success confirmation.
 *     - The board no longer appears in new listings or (if possible) direct GET fetches returns a not found/error result.
 *     - Only admins can perform deletion (if role switching is supported).
 *     - Logical deletion (soft-delete) is in place: board is not shown in endpoints intended for users, but (if auditable) backend/auditing/soft-delete confirmation is possible. (Scoped to what API exposes.)
 *  b) Error path – Attempts to delete a non-existent board and an already-deleted board, confirming that the API returns a suitable error response in both cases.
 *
 * Steps:
 * 1. Create a board (POST /discussionBoard/boards), capture the board ID.
 * 2. Delete the board via DELETE /discussionBoard/boards/{id}.
 *    a. Assert success in IDeleteConfirmation.
 * 3. Attempt to DELETE the same board again - expect an error (TestValidator.error).
 * 4. Attempt to DELETE a random non-existent (uuid) board - expect an error.
 */
export async function test_api_discussionBoard_boards_test_delete_board_success_and_handle_nonexistent_board(connection: api.IConnection) {
  // 1. Create a board for deletion test
  const newBoard = await api.functional.discussionBoard.boards.post(connection, {
    body: {
      title: RandomGenerator.paragraph()(1),
      slug: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardBoard.ICreate,
  });
  typia.assert(newBoard);

  // 2. Delete the board as admin
  const result = await api.functional.discussionBoard.boards.eraseById(connection, {
    id: newBoard.id,
  });
  typia.assert(result);
  TestValidator.equals("delete confirmation")(result.success)(true);

  // 3. Attempt to delete again (already deleted) – expect error
  await TestValidator.error("already deleted board returns error")(
    async () => {
      await api.functional.discussionBoard.boards.eraseById(connection, {
        id: newBoard.id,
      });
    }
  );

  // 4. Attempt to delete non-existent uuid
  await TestValidator.error("nonexistent board")(
    async () => {
      await api.functional.discussionBoard.boards.eraseById(connection, {
        id: typia.random<string & tags.Format<'uuid'>>(),
      });
    }
  );
}

