 * Steps:
 * 1. Create a board.
 * 2. Delete the board by its id as admin, and verify success.
 * 3. Attempt to delete the same board again, and expect error.
 * 4. Attempt to delete a non-existent board (random uuid), and expect error.
 */
export async function test_api_discussionBoard_boards_test_delete_board_success_and_handle_nonexistent_board(
