import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardReportCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportCategory";

/**
 * Validate updating a report category's name and description, ensuring business rules and permissions are enforced.
 *
 * This test ensures that admin users can update an existing report category's name and description, while validating proper error handling for uniqueness constraints, nonexistent resources, and permission checks.
 *
 * Steps:
 * 1. Create two distinct report categories as admin (catA, catB).
 * 2. Update catA's name and description—verify that the changes are reflected in the response.
 * 3. Attempt to update catA so its name equals catB's name—verify unique name error is triggered.
 * 4. Attempt to update catA as a non-admin—ensure a permission denied error is triggered.
 * 5. Attempt to update a non-existent ID—ensure a not found error is triggered.
 */
export async function test_api_discussionBoard_reportCategories_test_update_report_category_name_and_uniqueness(
  connection: api.IConnection,
) {
  // 1. Create two report categories as admin
  const categoryA = await api.functional.discussionBoard.reportCategories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(8) + "_uniqueA",
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(categoryA);

  const categoryB = await api.functional.discussionBoard.reportCategories.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(8) + "_uniqueB",
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(categoryB);

  // 2. Update catA's name and description
  const updatedName = RandomGenerator.alphaNumeric(8) + "_updated";
  const updatedDescription = RandomGenerator.paragraph()();
  const updatedCategoryA = await api.functional.discussionBoard.reportCategories.putById(connection, {
    id: categoryA.id,
    body: {
      name: updatedName,
      description: updatedDescription,
    },
  });
  typia.assert(updatedCategoryA);
  TestValidator.equals("updated name")(updatedCategoryA.name)(updatedName);
  TestValidator.equals("updated description")(updatedCategoryA.description)(updatedDescription);

  // 3. Attempt to update catA's name to catB's name (should fail uniqueness)
  await TestValidator.error("category name uniqueness")(() =>
    api.functional.discussionBoard.reportCategories.putById(connection, {
      id: categoryA.id,
      body: { name: categoryB.name },
    })
  );

  // 4. Attempt to update as non-admin (simulate by temp connection without rights). Should fail
  const guestConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("permission denied for non-admin")(() =>
    api.functional.discussionBoard.reportCategories.putById(guestConnection, {
      id: categoryA.id,
      body: { name: RandomGenerator.alphaNumeric(8) + "_guest" },
    })
  );

  // 5. Attempt to update non-existent ID
  await TestValidator.error("updating non-existent category fails")(() =>
    api.functional.discussionBoard.reportCategories.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { name: RandomGenerator.alphaNumeric(8) + "_nonexistent" },
    })
  );
}

