import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerationAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAppeal";
import type { IPageDiscussionBoardModerationAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardModerationAppeal";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that listing moderation appeals with filter criteria
 * for non-existent records returns an empty result set.
 *
 * This test verifies the behavior of the moderation appeals search
 * endpoint when sent filters that are not expected to match any
 * existing data, covering pagination metadata integrity and data array.
 *
 * Steps:
 * 1. Construct a filter using clearly non-existent values (e.g., UUIDs
 *    that should not correspond to any real action or member, status
 *    not used by the system, absurd date ranges).
 * 2. Call api.functional.discussionBoard.moderationAppeals.patch
 *    with the constructed filter request.
 * 3. Assert the returned data array is empty and pagination metadata
 *    indicates zero records and zero total pages.
 * 4. Validate response types with typia.assert and ensure correctness
 *    of all core pagination fields.
 */
export async function test_api_discussionBoard_test_list_moderation_appeals_empty_result_when_no_matches(
  connection: api.IConnection,
) {
  // 1. Construct filter object with intentionally non-existent values
  const filter: IDiscussionBoardModerationAppeal.IRequest = {
    moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
    member_id: typia.random<string & tags.Format<"uuid">>(),
    appeal_status: "impossible_status_value",
    created_at_from: "2099-01-01T00:00:00.000Z",
    created_at_to: "2099-12-31T23:59:59.999Z",
    page: 1,
    limit: 20,
  };

  // 2. Request list using advanced search filter
  const output = await api.functional.discussionBoard.moderationAppeals.patch(
    connection,
    { body: filter },
  );
  typia.assert(output);

  // 3. Assert empty data array
  TestValidator.equals("no data matches filter")(output.data)([]);

  // 4. Assert correct pagination meta (zero records/pages, current = 1, limit = 20)
  const p = output.pagination;
  TestValidator.equals("current page")(p.current)(1);
  TestValidator.equals("page limit")(p.limit)(20);
  TestValidator.equals("zero records")(p.records)(0);
  TestValidator.equals("zero pages")(p.pages)(0);
}

