import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerationAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAppeal";
import type { DiscussionBoardModerationAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardModerationAppeal";

/**
 * Validate successful withdrawal (soft-delete) of a moderation appeal by its owner before decision.
 *
 * Business context:
 * - To ensure users can withdraw their moderation appeals as long as the appeal has not been decided.
 * - The owner of an appeal may withdraw it, which sets the appropriate 'withdrawn' or 'deleted' status, preserves an audit trail, and effectively removes the appeal from the list of active (pending) appeals.
 * - This operation must be allowed only for the owner and only for undecided appeals.
 *
 * Steps:
 * 1. Create a new moderation appeal (with unique moderation_action_id and member_id, and a sample appeal_reason).
 * 2. Withdraw the moderation appeal as the creator/owner BEFORE any decision or status change.
 * 3. Validate that the returned record indicates the appeal has been withdrawn (appeal_status is 'withdrawn', timestamps reflect update, and audit-related info remains consistent).
 * 4. Confirm via returned entity that the appeal is no longer active/pending.
 * 5. (Cannot fetch all appeals for user in this context, so just rely on entity and status logic.)
 */
export async function test_api_discussionBoard_moderationAppeals_test_withdraw_moderation_appeal_success_by_owner(connection: api.IConnection) {
  // 1. Create a new moderation appeal as an owner
  const createInput: IDiscussionBoardModerationAppeal.ICreate = {
    moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
    member_id: typia.random<string & tags.Format<"uuid">>(),
    appeal_reason: "I disagree with the moderation action due to lack of context.",
  };
  const appeal = await api.functional.discussionBoard.moderationAppeals.post(connection, { body: createInput });
  typia.assert(appeal);

  // 2. Withdraw the appeal before decision
  const withdrawn = await api.functional.discussionBoard.moderationAppeals.eraseById(connection, { id: appeal.id });
  typia.assert(withdrawn);

  // 3. Validate status is set to 'withdrawn', audit (timestamps/member/action) are consistent, and content is unchanged except status/last_updated.
  TestValidator.equals("appeal ID unchanged")(withdrawn.id)(appeal.id);
  TestValidator.equals("appeal still bound to original moderation action")(withdrawn.moderation_action_id)(appeal.moderation_action_id);
  TestValidator.equals("appeal still bound to owner")(withdrawn.member_id)(appeal.member_id);
  TestValidator.equals("appeal reason unchanged")(withdrawn.appeal_reason)(appeal.appeal_reason);
  TestValidator.equals("appeal status is withdrawn")(withdrawn.appeal_status)("withdrawn");
  TestValidator.notEquals("last_updated_at must change")(withdrawn.last_updated_at)(appeal.last_updated_at);
  // 4. Confirm withdrawn appeal is not active (pending)
  TestValidator.notEquals("appeal status not pending after withdrawal")(withdrawn.appeal_status)("pending");
}

