import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { DiscussionBoardContentPolicies } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardContentPolicies";

/**
 * Validate rejection when attempting to create a content policy (DiscussionBoardContentPolicies) with an invalid time range.
 *
 * Business rule: The expiration (effective_to) date must not be before the effective_from date.
 * This test ensures that the API enforces the logical sequence of effective dates for a policy, rejecting requests where the expiration precedes the effective date.
 *
 * Steps:
 * 1. Prepare a valid policy creation request as baseline (not sent, just for reference)
 * 2. Prepare a request with effective_from set to a date later than effective_to (i.e. inversion: expiration before effect)
 * 3. Attempt to create the policy with this invalid time range
 * 4. Verify that the API rejects the request and throws a validation error
 * 5. Confirm that no policy record is created and the response conveys the nature of the error (business logic enforcement)
 */
export async function test_api_discussionBoard_test_create_content_policy_with_invalid_time_range(
  connection: api.IConnection,
) {
  // Step 1: Prepare a baseline for valid input reference (not sent)
  const baseInput: DiscussionBoardContentPolicies.ICreate = {
    code: RandomGenerator.alphaNumeric(8),
    title: "Spam Policy",
    description: "Details regarding the handling of spam in the forum.",
    effective_from: new Date("2025-07-24T09:00:00.000Z").toISOString(),
    effective_to: new Date("2025-12-31T23:59:59.000Z").toISOString(),
    is_active: true,
  };

  // Step 2: Prepare invalid input where expiration is *before* effective date
  const invalidInput: DiscussionBoardContentPolicies.ICreate = {
    ...baseInput,
    effective_from: new Date("2025-07-24T09:00:00.000Z").toISOString(),
    effective_to: new Date("2025-07-20T09:00:00.000Z").toISOString(), // earlier than effective_from
  };

  // Step 3 & 4: Attempt creation, expect error
  await TestValidator.error("Should reject policy with expiration before effective date")(
    () =>
      api.functional.discussionBoard.contentPolicies.post(connection, {
        body: invalidInput,
      }),
  );
}

