import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { DiscussionBoardContentPolicies } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardContentPolicies";

/**
 * Test creation of a new content policy in the discussion board system with valid data.
 *
 * This test validates that when a content policy is created using a unique policy code,
 * along with a properly formatted title, detailed description, valid effective_from
 * timestamp, and (optionally) an effective_to value, the API:
 * 1. Accepts the input and returns the complete, created content policy object.
 * 2. Ensures all values are reflected correctly in the response.
 * 3. Fulfills schema/type validation including proper date-time formats and field requirements.
 * 4. Enforces business rules such as unique policy code.
 *
 * Test Steps:
 * 1. Prepare a content policy creation DTO with all required fields:
 *    - code: unique, e.g. 'GENERAL_POLICY_{random}'
 *    - title: clear string
 *    - description: long text
 *    - effective_from: valid ISO date-time string (now or future)
 *    - effective_to: valid ISO date-time string after effective_from or null (optional)
 *    - is_active: boolean
 * 2. Call the creation endpoint with this DTO and verify a successful response.
 * 3. Validate that all input data is reflected in the returned object (except for autogenerated fields like id, created_at, updated_at).
 * 4. Assert that the API enforces all schema validations and business rules.
 */
export async function test_api_discussionBoard_contentPolicies_post(
  connection: api.IConnection,
) {
  // 1. Prepare creation data with unique code and all fields populated
  const now = new Date();
  const effectiveFrom = now.toISOString();
  // 1 day after now for effective_to
  const effectiveTo = new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString();
  const code = `GENERAL_POLICY_${String(Math.floor(Math.random() * 1e6))}`;

  const input: DiscussionBoardContentPolicies.ICreate = {
    code,
    title: `Content Policy ${code}`,
    description: "All users must comply with general board rules. Any violation will result in administrative action.",
    effective_from: effectiveFrom,
    effective_to: effectiveTo,
    is_active: true,
  };

  // 2. Call the API to create the policy
  const policy = await api.functional.discussionBoard.contentPolicies.post(connection, {
    body: input,
  });
  typia.assert(policy);

  // 3. Validate the returned record
  TestValidator.equals("code matches")(policy.code)(input.code);
  TestValidator.equals("title matches")(policy.title)(input.title);
  TestValidator.equals("description matches")(policy.description)(input.description);
  TestValidator.equals("effective_from matches")(policy.effective_from)(input.effective_from);
  TestValidator.equals("effective_to matches")(policy.effective_to)(input.effective_to);
  TestValidator.equals("is_active matches")(policy.is_active)(input.is_active);
  TestValidator.predicate("policy id is uuid")(!!policy.id && policy.id.length > 10);
  TestValidator.predicate("created_at is ISO date-time")(!!policy.created_at && !Number.isNaN(Date.parse(policy.created_at)));
  TestValidator.predicate("updated_at is ISO date-time")(!!policy.updated_at && !Number.isNaN(Date.parse(policy.updated_at)));
}

