import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";

/**
 * 관리자 권한을 가진 사용자가 알림 설정 상세 정보를 조회하는 API를 검증한다.
 *
 * 이 테스트는 다음을 검증한다:
 * 1. 정상(성공) 케이스: 존재하는 알림 설정 ID를 조회했을 때 모든 필드가 정확하게 반환되는지(키값, 밸류, 설명, 생성일 등), 그리고 접근이 정상적으로 허용되는지.
 * 2. 실패(비정상) 케이스:
 *    a) 존재하지 않는 ID를 요청할 때 404 not found 오류가 정상적으로 반환되는지
 *    b) 관리자 권한이 아닌 경우(예: 일반 회원) 접근이 거부되는지(권한 오류 등)
 *    c) 민감/비공개 알림 설정을 비권한자가 접근 시도 시 접근 거부되는지(해당 시나리오가 백엔드 권한 처리와 연동되어 있다면)
 *
 * 단계별 흐름:
 * 1. (선행) 알림 설정 데이터를 사전에 생성한다(POST /discussionBoard/notificationSettings)
 * 2. 성공 케이스: 방금 생성한 알림 설정 ID를 getById로 조회하고, 반환된 모든 값이 입력값과 일치하며, 모든 필드가 반환되는지 비교한다
 * 3. 실패 케이스a: 무작위(존재하지 않는) UUID로 조회 시도 후 404 발생 확인
 * 4. 실패 케이스b: 비관리자 권한(~ connection 변환 필요시)에서 getById 실행 시 권한 거부 등 실패 확인 (명확한 권한 관리가 동작하는 경우만 체크)
 */
export async function test_api_discussionBoard_notificationSettings_getById(
  connection: api.IConnection,
) {
  // 1. 알림 설정 생성(사전 데이터 준비)
  const createBody: IDiscussionBoardNotificationSetting.ICreate = {
    key: `unit_test_key_${RandomGenerator.alphaNumeric(8)}`,
    value: "immediate",
    description: "테스트용 알림 설정 설명입니다.",
  };
  const created: IDiscussionBoardNotificationSetting = await api.functional.discussionBoard.notificationSettings.post(connection, { body: createBody });
  typia.assert(created);

  // 2. 성공 케이스 - 방금 생성한 알림 설정 ID로 상세조회
  const fetched: IDiscussionBoardNotificationSetting = await api.functional.discussionBoard.notificationSettings.getById(connection, { id: created.id });
  typia.assert(fetched);
  // 모든 필드(키, 값, 설명 등)가 정확히 반환되는지 확인
  TestValidator.equals("id 일치")(fetched.id)(created.id);
  TestValidator.equals("key 일치")(fetched.key)(createBody.key);
  TestValidator.equals("value 일치")(fetched.value)(createBody.value);
  TestValidator.equals("description 일치")(fetched.description)(createBody.description ?? null);

  // 3. 실패 케이스a - 존재하지 않는 id로 조회 시 404
  const nonExistentId: string = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("존재하지 않는 알림 설정 ID - 404 확인")(
    async () => {
      await api.functional.discussionBoard.notificationSettings.getById(connection, { id: nonExistentId });
