/**
 * Test soft-deleting a section as an admin
 *
 * This test validates the soft-delete functionality on a discussion board section using admin privileges. It ensures the deletion behaves correctly as per business and audit requirements:
 *
 * 1. Create a parent channel (required for valid section creation)
 * 2. Create a discussion board section under that channel
 * 3. Soft-delete the section by its ID as an admin
 * 4. Check the returned section has a non-null 'deleted_at' timestamp
 * 5. (Skipped: As no section search/filter/list APIs exist in the provided SDK, cannot check exclusion from regular search or admin search result set)
 * 6. (Skipped: As audit logging is not exposed in the provided API, cannot directly confirm audit log—this is handled by business logic)
 *
 * The test aligns with the scenario while only implementing what is strictly possible from the available API surface and DTO definitions.
 */
export async function test_api_discussionBoard_test_soft_delete_section_by_admin(
  connection: api.IConnection,
) {
