 * Steps:
 * 1. Register a new discussion board member (author).
 * 2. Create a new discussion board.
 * 3. Author creates a post in the board.
 * 4. Author updates their post with a new title and body.
 * 5. Assert that title, body, and updated_at are updated and is_locked remains false.
 * 6. Optionally, fetch the post again to confirm updates persist.
 */
export async function test_api_discussionBoard_test_update_post_by_author_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Register a new discussion board member (author)
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "Str0ng#P4ssw0rd"
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a new discussion board
  const board = await api.functional.discussionBoard.boards.post(connection, {
    body: {
      title: RandomGenerator.paragraph()(1),
      slug: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.content()(1)(1)
    } satisfies IDiscussionBoardBoard.ICreate,
  });
  typia.assert(board);

  // 3. Author creates a post in the board
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: board.id,
      author_id: member.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()()
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

