  const updatedTitle = RandomGenerator.paragraph()(1) + " - edited";
  const updatedBody = RandomGenerator.content()(1)(1) + "\n\nEdited contents.";
  const updated = await api.functional.discussionBoard.posts.putById(connection, {
    id: post.id,
    body: {
      title: updatedTitle,
      body: updatedBody
    } satisfies IDiscussionBoardPost.IUpdate,
  });
  typia.assert(updated);

  // 5. Assert that title, body, and updated_at are changed; is_locked is still false
  TestValidator.notEquals("updated_at changed")(updated.updated_at)(post.updated_at);
  TestValidator.equals("title updated")(updated.title)(updatedTitle);
  TestValidator.equals("body updated")(updated.body)(updatedBody);
  TestValidator.equals("still unlocked")(updated.is_locked)(false);

  // 6. Fetch the post again and confirm persistence
  // (Assume no GET API - if it's available in the SDK in future, add here)
}

