  };
  const reaction = await api.functional.discussionBoard.commentReactions.post(connection, { body: reactionInput });
  typia.assert(reaction);

  // 4. Attempt to add the same reaction type again
  TestValidator.error("Duplicate reaction not allowed")(async () => {
