      password: typia.random<string & tags.Format<"password">>(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(recipient);

  // 2. 관리자 계정 + 관리자 역할 등록 (관리자 인증 상태 처리)
  const admin_member: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: typia.random<string & tags.Format<"password">>(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(admin_member);
  const admin: IDiscussionBoardAdmin = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: admin_member.id,
      appointed_by_admin_id: admin_member.id, // 자기 자신을 최초 관리자로 지정
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(admin);

  // (관리자 인증 상태, 즉 admin_member가 인증된 상황이라고 가정)

  // 3. 존재하지 않는 게시글 ID로 notification 생성 요청 (target_post_id에 랜덤 UUID)
  const bogus_post_id: string = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("존재하지 않는 게시글을 알림 타깃으로 지정 시 에러 반환")(() =>
    api.functional.discussionBoard.notifications.post(connection, {
      body: {
        recipient_member_id: recipient.id,
        trigger_actor_id: admin_member.id,
        type: "mention",
        target_post_id: bogus_post_id,
        target_comment_id: null,
        target_report_id: null,
        target_section_id: null,
        delivered_at: new Date().toISOString() as string & tags.Format<"date-time">,
      } satisfies DiscussionBoardNotification.ICreate,
    })
  );
}

