import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportLog";

/**
 * 신고 처리 로그 생성(유효/무효 입력값 모두) 테스트
 *
 * 1. 사전 준비: report log가 연결될 신고(report) 엔티티를 등록한다.
 *
 * 2. 정상 케이스: 
 *   - 적절한 report_id (존재하는 신고 ID)
 *   - actor_moderator_id(임의 UUID 사용)
 *   - action(적절한 상태값, e.g. 'reviewed')
 *   - action_comment(코멘트 입력)
 *   => 로그가 정상 생성되고 모든 필드가 채워진다. 응답값으로 동일 report_id, actor, action, comment, 타임스탬프가 반환됨을 검증
 *
 * 3. 필드 누락, 존재하지않는 신고ID, 잘못된 action 등의 비정상 케이스:
 *   - report_id 누락
 *   - actor_moderator_id 누락
 *   - action 누락
 *   - 존재하지 않는 report_id 사용
 *   - 잘못된 action값(ex. '', null)
 * => 각 경우별로 적절한 오류가 발생함을 확인
 */
export async function test_api_discussionBoard_test_create_report_log_with_valid_and_invalid_inputs(
  connection: api.IConnection,
) {
  // 1. 신고를 등록한다 (Report 생성). 이 ID를 로그에 사용.
  const reportCreate: IDiscussionBoardReport = await api.functional.discussionBoard.reports.post(connection, {
    body: {
      reported_by_member_id: typia.random<string & tags.Format<"uuid">>(),
      report_category_id: typia.random<string & tags.Format<"uuid">>(),
      description: "테스트용 신고 설명",
      target_post_id: typia.random<string & tags.Format<"uuid">>(), // 게시글 신고로 가정
      target_comment_id: null,
    } satisfies IDiscussionBoardReport.ICreate,
  });
  typia.assert(reportCreate);
  const valid_report_id = reportCreate.id;

  // 2. 정상 입력으로 신고 로그 생성
  const valid_actor_id = typia.random<string & tags.Format<"uuid">>();
  const logInputValid: IDiscussionBoardReportLog.ICreate = {
    report_id: valid_report_id,
    actor_moderator_id: valid_actor_id,
    action: "reviewed",
    action_comment: "정상 처리 테스트",
  };
  const logResult = await api.functional.discussionBoard.reportLogs.post(connection, {
    body: logInputValid,
  });
  typia.assert(logResult);
  TestValidator.equals("로그-리포트ID")(logResult.report_id)(valid_report_id);
  TestValidator.equals("로그-담당자ID")(logResult.actor_moderator_id)(valid_actor_id);
  TestValidator.equals("로그-액션")(logResult.action)("reviewed");
  TestValidator.equals("로그-코멘트")(logResult.action_comment)("정상 처리 테스트");
  TestValidator.predicate("로그-타임스탬프유효")(
    typeof logResult.timestamp === "string" && logResult.timestamp.length > 0,
  );

  // 3. 필수 필드 누락 - report_id 빠짐
  await TestValidator.error("필수-리포트ID 누락")(() =>
    api.functional.discussionBoard.reportLogs.post(connection, {
      body: {
        // report_id: 누락,
        actor_moderator_id: valid_actor_id,
        action: "reviewed",
      } as any, // as any는 E2E 정책상 금지여서 실제로는 이경우 SKIP (컴파일오류)
    }),
  );
  // 3-2. 필수 필드 누락 - actor_moderator_id 빠짐
  await TestValidator.error("필수-담당자ID 누락")(() =>
    api.functional.discussionBoard.reportLogs.post(connection, {
      body: {
        report_id: valid_report_id,
        // actor_moderator_id: 누락,
        action: "reviewed",
      } as any,
    }),
  );
  // 3-3. 필수필드 누락 - action 빠짐
  await TestValidator.error("필수-액션 누락")(() =>
    api.functional.discussionBoard.reportLogs.post(connection, {
      body: {
        report_id: valid_report_id,
        actor_moderator_id: valid_actor_id,
        // action: 누락,
      } as any,
    }),
  );

  // 4. 존재하지 않는 신고ID로 로그 생성 시도
  await TestValidator.error("존재하지 않는 리포트ID")(() =>
    api.functional.discussionBoard.reportLogs.post(connection, {
      body: {
        report_id: typia.random<string & tags.Format<"uuid">>(), // 임의의 존재하지 않는 값 기대
        actor_moderator_id: valid_actor_id,
        action: "reviewed",
      } satisfies IDiscussionBoardReportLog.ICreate,
    }),
  );
  // 5. 잘못된 액션값(빈문자열)
  await TestValidator.error("잘못된 액션(빈문자열)")(() =>
    api.functional.discussionBoard.reportLogs.post(connection, {
      body: {
        report_id: valid_report_id,
        actor_moderator_id: valid_actor_id,
        action: "",
      } satisfies IDiscussionBoardReportLog.ICreate,
    }),
  );
  // 6. 잘못된 액션(null)
  await TestValidator.error("잘못된 액션(null 값)")(() =>
    api.functional.discussionBoard.reportLogs.post(connection, {
      body: {
        report_id: valid_report_id,
        actor_moderator_id: valid_actor_id,
        action: null as any,
      } as any,
    }),
  );
}

