import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSection";

/**
 * Test creating a new section under a discussion board channel as an admin with valid data
 *
 * This test ensures the full workflow for registering a section under a valid, existing channel as an administrator. It validates business rules such as:
 * - The parent channel must exist
 * - Section name must be unique within its channel
 * - Section should be immediately accessible after creation
 * - Audit and admin-only requirements are implied business rules
 *
 * Steps:
 * 1. Create a parent channel using the channel creation API (admin action)
 * 2. Create a section referencing the channel by id, using a unique name and a non-null/blank description (admin action)
 * 3. Assert that the returned section references the channel, and includes submitted business fields
 * 4. Attempt to create a section with the SAME name in the same channel—should fail (unique constraint)
 * 5. Optionally, confirm that a section with the same name CAN be created in a DIFFERENT channel
 */
export async function test_api_discussionBoard_test_create_section_with_valid_data_by_admin(
  connection: api.IConnection,
) {
  // 1. Create parent channel (simulate admin)
  const channelName = RandomGenerator.alphaNumeric(12);
  const channelCreate: IDiscussionBoardChannel.ICreate = {
    name: channelName,
    description: RandomGenerator.paragraph()(),
  };
  const channel = await api.functional.discussionBoard.channels.post(connection, { body: channelCreate });
  typia.assert(channel);

  // 2. Create section in this channel
  const sectionName = RandomGenerator.alphaNumeric(14);
  const sectionDesc = RandomGenerator.paragraph()();
  const sectionCreate: IDiscussionBoardSection.ICreate = {
    discussionboard_channel_id: channel.id,
    name: sectionName,
    description: sectionDesc,
  };
  const section = await api.functional.discussionBoard.sections.post(connection, { body: sectionCreate });
  typia.assert(section);
  TestValidator.equals("channel ref")(section.discussionboard_channel_id)(channel.id);
  TestValidator.equals("section name")(section.name)(sectionName);
  TestValidator.equals("section desc")(section.description)(sectionDesc);
  TestValidator.predicate("created_at defined")(!!section.created_at);
  TestValidator.predicate("updated_at defined")(!!section.updated_at);
  TestValidator.equals("not deleted")(section.deleted_at)(null);

  // 3. Section is accessible immediately (in this API, confirmed by valid returned data above)
  // 4. Attempt duplicate section name in same channel (should fail)
  await TestValidator.error("duplicate section name in same channel")(() =>
    api.functional.discussionBoard.sections.post(connection, { body: {
      discussionboard_channel_id: channel.id,
      name: sectionName,
      description: RandomGenerator.paragraph()(),
    } }),
  );

  // 5. Create a second channel
  const secondChannel = await api.functional.discussionBoard.channels.post(connection, { body: {
    name: RandomGenerator.alphaNumeric(12),
    description: RandomGenerator.paragraph()(),
  } });
  typia.assert(secondChannel);

  // 6. Section with same name can be created in different channel
  const altSection = await api.functional.discussionBoard.sections.post(connection, { body: {
    discussionboard_channel_id: secondChannel.id,
    name: sectionName, // same name, different channel
    description: RandomGenerator.paragraph()(),
  } });
  typia.assert(altSection);
  TestValidator.equals("alternate section channel id")(altSection.discussionboard_channel_id)(secondChannel.id);
  TestValidator.equals("alternate section name")(altSection.name)(sectionName);
}

