 * Validate that only the owner of a notification preference can delete it.
 *
 * This test verifies access control enforcement, ensuring that a discussion board member cannot delete another member's notification preferences. It covers the following sequence:
 *
 * 1. Register two distinct members (Member A - the owner, and Member B - a non-owner).
 * 2. As Member A, create a notification preference entry.
 * 3. Attempt to delete Member A's notification preference as Member B.
 * 4. Assert that deletion is forbidden and the system returns an appropriate error indicating lack of permission.
 *
 * This prevents privilege escalation and protects user-specific configuration from unauthorized manipulation.
 */
export async function test_api_discussionBoard_test_delete_notification_preference_forbidden_for_non_owner(connection: api.IConnection) {
  // 1. Register Member A (the owner)
  const memberA = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12) as string & tags.Format<"password">,
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(memberA);

  // 2. Register Member B (the non-owner)
  const memberB = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12) as string & tags.Format<"password">,
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(memberB);

  // 3. As Member A, create a notification preference
  // (Assume connection context is for Member A - system should bind preference to Member A's id)
  const notificationPreference = await api.functional.discussionBoard.notificationPreferences.post(connection, {
    body: {
      member_id: memberA.id,
      enable_email: true,
      enable_web_push: false,
      enable_system_announcements: true,
    } satisfies DiscussionBoardNotificationPreferences.ICreate
  });
  typia.assert(notificationPreference);

  // 4. Simulate operation as Member B - attempt to delete Member A's notification preference
  // (In reality, authentication would be required here. If the SDK supported per-user connection simulation, switch to Member B context.)
  // For this test, suppose connection is switched to Member B's context (conceptually).

  // Attempt the unauthorized delete and expect an error
  await TestValidator.error("Non-owner cannot delete another member's notification preference")(
    async () => {
      await api.functional.discussionBoard.notificationPreferences.eraseById(connection, {
        id: notificationPreference.id,
      });
    }
  );
}

