 * 2. Create a regular board member (non-admin, non-moderator)
 * 3. As the admin, create a configuration
 * 4. As the admin (creator), retrieve the configuration by its ID and validate all returned details
 * 5. As the regular member, retrieve the configuration by its ID and validate the result (permission should allow access if not restricted, or enforce error if expected)
 * 6. Confirm all business logic and permission rules are enforced
 */
export async function test_api_discussionBoard_test_get_existing_configuration_by_id_with_proper_permissions(connection: api.IConnection) {
  // 1. Create an admin member
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminUsername: string = RandomGenerator.alphaNumeric(12);
  const admin: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: adminUsername,
      email: adminEmail,
      display_name: RandomGenerator.name(),
      password: "strong-Password1!"
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(admin);

  // 2. Create a regular member
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberUsername: string = RandomGenerator.alphaNumeric(12);
  const member: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: memberUsername,
      email: memberEmail,
      display_name: RandomGenerator.name(),
      password: "strong-Password1!"
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 3. As admin, create a configuration
  const configKey = `max_post_length_${RandomGenerator.alphaNumeric(8)}`;
  const configValue = String(typia.random<number & tags.Type<"uint32"> & tags.Minimum<100> & tags.Maximum<10000>>());
  const configDescription = "Maximum allowed post length in characters.";
  const configuration: IDiscussionBoardConfiguration = await api.functional.discussionBoard.configurations.post(connection, {
    body: {
      key: configKey,
      value: configValue,
      description: configDescription,
    } satisfies IDiscussionBoardConfiguration.ICreate,
  });
  typia.assert(configuration);
  TestValidator.equals("created config key")(configuration.key)(configKey);
  TestValidator.equals("created config value")(configuration.value)(configValue);
  TestValidator.equals("created config description")(configuration.description)(configDescription);

  // 4. As the admin, retrieve the configuration by ID
  const configResultAsAdmin: IDiscussionBoardConfiguration = await api.functional.discussionBoard.configurations.getById(connection, { id: configuration.id });
  typia.assert(configResultAsAdmin);
  TestValidator.equals("key matches")(configResultAsAdmin.key)(configKey);
  TestValidator.equals("value matches")(configResultAsAdmin.value)(configValue);
  TestValidator.equals("description matches")(configResultAsAdmin.description)(configDescription);
  TestValidator.equals("id matches")(configResultAsAdmin.id)(configuration.id);

  // 5. As a regular member, retrieve the configuration by ID (should succeed for non-sensitive keys)
  // (NOTE: Since permission details are not specified in the DTO/API, we assume allowed. If business logic restricts, adjust error check accordingly)
  const configResultAsMember: IDiscussionBoardConfiguration = await api.functional.discussionBoard.configurations.getById(connection, { id: configuration.id });
  typia.assert(configResultAsMember);
  TestValidator.equals("key matches for member")(configResultAsMember.key)(configKey);
}

