import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostEdit";

/**
 * Test creation of new post edit records in Discussion Board.
 *
 * This workflow validates three major cases:
 * 1. Happy path (authorized edit): A member edits their own post—the edit is accepted, and all audit fields are correct.
 * 2. Edit a non-existent post: The API should return a validation error when the post_id does not exist.
 * 3. Unauthorized member tries edit: A different user attempts to edit a post they do not own. The system should reject the edit.
 *
 * Steps:
 * 1. Create two unique members (author and stranger).
 * 2. Create a board.
 * 3. Original author creates a post on the board.
 * 4. Author makes a valid edit to the post.
 *   - Confirm response contains correct post_id, editor_id, body_after_edit, and audit fields (id, created_at).
 * 5. Attempt to edit a random/non-existent post_id (by author): Expect validation error.
 * 6. Attempt to edit the real post, but by the stranger member: Expect authorization error.
 */
export async function test_api_discussionBoard_test_create_post_edit_success_and_failure_cases(
  connection: api.IConnection,
) {
  // 1. Create two unique members
  const authorResult = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "AuthorPass123!" as string & tags.Format<"password">,
    },
  });
  typia.assert(authorResult);

  const strangerResult = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "Stranger123!" as string & tags.Format<"password">,
    },
  });
  typia.assert(strangerResult);


  // 2. Create a board
  const boardResult = await api.functional.discussionBoard.boards.post(connection, {
    body: {
      title: RandomGenerator.paragraph()(1),
      slug: RandomGenerator.alphaNumeric(9),
      description: RandomGenerator.content()()(),
    },
  });
  typia.assert(boardResult);

  // 3. Author creates a post
  const postResult = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: boardResult.id,
      author_id: authorResult.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(postResult);

  // 4. Author edits their post (happy path)
  const happyEditInput = {
    post_id: postResult.id,
    editor_id: authorResult.id,
    edit_summary: "Fixed typo.",
    body_after_edit: "[EDITED] " + postResult.body,
  } satisfies IDiscussionBoardPostEdit.ICreate;
  const happyEditOutput = await api.functional.discussionBoard.postEdits.post(connection, {
    body: happyEditInput,
  });
  typia.assert(happyEditOutput);
  TestValidator.equals("happy path post_id correct")(happyEditOutput.post_id)(postResult.id);
  TestValidator.equals("editor_id matches author")(happyEditOutput.editor_id)(authorResult.id);
  TestValidator.equals("edit_summary set")(happyEditOutput.edit_summary)(happyEditInput.edit_summary);
  TestValidator.equals("body_after_edit matches")(happyEditOutput.body_after_edit)(happyEditInput.body_after_edit);
  TestValidator.predicate("id is uuid")(!!happyEditOutput.id && happyEditOutput.id.length >= 32);
  TestValidator.predicate("created_at set")(typeof happyEditOutput.created_at === "string");

  // 5. Author tries to edit non-existent post (should fail)
  await TestValidator.error("edit with invalid post_id throws")(
    async () => {
      await api.functional.discussionBoard.postEdits.post(connection, {
        body: {
          post_id: typia.random<string & tags.Format<"uuid">>(),
          editor_id: authorResult.id,
          edit_summary: "Attempt edit non-existent post.",
          body_after_edit: RandomGenerator.content()()(),
        },
      });
    }
  );

  // 6. Stranger attempts to edit real post (should fail)
  await TestValidator.error("stranger cannot edit others' post")(
    async () => {
      await api.functional.discussionBoard.postEdits.post(connection, {
        body: {
          post_id: postResult.id,
          editor_id: strangerResult.id,
          edit_summary: "Trying unauthorized edit.",
          body_after_edit: RandomGenerator.content()()(),
        },
      });
    }
  );
}

