  TestValidator.equals("삭제한 알림의 수신자 일치")(deleted.recipient_member_id)(member.id);

  // 4. 통상(fetch) 알림 목록에 삭제된 알림이 보이지 않아야 하나
  // 별도 fetch API가 없어 본 단계는 생략합니다.
}

