    body: adminInput,
  });
  typia.assert(adminMember);

  // 2. (key 누락) 필수값 미포함 – value만으로 생성: 런타임 입력값 오류 반환 검증
  await TestValidator.error("key가 없는 configuration 생성은 실패해야 함")(
    async () => {
      return api.functional.discussionBoard.configurations.post(connection, {
        body: {
          // key: intentionally omitted
          value: "some-value",
        } as any, // 실제 코드에서는 satisfies를 쓸 수 없지만, 타입 정책상 오류 케이스는 as any로 처리해야 함.
      });
    }
  );

  // 3. (빈 key) key가 빈 문자열인 경우도 거부 (비즈니스 제약이 있다면 검증)
