import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCommentThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentThread";

/**
 * Validate nested comment thread creation under an existing thread in a discussion board post.
 *
 * This test ensures that:
 * 1. A member can be registered for thread creation.
 * 2. A discussion board post can be created (requires board_id and author_id).
 * 3. A root comment thread (depth 0, no parent) can be created for the post.
 * 4. A nested (child) thread can be created by specifying the parent thread's ID and incrementing the depth to 1.
 * 5. The system correctly links the nested thread to its parent and enforces parent-child depth logic according to business rules.
 *
 * Test Steps:
 * 1. Register a discussion board member with unique username and email.
 * 2. Create a post in a discussion board, referencing the newly registered member.
 * 3. Create a root comment thread with post_id, no parent_thread_id, and depth 0.
 * 4. Create a nested child thread by supplying the root thread's ID as parent_thread_id and depth 1.
 * 5. Validate the response: The child thread's parent_thread_id must match the root's ID, the depth must be exactly 1, the post_id must match the original post, and all threads must have valid structure as per IDiscussionBoardCommentThread. Optionally, check that depth increments no more than business maximum (if specified).
 */
export async function test_api_discussionBoard_test_create_nested_comment_thread_under_existing_thread(connection: api.IConnection) {
  // 1. Register a new member
  const username = RandomGenerator.alphaNumeric(8);
  const email = typia.random<string & tags.Format<"email">>();
  const display_name = RandomGenerator.name();
  const password = "Password123!";
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username,
      email,
      display_name,
      password,
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(member);

  // 2. Create a new post
  // In absence of a board creation API, assume a pre-existing board_id
  const board_id = typia.random<string & tags.Format<"uuid">>();
  const post_title = RandomGenerator.paragraph()();
  const post_body = RandomGenerator.content()()();
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id,
      author_id: member.id,
      title: post_title,
      body: post_body,
    } satisfies IDiscussionBoardPost.ICreate
  });
  typia.assert(post);

  // 3. Create root comment thread (depth 0, no parent)
  const rootThread = await api.functional.discussionBoard.commentThreads.post(connection, {
    body: {
      post_id: post.id,
      parent_thread_id: null,
      depth: 0,
    } satisfies IDiscussionBoardCommentThread.ICreate
  });
  typia.assert(rootThread);
  TestValidator.equals("root thread has depth 0")(rootThread.depth)(0);
  TestValidator.equals("root thread has no parent")(rootThread.parent_thread_id)(null);

  // 4. Create child thread (depth 1, parent is root thread)
  const childThread = await api.functional.discussionBoard.commentThreads.post(connection, {
    body: {
      post_id: post.id,
      parent_thread_id: rootThread.id,
      depth: 1,
    } satisfies IDiscussionBoardCommentThread.ICreate
  });
  typia.assert(childThread);
  TestValidator.equals("child thread links to parent")(childThread.parent_thread_id)(rootThread.id);
  TestValidator.equals("child thread has depth 1")(childThread.depth)(1);
  TestValidator.equals("child thread's post_id matches")(childThread.post_id)(post.id);

  // (Optionally test for max-depth enforcement -- unavailable unless configured elsewhere)
}

