import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated listing of discussion board posts with basic filtering.
 *
 * Business context:
 * This tests the main entry point for post discovery in a discussion board platform. All members can fetch paginated lists of posts, with or without query filters. The platform must return correct pagination metadata, post summaries, and handle empty board results gracefully.
 *
 * Test Steps:
 * 1. Register a member (for authentication & authorship)
 * 2. Create a discussion board
 * 3. Fetch posts with PATCH /discussionBoard/posts for the new (empty) board — expect empty results and correct pagination metadata.
 * 4. Create multiple posts on the board by that member
 * 5. List posts with PATCH /discussionBoard/posts using the board ID (no filters) and validate:
 *    - Correct number of posts is returned (matching what was created)
 *    - Pagination metadata matches expectations (current page, limit, total records)
 *    - Each listed post matches the board and contains essential summary fields
 *    - No duplicates, ordering is consistent
 * 6. Fetch another page (if possible)
 * 7. Validate empty page results/pagination when page is out-of-bounds.
 */
export async function test_api_discussionBoard_test_list_posts_with_basic_pagination(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "Password123*"
  };
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Create a discussion board
  const boardInput: IDiscussionBoardBoard.ICreate = {
    title: RandomGenerator.paragraph()(1),
    slug: RandomGenerator.alphaNumeric(8),
    description: RandomGenerator.paragraph()(),
  };
  const board = await api.functional.discussionBoard.boards.post(connection, {
    body: boardInput,
  });
  typia.assert(board);

  // 3. Fetch posts for new empty board
  let pageResp = await api.functional.discussionBoard.posts.patch(connection, {
    body: { board_id: board.id } satisfies IDiscussionBoardPost.IRequest,
  });
  typia.assert(pageResp);
  TestValidator.equals("empty page data")(pageResp.data.length)(0);
  TestValidator.equals("empty board pagination total records")(pageResp.pagination.records)(0);

  // 4. Create multiple posts as this member on this board
  const NUM_POSTS = 7;
  const createdPosts: IDiscussionBoardPost[] = [];
  for (let i = 0; i < NUM_POSTS; ++i) {
    const postInput: IDiscussionBoardPost.ICreate = {
      board_id: board.id,
      author_id: member.id,
      title: `Test Post ${i+1}`,
      body: RandomGenerator.content()()(),
    };
    const post = await api.functional.discussionBoard.posts.post(connection, {
      body: postInput,
    });
    typia.assert(post);
    createdPosts.push(post);
  }

  // 5. List first page (default paging) for board
  pageResp = await api.functional.discussionBoard.posts.patch(connection, {
    body: { board_id: board.id } satisfies IDiscussionBoardPost.IRequest,
  });
  typia.assert(pageResp);
  TestValidator.equals("number of posts")(pageResp.data.length)(NUM_POSTS);
  TestValidator.equals("pagination records matches")(pageResp.pagination.records)(NUM_POSTS);
  TestValidator.equals("correct page")(pageResp.pagination.current)(1);
  // Validate post summaries, each belongs to the board & has basic fields
  for (const row of pageResp.data) {
    TestValidator.equals("board_id matches")(row.board_id)(board.id);
    TestValidator.predicate("ID non-empty string")(!!row.id && typeof row.id === "string");
    TestValidator.predicate("title non-empty")(!!row.title && typeof row.title === "string");
    TestValidator.predicate("author_id exists")(!!row.author_id && typeof row.author_id === "string");
    TestValidator.equals("not deleted")(row.deleted_at)(null);
  }
  // Validate no duplicates
  const uniqueIDs = new Set(pageResp.data.map(r => r.id));
  TestValidator.equals("no duplicate post IDs")(uniqueIDs.size)(pageResp.data.length);

  // 6. (optional) Validate that out-of-bounds page returns empty data
  const outOfBoundsPage = Math.ceil(NUM_POSTS/2) + 10;
  const emptyPageResp = await api.functional.discussionBoard.posts.patch(connection, {
    body: { board_id: board.id, page: outOfBoundsPage } satisfies IDiscussionBoardPost.IRequest,
  });
  typia.assert(emptyPageResp);
  TestValidator.equals("empty data for out-of-bounds page")(emptyPageResp.data.length)(0);
}

