 * 4. Compare all fields between creation and retrieval, ensuring full fidelity and presence of audit/cross-reference fields
 * 5. Confirm that actor/member/content/audit fields are present and valid.
 *
 * Business Context:
 * - Moderators or admins can perform actions (such as warning, editing, or banning members or content), which are tracked for compliance and audit trail purposes.
 * - The endpoint ensures that an authorized user can retrieve a full record for appeals and dispute investigation scenarios.
 */
export async function test_api_discussionBoard_test_get_moderation_action_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a new moderation action (simulate moderator or admin action)
  const createInput: IDiscussionBoardModerationAction.ICreate = {
    affected_member_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "warn",
    action_reason: "Inappropriate language in comment.",
    action_note: "Test note for audit.",
    // Optionally assign as moderator or admin. Here, assign moderator.
    moderator_id: typia.random<string & tags.Format<"uuid">>(),
    // Optionally target a post or comment; here, target a comment.
    target_comment_id: typia.random<string & tags.Format<"uuid">>(),
    target_post_id: null,
    admin_id: null,
  };
  const created = await api.functional.discussionBoard.moderationActions.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Fetch moderation action by its ID
  const fetched = await api.functional.discussionBoard.moderationActions.getById(connection, {
    id: created.id,
  });
  typia.assert(fetched);

  // 3. Validate fetched record matches the created one (field-by-field, w/ audit fields)
  TestValidator.equals("moderation action id")(fetched.id)(created.id);
  TestValidator.equals("actor moderator id")(fetched.moderator_id)(createInput.moderator_id);
  TestValidator.equals("actor admin id")(fetched.admin_id)(createInput.admin_id ?? null);
  TestValidator.equals("affected member id")(fetched.affected_member_id)(createInput.affected_member_id);
  TestValidator.equals("action type")(fetched.action_type)(createInput.action_type);
  TestValidator.equals("reason")(fetched.action_reason)(createInput.action_reason);
  TestValidator.equals("note")(fetched.action_note)(createInput.action_note ?? null);
  TestValidator.equals("target post id")(fetched.target_post_id)(createInput.target_post_id ?? null);
  TestValidator.equals("target comment id")(fetched.target_comment_id)(createInput.target_comment_id ?? null);
  // 4. Audit: created_at is present and ISO string
  TestValidator.predicate("created_at present and ISO format")(!!fetched.created_at && !isNaN(Date.parse(fetched.created_at)));
}

