/**
 * Validate updating selected attributes of an existing discussion board channel as an admin user.
 *
 * This test simulates a real-world scenario where an admin user updates the name and description of a discussion board channel. It covers business rules such as uniqueness of the channel name, correct handling of optional and null fields, and platform audit requirements that every update is logged. It also verifies the API response returns the updated channel entity, and normalization/validation constraints are respected.
 *
 * Step-by-step process:
 * 1. Create an initial channel with a random (unique) name and nullable description.
 * 2. Modify both the name and description of the channel to new, valid values. Confirm a successful update and audit compliance by checking that timestamps change and the new values appear in the response.
 * 3. Attempt to update the channel to a name already in use (by another channel) and confirm the update fails due to unique name constraint.
 * 4. Update the channel using values with leading/trailing spaces (to check normalization acceptance).
 * 5. Update only one field (partial update where other values remain unchanged).
 * 6. Update with explicit nulls for optional properties and confirm semantics (should skip update if null, per patch convention).
 * 7. Confirm the update response contains the updated entity, with correct fields and timestamps.
 * 8. Negative scenario: try update with invalid UUID and confirm error.
 */
export async function test_api_discussionBoard_test_update_channel_attributes_success_by_admin(connection: api.IConnection) {
  // 1. Create an initial channel (dependency)
  const initialChannel = await api.functional.discussionBoard.channels.post(connection, {
    body: {
      name: `Channel_${RandomGenerator.alphabets(10)}`,
      description: "Initial description for e2e test channel",
    },
  });
  typia.assert(initialChannel);

  // 2. Create a second channel for name conflict testing
  const otherChannel = await api.functional.discussionBoard.channels.post(connection, {
    body: {
      name: `Another_${RandomGenerator.alphabets(10)}`,
      description: "Other channel for conflict test",
    },
  });
  typia.assert(otherChannel);

  // 3. Update name & description to new valid values
  const updatedName = `Updated_${RandomGenerator.alphaNumeric(8)}`;
  const updatedDescription = "Updated channel description.";
  const updateRes = await api.functional.discussionBoard.channels.putById(connection, {
    id: initialChannel.id,
    body: {
      name: updatedName,
      description: updatedDescription,
    },
  });
  typia.assert(updateRes);
  TestValidator.equals("name updated")(updateRes.name)(updatedName);
  TestValidator.equals("description updated")(updateRes.description)(updatedDescription);
  TestValidator.notEquals("updated_at changed after update")(updateRes.updated_at)(initialChannel.updated_at);

  // 4. Attempt update with duplicate name (should fail)
  await TestValidator.error("unique name constraint enforced")(async () => {
    await api.functional.discussionBoard.channels.putById(connection, {
      id: initialChannel.id,
      body: {
        name: otherChannel.name,
      },
    });
  });

  // 5. Update with normalization checks (spaces in fields)
  const spacedName = `  ${RandomGenerator.alphaNumeric(6)}  `;
  const spacedDesc = `   ${RandomGenerator.paragraph()(1)}   `;
  const normalizationRes = await api.functional.discussionBoard.channels.putById(connection, {
    id: initialChannel.id,
    body: {
      name: spacedName,
      description: spacedDesc,
    },
  });
