 * 1. Create diverse moderation appeals across different moderation_action_ids, member_ids, statuses, and dates.
 * 2. Perform listing via PATCH endpoint for scenarios:
 *    a. Filter by moderation_action_id and verify all results match
 *    b. Filter by appeal_status and verify
 *    c. Filter by date range (created_at_from, created_at_to)
 *    d. Combine filters (multi-field, e.g., action+status+date)
 *    e. Use pagination (page, limit) – check paging metadata and order
 * 3. Test invalid filter parameters (e.g., negative page, bad uuid) and confirm error responses
 */
export async function test_api_discussionBoard_moderationAppeals_test_list_moderation_appeals_as_admin_with_pagination_and_filters(
  connection: api.IConnection,
) {
  // Step 1: Create diverse moderation appeals
  const NUM_ACTIONS = 3;
  const NUM_MEMBERS = 3;
  const NUM_STATUSES = 3;
  const appeal_statuses = [
    "pending",
    "under_review",
    "decided",
    // plus additional custom test statuses if relevant
  ];
  // Generate distinct action IDs, member IDs
  const moderation_action_ids = ArrayUtil.repeat(NUM_ACTIONS)(() => typia.random<string & tags.Format<"uuid">>());
  const member_ids = ArrayUtil.repeat(NUM_MEMBERS)(() => typia.random<string & tags.Format<"uuid">>());

  const created_appeals: IDiscussionBoardModerationAppeal[] = [];
  for (let i = 0; i < NUM_ACTIONS * NUM_MEMBERS * NUM_STATUSES; ++i) {
    const moderation_action_id = moderation_action_ids[i % NUM_ACTIONS];
    const member_id = member_ids[Math.floor(i / NUM_ACTIONS) % NUM_MEMBERS];
    const appeal_status = appeal_statuses[i % NUM_STATUSES];
    // Vary created_at for date-range testing
    const now = new Date();
    const created_at = new Date(now.getTime() - i * 1000 * 60 * 60 * 24).toISOString();
    const result = await api.functional.discussionBoard.moderationAppeals.post(
      connection,
      {
        body: {
          moderation_action_id,
          member_id,
          appeal_reason: RandomGenerator.paragraph()(),
        } satisfies IDiscussionBoardModerationAppeal.ICreate,
      },
    );
    typia.assert(result);
    // Patch status and created_at using manual assignment since API does not support direct set (for testing, assume direct object manipulation or skip further mutation if not allowed)
    created_appeals.push({
      ...result,
      appeal_status,
      created_at,
      last_updated_at: created_at,
    });
  }

  // Helper for PATCH: invoke, assert response page, return appeal list
  async function fetchAppeals(body: IDiscussionBoardModerationAppeal.IRequest) {
    const output = await api.functional.discussionBoard.moderationAppeals.patch(connection, { body });
    typia.assert(output);
    return output;
  }

  // 2a. Filter by moderation_action_id
  {
    const action_id = moderation_action_ids[0];
    const output = await fetchAppeals({ moderation_action_id: action_id });
    for (const appeal of output.data) {
      TestValidator.equals("filter by moderation_action_id")(appeal.moderation_action_id)(action_id);
    }
  }

  // 2b. Filter by appeal_status
  {
    const status = appeal_statuses[1];
    const output = await fetchAppeals({ appeal_status: status });
    for (const appeal of output.data) {
      TestValidator.equals("filter by appeal_status")(appeal.appeal_status)(status);
    }
  }

  // 2c. Filter by date range
  {
    const fromIdx = 2;
    const toIdx = 5;
    const created_at_from = created_appeals[fromIdx].created_at;
    const created_at_to = created_appeals[toIdx].created_at;
    const output = await fetchAppeals({ created_at_from, created_at_to });
    for (const appeal of output.data) {
      TestValidator.predicate("appeal.created_at >= from")(
        new Date(appeal.created_at).getTime() >= new Date(created_at_from).getTime(),
      );
      TestValidator.predicate("appeal.created_at <= to")(
        new Date(appeal.created_at).getTime() <= new Date(created_at_to).getTime(),
      );
    }
  }

  // 2d. Combine filters (action + status + date)
  {
    const action_id = moderation_action_ids[1];
    const status = appeal_statuses[2];
    const created_at_from = created_appeals[0].created_at;
    const created_at_to = created_appeals[created_appeals.length - 1].created_at;
    const body: IDiscussionBoardModerationAppeal.IRequest = {
      moderation_action_id: action_id,
      appeal_status: status,
      created_at_from,
      created_at_to,
    };
    const output = await fetchAppeals(body);
    for (const appeal of output.data) {
      TestValidator.equals("action filter")(appeal.moderation_action_id)(action_id);
      TestValidator.equals("status filter")(appeal.appeal_status)(status);
      TestValidator.predicate("date >= from")(
        new Date(appeal.created_at).getTime() >= new Date(created_at_from).getTime(),
      );
      TestValidator.predicate("date <= to")(
        new Date(appeal.created_at).getTime() <= new Date(created_at_to).getTime(),
      );
    }
  }

  // 2e. Pagination check
  {
    const limit = 2;
    const page = 2;
    const output = await fetchAppeals({ limit, page });
    TestValidator.equals("pagination.limit")(output.pagination.limit)(limit);
    TestValidator.equals("pagination.current")(output.pagination.current)(page);
    TestValidator.predicate("page result data count")(
      output.data.length <= limit,
    );
  }

  // 3. Error handling
  // 3a. Invalid UUID
  await TestValidator.error("invalid moderation_action_id uuid")(() =>
    fetchAppeals({ moderation_action_id: "not-a-uuid" as any }),
  );
  // 3b. Negative page number
  await TestValidator.error("negative page number")(() =>
    fetchAppeals({ page: -1 as any }),
  );
  // 3c. Excessively large limit
  await TestValidator.error("excess limit")(() =>
    fetchAppeals({ limit: 1_000_000 }),
  );
}

