import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostReaction";

/**
 * Validate creation of discussion board post reactions with both valid and invalid data.
 *
 * This function verifies the business rules and error handling for creating post reactions (like/dislike) in the discussion board.
 *
 * 1. Create a discussion board member (the reacting user)
 * 2. Create a post for the member to react to
 * 3. Successfully create a 'like' post reaction for that member and post
 *    - Check all fields in the returned reaction object
 * 4. Attempt to create a second, duplicate reaction of the same type by the same member for the same post
 *    - Validate enforcement of unique user/post reaction constraint (expect error)
 * 5. Try reaction creation with an invalid reaction_type (not allowed string)
 *    - Expect error for reaction type validation
 * 6. Try reaction creation referencing a non-existent post (random UUID)
 *    - Expect error (not found)
 * 7. Try reaction creation referencing a non-existent member (random UUID)
 *    - Expect error (not found)
 * 8. Try to create a reaction without required fields (e.g., missing reaction_type)
 *    - Expect error (missing field)
 * 9. Try to create a reaction as an unauthenticated (simulated) user (simulate by omitting member reference)
 *    - Expect authentication/authorization error
 */
export async function test_api_discussionBoard_test_create_post_reaction_with_valid_and_invalid_data(connection: api.IConnection) {
  // 1. Create a discussion board member
  const memberReq: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: RandomGenerator.alphabets(10),
  };
  const member = await api.functional.discussionBoard.members.post(connection, { body: memberReq });
  typia.assert(member);

  // 2. Create a post to react to
  const postReq: IDiscussionBoardPost.ICreate = {
    board_id: typia.random<string & tags.Format<"uuid">>(), // Assume board exists or use fixed test board id
    author_id: member.id,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
  };
  const post = await api.functional.discussionBoard.posts.post(connection, { body: postReq });
  typia.assert(post);

  // 3. Successfully create a valid post reaction (like)
  const reactionReq: IDiscussionBoardPostReaction.ICreate = {
    discussionboard_member_id: member.id,
    discussionboard_post_id: post.id,
    reaction_type: "like",
  };
  const reaction = await api.functional.discussionBoard.postReactions.post(connection, { body: reactionReq });
  typia.assert(reaction);
  TestValidator.equals("reaction member")(reaction.discussionboard_member_id)(member.id);
  TestValidator.equals("reaction post")(reaction.discussionboard_post_id)(post.id);
  TestValidator.equals("reaction type")(reaction.reaction_type)("like");

  // 4. Attempt duplicate reaction by same user on same post
  await TestValidator.error("duplicate reaction should fail")(async () => {
    await api.functional.discussionBoard.postReactions.post(connection, { body: reactionReq });
  });

  // 5. Attempt with invalid reaction_type
  const invalidTypeReq = { ...reactionReq, reaction_type: "love" };
  await TestValidator.error("invalid reaction type should fail")(async () => {
    await api.functional.discussionBoard.postReactions.post(connection, { body: invalidTypeReq });
  });

  // 6. Non-existent post reference
  const notFoundPostReq = { ...reactionReq, discussionboard_post_id: typia.random<string & tags.Format<"uuid">>() };
  await TestValidator.error("nonexistent post should fail")(async () => {
    await api.functional.discussionBoard.postReactions.post(connection, { body: notFoundPostReq });
  });

  // 7. Non-existent member reference
  const notFoundMemberReq = { ...reactionReq, discussionboard_member_id: typia.random<string & tags.Format<"uuid">>() };
  await TestValidator.error("nonexistent member should fail")(async () => {
    await api.functional.discussionBoard.postReactions.post(connection, { body: notFoundMemberReq });
  });

  // 8. Missing required field (reaction_type)
  const { reaction_type, ...missingTypeReq } = reactionReq;
  await TestValidator.error("missing reaction_type should fail")(async () => {
    await api.functional.discussionBoard.postReactions.post(connection, { body: missingTypeReq as any }); // as any only in error test context
  });

  // 9. Unauthorized/Unauthenticated: Try omitting valid member, e.g. by using random UUID
  const fakeMemberReq = { ...reactionReq, discussionboard_member_id: typia.random<string & tags.Format<"uuid">>() };
  await TestValidator.error("unauthorized reaction should fail")(async () => {
    await api.functional.discussionBoard.postReactions.post(connection, { body: fakeMemberReq });
  });
}

