/**
 * Test updating an existing admin assignment record and permission enforcement.
 *
 * Scenario:
 * 1. Create a member who will be promoted to admin (to serve as the subject of the update).
 * 2. Create a second member who will serve as the "appointing admin" (to be set/changed via update).
 * 3. Assign admin status to the first member by having the second member (the admin) perform the appointment, creating an initial admin assignment record.
 * 4. Update the admin assignment:
 *    a. Change the appointing admin (appointed_by_admin_id) to a new admin member.
 *    b. Set or update revoked_at timestamp to simulate demotion.
 *    c. Confirm fields are updated in returned object and properly reflected for audit purposes.
 * 5. Confirm that audit trail fields (appointed_at, revoked_at, appointed_by_admin_id) match expectation after update.
 * 6. Negative cases:
 *    a. Attempt to update with a random non-existent ID (expect not found error).
 *    b. Attempt to update a record (simulate if possible) with a soft-deleted ID if supported (expect error or no effect).
 *    c. Try to set appointed_by_admin_id to a member with no admin rights (should be denied).
 *    d. Try to perform the update as a non-admin user (should be denied/forbidden).
 * 7. Validate that business constraints and error handling are strictly enforced.
 */
export async function test_api_discussionBoard_test_update_admin_assignment_and_permission_enforcement(connection: api.IConnection) {
  // 1. Create initial member (future admin)
  const subjectMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    }
  });
