import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerationAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAppeal";
import type { DiscussionBoardAppealDecision } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAppealDecision";
import type { PageDiscussionBoardAppealDecision } from "@ORGANIZATION/PROJECT-api/lib/structures/PageDiscussionBoardAppealDecision";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test: List appeal decisions with filter, pagination, and authorization controls.
 *
 * 1. Prepare appeals: Create multiple moderation appeals with unique actions and member IDs
 * 2. Prepare decisions: For each appeal, create corresponding appeal decisions; vary moderators/admins and outcomes
 * 3. Filter tests:
 *   a. Query by each unique outcome (decision_outcome) and assert correct filtering
 *   b. Query using moderator_id/admin_id and assert only their relevant decisions returned
 *   c. Query by single appeal_id and check correct linkage
 *   d. Use date filters (created_after, created_before) and check boundaries
 * 4. Pagination tests:
 *   a. Query with small limit, multiple pages, assert result counts and non-overlap
 *   b. Query out-of-bounds page, assert empty result
 * 5. Edge/negative tests:
 *   a. Filtering with non-existent values (UUIDs/outcomes) must return empty result list
 *   b. Submit malformed parameters (wrong types, missing required fields) and confirm error response
 * 6. Authorization:
 *   a. As moderator/admin: access is allowed
 *   b. As normal member: access must be denied (simulate by using their connection)
 */
export async function test_api_discussionBoard_test_list_appeal_decisions_with_various_filters_and_paginations(
  connection: api.IConnection,
) {
  // Preparation: create several appeals/actions/users (faked here as prereqs skipped)

  // 1. Create appeals
  const appeals = await ArrayUtil.asyncRepeat(3)(async () => {
    const appeal = await api.functional.discussionBoard.moderationAppeals.post(connection, {
      body: {
        moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
        member_id: typia.random<string & tags.Format<"uuid">>(),
        appeal_reason: RandomGenerator.paragraph()(),
      },
    });
    typia.assert(appeal);
    return appeal;
  });

  // 2. Create decisions for the appeals with varying actors and outcomes
  const outcomes = ["upheld", "overturned", "modified"];
  const moderator_id = typia.random<string & tags.Format<"uuid">>();
  const admin_id = typia.random<string & tags.Format<"uuid">>();

  const decisions = await ArrayUtil.asyncMap(appeals)(async (appeal, i) => {
    const outcome = outcomes[i % outcomes.length];
    const actorId = i % 2 === 0 ? { moderator_id } : { admin_id };
    const decision = await api.functional.discussionBoard.appealDecisions.post(connection, {
      body: {
        appeal_id: appeal.id,
        ...actorId,
        decision_outcome: outcome,
        decision_rationale: RandomGenerator.paragraph()(),
      },
    });
    typia.assert(decision);
    return decision;
  });

  // 3a. Filter: decision_outcome
  for (const outcome of outcomes) {
    const filtered = await api.functional.discussionBoard.appealDecisions.patch(connection, {
      body: { decision_outcome: outcome },
    });
    typia.assert(filtered);
    TestValidator.predicate(`all outcome filtered decisions === '${outcome}'`)(
      filtered.data.every((d) => d.decision_outcome === outcome),
    );
  }

  // 3b. Filter: moderator_id/admin_id
  {
    const modList = await api.functional.discussionBoard.appealDecisions.patch(connection, { body: { moderator_id } });
    typia.assert(modList);
    TestValidator.predicate("all filtered by moderator_id")(
      modList.data.every((d) => d.moderator_id === moderator_id),
    );
    const admList = await api.functional.discussionBoard.appealDecisions.patch(connection, { body: { admin_id } });
    typia.assert(admList);
    TestValidator.predicate("all filtered by admin_id")(
      admList.data.every((d) => d.admin_id === admin_id),
    );
  }

  // 3c. Filter: appeal_id
  for (const appeal of appeals) {
    const byAppeal = await api.functional.discussionBoard.appealDecisions.patch(connection, {
      body: { appeal_id: appeal.id },
    });
    typia.assert(byAppeal);
    TestValidator.predicate("appeal_id matches")(
      byAppeal.data.every((d) => d.appeal_id === appeal.id),
    );
  }

  // 3d. Date filter: created_after, created_before
  {
    const [decision] = decisions;
    const after = await api.functional.discussionBoard.appealDecisions.patch(connection, {
      body: { created_after: decision.created_at },
    });
    typia.assert(after);
    TestValidator.predicate("all decisions after created_at")(
      after.data.every((d) => new Date(d.created_at) > new Date(decision.created_at)),
    );
    const before = await api.functional.discussionBoard.appealDecisions.patch(connection, {
      body: { created_before: decision.created_at },
    });
    typia.assert(before);
    TestValidator.predicate("all decisions before created_at")(
      before.data.every((d) => new Date(d.created_at) < new Date(decision.created_at)),
    );
  }

  // 4a. Pagination: limit, multiple pages, no overlap
  {
    const limit = 1;
    const firstPage = await api.functional.discussionBoard.appealDecisions.patch(connection, { body: { limit, page: 0 } });
    const secondPage = await api.functional.discussionBoard.appealDecisions.patch(connection, { body: { limit, page: 1 } });
    typia.assert(firstPage);
    typia.assert(secondPage);
    TestValidator.notEquals("paged lists not same")(
      firstPage.data[0]?.id,
    )(secondPage.data[0]?.id);
  }

  // 4b. Out-of-bounds: high page index gives empty data
  {
    const oob = await api.functional.discussionBoard.appealDecisions.patch(connection, { body: { page: 1000, limit: 1 } });
    typia.assert(oob);
    TestValidator.equals("out-of-bounds page empty")(
      oob.data.length,
    )(0);
  }

  // 5a. Filtering with non-existent UUID/outcome
  {
    const emptyByUUID = await api.functional.discussionBoard.appealDecisions.patch(connection, { body: { appeal_id: typia.random<string & tags.Format<"uuid">>() } });
    typia.assert(emptyByUUID);
    TestValidator.equals("filter by non-existent appeal_id is empty")(
      emptyByUUID.data.length,
    )(0);
    const emptyByOutcome = await api.functional.discussionBoard.appealDecisions.patch(connection, { body: { decision_outcome: "nonexistent_outcome" } });
    typia.assert(emptyByOutcome);
    TestValidator.equals("filter by bogus outcome is empty")(
      emptyByOutcome.data.length,
    )(0);
  }

  // 5b. Malformed parameter (page as string) triggers error
  await TestValidator.error("malformed parameter type throws error")(
    async () => {
      await api.functional.discussionBoard.appealDecisions.patch(connection, { body: { page: "bad_string" as any } });
    }
  );

  // 6. Authorization: test with unauthorized user (simulate member, should fail)
  // (Skipped: concrete member connection switch not implemented here, as user auth mechanisms not provided)
}

