/**
 * Test updating an existing post edit record, including permissions and validation.
 *
 * This test verifies several scenarios for updating a post edit record in the Discussion Board platform:
 * 1. The original editor successfully updates the edit summary field of their own post edit (happy path).
 * 2. A second, unauthorized user attempts to update another user's post edit, which must be rejected (permission check).
 * 3. Validation: attempts to update the edit summary to an empty string or a string exceeding policy-imposed maximum length.
 * 4. Only allowed fields may change (edit_summary, body_after_edit); IDs, timestamps, and relationships must be preserved.
 * 5. After successful valid update, audit trails (created_at, editor_id, post_id) remain immutable, only allowed fields update.
 *
 * Steps:
 * 1. Register two discussion board members (one will be original editor, another is an unauthorized actor).
 * 2. Create a discussion board.
 * 3. Create a discussion post in that board, authored by the first member.
 * 4. Create a post edit record for that post, by the first member.
 * 5. The original editor updates their post edit's summary (success, verify output changes only allowed field).
 * 6. The unauthorized member attempts to update the post edit (should be rejected/raise error).
 * 7. Attempt to update with invalid summary (empty string, exceeding max length) as original editor (should be rejected).
 */
export async function test_api_discussionBoard_test_update_post_edit_with_permissions_and_validation(
  connection: api.IConnection,
) {
  // 1. Register two discussion board members
  const member1Input = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "EditorP@ssw0rd1"
  } satisfies IDiscussionBoardMember.ICreate;
  const member1 = await api.functional.discussionBoard.members.post(connection, { body: member1Input });
  typia.assert(member1);
  // Assume simulated SSO/session or implicit context – since no login endpoint is defined, the API treats us as member1.

  const member2Input = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "NotAllowedP@ss2"
  } satisfies IDiscussionBoardMember.ICreate;
  const member2 = await api.functional.discussionBoard.members.post(connection, { body: member2Input });
  typia.assert(member2);

  // 2. Create a discussion board
  const boardInput = {
    title: RandomGenerator.paragraph()(2),
    slug: RandomGenerator.alphaNumeric(12).toLowerCase(),
    description: RandomGenerator.paragraph()(3)
  } satisfies IDiscussionBoardBoard.ICreate;
  const board = await api.functional.discussionBoard.boards.post(connection, { body: boardInput });
  typia.assert(board);

  // 3. Create a post in that board (authored by member1)
  const postInput = {
    board_id: board.id,
    author_id: member1.id,
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()()
  } satisfies IDiscussionBoardPost.ICreate;
  const post = await api.functional.discussionBoard.posts.post(connection, { body: postInput });
  typia.assert(post);

  // 4. Create a post edit record for that post, by member1
  const originalSummary = "Initial edit for typo correction";
  const postEditInput = {
    post_id: post.id,
    editor_id: member1.id,
    edit_summary: originalSummary,
    body_after_edit: RandomGenerator.content()()()
  } satisfies IDiscussionBoardPostEdit.ICreate;
  const postEdit = await api.functional.discussionBoard.postEdits.post(connection, { body: postEditInput });
  typia.assert(postEdit);

  // 5. The original editor updates their own post edit's summary (success case)
  const newSummary = "Added more clarifying details to edit summary";
  const updatedEdit = await api.functional.discussionBoard.postEdits.putById(connection, {
    id: postEdit.id,
    body: { edit_summary: newSummary } satisfies IDiscussionBoardPostEdit.IUpdate
  });
  typia.assert(updatedEdit);
  TestValidator.equals("summary updated")(updatedEdit.edit_summary)(newSummary);
  TestValidator.equals("other fields unchanged")(updatedEdit.editor_id)(postEdit.editor_id);
  TestValidator.equals("post_id unchanged")(updatedEdit.post_id)(postEdit.post_id);
  TestValidator.equals("audit immutable")(typeof updatedEdit.created_at)("string");

  // 6. Unauthorized member attempts update (should fail)
  await TestValidator.error("unauthorized actor update rejected")(async () => {
    await api.functional.discussionBoard.postEdits.putById(connection, {
      id: postEdit.id,
      body: { edit_summary: "Illicit overwrite by other user" }
    });
  });

  // 7. Validation: empty string summary (should fail for required/length constraint)
  await TestValidator.error("empty summary rejected")(async () => {
    await api.functional.discussionBoard.postEdits.putById(connection, {
      id: postEdit.id,
      body: { edit_summary: "" }
    });
  });
  // 8. Validation: excessively long summary (e.g. 500+ chars)
  await TestValidator.error("overlong summary rejected")(async () => {
    await api.functional.discussionBoard.postEdits.putById(connection, {
      id: postEdit.id,
      body: { edit_summary: RandomGenerator.alphaNumeric(600) }
    });
  });
}

