import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentReaction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageDiscussionBoardCommentReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardCommentReaction";

/**
 * E2E test for searching and paginating comment reaction records.
 *
 * This test covers all business logic outlined in the scenario:
 *  1. Create multiple members (2+).
 *  2. Create several comments (2+), each on different posts and threads.
 *  3. For each member-comment-reaction_type combination (e.g., 'like', 'dislike'), create a reaction.
 *  4. Retrieve reactions using filters:
 *     a) By comment ID (ensure only appropriate reactions are returned)
 *     b) By member ID (ensure all that member's reactions are listed)
 *     c) By reaction_type (filter by 'like', 'dislike', etc.)
 *     d) By created_after / created_before (timestamp boundaries)
 *  5. Test pagination by limiting result size and fetching certain pages.
 *  6. Soft-delete a reaction and ensure it is excluded from subsequent standard searches.
 *  7. All responses and counts are validated for accuracy.
 */
export async function test_api_discussionBoard_test_list_comment_reactions_with_filtering_and_pagination(connection: api.IConnection) {
  // 1. Create members
  const memberInputs = ArrayUtil.repeat(2)(() => ({
    username: RandomGenerator.alphaNumeric(12),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: RandomGenerator.alphaNumeric(15),
  }) satisfies IDiscussionBoardMember.ICreate);
  const members = await ArrayUtil.asyncMap(memberInputs)(async (input) => {
    const member = await api.functional.discussionBoard.members.post(connection, {
      body: input,
    });
    typia.assert(member);
    return member;
  });

  // 2. Create comments
  const commentInputs = ArrayUtil.repeat(2)(() => ({
    post_id: typia.random<string & tags.Format<"uuid">>(),
    thread_id: typia.random<string & tags.Format<"uuid">>(),
    author_id: RandomGenerator.pick(members.map((m) => m.id)),
    body: RandomGenerator.content()()(),
    depth: 0,
  }) satisfies IDiscussionBoardComment.ICreate);
  const comments = await ArrayUtil.asyncMap(commentInputs)(async (input) => {
    const comment = await api.functional.discussionBoard.comments.post(connection, {
      body: input,
    });
    typia.assert(comment);
    return comment;
  });

  // 3. Define reaction types and create reactions for all combinations
  const reactionTypes = ["like", "dislike"];
  const createdReactions: IDiscussionBoardCommentReaction[] = [];
  for (const member of members) {
    for (const comment of comments) {
      for (const reaction_type of reactionTypes) {
        const reaction = await api.functional.discussionBoard.commentReactions.post(connection, {
          body: {
            discussionboard_member_id: member.id,
            discussionboard_comment_id: comment.id,
            reaction_type,
          } satisfies IDiscussionBoardCommentReaction.ICreate,
        });
        typia.assert(reaction);
        createdReactions.push(reaction);
      }
    }
  }

  // 4a. Filter by comment ID
  for (const comment of comments) {
    const result = await api.functional.discussionBoard.commentReactions.patch(connection, {
      body: {
        discussionboard_comment_id: comment.id,
        paging: { page: 1, limit: 100 },
      } satisfies IDiscussionBoardCommentReaction.IRequest,
    });
    typia.assert(result);
    TestValidator.predicate("all reactions for this comment returned")(result.data.every((r) => r.discussionboard_comment_id === comment.id));
  }

  // 4b. Filter by member ID
  for (const member of members) {
    const result = await api.functional.discussionBoard.commentReactions.patch(connection, {
      body: {
        discussionboard_member_id: member.id,
        paging: { page: 1, limit: 100 },
      } satisfies IDiscussionBoardCommentReaction.IRequest,
    });
    typia.assert(result);
    TestValidator.predicate("all reactions for this member returned")(result.data.every((r) => r.discussionboard_member_id === member.id));
  }

  // 4c. Filter by reaction_type
  for (const reaction_type of reactionTypes) {
    const result = await api.functional.discussionBoard.commentReactions.patch(connection, {
      body: {
        reaction_type,
        paging: { page: 1, limit: 100 },
      } satisfies IDiscussionBoardCommentReaction.IRequest,
    });
    typia.assert(result);
    TestValidator.predicate("all reactions have correct type")(result.data.every((r) => r.reaction_type === reaction_type));
  }

  // 4d. Filter by created_after/created_before
  // Pick a known start/end timestamp for one of the reactions
  const firstReaction = createdReactions[0];
  const after = firstReaction.created_at;

  const afterResults = await api.functional.discussionBoard.commentReactions.patch(connection, {
    body: { created_after: after, paging: { page: 1, limit: 100 } },
  });
  typia.assert(afterResults);
  TestValidator.predicate("all after results >= start")(afterResults.data.every((r) => r.created_at >= after));

  const before = createdReactions[createdReactions.length - 1].created_at;
  const beforeResults = await api.functional.discussionBoard.commentReactions.patch(connection, {
    body: { created_before: before, paging: { page: 1, limit: 100 } },
  });
  typia.assert(beforeResults);
  TestValidator.predicate("all before results < end")(beforeResults.data.every((r) => r.created_at < before));

  // 5. Test pagination: fetch first page of reactions (limit 2)
  const pagedResult = await api.functional.discussionBoard.commentReactions.patch(connection, {
