 *    d. member_id — only assignments for that member.
 *    e. appointed_by_admin_id — only assignments made by root admin.
 *    f. appointed_from / appointed_to — filter by date range.
 *    g. Combination queries (e.g. status+date/member_id+status).
 *    h. Pagination checks: request limit=1/page=2/etc. Validate pagination meta (current, limit, records, pages).
 *    i. Out-of-bounds page (page > last) — returns empty list with valid metadata.
 * 5. Send an invalid filter (e.g., status=invalid or broken date) and assert error.
 */
export async function test_api_discussionBoard_test_list_admin_assignments_with_full_pagination_and_filters(
  connection: api.IConnection,
) {
  // 1. Register three members eligible for admin assignment
  const memberInputs = ArrayUtil.repeat(3)(() => ({
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: RandomGenerator.alphaNumeric(12) as string & tags.Format<"password">,
  }));
  const members = await ArrayUtil.asyncMap(memberInputs)(async body => {
    const member = await api.functional.discussionBoard.members.post(connection, {body});
    typia.assert(member);
    return member;
  });

  // 2. Promote member[0] as the "root" admin (appointed_by_admin_id is null/self)
  const rootAdmin = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: members[0].id,
      appointed_by_admin_id: members[0].id, // or null if allowed by business, using self-appoint as root
    },
  });
  typia.assert(rootAdmin);

  // 3. Promote the next two members to admin via the root admin; revoke one.
  // Assign member[1] as admin
  const admin1 = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: members[1].id,
      appointed_by_admin_id: rootAdmin.member_id,
    },
  });
  typia.assert(admin1);

  // Assign member[2] as admin
  const admin2 = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: members[2].id,
      appointed_by_admin_id: rootAdmin.member_id,
    },
  });
  typia.assert(admin2);

  // "Revoke" admin1 by simulating revocation (cannot do via provided API, so set status by manipulating the assigned_at and revoked_at for test filtering)
  // As we lack a revoke endpoint, only simulate by filter

  // 4a. No filter (all assignments)
  let pageAll = await api.functional.discussionBoard.admins.patch(connection, {body: {}});
  typia.assert(pageAll);
  TestValidator.predicate("all admins present")(
    pageAll.data.some(x => x.id === rootAdmin.id)
     && pageAll.data.some(x => x.id === admin1.id)
     && pageAll.data.some(x => x.id === admin2.id)
  );
  TestValidator.equals("pagination: all current page")(
    pageAll.pagination.current
  )(1);
  TestValidator.predicate("pagination meta valid")(
    pageAll.pagination.limit >= 1 && pageAll.pagination.pages >= 1 && pageAll.pagination.records >= 3
  );

  // 4b. status="active": active assignments are those with revoked_at==null
  let pageActive = await api.functional.discussionBoard.admins.patch(connection, {body: {status: "active"}});
  typia.assert(pageActive);
  TestValidator.predicate("all status active are non-revoked")(
    pageActive.data.every(x => x.revoked_at == null)
  );

  // 4c. status="revoked": only those with revoked_at != null
  let pageRevoked = await api.functional.discussionBoard.admins.patch(connection, {body: {status: "revoked"}});
  typia.assert(pageRevoked);
  TestValidator.predicate("all status revoked have revoked_at")(
    pageRevoked.data.every(x => x.revoked_at != null)
  );

  // 4d. member_id filter: should only match assignments belonging to a specific member
  let pageByMember = await api.functional.discussionBoard.admins.patch(connection, {body: {member_id: admin1.member_id}});
  typia.assert(pageByMember);
  TestValidator.predicate("by member_id filter")(
    pageByMember.data.every(x => x.member_id === admin1.member_id)
  );

  // 4e. appointed_by_admin_id filter
  let pageByAppointer = await api.functional.discussionBoard.admins.patch(connection, {body: {appointed_by_admin_id: rootAdmin.member_id}});
  typia.assert(pageByAppointer);
  TestValidator.predicate("by appointed_by_admin_id filter")(
    pageByAppointer.data.every(x => x.appointed_by_admin_id === rootAdmin.member_id)
  );

  // 4f. appointed_from/appointed_to: use admin2's appointed_at for window
  let pageByAppointedFrom = await api.functional.discussionBoard.admins.patch(connection, {body: {appointed_from: admin2.appointed_at}});
  typia.assert(pageByAppointedFrom);
  TestValidator.predicate("appointed_from filter")(
    pageByAppointedFrom.data.every(x => x.appointed_at >= admin2.appointed_at)
  );

  let pageByAppointedTo = await api.functional.discussionBoard.admins.patch(connection, {body: {appointed_to: admin2.appointed_at}});
  typia.assert(pageByAppointedTo);
  TestValidator.predicate("appointed_to filter")(
    pageByAppointedTo.data.every(x => x.appointed_at <= admin2.appointed_at)
  );

  // 4g. Combination filters: status+appointed_by_admin_id
  let pageCombo = await api.functional.discussionBoard.admins.patch(connection, {body: {appointed_by_admin_id: rootAdmin.member_id, status: "active"}});
  typia.assert(pageCombo);
  TestValidator.predicate("combo filter active by root")(
    pageCombo.data.every(x => x.appointed_by_admin_id === rootAdmin.member_id && x.revoked_at == null)
  );

  // 4h. Pagination: limit=1
  let pageLimited = await api.functional.discussionBoard.admins.patch(connection, {body: {limit: 1, page: 2}});
  typia.assert(pageLimited);
  TestValidator.equals("pagination limit")(
    pageLimited.pagination.limit
  )(1);
  TestValidator.equals("pagination page")(
    pageLimited.pagination.current
  )(2);
  if (pageLimited.pagination.pages > 1) {
    TestValidator.predicate("pagination second page has results/list empty")(
      Array.isArray(pageLimited.data)
    );
  }

  // 4i. Out-of-bounds page: page > last
  let pageOob = await api.functional.discussionBoard.admins.patch(connection, {body: {limit: 1, page: 100}});
  typia.assert(pageOob);
  TestValidator.equals("pagination out of bounds is empty")(
    pageOob.data.length
  )(0);

  // 5. Invalid filter value: status="invalid"
  await TestValidator.error("invalid status")(() =>
    api.functional.discussionBoard.admins.patch(connection, {body: {status: "invalid" as any}})
  );
}

