import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IPageIDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E: Full admin assignment list, filter, and pagination coverage for /discussionBoard/admins
 *
 * This test verifies that administrative assignment listings can be filtered and paginated according to business rules, including edge cases. It tests:
 *
 *  - Creation of a root admin via self-appointment (a business assumption: member[0] appoints themselves as the first admin, as system has no explicit root or superadmin appointment flow)
 *  - Assignment of two further member accounts as admins (by the root admin)
 *  - Status filter ("active"/"revoked") and multi-field filter (by member, by appointing admin, by date range)
 *  - Combination filtering
 *  - Pagination and result set edge cases (no results, out-of-bounds pages)
 *  - Invalid status value rejection
 *
 * Note: As there is no admin revocation API, "revoked" status cannot be dynamically triggered—so status=revoked query tests only that system does not crash, not a real revocation.
 *
 * Steps:
 * 1. Register three members
 * 2. Assign root admin (self-appoint)
 * 3. Assign two more admins (by root admin)
 * 4. Run all major filter/pagination combos and check meta/results
 * 5. Assert appropriate API errors on filter input errors
 */
export async function test_api_discussionBoard_test_list_admin_assignments_with_full_pagination_and_filters(
  connection: api.IConnection,
) {
  // 1. Register three members for admin assignment eligibility
  const memberInputs = ArrayUtil.repeat(3)(() => ({
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: RandomGenerator.alphaNumeric(12) as string & tags.Format<"password">,
  }));
  const members = await ArrayUtil.asyncMap(memberInputs)(async body => {
    const member = await api.functional.discussionBoard.members.post(connection, {body});
    typia.assert(member);
    return member;
  });

  // 2. Create root admin (self-appoint). Business assumes member[0] can bootstrap system privileges.
  const rootAdmin = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: members[0].id,
      appointed_by_admin_id: members[0].id,
    },
  });
  typia.assert(rootAdmin);

  // 3. Appoint two further admin assignments by root admin
  const admin1 = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: members[1].id,
      appointed_by_admin_id: rootAdmin.member_id,
    },
  });
  typia.assert(admin1);

  const admin2 = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: members[2].id,
      appointed_by_admin_id: rootAdmin.member_id,
    },
  });
  typia.assert(admin2);

  // 4a. All assignments (no filters). Ensure all admins present, pagination correct.
  const pageAll = await api.functional.discussionBoard.admins.patch(connection, {body: {}});
  typia.assert(pageAll);
  TestValidator.predicate("all admins present")(
    pageAll.data.some(x => x.id === rootAdmin.id)
    && pageAll.data.some(x => x.id === admin1.id)
    && pageAll.data.some(x => x.id === admin2.id)
  );
  TestValidator.equals("pagination current page")(pageAll.pagination.current)(1);
  TestValidator.predicate("pagination meta valid")(
    pageAll.pagination.limit >= 1 && pageAll.pagination.pages >= 1 && pageAll.pagination.records >= 3
  );

  // 4b. Active admins filter (status="active")
  const pageActive = await api.functional.discussionBoard.admins.patch(connection, {body: {status: "active"}});
  typia.assert(pageActive);
  TestValidator.predicate("all returned active")(
    pageActive.data.every(x => x.revoked_at == null)
  );

  // 4c. Revoked admins filter (status="revoked")
  const pageRevoked = await api.functional.discussionBoard.admins.patch(connection, {body: {status: "revoked"}});
  typia.assert(pageRevoked);
  TestValidator.predicate("all returned revoked")(
    pageRevoked.data.every(x => x.revoked_at != null)
  );

  // 4d. member_id filter (assignment for one member)
  const pageByMember = await api.functional.discussionBoard.admins.patch(connection, {body: {member_id: admin1.member_id}});
  typia.assert(pageByMember);
  TestValidator.predicate("by member_id only")(
    pageByMember.data.every(x => x.member_id === admin1.member_id)
  );

  // 4e. appointed_by_admin_id filter (assignments by root admin)
  const pageByAppointer = await api.functional.discussionBoard.admins.patch(connection, {body: {appointed_by_admin_id: rootAdmin.member_id}});
  typia.assert(pageByAppointer);
  TestValidator.predicate("by appointed_by_admin_id only")(
    pageByAppointer.data.every(x => x.appointed_by_admin_id === rootAdmin.member_id)
  );

  // 4f. appointed_from filter: select using admin2's appointed_at as lower bound
  const pageByAppointedFrom = await api.functional.discussionBoard.admins.patch(connection, {body: {appointed_from: admin2.appointed_at}});
  typia.assert(pageByAppointedFrom);
  TestValidator.predicate("all appointed_at >= filter")(
    pageByAppointedFrom.data.every(x => x.appointed_at >= admin2.appointed_at)
  );

  // 4f. appointed_to filter: admin2's timestamp as upper bound
  const pageByAppointedTo = await api.functional.discussionBoard.admins.patch(connection, {body: {appointed_to: admin2.appointed_at}});
  typia.assert(pageByAppointedTo);
  TestValidator.predicate("all appointed_at <= filter")(
    pageByAppointedTo.data.every(x => x.appointed_at <= admin2.appointed_at)
  );

  // 4g. Combination filter: status + appointed_by_admin_id
  const pageCombo = await api.functional.discussionBoard.admins.patch(connection, {body: {appointed_by_admin_id: rootAdmin.member_id, status: "active"}});
  typia.assert(pageCombo);
  TestValidator.predicate("all combo matched")(
    pageCombo.data.every(x => x.appointed_by_admin_id === rootAdmin.member_id && x.revoked_at == null)
  );

  // 4h. Pagination test, limit=1, page=2
  const pageLimited = await api.functional.discussionBoard.admins.patch(connection, {body: {limit: 1, page: 2}});
  typia.assert(pageLimited);
  TestValidator.equals("pagination limit is 1")(pageLimited.pagination.limit)(1);
  TestValidator.equals("pagination page is 2")(pageLimited.pagination.current)(2);
  // It's possible last page will be empty due to total # admins; just check .data is an array
  TestValidator.predicate("pagination page has results or empty")(
    Array.isArray(pageLimited.data)
  );

  // 4i. Out-of-bounds page: page number > pages returns empty data
  const pageOob = await api.functional.discussionBoard.admins.patch(connection, {body: {limit: 1, page: 100}});
  typia.assert(pageOob);
  TestValidator.equals("pagination out of bounds is empty")(
    pageOob.data.length
  )(0);

  // 5. Invalid status filter (non-enum): should throw error
  await TestValidator.error("invalid status enum")(() =>
    api.functional.discussionBoard.admins.patch(connection, {body: {status: "invalid" as any}})
  );
}

