import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IPageIDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardChannel";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 테스트 목적: 토론 게시판 채널 목록을 페이징, 검색 조건과 함께 조회하는 E2E 테스트입니다.
 * 
 * 시나리오:
 * 1. 테스트 의미 있는 데이터 생성을 위해, 다양한 이름과 설명을 가진 채널 여러 개를 등록합니다.
 * 2. 기본 목록 조회: 요청 파라미터 없이(또는 기본값) 목록을 조회하면, 삭제되지 않고(active) 생성된 채널만 반환되어야 합니다. (soft deleted 항목 불포함)
 * 3. 이름(name)으로 부분 검색: 임의의 채널 이름 일부를 검색어로 하여 목록을 조회하면 기대한 항목만 반환됩니다.
 * 4. 설명(description)으로 부분 검색도 동작하는지 테스트합니다.
 * 5. 페이지네이션 테스트: limit(페이지 크기)과 page(페이지 번호)를 명시적으로 보내 여러 페이지에 걸쳐 결과가 분할되는지 확인합니다.
 * 6. 정렬 테스트: 생성일 순으로 정렬되어 반환되는지 확인합니다(명시 혹은 기본 동작).
 * 7. 필터 파라미터가 잘못 입력된 경우(예: 음수 page, 한계 초과 limit, 문자열 전달 등) 오류 응답이 반환되는지 테스트합니다.
 * 8. (옵션) soft delete(논리삭제)된 채널에 대한 조회 권한이 관리자가 아닌 경우 접근불가임을 확인합니다.
 * 
 * 주요 검증 포인트:
 * - 삭제되지 않은(활성) 채널만 일반 사용자에게 노출되는지
 * - 검색 및 필터 동작의 정확성
 * - 페이징 응답 메타(전체, 페이지수, 페이지번호 등) 및 데이터 배열의 유효성
 * - 잘못된 요청 파라미터에 대한 에러 처리
 */
export async function test_api_discussionBoard_test_list_channels_with_pagination_and_search_filters(
  connection: api.IConnection,
) {
  // 1. 임의의 이름/설명 조합으로 채널 여러개 등록
  const baseChannels = await Promise.all(ArrayUtil.repeat(6)(async () => {
    const name = RandomGenerator.alphabets(5);
    const desc = RandomGenerator.paragraph()();
    const c = await api.functional.discussionBoard.channels.post(connection, {
      body: { name, description: desc } satisfies IDiscussionBoardChannel.ICreate,
    });
    typia.assert(c);
    return c;
  }));

  // 2. 기본 목록 조회 - 삭제 안된 모든 채널 포함, soft delete 미포함, 수량 일치
  const basicList = await api.functional.discussionBoard.channels.patch(connection, {
    body: {}
  });
  typia.assert(basicList);
  TestValidator.predicate("deleted_at 없는 채널만 포함됨")(
    basicList.data.every((item) => item.description !== undefined)
  );

  // 3. 부분 이름 검색 (첫 번째 채널의 일부로)
  const partialName = baseChannels[0].name.slice(1, 4); // 3글자 중간
  const filteredByName = await api.functional.discussionBoard.channels.patch(connection, {
    body: { name: partialName },
  });
  typia.assert(filteredByName);
  TestValidator.predicate("name substring 검색 결과 모두 매칭")(
    filteredByName.data.every((item) => item.name.includes(partialName))
  );

  // 4. 부분 설명 검색
  const partialDesc = baseChannels[1].description?.slice(0, 8) ?? "";
  const filteredByDesc = await api.functional.discussionBoard.channels.patch(connection, {
    body: { description: partialDesc },
  });
  typia.assert(filteredByDesc);
  TestValidator.predicate("description 부분검색 동작확인")(
    filteredByDesc.data.every((item) => item.description?.includes(partialDesc) ?? false)
  );

  // 5. 페이지네이션 테스트
  const paged1 = await api.functional.discussionBoard.channels.patch(connection, {
    body: { page: 1, limit: 2 },
  });
  typia.assert(paged1);
  TestValidator.equals("페이지네이션1 데이터 개수")(paged1.data.length)(2);

  const paged2 = await api.functional.discussionBoard.channels.patch(connection, {
    body: { page: 2, limit: 2 },
  });
  typia.assert(paged2);
  TestValidator.equals("페이지네이션2 데이터 개수")(paged2.data.length)(2);
  TestValidator.notEquals("페이지 1, 2의 결과 다름")(paged1.data[0].id)(paged2.data[0].id);

  // 6. 기본 정렬(생성일순) 확인
  TestValidator.predicate("생성일 오름차순 또는 정렬됨")(
    paged1.data.every((item, idx, arr) =>
      idx === 0 || (item.id && item.id !== arr[idx - 1].id && true)
    )
  );

  // 7. 잘못된 파라미터 테스트 (음수 페이지 등)
  await TestValidator.error("잘못된 page param")(() =>
    api.functional.discussionBoard.channels.patch(connection, {
      body: { page: -1 },
    })
  );

  await TestValidator.error("limit에 대한 범위초과 또는 문자열 입력")(() =>
    api.functional.discussionBoard.channels.patch(connection, {
      body: { limit: 1000000 },
    })
  );

  await TestValidator.error("limit에 문자열 입력")(() =>
    api.functional.discussionBoard.channels.patch(connection, {
      body: { limit: "two" as any },
    })
  );
}

