import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";

/**
 * E2E test for editing (updating) an existing discussion board comment as author (and invalid/edge cases).
 * 
 * This test covers the complete permission and workflow spectrum for comment editing:
 *
 * 1. Register two users: original author and non-author.
 * 2. Create a board and a post.
 * 3. Author user creates a comment.
 * 4. Author successfully edits their comment (changes body, depth, ensures edit flag set).
 * 5. Attempt to edit the comment as a non-author (should fail – permissions).
 * 6. Attempt to edit a locked comment (should fail – locked).
 * 7. Attempt to edit a deleted comment (should fail – deleted).
 * 8. Attempt to edit a non-existent comment (should fail – not found).
 * 9. Attempt to edit with content violating rules (e.g., banned words – should fail validation).
 * 10. (If possible with available APIs) Test moderator/admin override permissions for editing others’ comments (skipped if not supported by test APIs).
 *
 * All successful edits should:
 *   - Allow update of the body/depth
 *   - Set is_edited
 *   - Return an updated comment entity
 *   - (Business logic) Log the edit/compliance in audit (not directly asserted unless exposed)
 *
 * All error tests must validate the correct error is raised.
 */
export async function test_api_discussionBoard_test_update_comment_as_author_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Register two users: author and non-author
  const authorReg = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "authorPW1234!",
    },
  });
  typia.assert(authorReg);
  const nonAuthorReg = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "nonAuthorPW4567!",
    },
  });
  typia.assert(nonAuthorReg);

  // 2. Create a board
  const board = await api.functional.discussionBoard.boards.post(connection, {
    body: {
      title: RandomGenerator.paragraph()(1),
      slug: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(1),
    },
  });
  typia.assert(board);

  // 3. Create a post (by author)
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: board.id,
      author_id: authorReg.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 4. Author creates a comment
  const comment = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: post.id,
      thread_id: post.id, // top-level (thread_id convention)
      author_id: authorReg.id,
      body: "This is the original comment.",
      depth: 0,
    },
  });
  typia.assert(comment);

  // 5. Author edits their comment: change body & set edit flag
  const newBody = "This is the edited comment content.";
  const update1 = await api.functional.discussionBoard.comments.putById(connection, {
    id: comment.id,
    body: {
      body: newBody,
      is_edited: true,
    },
  });
  typia.assert(update1);
  TestValidator.equals("edited comment body matches")(update1.body)(newBody);
  TestValidator.equals("is_edited flag set")(update1.is_edited)(true);
  TestValidator.notEquals("updated_at changed")(update1.updated_at)(comment.updated_at);

  // 6. Non-author attempts to edit: expecting permissions error (should fail)
  await TestValidator.error("non-author cannot edit comment")(
    async () => await api.functional.discussionBoard.comments.putById(connection, {
      id: comment.id,
      body: {
        body: "Illegal edit.",
        is_edited: true,
      },
    }),
  );

  // 7. Lock the comment: (simulate by creating a locked post then comment and trying to edit)
  const lockedPost = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: board.id,
      author_id: authorReg.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(lockedPost);
  // simulate post locked status
  (lockedPost as any).is_locked = true; // only in-memory as API lacks direct lock. Real lock enforcement cannot be tested unless API supports update lock
  const lockedComment = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: lockedPost.id,
      thread_id: lockedPost.id,
      author_id: authorReg.id,
      body: "Will be locked.",
      depth: 0,
    },
  });
  typia.assert(lockedComment);
  // Try to edit locked comment (should fail if lock enforced by API)
  await TestValidator.error("editing a comment in a locked post fails")(
    async () => await api.functional.discussionBoard.comments.putById(connection, {
      id: lockedComment.id,
      body: {
        body: "Edit attempt on locked.",
        is_edited: true,
      },
    }),
  );

  // 8. Delete the comment (simulate soft-delete by updating with deleted_at)
  const now = new Date().toISOString();
  const deleted = await api.functional.discussionBoard.comments.putById(connection, {
    id: comment.id,
    body: {
      deleted_at: now,
    },
  });
  typia.assert(deleted);
  TestValidator.equals("soft-deleted")(deleted.deleted_at)(now);
  // Try to edit deleted comment (should fail)
  await TestValidator.error("edit deleted fails")(
    async () => await api.functional.discussionBoard.comments.putById(connection, {
      id: comment.id,
      body: {
        body: "Edit after deletion.",
        is_edited: true,
      },
    }),
  );

  // 9. Non-existent comment ID update
  await TestValidator.error("edit non-existent comment fails")(
    async () => await api.functional.discussionBoard.comments.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        body: "Edit ghost comment.",
      },
    }),
  );

  // 10. Content rule violation: e.g., banned word
  await TestValidator.error("edit with rule-violating content fails")(
    async () => await api.functional.discussionBoard.comments.putById(connection, {
      id: comment.id,
      body: {
        body: "This contains a bannedword.",
      },
    }),
  );

  // Skipping moderator/admin override test – no APIs for role elevation.
}

