import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";

/**
 * E2E test for updating a notification setting entry by ID as an admin.
 *
 * Business Context:
 * - This test ensures that administrators can successfully update notification setting entries, while non-admins are properly forbidden.
 * - Only the 'value' and 'description' fields of a notification setting may be updated. The 'key' is immutable after creation.
 *
 * Test Workflow:
 * 1. Create two notification settings as admin to prepare for unique key and data constraints.
 * 2. Update the value and description of the first notification setting; ensure change is reflected in response.
 * 3. Attempt to update the first setting with missing required field (no value) and expect a validation error.
 * 4. Attempt to update with malformed value type (number instead of string) and expect a validation error.
 * 5. Update the entry with description set to null (edge case for optional fields).
 * 6. Attempt update as unauthenticated or non-admin user; expect forbidden error.
 *
 * Note:
 * - The API schema does not allow changing the key of an existing entry via the update endpoint; thus, duplicate key testing on update is not possible here.
 */
export async function test_api_discussionBoard_notificationSettings_test_update_notification_setting_with_valid_data_and_duplicate_key_error(
  connection: api.IConnection
) {
  // 1. Create two distinct notification settings as admin
  const createInput1: IDiscussionBoardNotificationSetting.ICreate = {
    key: RandomGenerator.alphabets(10),
    value: RandomGenerator.alphabets(8),
    description: RandomGenerator.paragraph()(),
  };
  const setting1 = await api.functional.discussionBoard.notificationSettings.post(
    connection,
    { body: createInput1 }
  );
  typia.assert(setting1);

  const createInput2: IDiscussionBoardNotificationSetting.ICreate = {
    key: RandomGenerator.alphabets(10),
    value: RandomGenerator.alphabets(8),
    description: RandomGenerator.paragraph()(),
  };
  const setting2 = await api.functional.discussionBoard.notificationSettings.post(
    connection,
    { body: createInput2 }
  );
  typia.assert(setting2);

  // 2. Update first setting's value and description
  const updateInput: IDiscussionBoardNotificationSetting.IUpdate = {
    value: RandomGenerator.alphaNumeric(12),
    description: RandomGenerator.paragraph()(),
  };
  const updated = await api.functional.discussionBoard.notificationSettings.putById(
    connection,
    { id: setting1.id, body: updateInput }
  );
  typia.assert(updated);
  TestValidator.equals("updated value")(updated.value)(updateInput.value);
  TestValidator.equals("updated description")(updated.description)(updateInput.description);
  TestValidator.equals("updated id matches")(updated.id)(setting1.id);

  // 3. Edge case: Update with description set to null
  const updateNullDesc: IDiscussionBoardNotificationSetting.IUpdate = {
    value: RandomGenerator.alphabets(12),
    description: null,
  };
  const updatedNullDesc = await api.functional.discussionBoard.notificationSettings.putById(
    connection,
    { id: setting1.id, body: updateNullDesc }
  );
  typia.assert(updatedNullDesc);
  TestValidator.equals("updated value with null desc")(updatedNullDesc.value)(updateNullDesc.value);
  TestValidator.equals("updated description null")(updatedNullDesc.description)(null);

  // 4. Validation: Missing required 'value' property
  await TestValidator.error("missing value fails")(
    async () => {
      // Omit required 'value' by creating minimal malformed object
      await api.functional.discussionBoard.notificationSettings.putById(
        connection,
        { id: setting1.id, body: { /* intentionally empty */ } as unknown as IDiscussionBoardNotificationSetting.IUpdate },
      );
    }
  );

  // 5. Validation: Malformed 'value' property (number instead of string)
  await TestValidator.error("malformed value fails")(
    async () => {
      // Use object with 'value' as number, cast via JSON.parse
      const malformedBody = JSON.parse('{"value":123456, "description": "desc"}');
      await api.functional.discussionBoard.notificationSettings.putById(
        connection,
        { id: setting1.id, body: malformedBody },
      );
    }
  );

  // 6. Simulate non-admin or unauthenticated attempt: Remove likely auth headers
  const connectionNoAuth = {
    ...connection,
    headers: { ...(connection.headers ?? {}) }
  };
  delete connectionNoAuth.headers.Authorization;
  delete connectionNoAuth.headers.authorization;
  await TestValidator.error("forbidden for non-admin")(
    async () => {
      await api.functional.discussionBoard.notificationSettings.putById(
        connectionNoAuth,
        { id: setting1.id, body: updateInput },
      );
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";

/**
 * Validate soft-deletion (logical deletion) of a discussion board notification setting.
 *
 * This test covers the following business and access control requirements:
 *
 * 1. Create a notification setting as an admin user (dependency).
 * 2. As admin, soft-delete the notification setting by its ID (verify `deleted_at` property is set, no physical removal).
 * 3. Attempt a redundant soft-delete by ID (expect an error as the entry is already deleted).
 * 4. Attempt to soft-delete a non-existent notification setting ID (expect an error response).
 * 5. Simulate non-admin (unauthorized) and verify deletion is forbidden (expect error).
 *
 * The test ensures core CRUD soft-delete logic for notification settings and validates access rules for the endpoint.
 */
export async function test_api_discussionBoard_notificationSettings_test_soft_delete_notification_setting_and_access_post_delete(
  connection: api.IConnection,
) {
  // 1. Create notification setting as admin
  const createInput: IDiscussionBoardNotificationSetting.ICreate = {
    key: RandomGenerator.alphabets(10),
    value: RandomGenerator.alphabets(8),
    description: RandomGenerator.paragraph()(),
  };
  const setting = await api.functional.discussionBoard.notificationSettings.post(connection, { body: createInput });
  typia.assert(setting);

  // 2. Admin soft-deletes the notification setting
  const erased = await api.functional.discussionBoard.notificationSettings.eraseById(connection, { id: setting.id });
  typia.assert(erased);
  TestValidator.equals("deleted_at must be set after deletion")(typeof erased.deleted_at === "string")(true);
  TestValidator.equals("ID is preserved after logical deletion")(erased.id)(setting.id);
  TestValidator.equals("key is preserved after logical deletion")(erased.key)(setting.key);
  TestValidator.equals("value is preserved after logical deletion")(erased.value)(setting.value);

  // 3. Attempt to soft-delete already deleted ID (should throw)
  await TestValidator.error("cannot erase an already deleted setting")(() =>
    api.functional.discussionBoard.notificationSettings.eraseById(connection, { id: setting.id })
  );

  // 4. Attempt to soft-delete a non-existent ID (should throw)
  const fakeId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("cannot erase a non-existent setting")(() =>
    api.functional.discussionBoard.notificationSettings.eraseById(connection, { id: fakeId })
  );

  // 5. Try to soft-delete as unauthorized/non-admin (simulate by clearing Authorization header)
  const unauthorized = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("forbidden for non-admin/unauthorized")(() =>
    api.functional.discussionBoard.notificationSettings.eraseById(unauthorized, { id: setting.id })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
