 *
 * - 여러 명의 회원 가입(서로 구분 가능한 username/email 패턴 적용)
 * - 특정 계정 admin 등업 처리 (최초 user → admin 전환 논리)
 * - 다양한 페이지, 검색 조합으로 목록 API 호출 및 검증
 *     - username, email 전체/부분/불일치 검색
 *     - page/limit 정상 및 비정상(0, 음수) 케이스
 *     - 결과 전체건수/페이지/limit 등 pagination 정보의 정합성
 *     - 검색조건 불충족(empty result) 확인
 */
export async function test_api_discussionBoard_test_list_members_with_pagination_and_search_by_admin(
  connection: api.IConnection,
) {
  // 1. 테스트용 회원 데이터 여러 개 생성 (username/email 구분되게)
  const members: api.IDiscussionBoardMember[] = [];
  for (let i = 0; i < 7; ++i) {
    const suffix = String(i + 1).padStart(2, "0");
    const username = `autotest_member_${suffix}`;
    const email = `autotest_member_${suffix}@testdomain.dev` as string & tags.Format<"email">;
    const member = await api.functional.discussionBoard.members.post(connection, {
      body: {
        username,
        email,
        display_name: `테스트유저${suffix}`,
        password: "Password123!" as string & tags.Format<"password">,
      },
    });
    typia.assert(member);
    members.push(member);
  }

  // 2. 관리자용 계정 생성 및 admin 등업(권한에 필요한 appointing admin 지정)
  const adminUsername = "autotest_admin";
  const adminEmail = "autotest_admin@testdomain.dev" as string & tags.Format<"email">;
  const adminMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: adminUsername,
      email: adminEmail,
      display_name: "관리자유저",
      password: "SecureAdminPW!1" as string & tags.Format<"password">,
    },
  });
  typia.assert(adminMember);

  // manager self-appoints/assigns as admin (최초 admin이면 자기 자신 지정, 아니면 기존 admin이 지정 필요)
  const adminAssignment = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: adminMember.id,
      appointed_by_admin_id: adminMember.id,
    },
  });
  typia.assert(adminAssignment);

  // 3. 페이징+검색 조합으로 목록 조회

  // (a) 전체회원 page=1, limit=3
  let result = await api.functional.discussionBoard.members.patch(connection, {
    body: { page: 1, limit: 3 },
  });
  typia.assert(result);
  TestValidator.equals("페이지 개수 = limit")(result.data.length)(3);
  TestValidator.equals("pagination.current")(result.pagination.current)(1);
  TestValidator.equals("pagination.limit")(result.pagination.limit)(3);
  // 총 회원 수가 (members + 관리자 1명)
  TestValidator.equals("pagination.records, 총 회원 수")(
    result.pagination.records,
  )(members.length + 1);

  // (b) username 부분일치(autotest_member_0) 검색 (page=1, limit=10)
  result = await api.functional.discussionBoard.members.patch(connection, {
    body: { page: 1, limit: 10, username: "autotest_member_0" },
  });
  typia.assert(result);
  // username에 "autotest_member_0" 포함된 회원만 반환
  for (const u of result.data) {
    TestValidator.predicate("username 부분일치 검색 결과 필터")(
      u.username.includes("autotest_member_0"),
    );
  }

  // (c) email 전체일치 검색
  const targetEmail = members[3].email;
  result = await api.functional.discussionBoard.members.patch(connection, {
    body: { page: 1, limit: 10, email: targetEmail },
  });
  typia.assert(result);
  TestValidator.equals("email 전체일치 사용자 단 1인 반환됨")(
    result.data.length,
  )(1);
  TestValidator.equals("반환 email값 매칭")(
    result.data[0].email,
  )(targetEmail);

  // (d) 존재하지 않는 display_name 검색(빈 결과)
  result = await api.functional.discussionBoard.members.patch(connection, {
    body: { page: 1, limit: 10, display_name: "__존재하지않음__" },
  });
  typia.assert(result);
  TestValidator.equals("display_name 불일치 검색 결과, 비어있음")(
    result.data.length,
  )(0);

  // (e) invalid page, limit(0/음수 등) → 에러 확인
  for (const params of [ { page: 0, limit: 3 }, { page: -1, limit: 2 }, { page: 2, limit: 0 } ]) {
    await TestValidator.error(`잘못된 page/limit: ${JSON.stringify(params)}`)(
      async () => {
        await api.functional.discussionBoard.members.patch(connection, {
          body: params,
        });
      },
    );
  }
}

