  await TestValidator.error("존재하지 않는 멤버는 404 오류 반환")(
    async () => {
      await api.functional.discussionBoard.members.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 5. 비활성화 멤버 조회 시 권한/인증 오류 (API 미구현으로 skip, 엔드포인트 확장 시 실제 값 기반 확인 추가)
