import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostEdit";

/**
 * Test updating an existing post edit record, covering permission and validation checks
 *
 * This E2E test validates the update workflow for post edit records in the Discussion Board application:
 * - Ensures the original editor can update their own edit summary successfully
 * - Verifies that an unauthorized member cannot update another user's post edit (permission enforcement)
 * - Checks validation for edit summary field (rejects empty string and excessively long summary)
 * - Confirms that only allowed fields (edit_summary, body_after_edit) can be changed and audit fields are preserved
 *
 * Steps:
 * 1. Register two discussion board members (member1 as editor, member2 as unauthorized actor)
 * 2. Create a discussion board
 * 3. Create a post in that board (by member1)
 * 4. Create a post edit record for that post (by member1)
 * 5. Update the edit summary as the original editor (should succeed and change only the allowed field)
 * 6. Attempt update as unauthorized member (should be rejected)
 * 7. Attempt invalid updates (empty summary, overlength summary; both should be rejected)
 */
export async function test_api_discussionBoard_test_update_post_edit_with_permissions_and_validation(
  connection: api.IConnection,
) {
  // 1. Register two members: member1 (editor) and member2 (unauthorized actor)
  const member1Input = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "EditorP@ssw0rd1"
  } satisfies IDiscussionBoardMember.ICreate;
  const member1 = await api.functional.discussionBoard.members.post(connection, { body: member1Input });
  typia.assert(member1);

  const member2Input = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "NotAllowedP@ss2"
  } satisfies IDiscussionBoardMember.ICreate;
  const member2 = await api.functional.discussionBoard.members.post(connection, { body: member2Input });
  typia.assert(member2);

  // 2. Create a discussion board
  const boardInput = {
    title: RandomGenerator.paragraph()(2),
    slug: RandomGenerator.alphaNumeric(12).toLowerCase(),
    description: RandomGenerator.paragraph()(3)
  } satisfies IDiscussionBoardBoard.ICreate;
  const board = await api.functional.discussionBoard.boards.post(connection, { body: boardInput });
  typia.assert(board);

  // 3. Create a post in that board (by member1)
  const postInput = {
    board_id: board.id,
    author_id: member1.id,
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()()
  } satisfies IDiscussionBoardPost.ICreate;
  const post = await api.functional.discussionBoard.posts.post(connection, { body: postInput });
  typia.assert(post);

  // 4. Create a post edit record for that post (by member1)
  const originalSummary = "Initial edit for typo correction";
  const postEditInput = {
    post_id: post.id,
    editor_id: member1.id,
    edit_summary: originalSummary,
    body_after_edit: RandomGenerator.content()()()
  } satisfies IDiscussionBoardPostEdit.ICreate;
  const postEdit = await api.functional.discussionBoard.postEdits.post(connection, { body: postEditInput });
  typia.assert(postEdit);

  // 5. Editor successfully updates edit summary (happy path)
  const newSummary = "Editor clarifies rationale for this change.";
  const updatedEdit = await api.functional.discussionBoard.postEdits.putById(connection, {
    id: postEdit.id,
    body: { edit_summary: newSummary } satisfies IDiscussionBoardPostEdit.IUpdate
  });
  typia.assert(updatedEdit);
  TestValidator.equals("summary updated")(updatedEdit.edit_summary)(newSummary);
  TestValidator.equals("editor remains unchanged")(updatedEdit.editor_id)(postEdit.editor_id);
  TestValidator.equals("post_id remains unchanged")(updatedEdit.post_id)(postEdit.post_id);
  TestValidator.equals("created_at is string")(typeof updatedEdit.created_at)("string");

  // 6. Unauthorized member attempts update (should be rejected)
  await TestValidator.error("unauthorized update rejected")(async () => {
    // NOTE: In a real system, you would switch session/context to member2. Here, we simulate the attempt.
    await api.functional.discussionBoard.postEdits.putById(connection, {
      id: postEdit.id,
      body: { edit_summary: "Illicit overwrite attempt by non-owner" }
    });
  });

  // 7. Invalid update: empty summary (should be rejected)
  await TestValidator.error("empty edit summary rejected")(async () => {
    await api.functional.discussionBoard.postEdits.putById(connection, {
      id: postEdit.id,
      body: { edit_summary: "" }
    });
  });

  // 8. Invalid update: overlong summary (should be rejected)
  await TestValidator.error("edit summary over max length rejected")(async () => {
    await api.functional.discussionBoard.postEdits.putById(connection, {
      id: postEdit.id,
      body: { edit_summary: RandomGenerator.alphaNumeric(600) }
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
