  // 3. As admin, appoint member B as admin
  const adminAssignB = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: memberB.id,
      appointed_by_admin_id: memberA.id
    }
  });
  typia.assert(adminAssignB);

  // 4. Retrieve B's admin assignment record by ID as admin
  const getAdminB = await api.functional.discussionBoard.admins.getById(connection, {
