import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";

/**
 * Test admin creation of a new admin assignment for a member.
 *
 * Purpose: End-to-end validation of the administrator assignment workflow, including positive and negative paths.
 * Ensures that only eligible members can be promoted by existing admins, role uniqueness and business rules are enforced,
 * and that failures due to invalid operations produce correct error responses.
 *
 * Steps:
 * 1. Register two normal user members (candidate1, candidate2)
 * 2. Register a bootstrap system admin (admin1) who will act as assignor
 * 3. Assign admin role to candidate1 (expect success, check data)
 * 4. Attempt assignment to non-existent member (expect error)
 * 5. Attempt duplicate admin assignment for candidate1 (expect error)
 * 6. Attempt to assign an admin using a non-admin (candidate2 as assignor, expect forbidden)
 *  - Note: Skips explicit audit log validation as there is no exposed endpoint
 */
export async function test_api_discussionBoard_test_create_admin_assignment_for_eligible_and_ineligible_members(
  connection: api.IConnection,
) {
  // 1. Register candidate1
  const candidate1 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(candidate1);

  // 2. Register candidate2
  const candidate2 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(candidate2);

  // 3. Register admin1 (bootstrapping a system admin)
  const admin1 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(admin1);

  // Manually assign admin1 as initial admin (bypass: this is needed in real infra)
  // For test: assign admin role using system self—appointing
  const bootstrapAdmin = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: admin1.id,
      appointed_by_admin_id: admin1.id,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(bootstrapAdmin);
  TestValidator.equals("admin1 assigned to self")(bootstrapAdmin.member_id)(admin1.id);

  // 4. Admin1 assigns admin role to candidate1
  const adminAssignment = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: candidate1.id,
      appointed_by_admin_id: admin1.id,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAssignment);
  TestValidator.equals("candidate1 is admin")(adminAssignment.member_id)(candidate1.id);
  TestValidator.equals("appointing admin reference")(adminAssignment.appointed_by_admin_id)(admin1.id);
  TestValidator.predicate("has appointment timestamp")(typeof adminAssignment.appointed_at === "string" && adminAssignment.appointed_at.length > 0);
  TestValidator.equals("not revoked")(adminAssignment.revoked_at)(null);

  // 5. Failure: assign admin to non-existent random member
  await TestValidator.error("fail on non-existent member")(async () => {
    await api.functional.discussionBoard.admins.post(connection, {
      body: {
        member_id: typia.random<string & tags.Format<"uuid">>(),
        appointed_by_admin_id: admin1.id,
      } satisfies IDiscussionBoardAdmin.ICreate,
    });
  });

  // 6. Failure: duplicate admin assignment for candidate1
  await TestValidator.error("fail on duplicate admin")(async () => {
    await api.functional.discussionBoard.admins.post(connection, {
      body: {
        member_id: candidate1.id,
        appointed_by_admin_id: admin1.id,
      } satisfies IDiscussionBoardAdmin.ICreate,
    });
  });

  // 7. Failure: non-admin (candidate2) attempts assignment
  await TestValidator.error("fail on non-admin appointor")(async () => {
    await api.functional.discussionBoard.admins.post(connection, {
      body: {
        member_id: candidate2.id,
        appointed_by_admin_id: candidate2.id,
      } satisfies IDiscussionBoardAdmin.ICreate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";

/**
 * Test updating an existing admin assignment record and permission enforcement.
 *
 * Scenario:
 * 1. Create a member who will be promoted to admin (subject).
 * 2. Create a second member as the initial "appointing admin".
 * 3. Assign admin status to the subject by having the appointing admin perform the assignment.
 * 4. Update the assignment record:
 *    a. Change the appointing admin to a new admin member.
 *    b. Set revoked_at timestamp to simulate demotion.
 *    c. Confirm the update reflects all changed and audited fields.
 * 5. Check that audit trail fields (appointed_at, revoked_at, appointed_by_admin_id) are as expected.
 * 6. Negative tests:
 *    a. Attempt update with a random non-existent ID (expect error).
 *    b. Try assigning appointed_by_admin_id to a non-admin (expect error).
 *    c. Try to perform the update as a non-admin user (simulated, expect error).
 *    d. (Soft-delete negative test omitted; not implementable here)
 *
 * All business constraints and error handling are validated for strict enforcement.
 */
export async function test_api_discussionBoard_test_update_admin_assignment_and_permission_enforcement(
  connection: api.IConnection,
) {
  // 1. Create member who will be admin (subjectMember)
  const subjectMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    },
  });
  typia.assert(subjectMember);

  // 2. Create initial "appointing admin"
  const appointingAdmin = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    },
  });
  typia.assert(appointingAdmin);

  // 3. Assign admin: appointingAdmin elevates subjectMember
  const assignment = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: subjectMember.id,
      appointed_by_admin_id: appointingAdmin.id,
    },
  });
  typia.assert(assignment);

  // 4a. Create a new admin member
  const newAdmin = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    },
  });
  typia.assert(newAdmin);
  // Promote newAdmin to admin using appointingAdmin
  const newAdminAssignment = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: newAdmin.id,
      appointed_by_admin_id: appointingAdmin.id,
    },
  });
  typia.assert(newAdminAssignment);

  // 4b. Update: assign new appointing admin and set revoked_at
  const revokedAt = new Date().toISOString();
  const updated = await api.functional.discussionBoard.admins.putById(connection, {
    id: assignment.id,
    body: {
      appointed_by_admin_id: newAdmin.id,
      revoked_at: revokedAt,
    },
  });
  typia.assert(updated);
  TestValidator.equals("appointed_by_admin_id changed")(updated.appointed_by_admin_id)(newAdmin.id);
  TestValidator.equals("revoked_at set")(updated.revoked_at)(revokedAt);
  TestValidator.equals("assignment id")(updated.id)(assignment.id);
  TestValidator.equals("member_id not changed")(updated.member_id)(assignment.member_id);
  TestValidator.equals("appointed_at not changed")(updated.appointed_at)(assignment.appointed_at);

  // 6a. Update with non-existent ID
  await TestValidator.error("update with non-existent id should fail")(async () => {
    await api.functional.discussionBoard.admins.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { appointed_by_admin_id: appointingAdmin.id },
    });
  });

  // 6b. appointed_by_admin_id = non-admin (should error)
  const outsider = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    },
  });
  typia.assert(outsider);
  await TestValidator.error("non-admin cannot be assigning admin")(async () => {
    await api.functional.discussionBoard.admins.putById(connection, {
      id: assignment.id,
      body: { appointed_by_admin_id: outsider.id },
    });
  });

  // 6c. Simulate non-admin performing update by using outsider as assigning admin (error expected)
  await TestValidator.error("non-admin permission denied")(async () => {
    await api.functional.discussionBoard.admins.putById(connection, {
      id: assignment.id,
      body: { appointed_by_admin_id: outsider.id },
    });
  });

  // 6d. Soft-delete negative test omitted (no API support)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
