 *
 * 3. Simulate a non-admin user (e.g., omit or alter admin token in connection.headers) attempting to create a new report category.
 *    - API should reject the request with a permissions error (typically HTTP 403 or 401).
 *    - Use TestValidator.error to ensure error occurs for insufficient permissions.
 *
 * Business rules being validated:
 * - Category name uniqueness required by backend (duplicate names rejected).
 * - Only admins permitted to create report categories.
 */
export async function test_api_discussionBoard_test_create_report_category_with_valid_and_duplicate_name(
  connection: api.IConnection,
) {
