/**
 * E2E test for updating moderation appeal decisions (Discussion Board).
 *
 * This test ensures that only the original moderator/admin who made a decision on a moderation appeal can update the rationale or outcome before the decision is finalized. The test performs the following steps:
 *
 * 1. Create a mock moderation action ID and two different member IDs (one acting as moderator, one as a regular member).
 * 2. Member files a moderation appeal against the moderation action.
 * 3. Moderator creates a corresponding appeal decision.
 * 4. Moderator updates the decision's rationale/outcome before finalization (should succeed).
 * 5. Try updating as a different, unauthorized actor (should fail: forbidden).
 * 6. Simulate 'finalization' (not directly possible—so E2E can only verify that if state-locked or simulated, future updates are forbidden).
 * 7. Try updating with a not-found decision ID (should fail: not found).
 * 8. Try updating with an invalid enum value for outcome (should fail input validation if platform enforces enums).
 * 9. Try updating with empty body (should fail validation if fields are required/non-empty).
 *
 * Each step verifies both happy-path and error outcomes, including correct authorization and input validation. Error checks are performed using TestValidator.error.
 */
export async function test_api_discussionBoard_test_update_appeal_decision_with_role_and_state_validation(connection: api.IConnection) {
  // 1. Prepare test IDs for moderation action and member roles
  const moderation_action_id = typia.random<string & tags.Format<"uuid">>();
  const moderator_id = typia.random<string & tags.Format<"uuid">>();
  const admin_id = typia.random<string & tags.Format<"uuid">>();
  const member_id = typia.random<string & tags.Format<"uuid">>(); // Appeal submitter
  const wrong_moderator_id = typia.random<string & tags.Format<"uuid">>();

  // 2. Member files appeal
  const appeal = await api.functional.discussionBoard.moderationAppeals.post(connection, {
    body: {
      moderation_action_id,
      member_id,
      appeal_reason: "I disagree with the moderation and want a review."
    }
  });
  typia.assert(appeal);

  // 3. Moderator creates a decision
  const initial_decision_outcome = "upheld";
  const decision = await api.functional.discussionBoard.appealDecisions.post(connection, {
    body: {
      appeal_id: appeal.id,
      moderator_id,
      decision_outcome: initial_decision_outcome,
      decision_rationale: "The original moderation is valid."
    }
  });
  typia.assert(decision);

  // 4. Moderator updates the decision before finalization
  const updated_rationale = "Upon further review, some mitigating factors were found.";
  const updated_outcome = "modified";
  const updated = await api.functional.discussionBoard.appealDecisions.putById(connection, {
    id: decision.id,
    body: {
      decision_rationale: updated_rationale,
      decision_outcome: updated_outcome
    }
  });
  typia.assert(updated);
  TestValidator.equals("rationale updated")(updated.decision_rationale)(updated_rationale);
  TestValidator.equals("outcome updated")(updated.decision_outcome)(updated_outcome);

  // 5. Unauthorized actor attempts update (should fail)
  await TestValidator.error("forbidden update from wrong actor")(() =>
    api.functional.discussionBoard.appealDecisions.putById(connection, {
      id: decision.id,
      body: {
        decision_rationale: "Attempted by wrong moderator.",
        decision_outcome: "overturned"
      }
    })
  );

  // 6. (Optional in E2E) Simulate finalization/lock (simulate by assuming immutable after update, since no explicit API for lock)
  // Assuming API will forbid further updates for finalized decisions, try update again (should error if locked)
  await TestValidator.error("update forbidden after (assumed) finalization")(() =>
    api.functional.discussionBoard.appealDecisions.putById(connection, {
      id: decision.id,
      body: {
        decision_rationale: "Trying to update after lock.",
        decision_outcome: "overturned"
      }
    })
  );

  // 7. Update with not-found ID
  await TestValidator.error("not found for non-existent decision id")(() =>
    api.functional.discussionBoard.appealDecisions.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        decision_rationale: "Non-existent.",
      }
    })
  );

  // 8. Update with invalid 'decision_outcome' value
  await TestValidator.error("invalid enum for decision_outcome")(() =>
    api.functional.discussionBoard.appealDecisions.putById(connection, {
      id: decision.id,
      body: {
        decision_outcome: "foobar",
        decision_rationale: "Invalid outcome enum value."
      }
    })
  );

  // 9. Update with empty body
  await TestValidator.error("empty body should fail validation")(() =>
    api.functional.discussionBoard.appealDecisions.putById(connection, {
      id: decision.id,
      body: {}
    })
  );
}

