/**
 * 테스트: 댓글을 작성자와 관리자가 소프트 삭제(erase)할 수 있는지 검증
 *
 * 시나리오:
 * 1. 일반 사용자(작성자)와 관리자를 등록한다.
 * 2. 관리자로 게시판을 생성한다.
 * 3. 작성자가 해당 게시판에 게시글을 작성한다.
 * 4. 작성자가 댓글을 단다.
 * 5. 댓글 작성자가 댓글을 삭제(소프트 삭제)한다. → 성공해야 함.
 * 6. 이미 삭제된 댓글을 다시 삭제 시도 → 실패(오류)해야 함.
 * 7. 다른 사용자가 댓글 지우기 시도 → 실패(오류)해야 함.
 * 8. (가능할 경우) 관리자가 댓글 삭제 시도 → 허용 시 성공, 불가 시 오류
 * 9. 존재하지 않는 댓글 id로 삭제 시도 → 실패(오류)해야 함.
 *
 * 검증 포인트:
 * - 각 삭제 결과의 success 필드/실패 시 오류 발생 여부
 * - 댓글의 deleted_at이 설정되는지(실제 검사 불가: 조회 API 미제공)
 * - 본인/관리자만 삭제 가능 비즈니스 룰 적용 여부
 *
 * 주의: 인증 전환(로그인/역할 변경)·댓글 목록/상세 조회·로그 검증·이벤트 발생 등은 현재 제공된 SDK/DTO만으로는 구현 불가하므로 코드에서 테스트 불가.
 */
export async function test_api_discussionBoard_test_delete_comment_as_owner_and_admin(
  connection: api.IConnection,
) {
  // 1. 댓글 작성자(일반 사용자)와 관리자, 그리고 또 다른 사용자를 회원으로 등록
  const author = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.name(),
      password: '1234' as string & tags.Format<'password'>,
    },
  });
  typia.assert(author);
  const admin = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.name(),
      password: '1234' as string & tags.Format<'password'>,
    },
  });
  typia.assert(admin);
  const another = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.name(),
      password: '1234' as string & tags.Format<'password'>,
    },
  });
  typia.assert(another);

  // 2. 관리자가 게시판 생성
  const board = await api.functional.discussionBoard.boards.post(connection, {
    body: {
      title: RandomGenerator.paragraph()(1),
      slug: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(board);

  // 3. 작성자가 게시글 작성
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: board.id,
      author_id: author.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 4. 댓글 작성(작성자)
  const comment = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: post.id,
      thread_id: post.id,
      author_id: author.id,
      body: RandomGenerator.content()()(),
      depth: 0,
    },
  });
  typia.assert(comment);

  // 5. 댓글 작성자가 본인 댓글 삭제(성공)
  const deleteResult = await api.functional.discussionBoard.comments.eraseById(connection, {
    id: comment.id,
  });
  typia.assert(deleteResult);
  TestValidator.predicate('본인 댓글 삭제 성공')(deleteResult.success === true);

  // 6. 이미 삭제된 댓글을 재삭제 시도(실패)
  await TestValidator.error('이미 삭제됨 - 중복 삭제 실패')(async () => {
    await api.functional.discussionBoard.comments.eraseById(connection, { id: comment.id });
  });

  // 7. 새로운 댓글 작성 후 다른 이용자(본인 아님)가 삭제 시도 (실패해야 함)
  const otherComment = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: post.id,
      thread_id: post.id,
      author_id: author.id,
      body: RandomGenerator.content()()(),
      depth: 0,
    },
  });
  typia.assert(otherComment);
  // (실제 인증 전환 없이 테스트 블록으로 롤 분리 simulation)
  await TestValidator.error('타인 댓글 삭제 불가')(async () => {
    await api.functional.discussionBoard.comments.eraseById(connection, { id: otherComment.id });
  });

  // 8. (가능하다면) 관리자 권한으로 댓글 삭제 허용 여부 (SDK 인증 전환 미제공, 직접 검증 불가)
  // 참고: 인증/역할 변환 API가 없으므로 스킵

  // 9. 무작위 존재하지 않는 UUID로 삭제 시도(실패)
  await TestValidator.error('존재하지 않는 댓글 삭제 실패')(async () => {
    await api.functional.discussionBoard.comments.eraseById(connection, { id: typia.random<string & tags.Format<'uuid'>>() });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated listing of discussion board posts with basic filtering.
 *
 * Business context:
 * This tests the main entry point for post discovery in a discussion board platform. All members can fetch paginated lists of posts, with or without query filters. The platform must return correct pagination metadata, post summaries, and handle empty board results gracefully.
 *
 * Test Steps:
 * 1. Register a member (for authentication & authorship)
 * 2. Create a discussion board
 * 3. Fetch posts with PATCH /discussionBoard/posts for the new (empty) board — expect empty results and correct pagination metadata.
 * 4. Create multiple posts on the board by that member
 * 5. List posts with PATCH /discussionBoard/posts using the board ID (no filters) and validate:
 *    - Correct number of posts is returned (matching what was created)
 *    - Pagination metadata matches expectations (current page, limit, total records)
 *    - Each listed post matches the board and contains essential summary fields
 *    - No duplicates, ordering is consistent
 * 6. Fetch another page (if possible)
 * 7. Validate empty page results/pagination when page is out-of-bounds.
 */
export async function test_api_discussionBoard_test_list_posts_with_basic_pagination(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "Password123*"
  };
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Create a discussion board
  const boardInput: IDiscussionBoardBoard.ICreate = {
    title: RandomGenerator.paragraph()(1),
    slug: RandomGenerator.alphaNumeric(8),
    description: RandomGenerator.paragraph()(),
  };
  const board = await api.functional.discussionBoard.boards.post(connection, {
    body: boardInput,
  });
  typia.assert(board);

  // 3. Fetch posts for new empty board
  let pageResp = await api.functional.discussionBoard.posts.patch(connection, {
    body: { board_id: board.id } satisfies IDiscussionBoardPost.IRequest,
  });
  typia.assert(pageResp);
  TestValidator.equals("empty page data")(pageResp.data.length)(0);
  TestValidator.equals("empty board pagination total records")(pageResp.pagination.records)(0);

  // 4. Create multiple posts as this member on this board
  const NUM_POSTS = 7;
  const createdPosts: IDiscussionBoardPost[] = [];
  for (let i = 0; i < NUM_POSTS; ++i) {
    const postInput: IDiscussionBoardPost.ICreate = {
      board_id: board.id,
      author_id: member.id,
      title: `Test Post ${i+1}`,
      body: RandomGenerator.content()()(),
    };
    const post = await api.functional.discussionBoard.posts.post(connection, {
      body: postInput,
    });
    typia.assert(post);
    createdPosts.push(post);
  }

  // 5. List first page (default paging) for board
  pageResp = await api.functional.discussionBoard.posts.patch(connection, {
    body: { board_id: board.id } satisfies IDiscussionBoardPost.IRequest,
  });
  typia.assert(pageResp);
  TestValidator.equals("number of posts")(pageResp.data.length)(NUM_POSTS);
  TestValidator.equals("pagination records matches")(pageResp.pagination.records)(NUM_POSTS);
  TestValidator.equals("correct page")(pageResp.pagination.current)(1);
  // Validate post summaries, each belongs to the board & has basic fields
  for (const row of pageResp.data) {
    TestValidator.equals("board_id matches")(row.board_id)(board.id);
    TestValidator.predicate("ID non-empty string")(!!row.id && typeof row.id === "string");
    TestValidator.predicate("title non-empty")(!!row.title && typeof row.title === "string");
    TestValidator.predicate("author_id exists")(!!row.author_id && typeof row.author_id === "string");
    TestValidator.equals("not deleted")(row.deleted_at)(null);
  }
  // Validate no duplicates
  const uniqueIDs = new Set(pageResp.data.map(r => r.id));
  TestValidator.equals("no duplicate post IDs")(uniqueIDs.size)(pageResp.data.length);

  // 6. (optional) Validate that out-of-bounds page returns empty data
  const outOfBoundsPage = Math.ceil(NUM_POSTS/2) + 10;
  const emptyPageResp = await api.functional.discussionBoard.posts.patch(connection, {
    body: { board_id: board.id, page: outOfBoundsPage } satisfies IDiscussionBoardPost.IRequest,
  });
  typia.assert(emptyPageResp);
  TestValidator.equals("empty data for out-of-bounds page")(emptyPageResp.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for filtering and sorting discussion board posts.
 *
 * This test covers advanced search/list functionality for discussion posts with various filters and sorting, thoroughly validating both business rules and core response contract. It ensures posts can be filtered by board, author, and basic pagination, and that invalid filters are handled correctly.
 *
 * **Test Workflow:**
 * 1. Create multiple discussion boards (different slugs/titles).
 * 2. Register multiple members (writers).
 * 3. Each member posts to multiple boards—diverse attributes/timestamps established via a matrix.
 * 4. Query post listing by:
 *    - Only board ID
 *    - Only author ID
 *    - Both board and author
 *    - Title filter (fuzzy search)
 *    - No filters (all posts)
 *    - Pagination (limit)
 *    - Sorting by created_at descending (using returned order)
 * 5. Check:
 *    - All filtered posts match filter values (board, author, title)
 *    - Pagination respected
 *    - Sorting order is descending by created_at
 * 6. Error paths: malformed board/author UUIDs result in error
 *
 * Relies only on provided SDK/DTO contracts and scenario; all token/context handled via standard API functions.
 */
export async function test_api_discussionBoard_test_search_posts_with_filters_and_sorting(
  connection: api.IConnection,
) {
  // 1. Create distinct boards
  const boards = await ArrayUtil.asyncRepeat(2)(async (i) => {
    const board = await api.functional.discussionBoard.boards.post(connection, {
      body: {
        title: `Board ${i + 1}`,
        slug: `board-${i + 1}-${RandomGenerator.alphaNumeric(8)}`,
        description: `Description for board ${i + 1}`,
      },
    });
    typia.assert(board);
    return board;
  });

  // 2. Register members
  const members = await ArrayUtil.asyncRepeat(2)(async (i) => {
    const member = await api.functional.discussionBoard.members.post(connection, {
      body: {
        username: `member_${i + 1}_${RandomGenerator.alphabets(5)}`,
        email: typia.random<string & tags.Format<"email">>(),
        display_name: `DisplayName${i + 1}`,
        password: "password123!@#",
      },
    });
    typia.assert(member);
    return member;
  });

  // 3. Create posts - each member posts to every board
  const postMatrix: IDiscussionBoardPost[][] = [];
  for (let memberIdx = 0; memberIdx < members.length; ++memberIdx) {
    const row: IDiscussionBoardPost[] = [];
    for (let boardIdx = 0; boardIdx < boards.length; ++boardIdx) {
      const post = await api.functional.discussionBoard.posts.post(connection, {
        body: {
          board_id: boards[boardIdx].id,
          author_id: members[memberIdx].id,
          title: `Title ${memberIdx + 1}-${boardIdx + 1}`,
          body: `Body for post ${memberIdx + 1}-${boardIdx + 1}`,
        },
      });
      typia.assert(post);
      row.push(post);
      // Delay ensures different timestamps (for sorting checks)
      await new Promise((r) => setTimeout(r, 10));
    }
    postMatrix.push(row);
  }
  const allPosts = postMatrix.flat();

  // 4. Filtering: board only
  const byBoard = await api.functional.discussionBoard.posts.patch(connection, {
    body: { board_id: boards[0].id },
  });
  typia.assert(byBoard);
  TestValidator.predicate("all posts match board")(byBoard.data.every((post) => post.board_id === boards[0].id));

  // Filtering: author only
  const byAuthor = await api.functional.discussionBoard.posts.patch(connection, {
    body: { author_id: members[1].id },
  });
  typia.assert(byAuthor);
  TestValidator.predicate("all posts match author")(byAuthor.data.every((post) => post.author_id === members[1].id));

  // Filtering: both board & author (matrix intersection)
  const byBoth = await api.functional.discussionBoard.posts.patch(connection, {
    body: { board_id: boards[1].id, author_id: members[0].id },
  });
  typia.assert(byBoth);
  TestValidator.equals("filtered post count")(byBoth.data.length)(1);
  TestValidator.equals("matching post's board")(byBoth.data[0].board_id)(boards[1].id);
  TestValidator.equals("matching post's author")(byBoth.data[0].author_id)(members[0].id);

  // Filtering: title (partial match)
  const byTitle = await api.functional.discussionBoard.posts.patch(connection, {
    body: { title: "Title " },
  });
  typia.assert(byTitle);
  TestValidator.predicate("title filter present")(byTitle.data.length > 0);
  TestValidator.predicate("filtered titles include search term")(byTitle.data.every((p) => p.title.includes("Title ")));

  // Pagination test: limit param
  const byLimit = await api.functional.discussionBoard.posts.patch(connection, {
    body: { limit: 1 },
  });
  typia.assert(byLimit);
  TestValidator.equals("limit respected")(byLimit.data.length)(1);
  TestValidator.predicate("pagination metadata honored")(byLimit.pagination.limit === 1);

  // Sorting: created_at descending (based on postMatrix timing/delays)
  const byDesc = await api.functional.discussionBoard.posts.patch(connection, {
    body: {},
  });
  typia.assert(byDesc);
  TestValidator.predicate("order is created_at desc")(
    byDesc.data.every((post, i, arr) => i === 0 || post.created_at <= arr[i - 1].created_at),
  );

  // 5. Error: invalid board_id (malformed UUID string)
  await TestValidator.error("invalid board_id")(() =>
    api.functional.discussionBoard.posts.patch(connection, {
      body: { board_id: "not-a-uuid" as any },
    }),
  );

  // Error: invalid author_id (malformed UUID string)
  await TestValidator.error("invalid author_id")(() =>
