 * will be forbidden and the API will respond with a 403 Forbidden error (no moderator or admin privilege
 * involved).
 *
 * Step-by-step process:
 * 1. Register the first member (author)
 * 2. Register the second member (non-author, will attempt the forbidden update)
 * 3. Create a new board
 * 4. Create a post in the new board as the first member
 * 5. Attempt to update the post as the second (non-author) member, expecting a 403 Forbidden error
 */
export async function test_api_discussionBoard_test_update_post_by_non_author_forbidden(connection: api.IConnection) {
  // 1. Register the first member (author)
  const member1Data = {
    username: RandomGenerator.alphabets(12),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "AuthorPass123!" as string & tags.Format<"password">,
