    title: RandomGenerator.paragraph()(1, 2),
    slug: RandomGenerator.alphabets(10).toLowerCase(),
    description: RandomGenerator.paragraph()(1, 2),
  };
  const board = await api.functional.discussionBoard.boards.post(connection, { body: boardData });
  typia.assert(board);

  // 4. Create a post as member1 (the author)
  const postData = {
    board_id: board.id,
    author_id: member1.id,
    title: RandomGenerator.paragraph()(1, 2),
    body: RandomGenerator.content()(1, 2, 64, 128),
  };
  const post = await api.functional.discussionBoard.posts.post(connection, { body: postData });
  typia.assert(post);

  // 5. Attempt to update the post as member2 (non-author), expecting a 403 error
  //
  // Note: In a real auth environment, the connection should be re-authenticated as member2 before this step.
