import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostSnapshot";

/**
 * Validates that unauthorized users and unauthenticated requests cannot delete a post snapshot in the discussion board.
 *
 * This test ensures permission enforcement for deletion of post snapshots by checking:
 *  - Another member (not the creator) is denied access
 *  - Unauthenticated (no login) access is denied
 *
 * Test Steps:
 * 1. Register member A (author/snapshot creator)
 * 2. Register member B (unauthorized user)
 * 3. Create a board
 * 4. Member A creates a post on the board
 * 5. Member A creates a snapshot for the post
 * 6. Member B attempts to delete the snapshot (should fail with permission error)
 * 7. An unauthenticated request attempts to delete the snapshot (should fail with permission error)
 *
 * Validates correct permission checks and proper error handling for unauthorized access scenarios.
 */
export async function test_api_discussionBoard_test_delete_post_snapshot_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. Register member A (the creator)
  const memberAInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "MemberA_password1!",
  };
  const memberA = await api.functional.discussionBoard.members.post(connection, {
    body: memberAInput,
  });
  typia.assert(memberA);

  // 2. Register member B (unauthorized account)
  const memberBInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "MemberB_password2!",
  };
  const memberB = await api.functional.discussionBoard.members.post(connection, {
    body: memberBInput,
  });
  typia.assert(memberB);

  // 3. Create a new board
  const boardInput: IDiscussionBoardBoard.ICreate = {
    title: RandomGenerator.paragraph()(1),
    slug: RandomGenerator.alphaNumeric(12),
    description: RandomGenerator.paragraph()(1),
  };
  const board = await api.functional.discussionBoard.boards.post(connection, {
    body: boardInput,
  });
  typia.assert(board);

  // 4. Member A creates a post on the board
  const postInput: IDiscussionBoardPost.ICreate = {
    board_id: board.id,
    author_id: memberA.id,
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(1),
  };
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: postInput,
  });
  typia.assert(post);

  // 5. Member A creates a snapshot for the post
  const snapshotInput: IDiscussionBoardPostSnapshot.ICreate = {
    post_id: post.id,
    created_by_id: memberA.id,
    title: post.title,
    body: post.body,
  };
  const snapshot = await api.functional.discussionBoard.postSnapshots.post(connection, {
    body: snapshotInput,
  });
  typia.assert(snapshot);

  // 6. Member B attempts to delete the snapshot (permission denied expected)
  // Simulate as member B (auth context is updated if system tracks last join)
  await TestValidator.error("Member B cannot delete another member's snapshot")(
    () => api.functional.discussionBoard.postSnapshots.eraseById(connection, { id: snapshot.id }),
  );

  // 7. Unauthenticated request attempts to delete the snapshot (should fail)
  const unauthConn = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("Unauthenticated request cannot delete snapshot")(
    () => api.functional.discussionBoard.postSnapshots.eraseById(unauthConn, { id: snapshot.id }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportLog";
import type { IPageIDiscussionBoardReportLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardReportLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing report logs with various filters and pagination, including role-based access control.
 *
 * This function validates the Discussion Board report logs list endpoint:
 * - Returns correct, paginated log lists for moderators/admins
 * - Supports filter: report ID, actor (moderator/admin), action type, date range
 * - Verifies edge behaviors (empty results, pagination excess, malformed body)
 * - Ensures regular members CANNOT access the endpoint (skipped; no auth API)
 * - Confirms correct error handling for invalid filters/values
 *
 * Test workflow:
 * 1. Create a regular member and a moderator member
 * 2. As a regular member, create a sample report
 * 3. As moderator, create a report log for that report
 * 4. As moderator, list logs by various filters (report_id, actor_moderator_id, action, date range)
 * 5. List logs with filters that return empty results
 * 6. Paginate beyond available pages and assert empty list
 * 7. Submit malformed request bodies or bad input, confirm error
 * 8. Attempt to access with insufficient permissions is commented/skipped (no login API to switch roles)
 * 9. Validate presence of pagination metadata in responses
 */
export async function test_api_discussionBoard_test_list_report_logs_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create regular member and moderator
  const regularMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "TestP@ssw0rd"
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(regularMember);

  const moderatorMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "TestP@ssw0rd"
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(moderatorMember);

  // [SKIP: role elevation to true moderator requires external support, so we use created ID as if privileged]

  // 2. Regular member creates a report
  const report = await api.functional.discussionBoard.reports.post(connection, {
    body: {
      reported_by_member_id: regularMember.id,
      report_category_id: typia.random<string & tags.Format<"uuid">>(),
      target_post_id: typia.random<string & tags.Format<"uuid">>(),
      target_comment_id: null,
      description: RandomGenerator.paragraph()()
    } satisfies IDiscussionBoardReport.ICreate
  });
  typia.assert(report);

  // 3. Moderator creates a report log for the report
  const reportLog = await api.functional.discussionBoard.reportLogs.post(connection, {
    body: {
      report_id: report.id,
      actor_moderator_id: moderatorMember.id,
      action: "REVIEWED",
      action_comment: "Moderation review comment"
    } satisfies IDiscussionBoardReportLog.ICreate
  });
  typia.assert(reportLog);

  // 4. List logs with filters: report_id, actor_moderator_id, action, date range
  let logsPage = await api.functional.discussionBoard.reportLogs.patch(connection, {
    body: {
      report_id: report.id,
      page: 1,
      limit: 10
    } satisfies IDiscussionBoardReportLog.IRequest
  });
  typia.assert(logsPage);
  TestValidator.predicate("contains created report log")(
    logsPage.data.some(x => x.id === reportLog.id)
  );

  logsPage = await api.functional.discussionBoard.reportLogs.patch(connection, {
    body: {
      actor_moderator_id: moderatorMember.id,
      page: 1,
      limit: 10
    } satisfies IDiscussionBoardReportLog.IRequest
  });
  typia.assert(logsPage);
  TestValidator.predicate("contains created report log (moderator)")(
    logsPage.data.some(x => x.id === reportLog.id)
  );

  logsPage = await api.functional.discussionBoard.reportLogs.patch(connection, {
    body: {
      action: "REVIEWED",
      page: 1,
      limit: 10
    } satisfies IDiscussionBoardReportLog.IRequest
  });
  typia.assert(logsPage);
  TestValidator.predicate("contains created report log (action)")(
    logsPage.data.some(x => x.id === reportLog.id)
  );

  logsPage = await api.functional.discussionBoard.reportLogs.patch(connection, {
    body: {
      created_from: new Date(Date.now() - 5 * 60 * 1000).toISOString(),
      created_to: new Date(Date.now() + 5 * 60 * 1000).toISOString(),
      page: 1,
      limit: 10
    } satisfies IDiscussionBoardReportLog.IRequest
  });
  typia.assert(logsPage);
  TestValidator.predicate("contains created report log (date range)")(
    logsPage.data.some(x => x.id === reportLog.id)
  );

  // 5. Filters that match nothing
  logsPage = await api.functional.discussionBoard.reportLogs.patch(connection, {
    body: {
      report_id: typia.random<string & tags.Format<"uuid">>(),
      page: 1,
      limit: 10
    } satisfies IDiscussionBoardReportLog.IRequest
  });
  typia.assert(logsPage);
  TestValidator.equals("empty data for unmatched report")(
    logsPage.data
  )([]);

  // 6. Extreme page value (beyond available pages/records)
  logsPage = await api.functional.discussionBoard.reportLogs.patch(connection, {
    body: {
      page: 9999,
      limit: 10
    } satisfies IDiscussionBoardReportLog.IRequest
  });
  typia.assert(logsPage);
  TestValidator.equals("empty data for high page number")(logsPage.data)([]);

  // 7. Bad input and malformed bodies (runtime failures, not TS type errors)
  await TestValidator.error("invalid uuid for report_id")(() =>
    api.functional.discussionBoard.reportLogs.patch(connection, {
      body: {
        report_id: "not-a-uuid"
      } as any
    })
  );

  await TestValidator.error("malformed request body")(async () =>
    api.functional.discussionBoard.reportLogs.patch(connection, {
      body: { page: "str", limit: null } as any
    })
  );

  // 8. Skipped: regular member access denial (no role switch/login API available)
  // await TestValidator.error("regular member forbidden")(...)

  // 9. Pagination object structural check
  TestValidator.predicate("pagination fields present")(
    typeof logsPage.pagination.current === "number" &&
      typeof logsPage.pagination.limit === "number" &&
      typeof logsPage.pagination.records === "number" &&
      typeof logsPage.pagination.pages === "number"
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportLog";

/**
 * Validate permissions and retrieval accuracy for fetching a discussion board report log by ID.
 *
 * This test confirms:
 * 1. When a valid report log exists and is fetched by an authorized moderator/admin, all returned properties match what was saved.
 * 2. When attempting to fetch a non-existent log, a not found error is returned.
 * 3. Scenarios involving unauthorized access or soft-deleted logs are noted but omitted, as related APIs are not provided.
 *
 * Steps:
 * 1. Create a report (so a report log can reference it)
 * 2. Generate a fake moderator/admin actor ID
 * 3. Create a report log referencing the above
 * 4. Fetch the log by its id, assert all properties match
 * 5. Try to fetch a random (non-existent) log id, expect a not found error
 */
export async function test_api_discussionBoard_test_get_report_log_by_id_as_authorized_and_unauthorized_user(
  connection: api.IConnection,
) {
  // 1. Create a report to reference in the log
  const report = await api.functional.discussionBoard.reports.post(connection, {
    body: {
      reported_by_member_id: typia.random<string & tags.Format<"uuid">>(),
      report_category_id: typia.random<string & tags.Format<"uuid">>(),
      target_post_id: typia.random<string & tags.Format<"uuid">>(),
      description: "Offensive post for testing",
    },
  });
  typia.assert(report);

  // 2. Generate a fake moderator/admin actor id
  const moderator_id = typia.random<string & tags.Format<"uuid">>();

  // 3. Create a report log
  const log = await api.functional.discussionBoard.reportLogs.post(connection, {
    body: {
      report_id: report.id,
      actor_moderator_id: moderator_id,
      action: "RESOLVE",
      action_comment: "Issue resolved.",
    },
  });
  typia.assert(log);

  // 4. Fetch the log by id, assert all main fields match
  const read = await api.functional.discussionBoard.reportLogs.getById(connection, {
    id: log.id,
  });
  typia.assert(read);
  TestValidator.equals("log id matches")(read.id)(log.id);
  TestValidator.equals("report id matches")(read.report_id)(report.id);
  TestValidator.equals("actor moderator id matches")(read.actor_moderator_id)(moderator_id);
  TestValidator.equals("action matches")(read.action)("RESOLVE");
  TestValidator.equals("comment matches")(read.action_comment)("Issue resolved.");
  // timestamp validity (format, presence) is enforced by typia.assert

  // 5. Fetch a non-existent log, expect not found error
  await TestValidator.error("log not found for unknown id")(async () => {
    await api.functional.discussionBoard.reportLogs.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // Note: Unauthorized access or deleted log cases are omitted (no API support)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportLog";

/**
 * 신고 처리 로그 생성(유효/무효 입력값 모두) 테스트
 *
 * 신고 처리 로그 생성 API의 정상 및 실패 케이스를 검증한다.
 *
 * - 선행적으로 연결될 신고 엔티티를 등록한다.
 * - 정상: 존재하는 신고ID/담당자ID/액션/코멘트 등 유효 값으로 로그 생성, 모든 필드가 정확함을 asserts로 확인
 * - 오류: 필수 필드 누락(컴파일러 레벨에서는 TypeScript 타입오류로 테스트 불가이므로, 실제 호출은 스킵), 존재하지 않는 신고ID/잘못된 action 등 실 런타임에서 발생 가능한 오류 케이스 체크
 * - 모든 결과는 audit log 정확성, 필드 유효성(타입, 값)까지 assert 수행
 */
export async function test_api_discussionBoard_test_create_report_log_with_valid_and_invalid_inputs(
  connection: api.IConnection,
) {
  // 1. 신고(reports) 엔티티 생성 - 로그 연결에 필요
  const report: IDiscussionBoardReport = await api.functional.discussionBoard.reports.post(connection, {
    body: {
      reported_by_member_id: typia.random<string & tags.Format<"uuid">>(),
      report_category_id: typia.random<string & tags.Format<"uuid">>(),
      description: "테스트 신고 설명",
      target_post_id: typia.random<string & tags.Format<"uuid">>(),
      target_comment_id: null,
    } satisfies IDiscussionBoardReport.ICreate,
  });
  typia.assert(report);

  const valid_report_id = report.id;
  const valid_actor_id = typia.random<string & tags.Format<"uuid">>();

  // 2. 정상 입력 시 로그 생성 → 결과 assert
  const validLogInput: IDiscussionBoardReportLog.ICreate = {
    report_id: valid_report_id,
    actor_moderator_id: valid_actor_id,
    action: "reviewed",
    action_comment: "정상 처리 코멘트",
  };
  const log: IDiscussionBoardReportLog = await api.functional.discussionBoard.reportLogs.post(connection, {
    body: validLogInput,
  });
  typia.assert(log);
  TestValidator.equals("로그-리포트ID")(log.report_id)(valid_report_id);
  TestValidator.equals("로그-담당자ID")(log.actor_moderator_id)(valid_actor_id);
  TestValidator.equals("로그-액션")(log.action)("reviewed");
  TestValidator.equals("로그-코멘트")(log.action_comment)("정상 처리 코멘트");
  TestValidator.predicate("로그-생성타임스탬프 유효")(
    typeof log.timestamp === "string" && log.timestamp.length > 0,
  );

  // 3. 필수 필드 누락 케이스(타입 컴파일러가 체크하는 부분, 실제 호출 불가): SKIP
  //    - report_id, actor_moderator_id, action 누락 테스트는 TypeScript 타입 시스템이 잡아내므로 실제 코드 실행은 생략

  // 4. 존재하지 않는 신고ID 사용
  await TestValidator.error("존재하지 않는 신고ID로 로그 생성")(() =>
    api.functional.discussionBoard.reportLogs.post(connection, {
      body: {
        report_id: typia.random<string & tags.Format<"uuid">>(),
        actor_moderator_id: valid_actor_id,
        action: "reviewed"
      } satisfies IDiscussionBoardReportLog.ICreate,
    }),
  );
  // 5. 잘못된 action 값(빈문자열)
  await TestValidator.error("잘못된 액션(빈문자열)")(() =>
    api.functional.discussionBoard.reportLogs.post(connection, {
      body: {
        report_id: valid_report_id,
        actor_moderator_id: valid_actor_id,
        action: ""
      } satisfies IDiscussionBoardReportLog.ICreate,
    }),
  );
  // 6. 잘못된 action 값(null) → 타입차원에서 불가하지만 방어적으로 케이스 커버
  await TestValidator.error("잘못된 액션(null)")(() =>
    api.functional.discussionBoard.reportLogs.post(connection, {
      body: {
        report_id: valid_report_id,
        actor_moderator_id: valid_actor_id,
        action: null as any,
      } as any,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportLog";

/**
 * Validate updating report log entries with permissions and validation scenarios.
 *
 * This test ensures the update endpoint for discussion board report logs is secure, correctly enforces permissions, and validates input. It also confirms audit trails and error handling. The target endpoint is /discussionBoard/reportLogs/{id} (PUT).
 *
 * Test workflow:
 * 1. Create a report (to obtain a valid report ID for log linkage)
 * 2. Create a report log entry as an authorized moderator/admin
 * 3. Update the log as a moderator or admin: change action, action_comment
 *    - Verify returned object is updated, audit trail fields are untouched
 * 4. Attempt to update the log as an unauthorized (non-moderator) user:
 *    - Expect a permission denied error
 * 5. Attempt invalid updates: invalid action value (should fail validation)
 * 6. Attempt to update a non-existent or already soft-deleted log ID:
 *    - Expect not found or error response
 */
export async function test_api_discussionBoard_test_update_report_log_with_permissions_and_validation(connection: api.IConnection) {
  // 1. Create a report
  const report = await api.functional.discussionBoard.reports.post(connection, {
    body: {
      reported_by_member_id: typia.random<string & tags.Format<"uuid">>(),
      report_category_id: typia.random<string & tags.Format<"uuid">>(),
      description: "Test report for log update",
      target_post_id: typia.random<string & tags.Format<"uuid">>(),
    }
  });
  typia.assert(report);

  // 2. Create a log entry
  const log = await api.functional.discussionBoard.reportLogs.post(connection, {
    body: {
      report_id: report.id,
      actor_moderator_id: typia.random<string & tags.Format<"uuid">>(),
      action: "assigned",
      action_comment: "Initial assignment."
    }
  });
  typia.assert(log);

  // 3. Update log (authorized)
  const updatedAction = "resolved";
  const updatedComment = "Report resolved with note.";
  const logUpdate = await api.functional.discussionBoard.reportLogs.putById(connection, {
    id: log.id,
    body: {
      action: updatedAction,
      action_comment: updatedComment,
    }
  });
  typia.assert(logUpdate);
  TestValidator.equals("id unchanged")(logUpdate.id)(log.id);
  TestValidator.equals("report id unchanged")(logUpdate.report_id)(log.report_id);
  TestValidator.equals("action updated")(logUpdate.action)(updatedAction);
  TestValidator.equals("action_comment updated")(logUpdate.action_comment)(updatedComment);

  // 4. Update as unauthorized user - expect error
  // In a real implementation, user role switch/auth would be required;
  // This simulates an unauthorized update attempt and expects access to be denied by backend policy.
  TestValidator.error("permission denied updating as unauthorized")(
    async () => {
      await api.functional.discussionBoard.reportLogs.putById(connection, {
        id: log.id,
        body: {
          action: "rejected",
          action_comment: "Tried without permission"
        }
      });
    }
  );

  // 5. Invalid action value (should be rejected if system restricts allowed actions)
  TestValidator.error("invalid action value should fail")(
    async () => {
      await api.functional.discussionBoard.reportLogs.putById(connection, {
        id: log.id,
        body: {
          action: "thisIsNotARealAction",
          action_comment: "Should fail validation"
        }
      });
    }
  );

  // 6. Update non-existent log ID
  TestValidator.error("update nonexistent log")(async () => {
    await api.functional.discussionBoard.reportLogs.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // random likely non-existent
      body: {
        action: "resolved",
        action_comment: "Update non-existent log"
      }
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportLog";

/**
 * Validate the deletion (soft-deletion) of a report log by moderator/admin and error/edge cases.
 *
 * This test covers:
 * 1. Creating a report and a corresponding report log, as setup.
 * 2. Successfully deleting the report log as a moderator or admin (should succeed, perform soft-delete).
 * 3. Attempting to delete the same log as an unauthorized user (should fail with a permission error).
 * 4. Attempting to delete a non-existent report log (should fail with not found error, not affecting system state).
 * 5. Attempting to delete a report log already deleted (should fail gracefully).
 * 6. Verifying audit logging occurred for delete actions as required.
 *
 * Steps:
 * - Prepare: Create a report, then create a report log referencing that report (using dependencies).
