 * - That a new section can be successfully registered under an existing channel by an admin
 * - Section names are unique within a channel (duplicate check)
 * - Sections become accessible and return correct structure immediately post-creation
 * - Only valid API DTOs and endpoints are used, with all references and constraints followed
 *
 * Workflow:
 * 1. Create a parent channel (admin action)
 * 2. Register a section with a unique name and description for the channel
 * 3. Assert the new section references the correct channel id and fields
 * 4. Attempt to create another section with the same name under the same channel (should error—uniqueness)
 * 5. Create a second channel
 * 6. Register a section using the same name under the new channel (should succeed: uniqueness only within a single channel)
 */
export async function test_api_discussionBoard_test_create_section_with_valid_data_by_admin(
  connection: api.IConnection,
) {
  // 1. Create parent channel
  const channelName = RandomGenerator.alphaNumeric(12);
  const channel = await api.functional.discussionBoard.channels.post(connection, {
    body: {
      name: channelName,
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(channel);

  // 2. Register unique section for this channel
  const sectionName = RandomGenerator.alphaNumeric(14);
  const sectionDescription = RandomGenerator.paragraph()();
  const section = await api.functional.discussionBoard.sections.post(connection, {
    body: {
      discussionboard_channel_id: channel.id,
      name: sectionName,
      description: sectionDescription,
    },
  });
