  TestValidator.equals("channel id matches")(section.discussionboard_channel_id)(channel.id);
  TestValidator.equals("section name matches")(section.name)(sectionName);
  TestValidator.equals("section desc matches")(section.description)(sectionDescription);
  TestValidator.predicate("created_at populated")(!!section.created_at);
  TestValidator.predicate("updated_at populated")(!!section.updated_at);
  TestValidator.equals("not deleted")(section.deleted_at)(null);

  // 3. Uniqueness constraint: attempt duplicate section name in same channel (should error)
  await TestValidator.error("duplicate section name in same channel should fail")(() =>
    api.functional.discussionBoard.sections.post(connection, {
      body: {
        discussionboard_channel_id: channel.id,
        name: sectionName,
        description: RandomGenerator.paragraph()(),
      },
    }),
  );

  // 4. Create second channel
  const channel2 = await api.functional.discussionBoard.channels.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(channel2);

  // 5. Section with same name in different channel should succeed
  const altSection = await api.functional.discussionBoard.sections.post(connection, {
    body: {
      discussionboard_channel_id: channel2.id,
      name: sectionName,
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(altSection);
  TestValidator.equals("channel id for alt section")(altSection.discussionboard_channel_id)(channel2.id);
  TestValidator.equals("alt section name")(altSection.name)(sectionName);
}

