/**
 * 테스트 목적: 관리자가 섹션 메타데이터(이름, 설명 등)를 정상적으로 수정할 수 있는지 검증한다.
 *
 * 주요 시나리오:
 * 1. 부모 채널을 생성한다 (외래키 제약 충족).
 * 2. 생성된 채널 하위에 새로운 섹션을 만든다.
 * 3. 생성된 섹션의 메타데이터(이름, 설명 등)를 관리자가 일부 수정한다.
 * 4. API 응답 결과가 실제 변경 내용을 정확히 반영하는지, 그리고 updated_at 필드 등 감시 필드가 갱신되는지 검증한다.
 *
 * 검증 포인트:
 * - 이름 및 설명 등의 수정 후 값이 적용되는지
 * - updated_at 필드 값이 변경 전과 다르게 갱신되는지
 * - 불필요한 필드(예: id, 생성일자)가 변하지 않는지
 */
export async function test_api_discussionBoard_test_update_section_metadata_success_by_admin(
  connection: api.IConnection,
) {
  // 1. 부모 채널 생성
  const channel = await api.functional.discussionBoard.channels.post(connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(2),
    } satisfies IDiscussionBoardChannel.ICreate,
  });
  typia.assert(channel);

  // 2. 섹션 생성
  const section = await api.functional.discussionBoard.sections.post(connection, {
    body: {
      discussionboard_channel_id: channel.id,
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(2),
    } satisfies IDiscussionBoardSection.ICreate,
  });
  typia.assert(section);

  // 3. 현재 updated_at 시점 저장
  const beforeUpdateAt = section.updated_at;

  // 4. 이름/설명 수정(빈 문자열/변경 문자열 등 다양한 케이스 대응)
  const updatedName = RandomGenerator.paragraph()(1) + "-수정";
  const updatedDescription = RandomGenerator.paragraph()(2) + " (설명수정)";
  const updated = await api.functional.discussionBoard.sections.putById(connection, {
    id: section.id,
    body: {
      name: updatedName,
      description: updatedDescription,
    } satisfies IDiscussionBoardSection.IUpdate,
  });
  typia.assert(updated);

  // 5. 필드 변경사항 검증
  TestValidator.notEquals("updated_at 갱신됨")(updated.updated_at)(beforeUpdateAt);
