  const update: IDiscussionBoardReport.IUpdate = {
    status: "resolved",
    report_category_id: typia.random<string & tags.Format<"uuid">>(),
    description: "Reviewed and resolved by moderator.",
    resolved_at: new Date().toISOString() as string & tags.Format<"date-time">,
