  TestValidator.equals("status updated")(updated.status)(update.status);
  if (update.report_category_id)
    TestValidator.equals("category updated")(updated.report_category_id)(update.report_category_id);
  if (update.description)
    TestValidator.equals("description updated")(updated.description)(update.description);
  if (update.resolved_at)
    TestValidator.equals("resolved_at updated")(updated.resolved_at)(update.resolved_at);

