import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentEdit";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentEdit";

/**
 * Test paginated and filterable retrieval of comment edit records for admin and regular members.
 *
 * This E2E test function verifies the /discussionBoard/commentEdits PATCH API endpoint's ability to:
 * - Filter by editor_id, comment_id, and date range
 * - Respect access control (admin sees all, regular user sees only their edits)
 * - Paginate results (one page and multi page)
 * - Return empty results on unmatched filters
 * - Handle malformed filter parameters (e.g., invalid uuid)
 *
 * Steps:
 * 1. Register three members: admin, userA, userB with unique emails/usernames
 * 2. Generate several comment UUIDs
 * 3. For each member, create multiple comment edit records referencing the comment UUIDs (simulate edit history)
 * 4. As admin (by using admin's editor_id in filter):
 *    - Filter by userA's editor_id: retrieve only userA's edits (check pagination, boundaries)
 *    - Filter by comment_id, by created_after/before ranges
 *    - Filter by non-existent comment_id: result is empty
 * 5. As userB:
 *    - Retrieve edits with no filter: only userB's own edits are returned
 *    - Attempt to use editor_id for userA: result is empty
 * 6. Send malformed filter input (invalid uuid in comment_id): API error is thrown
 */
export async function test_api_discussionBoard_test_list_comment_edits_as_admin_and_regular_user(
  connection: api.IConnection,
) {
  // 1. Register admin, userA, userB
  const email_admin = typia.random<string & tags.Format<"email">>();
  const email_userA = typia.random<string & tags.Format<"email">>();
  const email_userB = typia.random<string & tags.Format<"email">>();

  const admin = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: email_admin,
      display_name: RandomGenerator.name(),
      password: "adminPass123!"
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(admin);

  const userA = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: email_userA,
      display_name: RandomGenerator.name(),
      password: "userAPass456!"
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(userA);

  const userB = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: email_userB,
      display_name: RandomGenerator.name(),
      password: "userBPass789!"
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(userB);

  // 2. Generate comment UUIDs
  const NUM_COMMENTS = 3;
  const commentIds = ArrayUtil.repeat(NUM_COMMENTS)(() =>
    typia.random<string & tags.Format<"uuid">>()
  );

  // Helper to create a date spaced N minutes from now (for edit timestamps)
  function dateOffset(minutes: number): string {
    return new Date(Date.now() + minutes * 60 * 1000).toISOString();
  }

  // 3. Create multiple comment edit records for all three members
  const edits: { member: IDiscussionBoardMember; edits: IDiscussionBoardCommentEdit[] }[] = [];
  const editsPerUser = 4;
  const allMembers = [admin, userA, userB];

  for (const [idx, member] of allMembers.entries()) {
    const records: IDiscussionBoardCommentEdit[] = [];
    for (let i = 0; i < editsPerUser; ++i) {
      const comment_id = commentIds[(idx + i) % commentIds.length];
      const edit: IDiscussionBoardCommentEdit = await api.functional.discussionBoard.commentEdits.post(
        connection,
        {
          body: {
            comment_id,
            editor_id: member.id,
            edit_summary: `Edit summary ${member.username} ${i}`,
            body_after_edit: `Edit body for ${member.username} ${i}`,
          } satisfies IDiscussionBoardCommentEdit.ICreate,
        }
      );
      typia.assert(edit);
      records.push(edit);
    }
    edits.push({ member, edits: records });
  }

  // Find time ranges for date-based filters
  const firstEdit = edits[1].edits[0]; // userA's first edit
  const lastEdit = edits[1].edits[editsPerUser - 1]; // userA's last edit

  // 4. As admin: filter by userA's editor_id
  let pageLimit = 2; // Small limit to test pagination
  // First page
  let page1 = await api.functional.discussionBoard.commentEdits.patch(connection, {
    body: {
      editor_id: userA.id,
      paging: { page: 1, limit: pageLimit },
    } satisfies IDiscussionBoardCommentEdit.IRequest,
  });
  typia.assert(page1);
  TestValidator.predicate("Correct number of edits on first page")(
    page1.data.length === Math.min(pageLimit, editsPerUser)
  );
  TestValidator.predicate("Pagination page 1 current correct")(
    page1.pagination.current === 1
  );

  // Second page
  let page2 = await api.functional.discussionBoard.commentEdits.patch(connection, {
    body: {
      editor_id: userA.id,
      paging: { page: 2, limit: pageLimit },
    } satisfies IDiscussionBoardCommentEdit.IRequest,
  });
  typia.assert(page2);
  TestValidator.predicate("Correct number of edits on second page")(
    page2.data.length === editsPerUser - pageLimit
  );
  TestValidator.predicate("Pagination page 2 current correct")(
    page2.pagination.current === 2
  );

  // Verify all returned edits on both pages belong to userA
  for (const page of [page1, page2]) {
    for (const edit of page.data) {
      TestValidator.equals("editor is userA")(edit.editor_id)(userA.id);
    }
  }

  // Filter by comment_id for one of userA's edits
  const filterCommentId = edits[1].edits[0].comment_id;
  const commentIdResults = await api.functional.discussionBoard.commentEdits.patch(connection, {
    body: {
      comment_id: filterCommentId,
      paging: { page: 1, limit: editsPerUser },
    } satisfies IDiscussionBoardCommentEdit.IRequest,
  });
  typia.assert(commentIdResults);
  // Only edits for that comment (could be by any user)
  for (const edit of commentIdResults.data) {
    TestValidator.equals("Filtered comment_id matches")(edit.comment_id)(filterCommentId);
  }

  // Filter by created_after/before
  const after = firstEdit.created_at;
  const before = lastEdit.created_at;
  const limited = await api.functional.discussionBoard.commentEdits.patch(connection, {
    body: {
      editor_id: userA.id,
      created_after: after,
      created_before: before,
      paging: { page: 1, limit: editsPerUser },
    } satisfies IDiscussionBoardCommentEdit.IRequest,
  });
  typia.assert(limited);
  for (const edit of limited.data) {
    TestValidator.predicate("Edit timestamp in range")(
      edit.created_at >= after && edit.created_at < before
    );
    TestValidator.equals("editor is userA")(edit.editor_id)(userA.id);
  }

  // Filter by random UUID (no edits for this comment_id)
  const randomCommentId = typia.random<string & tags.Format<"uuid">>();
  const emptyResult = await api.functional.discussionBoard.commentEdits.patch(connection, {
    body: {
      comment_id: randomCommentId,
      paging: { page: 1, limit: 5 },
    } satisfies IDiscussionBoardCommentEdit.IRequest,
  });
  typia.assert(emptyResult);
  TestValidator.equals("No data for random comment_id")(emptyResult.data.length)(0);

  // 5. As userB: should only see userB's edits
  // Simulate userB context: use editor_id=userB.id filter (no authentication separation supported)
  const userBResults = await api.functional.discussionBoard.commentEdits.patch(connection, {
    body: {
      paging: { page: 1, limit: 10 },
    } satisfies IDiscussionBoardCommentEdit.IRequest,
  });
  typia.assert(userBResults);
  // All edits in result should have editor_id of userB (API reflects user context)
  for (const edit of userBResults.data) {
    TestValidator.equals("Only userB edits returned")(edit.editor_id)(userB.id);
  }

  // Try to get userA's edits as userB: should get empty data
  const forbidden = await api.functional.discussionBoard.commentEdits.patch(connection, {
    body: {
      editor_id: userA.id,
      paging: { page: 1, limit: 10 },
    } satisfies IDiscussionBoardCommentEdit.IRequest,
  });
  typia.assert(forbidden);
  TestValidator.equals("userB cannot view userA's edits")(forbidden.data.length)(0);

  // 6. Malformed input: invalid UUID
  await TestValidator.error("Malformed UUID for comment_id triggers error")(
    async () => {
      await api.functional.discussionBoard.commentEdits.patch(connection, {
        body: {
          comment_id: "not-a-uuid" as any, // intentional type violation in runtime test
          paging: { page: 1, limit: 5 },
        } as any, // INTENTIONALLY breaking type at runtime to test business error
      });
    }
  );
}

