/**
 * Test retrieving full details of a specific notification by its ID as the owning user.
 *
 * Validates that a user can only see their own notifications with full field visibility,
 * and that access control is enforced for non-existent or unauthorized IDs.
 *
 * Workflow:
 * 1. Register a discussion board member.
 * 2. Create a notification assigned to this member.
 * 3. Fetch the notification as the owner and validate all relevant fields.
 * 4. Attempt to fetch a notification using a random (non-existent) ID and confirm error is raised.
 */
export async function test_api_discussionBoard_test_get_notification_detail_for_owner_user(
  connection: api.IConnection,
) {
  // 1. Create a discussion board member (user registration)
  const userInput = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.alphabets(8),
    password: RandomGenerator.alphabets(12),
  } satisfies IDiscussionBoardMember.ICreate;
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: userInput,
  });
  typia.assert(member);

  // 2. Create a notification for this member
  const notifInput = {
    recipient_member_id: member.id,
    type: "mention",
    delivered_at: new Date().toISOString(),
    trigger_actor_id: null,
    target_post_id: null,
    target_comment_id: null,
    target_report_id: null,
    target_section_id: null,
  } satisfies DiscussionBoardNotification.ICreate;
  const notification = await api.functional.discussionBoard.notifications.post(connection, {
    body: notifInput,
  });
  typia.assert(notification);

  // 3. Fetch the notification by its ID as the owning user
  const detail = await api.functional.discussionBoard.notifications.getById(
    connection,
    { id: notification.id },
  );
  typia.assert(detail);
  TestValidator.equals("id")(detail.id)(notification.id);
  TestValidator.equals("recipient_member_id")(detail.recipient_member_id)(member.id);
  TestValidator.equals("type")(detail.type)(notifInput.type);
  TestValidator.equals("delivered_at")(detail.delivered_at)(notifInput.delivered_at);
  // Optionally check other fields for null if all were set to null
  TestValidator.equals("trigger_actor_id")(detail.trigger_actor_id)(null);
  TestValidator.equals("target_post_id")(detail.target_post_id)(null);
  TestValidator.equals("target_comment_id")(detail.target_comment_id)(null);
  TestValidator.equals("target_report_id")(detail.target_report_id)(null);
  TestValidator.equals("target_section_id")(detail.target_section_id)(null);

  // 4. Attempt to fetch a non-existent notification ID (negative test)
  await TestValidator.error("not found for non-existent notification")(() =>
    api.functional.discussionBoard.notifications.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

