 * - B의 사용자 인증으로 알림 상세조회 시도
 *
 * ## 기대 결과
 * - 본인(A)이 아닌 B가 접근하면 서버는 반드시 권한 오류(403 등)를 반환해야 한다.
 * - 상세 데이터 노출 없이, 명확한 접근 거부만 발생해야 한다.
 */
export async function test_api_discussionBoard_test_get_notification_detail_by_non_owner_forbidden(
  connection: api.IConnection,
) {
  // 1. 회원 A(수신자) 계정 생성
  const memberA = await api.functional.discussionBoard.members.post(connection, {
    body: {
