  const memberB = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "Password123!",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberB);

  // 3. 회원 A에게 알림 생성 (트리거=B)
  const notification = await api.functional.discussionBoard.notifications.post(connection, {
    body: {
      recipient_member_id: memberA.id,
      trigger_actor_id: memberB.id,
      type: "mention",
      delivered_at: new Date().toISOString(),
