  const bConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      "x-mock-user-id": memberB.id,
    },
  };

  // 5. B가 A의 알림 상세에 접근 시도 → 반드시 실패해야 함
  await TestValidator.error("비수신자 접근 차단")(() =>
    api.functional.discussionBoard.notifications.getById(bConnection, { id: notification.id })
  );
}

