  const recipient = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: typia.random<string & tags.Format<"password">>(),
    },
  });
  typia.assert(recipient);

  // 2. 관리자 계정 + 관리자 역할 등록 (관리자 인증 상태 처리)
  const admin_member = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: typia.random<string & tags.Format<"password">>(),
    },
  });
  typia.assert(admin_member);
  const admin = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: admin_member.id,
      appointed_by_admin_id: admin_member.id,
    },
  });
