import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { DiscussionBoardBusinessRules } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardBusinessRules";
import type { DiscussionBoardPageBusinessRules } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardPageBusinessRules";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardBusinessRules } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBusinessRules";

/**
 * Test paginated and filtered retrieval of business rules as admin and non-admin users.
 *
 * This test exercises the PATCH /discussionBoard/businessRules endpoint. The aim is to validate that the endpoint correctly implements filtering by business rule key, value, and description, and supports pagination parameters. It should also enforce permissions so only admin users can view the listing, and handle error cases (invalid filters, non-admin access) properly.
 *
 * Test process:
 * 1. Create a discussion board member and simulate admin privileges.
 * 2. Create two distinct business rules (with unique keys and values).
 * 3. As admin:
 *     a. Retrieve all business rules; verify both exist.
 *     b. Filter by exact key, value, and description (individually and in combination), and confirm only matching business rules are returned.
 *     c. Paginate with limit=1 and validate pagination.
 *     d. Search with filters that should yield empty results and confirm output is empty.
 *     e. Supply invalid pagination/filter parameters (e.g., negative page/limit).
 * 4. As a non-admin (or without auth):
 *     a. Attempt to retrieve business rules and confirm unauthorized access.
 */
export async function test_api_discussionBoard_test_list_business_rules_with_various_filters_and_pagination(connection: api.IConnection) {
  // 1. Create admin member (simulate admin-level access by registering a new member)
  const adminRegInput = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "AdminPass123!",
  } satisfies IDiscussionBoardMember.ICreate;
  const admin = await api.functional.discussionBoard.members.post(connection, { body: adminRegInput });
  typia.assert(admin);
  // Assumption: Test environment regards first/created account as admin (no explicit elevation API available)

  // 2. Register two distinct business rules that we'll use for all filter/pagination checks
  const rule1Input = {
    key: "MAX_POST_LENGTH",
    value: "1000",
    description: "Maximum length for posts in characters",
  } satisfies IDiscussionBoardBusinessRules.ICreate;
  const rule2Input = {
    key: "ALLOW_ANON_POST",
    value: "true",
    description: "Whether anonymous posting is allowed",
  } satisfies IDiscussionBoardBusinessRules.ICreate;

  const rule1 = await api.functional.discussionBoard.businessRules.post(connection, { body: rule1Input });
  const rule2 = await api.functional.discussionBoard.businessRules.post(connection, { body: rule2Input });
  typia.assert(rule1);
  typia.assert(rule2);

  // 3a. As admin, retrieve all business rules (no filters)
  let pagedRules = await api.functional.discussionBoard.businessRules.patch(connection, { body: {} });
  typia.assert(pagedRules);
  TestValidator.predicate("Should return at least two rules")(pagedRules.data.length >= 2);
  const allRuleKeys = pagedRules.data.map((r) => r.key);
  TestValidator.predicate("All inserted rule keys returned")(
    allRuleKeys.includes(rule1.key) && allRuleKeys.includes(rule2.key)
  );

  // 3b. Filter by key (rule1)
  pagedRules = await api.functional.discussionBoard.businessRules.patch(connection, { body: { key: rule1.key } });
  typia.assert(pagedRules);
  TestValidator.equals("Only rule1 is returned")(pagedRules.data.length)(1);
  TestValidator.equals("Rule key matches")(pagedRules.data[0].key)(rule1.key);

  // 3c. Filter by value (rule2)
  pagedRules = await api.functional.discussionBoard.businessRules.patch(connection, { body: { value: rule2.value } });
  typia.assert(pagedRules);
  TestValidator.equals("Only rule2 is returned")(pagedRules.data.length)(1);
  TestValidator.equals("Rule value matches")(pagedRules.data[0].value)(rule2.value);

  // 3d. Filter by description (rule1)
  pagedRules = await api.functional.discussionBoard.businessRules.patch(connection, { body: { description: rule1.description } });
  typia.assert(pagedRules);
  TestValidator.equals("Only rule1 is returned")(pagedRules.data.length)(1);
  TestValidator.equals("Rule description matches")(pagedRules.data[0].description)(rule1.description);

  // 3e. Combined filter (should yield rule2 only)
  pagedRules = await api.functional.discussionBoard.businessRules.patch(connection, {
    body: { key: rule2.key, value: rule2.value, description: rule2.description },
  });
  typia.assert(pagedRules);
  TestValidator.equals("Only rule2 by combined filter")(pagedRules.data.length)(1);
  TestValidator.equals("Rule matches all")(pagedRules.data[0])(rule2);

  // 3f. Pagination (limit=1)
  pagedRules = await api.functional.discussionBoard.businessRules.patch(connection, { body: { limit: 1 } });
  typia.assert(pagedRules);
  TestValidator.equals("One rule per page")(pagedRules.data.length)(1);
  TestValidator.equals("Page size matches")(pagedRules.pagination.limit)(1);

  // 3g. Empty results with unmatched key
  pagedRules = await api.functional.discussionBoard.businessRules.patch(connection, { body: { key: "DOES_NOT_EXIST" } });
  typia.assert(pagedRules);
  TestValidator.equals("No rules for fake key")(pagedRules.data.length)(0);

  // 3h. Invalid filter params (negative page/limit); expect error
  await TestValidator.error("Negative page triggers error")(async () => {
    await api.functional.discussionBoard.businessRules.patch(connection, { body: { page: -1 } });
  });
  await TestValidator.error("Negative limit triggers error")(async () => {
    await api.functional.discussionBoard.businessRules.patch(connection, { body: { limit: -5 } });
  });

  // 4. Non-admin member attempts businessRules.patch; should trigger authorization error
  const nonAdminInput = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "Userpass456!",
  } satisfies IDiscussionBoardMember.ICreate;
  const nonAdmin = await api.functional.discussionBoard.members.post(connection, { body: nonAdminInput });
  typia.assert(nonAdmin);
  // (If there were a non-authenticated connection or role switch function, you'd use that here.)
  await TestValidator.error("Non-admin not authorized")(async () => {
    await api.functional.discussionBoard.businessRules.patch(connection, { body: {} });
  });
}

