import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { DiscussionBoardBusinessRules } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardBusinessRules";
import type { IDiscussionBoardBusinessRules } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBusinessRules";

/**
 * Validate fetching a business rule by its unique ID, covering both valid and invalid cases.
 *
 * This comprehensive test verifies the following scenarios:
 *  - Admin-like member is registered (to fulfill business rule creation requirements).
 *  - Successfully creates a new business rule, then fetches it by ID to assert property equality.
 *  - Attempts to fetch a business rule using a random non-existent UUID, expecting a not-found error.
 *  - Attempts to fetch using a malformed UUID, expecting a format/validation error.
 *  - (If endpoint is admin-restricted) Optionally tests unauthorized access by a non-admin member (preparation logic included).
 *
 * Process steps:
 * 1. Register a member (serves as admin context if needed for business rule operations).
 * 2. Create a business rule and capture its ID for further retrievals.
 * 3. Retrieve the business rule by ID and assert that all returned properties match input values.
 * 4. Attempt to retrieve with a random (non-existent) UUID; expect an error.
 * 5. Attempt to retrieve with a malformed UUID; expect a format error.
 * 6. (Optional: If admin restriction applies and role switch is possible, try as non-admin member.)
 */
export async function test_api_discussionBoard_test_get_business_rule_by_id_valid_and_invalid_cases(
  connection: api.IConnection,
) {
  // 1. Register a discussion board member (admin simulation, if applicable)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: adminEmail,
      display_name: RandomGenerator.name(),
      password: "Password123!",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(adminMember);

  // 2. Create a business rule using admin context
  const createRuleInput = {
    key: `TEST_RULE_${RandomGenerator.alphaNumeric(6).toUpperCase()}`,
    value: "9999",
    description: "E2E test rule for validation",
  } satisfies IDiscussionBoardBusinessRules.ICreate;
  const createdRule = await api.functional.discussionBoard.businessRules.post(connection, {
    body: createRuleInput,
  });
  typia.assert(createdRule);

  // 3. Fetch the created business rule by its ID
  const fetched = await api.functional.discussionBoard.businessRules.getById(connection, {
    id: createdRule.id,
  });
  typia.assert(fetched);
  TestValidator.equals("Fetched rule equals creation input")({
    key: fetched.key,
    value: fetched.value,
    description: fetched.description,
  })({
    key: createRuleInput.key,
    value: createRuleInput.value,
    description: createRuleInput.description,
  });

  // 4. Fetch with a non-existent (random) UUID
  await TestValidator.error("Fetching with a non-existent UUID should fail")(() =>
    api.functional.discussionBoard.businessRules.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );

  // 5. Fetch with a malformed UUID string
  await TestValidator.error("Fetching with malformed UUID should fail")(() =>
    api.functional.discussionBoard.businessRules.getById(connection, {
      id: "not-a-uuid" as string & tags.Format<"uuid">,
    })
  );

  // 6. (Optional) Attempt as a non-admin user, if endpoint access control applies
  // Register a non-admin member and attempt fetch. If role switching/session auth is required, insert logic here.
  const nonAdminEmail = typia.random<string & tags.Format<"email">>();
  const nonAdminMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: nonAdminEmail,
      display_name: RandomGenerator.name(),
      password: "Password123!",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(nonAdminMember);
  // (Endpoint role-restriction logic placeholder: If session/role switch available, test non-admin forbidden access here.)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBusinessRules } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBusinessRules";

/**
 * Test the creation of a new business rule by an administrator, handle duplicate key rejection, and validation errors.
 *
 * This workflow will:
 * 1. Register a new admin member account to obtain permissions for creating business rules.
 * 2. Create a new business rule with a unique key and verify the success and field correctness.
 * 3. Attempt to create another business rule with the same key (should be rejected).
 * 4. Attempt creating rules with missing/invalid fields (should be rejected).
 *
 * Steps:
 * 1. Create an admin member with valid registration info required for authentication.
 * 2. Create a business rule with a unique new key (check that id, key, value, description are present and types match, and no error occurs).
 * 3. Attempt to create another business rule with the same key (should result in error, confirming enforcement of key uniqueness).
 * 4. (Negative) Try to create a business rule missing a required field (e.g., no value/description) and check that the API rejects the request.
 */
export async function test_api_discussionBoard_test_create_business_rule_with_valid_and_duplicate_key(
  connection: api.IConnection,
) {
  // 1. Register a new admin member for authentication.
  const username = RandomGenerator.alphaNumeric(10);
  const email = typia.random<string & tags.Format<'email'>>();
  const displayName = RandomGenerator.name();
  const password = RandomGenerator.alphaNumeric(12);

  const adminMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username,
      email,
      display_name: displayName,
      password
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(adminMember);
  TestValidator.equals('member username matches')(adminMember.username)(username);
  TestValidator.equals('member email matches')(adminMember.email)(email);

  // 2. Create a business rule with a unique key
  const ruleKey = `RULE_${RandomGenerator.alphaNumeric(8).toUpperCase()}`;
  const ruleValue = '1000';
  const ruleDescription = 'Max allowed posts per day.';

  const businessRule = await api.functional.discussionBoard.businessRules.post(connection, {
    body: {
      key: ruleKey,
      value: ruleValue,
      description: ruleDescription,
    } satisfies IDiscussionBoardBusinessRules.ICreate,
  });
  typia.assert(businessRule);
  TestValidator.equals('rule key matches')(businessRule.key)(ruleKey);
  TestValidator.equals('rule value matches')(businessRule.value)(ruleValue);
  TestValidator.equals('rule description matches')(businessRule.description)(ruleDescription);

  // 3. Attempt to create duplicate business rule (should error)
  await TestValidator.error('duplicate business rule key rejected')(async () => {
    await api.functional.discussionBoard.businessRules.post(connection, {
      body: {
        key: ruleKey,
        value: '999',
        description: 'Different description',
      } satisfies IDiscussionBoardBusinessRules.ICreate,
    });
  });

  // 4. Attempt to create rule with missing required field (should error)
  await TestValidator.error('missing value field rejected')(async () => {
    await api.functional.discussionBoard.businessRules.post(connection, {
      body: {
        key: `RULE_${RandomGenerator.alphaNumeric(8).toUpperCase()}`,
        value: '', // Empty value instead of valid value
        description: 'Description without value',
      } satisfies IDiscussionBoardBusinessRules.ICreate,
    });
  });

  await TestValidator.error('missing description field rejected')(async () => {
    await api.functional.discussionBoard.businessRules.post(connection, {
      body: {
        key: `RULE_${RandomGenerator.alphaNumeric(8).toUpperCase()}`,
        value: '10',
        description: '', // Description cannot be empty if required
      } satisfies IDiscussionBoardBusinessRules.ICreate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBusinessRules } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBusinessRules";

/**
 * 기존 비즈니스 룰의 key, value, description을 어드민 권한으로 수정하는 기능의 통합 테스트
 *
 * - 관리 권한 계정 생성 후 비즈니스 룰 2건 등록
 * - value/description 등 정상 수정 후 값 반영 확인
 * - key를 중복값으로 변경 시도시 에러 반환 확인
 * - 필수 입력 누락 업데이트에 대해 validation 혹은 에러 확인
 * - 존재하지 않는 rule id 수정시 not found 에러 확인
 *
 * (audit log 등 결과를 직접 검색/확인하는 기능은 지원되지 않으므로, 정상 API 동작만 검증)
 */
export async function test_api_discussionBoard_test_update_business_rule_with_unique_key_and_field_validation(
  connection: api.IConnection,
) {
  // 1. 어드민 discussion board 멤버 생성
  const adminMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "TestPassword123!"
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(adminMember);

  // 2. 비즈니스 룰 2건 등록 (서로 다른 key)
  const ruleA = await api.functional.discussionBoard.businessRules.post(connection, {
    body: {
      key: "E2E_RULE_A_" + RandomGenerator.alphaNumeric(5),
      value: "100",
      description: "Rule A description"
    } satisfies IDiscussionBoardBusinessRules.ICreate,
  });
  typia.assert(ruleA);

  const ruleB = await api.functional.discussionBoard.businessRules.post(connection, {
    body: {
      key: "E2E_RULE_B_" + RandomGenerator.alphaNumeric(5),
      value: "200",
      description: "Rule B description"
    } satisfies IDiscussionBoardBusinessRules.ICreate,
  });
  typia.assert(ruleB);

  // 3. ruleA value/description 정상 업데이트 및 assertion
  const updatedValue = "999";
  const updatedDescription = "Updated description";
  const updatedRule = await api.functional.discussionBoard.businessRules.putById(connection, {
    id: ruleA.id,
    body: {
      value: updatedValue,
      description: updatedDescription,
    } satisfies IDiscussionBoardBusinessRules.IUpdate,
  });
  typia.assert(updatedRule);
  TestValidator.equals("value 정상 반영")(updatedRule.value)(updatedValue);
  TestValidator.equals("description 정상 반영")(updatedRule.description)(updatedDescription);
  TestValidator.equals("key 변화 없음")(updatedRule.key)(ruleA.key);

  // 4. key를 ruleB의 key로 변경 시도 → 중복 에러 확인
  await TestValidator.error("중복된 key로 변경 시 오류")(async () => {
    await api.functional.discussionBoard.businessRules.putById(connection, {
      id: ruleA.id,
      body: {
        key: ruleB.key,
      },
    });
  });

  // 5. 필수 입력 누락 (예: 빈 body) → validation 에러 여부 확인
  await TestValidator.error("필수 입력 누락 validation 오류")(async () => {
    await api.functional.discussionBoard.businessRules.putById(connection, {
      id: ruleA.id,
      body: {},
    });
  });

  // 6. 존재하지 않는 id로 수정 → not found 에러 발생 확인
  await TestValidator.error("없는 id로 수정 시 not found 오류")(async () => {
    await api.functional.discussionBoard.businessRules.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        value: "new value",
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBusinessRules } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBusinessRules";
import type { INullResult } from "@ORGANIZATION/PROJECT-api/lib/structures/INullResult";

/**
 * E2E 테스트: 비즈니스 규칙 삭제 및 소프트 삭제 행동 검증
 *
 * 테스트 목적 및 중요성:
 * - 관리자(admin) 권한으로 비즈니스 규칙을 생성 후 해당 규칙을 삭제(Delete)하는 기능을 확인함
 * - 삭제 후 규칙이 일반적인 조회(/list, /get)에서는 더 이상 노출되지 않는 것을 검증함
 *   (단, soft-deleted 데이터를 명시적으로 포함하는 옵션이 없다면 기본적으로 안 보여야 함)
 * - 존재하지 않는 규칙 삭제 시 적절한 오류 반환을 확인함
 * - 동일 규칙에 대한 반복 삭제 요청 시 오류가 정확하게 처리되는지 검증
 *
 * 테스트 시나리오:
 * 1. 관리자 계정 생성
 * 2. 비즈니스 규칙 생성
 * 3. 해당 규칙 삭제(DELETE)
 * 4. 삭제한 규칙 재조회 시(예: get/list 엔드포인트로) 보이지 않는지 확인 (단, 관련 API 미제공 시 이 검증은 건너뜀)
 * 5. 임의의(존재하지 않는) id로 삭제 요청 시 오류 반환 확인
 * 6. 동일 규칙을 반복 삭제 시 오류 반환 확인
 * 7. (비즈니스 규칙에 감사 로그/컴플라이언스 정책 정의 시) 로그 적재 및 정책 준수 여부 확인 – 단, 이를 위한 별도 엔드포인트 없으면 생략함
*/
export async function test_api_discussionBoard_test_delete_business_rule_and_soft_deletion_behavior(
  connection: api.IConnection
) {
  // 1. 관리자 계정 생성
  const adminInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: RandomGenerator.alphaNumeric(12),
  };
  const admin = await api.functional.discussionBoard.members.post(connection, {
    body: adminInput,
  });
  typia.assert(admin);

  // 2. 새로운 비즈니스 규칙 생성
  const ruleInput: IDiscussionBoardBusinessRules.ICreate = {
    key: `MAX_${RandomGenerator.alphabets(6).toUpperCase()}`,
    value: "1234",
    description: "이 테스트용 임시 비즈니스 규칙입니다.",
  };
  const rule = await api.functional.discussionBoard.businessRules.post(connection, {
    body: ruleInput,
  });
  typia.assert(rule);

  // 3. 정상적인 삭제 요청: 생성한 규칙 삭제
  const delResult = await api.functional.discussionBoard.businessRules.eraseById(connection, {
    id: rule.id,
  });
  typia.assert(delResult);

  // 4. 삭제된 규칙에 동일 id로 다시 삭제 요청 → 오류 발생 확인
  await TestValidator.error("동일 ID 재삭제시 오류")(async () => {
    await api.functional.discussionBoard.businessRules.eraseById(connection, {
      id: rule.id,
    });
  });

  // 5. 완전히 임의로 존재하지 않을 것 같은 UUID로 삭제 시도 → 오류 반환 확인
  const fakeRuleId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("존재하지 않는 ID 삭제시 오류")(async () => {
    await api.functional.discussionBoard.businessRules.eraseById(connection, {
      id: fakeRuleId,
    });
  });

  // 6. (선택) 삭제 이후 get/list API를 통해 노출 안 되는지 확인 – 단, API 미제공시 건너뜀
  //    실제로는 이러한 검증 수행 위해 API가 필요하나, 현재 제공 엔드포인트 내역상 호출 불가 → 생략
  // 7. (선택) 감사 로그/정책 확인 – 별도 API 없으므로 건너뜀
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPolicyChangeLogs } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPolicyChangeLogs";
import type { IPageIDiscussionBoardPolicyChangeLogs } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPolicyChangeLogs";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates the filtered/paginated policy change log listing for admin and access denial for non-admins.
 *
 * Ensures filtering (by type/date/admin/policy/rule ID), sorting, and pagination work for admin list endpoint. Verifies access control and error handling for invalid input or non-admin usage.
 *
 * 1. Create multiple change log records (distinct change_type, actor_admin_id, policy/rule IDs, dates)
 * 2. List logs as admin with different filters (change_type, actor_admin_id, date range, policy/rule IDs, pagination)
 * 3. Assert returned results, pagination metadata, content fields, and that filtering works (subset, order, data correctness)
 * 4. Attempt to list logs as non-admin; must be error
 * 5. Attempt with invalid filter parameters (bad date-strings, invalid UUIDs) and verify error
 */
export async function test_api_discussionBoard_test_list_policy_change_logs_as_admin_with_filters_and_pagination(connection: api.IConnection) {
  // 1. Create policy change log records as prepared test data
  const adminId1 = typia.random<string & tags.Format<"uuid">>();
  const adminId2 = typia.random<string & tags.Format<"uuid">>();
  const policyId1 = typia.random<string & tags.Format<"uuid">>();
  const ruleId1 = typia.random<string & tags.Format<"uuid">>();
  // Two different timestamps, one last week, one now
  const dateNow = new Date();
  const dateLastWeek = new Date(dateNow.getTime() - 7 * 24 * 60 * 60 * 1000);
  // Insert two logs with different settings
  const changeLog1 = await api.functional.discussionBoard.policyChangeLogs.post(connection, {
    body: {
      change_type: "EDIT",
      changed_policy_id: policyId1,
      changed_rule_id: null,
      actor_admin_id: adminId1,
      before_value: JSON.stringify({ foo: "old" }),
      after_value: JSON.stringify({ foo: "new" }),
      changed_at: dateLastWeek.toISOString(),
    },
  });
  typia.assert(changeLog1);
  const changeLog2 = await api.functional.discussionBoard.policyChangeLogs.post(connection, {
    body: {
      change_type: "DEACTIVATE",
      changed_policy_id: null,
      changed_rule_id: ruleId1,
      actor_admin_id: adminId2,
      before_value: JSON.stringify({ active: true }),
      after_value: JSON.stringify({ active: false }),
      changed_at: dateNow.toISOString(),
    },
  });
  typia.assert(changeLog2);

  // 2. List logs filtered by change_type 'EDIT'
  const respType = await api.functional.discussionBoard.policyChangeLogs.patch(connection, {
    body: {
      change_type: "EDIT",
    },
  });
  typia.assert(respType);
  TestValidator.predicate("filter by change_type 'EDIT'")(
    respType.data.some((x) => x.id === changeLog1.id)
  );
  TestValidator.predicate("filter excludes non-EDIT")(
    respType.data.every((x) => x.change_type === "EDIT")
  );

  // 3. List by actor_admin_id
  const respAdmin = await api.functional.discussionBoard.policyChangeLogs.patch(connection, {
    body: {
      actor_admin_id: adminId2,
    },
  });
  typia.assert(respAdmin);
  TestValidator.predicate("adminId2 results")(
    respAdmin.data.some((x) => x.actor_admin_id === adminId2)
  );

  // 4. Filter by changed_policy_id and changed_rule_id
  const respPolicy = await api.functional.discussionBoard.policyChangeLogs.patch(connection, {
    body: {
      changed_policy_id: policyId1,
    },
  });
  typia.assert(respPolicy);
  TestValidator.predicate("changed_policy_id results")(
    respPolicy.data.some((x) => x.changed_policy_id === policyId1)
  );

  const respRule = await api.functional.discussionBoard.policyChangeLogs.patch(connection, {
    body: {
      changed_rule_id: ruleId1,
    },
  });
  typia.assert(respRule);
  TestValidator.predicate("changed_rule_id results")(
    respRule.data.some((x) => x.changed_rule_id === ruleId1)
  );

  // 5. Filter by date range - just last week (should include only changeLog1)
  const respDate = await api.functional.discussionBoard.policyChangeLogs.patch(connection, {
    body: {
      changed_at_from: dateLastWeek.toISOString(),
      changed_at_to: dateLastWeek.toISOString(),
    },
  });
  typia.assert(respDate);
  TestValidator.predicate("date range results contains changeLog1")(
    respDate.data.length === 1 && respDate.data[0].id === changeLog1.id
  );

  // 6. Pagination - set limit 1 per page
  const respFirstPage = await api.functional.discussionBoard.policyChangeLogs.patch(connection, {
    body: { limit: 1, page: 1 },
  });
  typia.assert(respFirstPage);
  TestValidator.equals("pagination limit=1")(respFirstPage.pagination.limit)(1);
  TestValidator.predicate("pagination records populated")(
    typeof respFirstPage.pagination.records === "number"
  );

  // 7. Test calling as non-admin (simulate by emptying token)
  const nonAdminConn = { ...connection, headers: { ...connection.headers } };
  delete nonAdminConn.headers.Authorization;
  await TestValidator.error("non-admin list denied")(() =>
    api.functional.discussionBoard.policyChangeLogs.patch(nonAdminConn, { body: {} })
  );

  // 8. Invalid filters: bad date, bad uuid
  await TestValidator.error("bad date format")(() =>
    api.functional.discussionBoard.policyChangeLogs.patch(connection, {
      body: { changed_at_from: "notadate" as any },
    })
  );
