import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPolicyChangeLogs } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPolicyChangeLogs";

/**
 * Validate admin update of a discussion board policy change log.
 *
 * This test ensures that an authenticated admin can update the details of an existing policy change log, such as by changing references, appending/correcting notes, or updating before/after values. It thoroughly covers successful update as well as edge/error cases, in accordance with business requirements for auditability and compliance.
 *
 * Steps:
 *
 * 1. Create a policy change log entry (POST /discussionBoard/policyChangeLogs) with valid references, admin actor, and before/after values.
 * 2. Perform a valid update via PUT /discussionBoard/policyChangeLogs/{id}, updating fields such as after_value, change_type, or references. Assert that updated fields are reflected correctly and trace/audit fields (actor_admin_id, changed_at, etc.) are as expected.
 * 3. Attempt an update with invalid (random, non-existent) references for policy or rule IDs. Assert error is thrown.
 * 4. Attempt to update a non-existent policy change log (random valid UUID). Assert error is thrown.
 *
 * Note: The scenario requests an edge case for non-admin update, but since no authentication or role API exists in the provided SDK/types, this test is omitted.
 *
 * All steps enforce strict type safety, business rule assertions, and audit traceability.
 */
export async function test_api_discussionBoard_policyChangeLogs_test_update_policy_change_log_details_as_admin(
  connection: api.IConnection,
) {
  // 1. Create a policy change log entry as admin
  const admin_id = typia.random<string & tags.Format<"uuid">>();
  const valid_policy_id = typia.random<string & tags.Format<"uuid">>();
  const created = await api.functional.discussionBoard.policyChangeLogs.post(connection, {
    body: {
      actor_admin_id: admin_id,
      change_type: "ADD",
      changed_at: new Date().toISOString(),
      changed_policy_id: valid_policy_id,
      before_value: JSON.stringify({ rule: "old" }),
      after_value: JSON.stringify({ rule: "initial" })
    } satisfies IDiscussionBoardPolicyChangeLogs.ICreate
  });
  typia.assert(created);

  // 2. Perform a valid update as admin
  const new_rule_id = typia.random<string & tags.Format<"uuid">>();
  const updated_body = {
    changed_policy_id: valid_policy_id, // Keep same policy reference
    changed_rule_id: new_rule_id, // Now associate an additional rule reference
    actor_admin_id: admin_id, // Admin stays same
    change_type: "EDIT",
    before_value: created.after_value, // Last after_value becomes new before_value for this update
    after_value: JSON.stringify({ rule: "amended", notes: "fixed typo in policy wording" }),
    changed_at: new Date().toISOString()
  } satisfies IDiscussionBoardPolicyChangeLogs.IUpdate;
  const updated = await api.functional.discussionBoard.policyChangeLogs.putById(connection, {
    id: created.id,
    body: updated_body
  });
  typia.assert(updated);
  // Updated fields should match
  TestValidator.equals("updated after_value")(updated.after_value)(updated_body.after_value);
  TestValidator.equals("updated before_value")(updated.before_value)(updated_body.before_value);
  TestValidator.equals("change_type EDIT")(updated.change_type)("EDIT");
  TestValidator.equals("actor_admin_id")(updated.actor_admin_id)(admin_id);
  TestValidator.equals("changed_policy_id")(updated.changed_policy_id)(valid_policy_id);
  TestValidator.equals("changed_rule_id")(updated.changed_rule_id)(new_rule_id);
  // changed_at assertion is equality but format and timezone can vary
  TestValidator.equals("changed_at updated")(updated.changed_at)(updated_body.changed_at);

  // 3. Attempt to update using invalid references (simulate non-existent policy/rule)
  const invalidUpdateBody = {
    ...updated_body,
    changed_policy_id: typia.random<string & tags.Format<"uuid">>(),
    changed_rule_id: typia.random<string & tags.Format<"uuid">>()
  } satisfies IDiscussionBoardPolicyChangeLogs.IUpdate;
  await TestValidator.error("update with invalid policy/rule reference should fail")(
    async () => {
      await api.functional.discussionBoard.policyChangeLogs.putById(connection, {
        id: created.id,
        body: invalidUpdateBody
      });
    }
  );

  // 4. Attempt to update a non-existent policy change log by ID
  await TestValidator.error("updating a non-existent log should fail")(
    async () => {
      await api.functional.discussionBoard.policyChangeLogs.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: updated_body
      });
    }
  );

  // Note: Scenario requests a test for update as non-admin, but this cannot be implemented with the provided functions/types.
}

