/**
 * Validates strict access control for moderation actions on the discussion board.
 *
 * This test ensures that a non-privileged member (regular user) and an unauthenticated user are both forbidden from creating moderation actions. This enforces that moderation operations can only be performed by moderators or admins, protecting integrity and auditability of sensitive actions (like banning, suspending, or editing others' content).
 *
 * Steps:
 * 1. Register a new regular member (not a moderator or admin)
 * 2. Attempt to create a moderation action using this regular member's session
 *    - Expect a forbidden (403) error (TestValidator.error)
 *    - Verify no moderation action is created
 * 3. Clear authentication (simulate unauthenticated session)
 * 4. Attempt to create a moderation action as an unauthenticated user
 *    - Again, expect a forbidden (403) error
 *    - Verify no moderation action is created
 */
export async function test_api_discussionBoard_test_create_moderation_action_as_unauthorized_user(
  connection: api.IConnection,
) {
  // 1. Register a new regular discussion board member
  const memberInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(12),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "UnaUthzUserPass123*",
  };
  const member = await api.functional.discussionBoard.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. Attempt to create a moderation action as this regular (non-authorized) member
  const moderationInput: IDiscussionBoardModerationAction.ICreate = {
    moderator_id: null, // null, as this user is NOT a moderator
    admin_id: null,     // null, as this user is NOT an admin
    target_post_id: null,     // not targeting a specific post
    target_comment_id: null,  // not targeting a specific comment
    affected_member_id: member.id, // try suspending the member (self)
    action_type: "suspend",
    action_reason: "Misuse test - non-privileged request should fail.",
    action_note: "E2E negative: regular user enforcement check.",
  };
  await TestValidator.error("Forbidden (403) - regular member cannot create moderation action")(
    async () => {
      await api.functional.discussionBoard.moderationActions.post(connection, { body: moderationInput });
    }
  );

  // 3. Clear authentication to simulate unauthenticated session
  const unauthConnection = { ...connection, headers: { ...connection.headers } };
  delete unauthConnection.headers.Authorization;

  // 4. Attempt as unauthenticated (no Authorization header)
  await TestValidator.error("Forbidden (403) - unauthenticated user cannot create moderation action")(
    async () => {
      await api.functional.discussionBoard.moderationActions.post(unauthConnection, { body: moderationInput });
    }
  );
}

