  const member2 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.name(),
      password: 'password2!',
    },
  });
  typia.assert(member2);

  const member3 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.name(),
      password: 'password3!',
    },
  });
  typia.assert(member3);

  // 2. Create posts by different members
  // All posts belong to same fake board id (simulate existing board)
  const board_id = typia.random<string & tags.Format<'uuid'>>();
  const post1 = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id,
      author_id: member1.id,
      title: 'First Post',
      body: 'Body A',
    },
  });
  typia.assert(post1);

  const post2 = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id,
      author_id: member2.id,
      title: 'Second Post',
      body: 'Body B',
    },
  });
  typia.assert(post2);

  // 3. Add post reactions by different users
  const reactionA = await api.functional.discussionBoard.postReactions.post(connection, {
    body: {
      discussionboard_member_id: member1.id,
      discussionboard_post_id: post1.id,
      reaction_type: 'like',
    },
  });
  typia.assert(reactionA);

  const reactionB = await api.functional.discussionBoard.postReactions.post(connection, {
    body: {
      discussionboard_member_id: member2.id,
      discussionboard_post_id: post1.id,
      reaction_type: 'like',
    },
  });
  typia.assert(reactionB);

  const reactionC = await api.functional.discussionBoard.postReactions.post(connection, {
    body: {
      discussionboard_member_id: member3.id,
      discussionboard_post_id: post1.id,
      reaction_type: 'dislike',
    },
  });
  typia.assert(reactionC);

  const reactionD = await api.functional.discussionBoard.postReactions.post(connection, {
    body: {
      discussionboard_member_id: member1.id,
      discussionboard_post_id: post2.id,
      reaction_type: 'like',
    },
  });
  typia.assert(reactionD);

  // 4a. Query by post ID
  const byPost = await api.functional.discussionBoard.postReactions.patch(connection, {
    body: {
      discussionboard_post_id: post1.id,
      paging: { page: 1, limit: 100 },
    },
  });
  typia.assert(byPost);
  TestValidator.predicate('All reactions match post1')(
    byPost.data.every(r => r.discussionboard_post_id === post1.id),
  );

  // 4b. Query by member ID
  const byMember = await api.functional.discussionBoard.postReactions.patch(connection, {
    body: {
      discussionboard_member_id: member1.id,
      paging: { page: 1, limit: 100 },
    },
  });
  typia.assert(byMember);
  TestValidator.predicate('All reactions by member1')(
    byMember.data.every(r => r.discussionboard_member_id === member1.id),
  );

  // 4c. Query by reaction type
  const byType = await api.functional.discussionBoard.postReactions.patch(connection, {
    body: {
      reaction_type: 'like',
      paging: { page: 1, limit: 100 },
    },
  });
  typia.assert(byType);
  TestValidator.predicate('All reactions are likes')(
    byType.data.every(r => r.reaction_type === 'like'),
  );

  // 4d. Query by creation date after a threshold and before now (use earliest created from above)
  const after = reactionA.created_at;
  const now = new Date().toISOString();
  const byDate = await api.functional.discussionBoard.postReactions.patch(connection, {
    body: {
      created_after: after,
      created_before: now,
      paging: { page: 1, limit: 100 },
    },
  });
  typia.assert(byDate);
  TestValidator.predicate('All reactions created after filter')(
    byDate.data.every(r => r.created_at >= after && r.created_at < now),
  );

  // 4e. Pagination test (limit=2 on all reactions)
  const paged = await api.functional.discussionBoard.postReactions.patch(connection, {
    body: {
      paging: { page: 1, limit: 2 },
    },
  });
  typia.assert(paged);
  TestValidator.equals('Paged data count')(paged.data.length)(2);
  TestValidator.predicate('Pagination meta matches')(
    paged.pagination.limit === 2 && paged.pagination.current === 1,
  );

  // 6. Error cases - invalid UUIDs/parameters
  await TestValidator.error('Invalid member UUID triggers error')(async () => {
    await api.functional.discussionBoard.postReactions.patch(connection, {
      body: {
        discussionboard_member_id: 'not-a-uuid',
        paging: { page: 1, limit: 10 },
      },
    });
  });
  await TestValidator.error('Paging out of bounds triggers error')(async () => {
    await api.functional.discussionBoard.postReactions.patch(connection, {
      body: {
        paging: { page: 0, limit: 10 },
      },
    });
  });
  await TestValidator.error('Negative limit triggers error')(async () => {
    await api.functional.discussionBoard.postReactions.patch(connection, {
      body: {
        paging: { page: 1, limit: -5 },
      },
    });
  });

  // 7. (If unauthenticated/permission logic enforced) test unauthorized access (skipped if not applicable)
}

