 * 1. Create Member A (who will add and own the initial reaction)
 * 2. Create Member B (to test unauthorized updates)
 * 3. Create a Post under a random Board by Member A
 * 4. Member A adds a valid reaction (e.g., 'like') to the post
 * 5. Member A successfully updates their own reaction (e.g., to 'dislike').
 *    - Validate that the update is reflected and created_at is unchanged (no updated_at field in the DTO)
 * 6. Member B attempts to update the same reaction (should trigger a permission error).
 * 7. Attempt to update with an invalid reaction type (e.g., 'invalidType') and expect validation failure.
 * 8. Attempt to update with malformed data (e.g., missing required field) and expect validation failure.
 */
export async function test_api_discussionBoard_test_update_post_reaction_type_and_permission_validation(
  connection: api.IConnection,
) {
  // 1. Create Member A (who will add the initial reaction)
  const memberAInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "TestPassword1!",
  };
  const memberA = await api.functional.discussionBoard.members.post(connection, { body: memberAInput });
  typia.assert(memberA);

  // 2. Create Member B (for unauthorized update test)
  const memberBInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "TestPassword1!",
  };
  const memberB = await api.functional.discussionBoard.members.post(connection, { body: memberBInput });
  typia.assert(memberB);

  // 3. Create a Post under a random Board by Member A
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: typia.random<string & tags.Format<"uuid">>(),
      author_id: memberA.id,
      title: RandomGenerator.paragraph()(8),
      body: RandomGenerator.content()(32)(),
    },
  });
  typia.assert(post);

  // 4. Member A adds a reaction (like) to the post
  const reaction = await api.functional.discussionBoard.postReactions.post(connection, {
    body: {
      discussionboard_member_id: memberA.id,
      discussionboard_post_id: post.id,
      reaction_type: "like",
    },
  });
  typia.assert(reaction);

  // 5. Member A successfully updates their own reaction (to 'dislike')
  const updatedReaction = await api.functional.discussionBoard.postReactions.putById(connection, {
    id: reaction.id,
    body: { reaction_type: "dislike" },
  });
  typia.assert(updatedReaction);
  TestValidator.equals("reaction type updated")(updatedReaction.reaction_type)("dislike");

  // 6. Member B attempts to update the same reaction (should fail - simulates lack of permission)
  await TestValidator.error("unauthorized member cannot update reaction")(
    async () => {
      await api.functional.discussionBoard.postReactions.putById(connection, {
        id: reaction.id,
        body: { reaction_type: "like" },
      });
    }
  );

  // 7. Attempt to update with invalid reaction type
  await TestValidator.error("invalid reaction type rejected")(
    async () => {
      await api.functional.discussionBoard.postReactions.putById(connection, {
        id: reaction.id,
        body: { reaction_type: "invalidType" },
      });
    }
  );

  // 8. Attempt to update with malformed data (missing required reaction_type field)
  await TestValidator.error("missing reaction_type should fail")(
    async () => {
      // Intentionally send malformed payload according to scenario instructions
      // @ts-expect-error
      await api.functional.discussionBoard.postReactions.putById(connection, {
        id: reaction.id,
        body: {},
      });
    }
  );
}

