import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";

/**
 * Validate access to soft-deleted discussion board configurations by member role.
 *
 * This test verifies that:
 * 1. An admin can create and soft-delete a configuration entry, and can still access
 *    its details (including the 'deleted_at' field) after deletion.
 * 2. A regular member cannot access soft-deleted configuration entries (should raise
 *    forbidden or not-found error).
 *
 * Steps:
 * 1. Register an admin member and a regular member.
 * 2. With the admin, create a configuration entry.
 * 3. Soft-delete the configuration as admin.
 * 4. As admin, fetch the soft-deleted configuration and confirm 'deleted_at' is set.
 * 5. As regular member, attempt to fetch the configuration and expect failure.
 */
export async function test_api_discussionBoard_test_get_soft_deleted_configuration_visibility_by_role(
  connection: api.IConnection,
) {
  // 1. Register an admin member (simulated admin, lacks explicit elevation API)
  const adminMember: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(
    connection,
    {
      body: {
        username: RandomGenerator.alphabets(8),
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(),
        password: "AdminPw123!",
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(adminMember);
  // For E2E, assume admin association is done out-of-band (infra/test fixture)

  // 2. Register a regular member
  const regularMember: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(
    connection,
    {
      body: {
        username: RandomGenerator.alphabets(8),
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(),
        password: "UserPw456!",
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(regularMember);

  // 3. As admin, create a configuration entry
  const config: IDiscussionBoardConfiguration = await api.functional.discussionBoard.configurations.post(
    connection,
    {
      body: {
        key: `test_key_${RandomGenerator.alphaNumeric(6)}`,
        value: "1234",
        description: "E2E test config",
      } satisfies IDiscussionBoardConfiguration.ICreate,
    },
  );
  typia.assert(config);

  // 4. Soft-delete the configuration by id (as admin)
  const erased: IDiscussionBoardConfiguration = await api.functional.discussionBoard.configurations.eraseById(
    connection,
    { id: config.id },
  );
  typia.assert(erased);
  TestValidator.predicate("deleted_at is set by erase")(!!erased.deleted_at);

  // 5. As admin, fetch the soft-deleted configuration
  const fetchedByAdmin: IDiscussionBoardConfiguration = await api.functional.discussionBoard.configurations.getById(
    connection,
    { id: config.id },
  );
  typia.assert(fetchedByAdmin);
  TestValidator.equals("admin sees deleted_at")(fetchedByAdmin.deleted_at)(erased.deleted_at);
  TestValidator.equals("admin fetch matches")(fetchedByAdmin.id)(config.id);

  // 6. As regular member, attempt to fetch the soft-deleted config
  // In the absence of an explicit login/switch-user method, this step is
  // presented for infra-assumed context. If context switching is supported,
  // it should perform the API call as the regular user.
  TestValidator.error("Regular member cannot access soft-deleted configuration")(
    async () => {
      await api.functional.discussionBoard.configurations.getById(connection, { id: config.id });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
