/**
 * Validate updating the value and description of a discussion board configuration by an authorized admin.
 *
 * This test scenario ensures:
 * - An admin user can update a configuration's value and description
 * - Changes are persisted and visible in the returned response
 * - Timestamps for modification are correctly updated (for audit compliance)
 * - No unintended fields are altered; only value/description are updatable
 *
 * Step-by-step validation:
 * 1. Create an admin member with unique credentials (simulated, as explicit admin promotion is unavailable in given APIs).
 * 2. Create a configuration entry with an initial value and description.
 * 3. As the admin, update both value and description of the configuration using the PUT endpoint.
 * 4. Assert the response reflects the updated value/description, unchanged key/id, and a refreshed updated_at field.
 * 5. Ensure created_at and deleted_at fields respect invariants (creation time remains constant, not soft-deleted).
 */
export async function test_api_discussionBoard_test_update_configuration_value_and_description_with_admin_role(
  connection: api.IConnection,
) {
  // 1. Create an admin member (here as a regular member; role elevation is assumed due to API limitation)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminUsername: string = RandomGenerator.alphaNumeric(10);
  const adminPassword: string = typia.random<string & tags.Format<"password">>();
  const admin: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: adminUsername,
      email: adminEmail,
      display_name: RandomGenerator.name(),
      password: adminPassword,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(admin);

  // 2. Create a configuration entry
  const initialConfig: IDiscussionBoardConfiguration = await api.functional.discussionBoard.configurations.post(connection, {
    body: {
      key: RandomGenerator.alphaNumeric(16),
      value: "original_value",
      description: "Initial configuration for update test.",
    } satisfies IDiscussionBoardConfiguration.ICreate,
  });
  typia.assert(initialConfig);

  // 3. Update configuration value and description
  const newValue = "updated_value";
  const newDescription = "Updated description (now optional).";
  const updatedConfig: IDiscussionBoardConfiguration = await api.functional.discussionBoard.configurations.putById(connection, {
    id: initialConfig.id,
    body: {
      value: newValue,
      description: newDescription,
    } satisfies IDiscussionBoardConfiguration.IUpdate,
  });
  typia.assert(updatedConfig);

  // 4. Assert updates are correct
  TestValidator.equals("config id")(updatedConfig.id)(initialConfig.id);
  TestValidator.equals("key remains")(updatedConfig.key)(initialConfig.key);
  TestValidator.equals("value updated")(updatedConfig.value)(newValue);
  TestValidator.equals("description updated")(updatedConfig.description)(newDescription);
  TestValidator.predicate("updated_at changed")(new Date(updatedConfig.updated_at).getTime() > new Date(initialConfig.updated_at).getTime());
  TestValidator.equals("created_at unchanged")(updatedConfig.created_at)(initialConfig.created_at);
  TestValidator.equals("not soft deleted")(updatedConfig.deleted_at)(null);
}

