import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";

/**
 * Test updating a discussion board configuration as a non-admin (member) to ensure permission handling works correctly.
 *
 * Business context:
 * System configurations (settings as key-value pairs) must be protected against editing by regular members. Only administrators have privilege to update them. Attempting to update as a member should result in a permission denied error and the update should not occur.
 *
 * Step-by-step process:
 * 1. Register an admin account via the member registration API (simulate admin context if possible, but as only registration is exposed, focus on non-admin).
 * 2. Register a regular member (non-admin) to use as the actor for the forbidden update.
 * 3. Register a configuration as setup (since only admins can do this, assume initial context permits creation).
 * 4. Attempt to update the configuration as the non-admin member. Expect a permission denied error (typically a 403 or custom error code).
