  TestValidator.equals("conf key remains unchanged after update")(updatedConfB.key)(confB.key);
  TestValidator.equals("conf value updated")(updatedConfB.value)("2222");
  TestValidator.equals("conf description updated")(updatedConfB.description)("Updated value only; key cannot be changed via update");

  // 4. Document limitation
  // Note: Uniqueness of 'key' can only be tested on creation, not on update, per the API and DTO constraints.
}

