import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentReaction";

/**
 * Test retrieving a specific comment reaction by ID.
 *
 * This test covers the workflow:
 * 1. Create a discussion board member (as the reaction author)
 * 2. Create a comment authored by that member
 * 3. Add a reaction (like/dislike) to the comment from that member
 * 4. Retrieve the reaction by ID using GET /discussionBoard/commentReactions/{id}
 * 5. Assert data integrity: all relevant fields match
 *
 * This validates both the correct end-to-end workflow for comment reactions and
 * the precise retrieval and data integrity for reactions in the system.
 */
export async function test_api_discussionBoard_test_get_comment_reaction_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a new member (reaction author)
  const memberInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: RandomGenerator.alphaNumeric(12),
  };
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Create a new comment authored by this member
  const postId = typia.random<string & tags.Format<"uuid">>();
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const commentInput: IDiscussionBoardComment.ICreate = {
    post_id: postId,
    thread_id: threadId,
    author_id: member.id,
    body: RandomGenerator.paragraph()(),
    depth: 0,
  };
  const comment = await api.functional.discussionBoard.comments.post(connection, {
    body: commentInput,
  });
  typia.assert(comment);

  // 3. Create a reaction (like/dislike) for the comment by this member
  const reactionType = RandomGenerator.pick(["like", "dislike"]);
  const reactionInput: IDiscussionBoardCommentReaction.ICreate = {
    discussionboard_member_id: member.id,
    discussionboard_comment_id: comment.id,
    reaction_type: reactionType,
  };
  const reaction = await api.functional.discussionBoard.commentReactions.post(connection, {
    body: reactionInput,
  });
  typia.assert(reaction);

  // 4. Retrieve the reaction by its ID
  const fetched = await api.functional.discussionBoard.commentReactions.getById(connection, {
    id: reaction.id,
  });
  typia.assert(fetched);

  // 5. Assert that all core fields match those from the creation
  TestValidator.equals("reaction id")(fetched.id)(reaction.id);
  TestValidator.equals("member id")(fetched.discussionboard_member_id)(reactionInput.discussionboard_member_id);
  TestValidator.equals("comment id")(fetched.discussionboard_comment_id)(reactionInput.discussionboard_comment_id);
  TestValidator.equals("reaction type")(fetched.reaction_type)(reactionInput.reaction_type);

  // System managed timestamps and deleted_at field are checked for proper presence
  TestValidator.predicate("created_at format")(typeof fetched.created_at === "string" && fetched.created_at.length > 0);
  TestValidator.equals("deleted_at is null or undefined")(fetched.deleted_at === undefined || fetched.deleted_at === null)(true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCommentReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentReaction";

/**
 * 댓글 리액션 단건 조회 API의 비정상 ID 처리 엔드 투 엔드 검증.
 *
 * 본 테스트는 실제 존재하지 않는 UUID 값을 사용하거나 UUID 형식이 아닌 문자열을 전달하여,
 * 아래 두 가지 상황에서 백엔드가 적절하게 오류(404 또는 validation)를 반환하는지 검증합니다.
 *
 * 1. 존재하지 않는 정상 uuid 포맷 (404 오류)
 * 2. uuid가 아닌 잘못된 포맷 (validation error)
 *
 * 각 경우에 대해 TestValidator.error()로 서버가 에러를 반환하는지만 검증합니다.
 */
export async function test_api_discussionBoard_test_get_comment_reaction_with_invalid_id(
  connection: api.IConnection,
) {
  // 1. 정상 uuid 포맷이지만 DB에 존재하지 않는 값
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("존재하지 않는 리액션 ID 시 404 반환")(async () => {
    await api.functional.discussionBoard.commentReactions.getById(connection, {
      id: nonExistentId,
    });
  });

  // 2. uuid 포맷이 아예 아닌 임의 문자열 (validation 에러)
  const invalidId = "not-a-uuid-string";
  await TestValidator.error("잘못된 id 포맷 시 validation error")(async () => {
    await api.functional.discussionBoard.commentReactions.getById(connection, {
      id: invalidId as any, // 컴파일러 우회 필요 (고의 invalid)
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentReaction";

/**
 * Test successful creation of a comment reaction with valid data
 *
 * This test verifies that a discussion board member, who has not previously reacted to a given comment, can react (e.g., 'like') to that comment. It ensures the API properly creates the reaction and returns a record accurately reflecting relationships: correct member, comment, and specified reaction type.
 *
 * Workflow:
 * 1. Register a new discussion board member (dependency step)
 * 2. Create a new comment authored by that member (dependency step)
 *    - Both post_id and thread_id use unique UUIDs; the comment will be a root comment (depth = 0)
 * 3. Submit a reaction (e.g., 'like') by that member to the comment
 * 4. Assert that the returned reaction:
 *    - Is linked to the correct member (member id)
 *    - Targets the correct comment (comment id)
 *    - Uses the intended reaction type ('like')
 *    - Has valid system fields (UUID id, created_at is date-time)
 */
export async function test_api_discussionBoard_test_create_comment_reaction_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Register a discussion board member
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a new comment authored by that member
  const comment = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: typia.random<string & tags.Format<"uuid">>(),
      thread_id: typia.random<string & tags.Format<"uuid">>(),
      author_id: member.id,
      body: RandomGenerator.paragraph()(),
      depth: 0,
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 3. Member submits a reaction to the comment
  const reactionType = "like";
  const reaction = await api.functional.discussionBoard.commentReactions.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      discussionboard_comment_id: comment.id,
      reaction_type: reactionType,
    } satisfies IDiscussionBoardCommentReaction.ICreate,
  });
  typia.assert(reaction);

  // 4. Validate result - correct relationships and record fields
  TestValidator.equals("reaction member link")(reaction.discussionboard_member_id)(member.id);
  TestValidator.equals("reaction comment link")(reaction.discussionboard_comment_id)(comment.id);
  TestValidator.equals("reaction type")(reaction.reaction_type)(reactionType);
  TestValidator.predicate("reaction id is valid UUID")(typeof reaction.id === "string" && /^[0-9a-fA-F-]{36}$/.test(reaction.id));
  TestValidator.predicate("created_at is valid ISO8601 date")(typeof reaction.created_at === "string" && !isNaN(Date.parse(reaction.created_at)));
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
