/**
 * Test prevention of duplicate comment reactions by a single member.
 *
 * This test verifies that the API prevents a member from reacting to the same comment with the same reaction type more than once. According to business rules and schema constraints, each member can only leave one reaction of a given type (e.g., 'like') per comment. The test ensures the unique restriction is enforced and that attempts to create a duplicate reaction are properly rejected with a conflict or duplicate error.
 *
 * Test Steps:
 * 1. Create a discussion board member (used as reaction author)
 * 2. Create a comment for a dummy post/thread, authored by the test member
 * 3. Add the first reaction (e.g., type 'like') to the comment as the test member
 * 4. Attempt to add the same reaction type ('like') again from the same member to the same comment
 * 5. Assert that the API throws an error (duplicate/conflict) on the second attempt
 */
export async function test_api_discussionBoard_test_create_comment_reaction_duplicate_not_allowed(
  connection: api.IConnection,
) {
  // 1. Create a discussion board member
  const memberInput = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "Password123!",
  } satisfies IDiscussionBoardMember.ICreate;
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Create a comment for a dummy post/thread
  const commentInput = {
    post_id: typia.random<string & tags.Format<"uuid">>(),
    thread_id: typia.random<string & tags.Format<"uuid">>(),
    author_id: member.id,
    body: RandomGenerator.paragraph()(),
    depth: 0,
  } satisfies IDiscussionBoardComment.ICreate;
  const comment = await api.functional.discussionBoard.comments.post(connection, {
    body: commentInput,
  });
  typia.assert(comment);

  // 3. Add the first reaction to the comment
  const reactionType = "like";
  const reactionInput = {
    discussionboard_member_id: member.id,
    discussionboard_comment_id: comment.id,
    reaction_type: reactionType,
  } satisfies IDiscussionBoardCommentReaction.ICreate;
  const reaction = await api.functional.discussionBoard.commentReactions.post(connection, {
    body: reactionInput,
  });
  typia.assert(reaction);

  // 4. Attempt to add the same reaction type again (should be rejected)
  TestValidator.error("Duplicate reaction not allowed")(async () => {
    await api.functional.discussionBoard.commentReactions.post(connection, {
      body: reactionInput,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCommentReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentReaction";

/**
 * Test prohibition of reaction creation using a non-existent member or comment.
 *
 * This test ensures that when attempting to create a discussion board comment reaction with either an invalid (non-existent) member ID or comment ID, the API enforces referential integrity and returns an error response.
 *
 * Steps:
 * 1. Attempt to create a comment reaction with an invalid member ID (well-formed UUID, but the member does not exist in the system).
 * 2. Assert that the API returns a not found or validation error for the invalid member.
 * 3. Attempt to create a comment reaction with an invalid comment ID (well-formed UUID, but the comment does not exist in the system).
 * 4. Assert that the API returns a not found or validation error for the invalid comment.
 *
 * This test does NOT require any real member or comment to be registered in the database. The focus is on validating API integrity checks for foreign keys and preventing orphan reactions. The test will use typia-generated UUIDs that are guaranteed not to exist in the database for both member and comment IDs.
 */
export async function test_api_discussionBoard_test_create_comment_reaction_with_invalid_member_or_comment(
  connection: api.IConnection,
) {
  // 1. Generate random (non-existent) UUIDs for both member and comment
  const invalidMemberId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const invalidCommentId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 2. Attempt to create a comment reaction with a non-existent member ID and comment ID
  await TestValidator.error("invalid member ID should not permit reaction creation")(
    async () => {
      await api.functional.discussionBoard.commentReactions.post(connection, {
        body: {
          discussionboard_member_id: invalidMemberId,
          discussionboard_comment_id: invalidCommentId,
          reaction_type: "like",
        } satisfies IDiscussionBoardCommentReaction.ICreate,
      });
    }
  );

  // 3. Attempt to create a comment reaction with a valid (well-formed) member ID and a new non-existent comment ID
  await TestValidator.error("invalid comment ID should not permit reaction creation")(
    async () => {
      await api.functional.discussionBoard.commentReactions.post(connection, {
        body: {
          discussionboard_member_id: invalidMemberId,
          discussionboard_comment_id: typia.random<string & tags.Format<"uuid">>(),
          reaction_type: "like",
        } satisfies IDiscussionBoardCommentReaction.ICreate,
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentReaction";

/**
 * 댓글 리액션의 작성자가 자신의 reaction_type을 정상적으로 수정할 수 있는지 검증합니다.
 *
 * - 비즈니스 컨텍스트: 게시판 멤버가 댓글에 'like'와 같은 리액션을 등록한 뒤, 작성자 본인이 직접 해당 리액션의 타입(예: 'like' → 'dislike')을 수정할 수 있어야 하며, 반영된 내용 및 감사타임스탬프가 제대로 갱신되는지 확인합니다. 또한 본인이 아닌 계정이 수정 시도 시 권한 오류가 발생함을 추가로 검증합니다.
 *
 * [절차]
 * 1. 신규 멤버(작성자) 등록
 * 2. 테스트용 댓글 생성 (임의 post/thread id 사용)
 * 3. 작성자가 댓글에 'like' 리액션 생성
 * 4. 작성자가 해당 리액션을 'dislike'로 수정
 * 5. 수정 결과 response에서 reaction_type 변경 및 타임스탬프 변화 확인
 * 6. 타인이 해당 리액션을 수정 시도 → 권한 오류 발생 검증
 */
export async function test_api_discussionBoard_test_update_comment_reaction_type_as_owner(
  connection: api.IConnection,
) {
  // 1. 신규 멤버(작성자) 등록
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. 테스트용 댓글 생성 (post_id, thread_id 임의)
  const postId = typia.random<string & tags.Format<"uuid">>();
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const comment = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: postId,
      thread_id: threadId,
      author_id: member.id,
      body: RandomGenerator.paragraph()(),
      depth: 0,
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 3. 작성자가 댓글에 'like' 리액션 생성
  const createdReaction = await api.functional.discussionBoard.commentReactions.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      discussionboard_comment_id: comment.id,
      reaction_type: "like",
    } satisfies IDiscussionBoardCommentReaction.ICreate,
  });
  typia.assert(createdReaction);

  // 4. 작성자가 해당 리액션을 'dislike'로 수정
  const updatedReaction = await api.functional.discussionBoard.commentReactions.putById(connection, {
    id: createdReaction.id,
    body: {
      reaction_type: "dislike",
    } satisfies IDiscussionBoardCommentReaction.IUpdate,
  });
  typia.assert(updatedReaction);

  // 5. reaction_type 변경 및 타임스탬프 변화 확인
  TestValidator.equals("reaction_type 변경됨")(updatedReaction.reaction_type)("dislike");
  // created_at은 생성 시각, updated_at이 있다면 비교하지만 여기선 created_at이 변경값을 대변한다고 간주
  TestValidator.notEquals("created_at 변경됨")(updatedReaction.created_at)(createdReaction.created_at);

  // 6. 타인이 해당 리액션 update 시도 → 권한 오류 확인
  const otherMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(otherMember);
  await TestValidator.error("타인은 댓글 리액션을 수정 불가")(() =>
    api.functional.discussionBoard.commentReactions.putById(connection, {
      id: createdReaction.id,
      body: {
        reaction_type: "like",
      } satisfies IDiscussionBoardCommentReaction.IUpdate,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentReaction";

/**
 * Validate uniqueness conflict on update of a comment reaction (PUT /discussionBoard/commentReactions/{id}).
 *
 * This test ensures that the API enforces uniqueness of (member, comment, reaction_type) tuples, by trying to update
 * one reaction to cause a duplicate collision with another existing reaction for the same member and comment.
 *
 * Test Steps:
 * 1. Create a member to act as the reaction author.
 * 2. Create two different comments that can each be reacted to.
 * 3. Have the created member react to comment1 with reaction type "like", and to comment2 with reaction type "dislike".
 * 4. Attempt to update the reaction to comment2, changing its type to "like". If both reactions are now for the same member, comment, and reaction type, this should cause a uniqueness conflict.
 * 5. Validate that the update fails with an error (e.g., duplicate constraint violation) and is not permitted.
 */
export async function test_api_discussionBoard_test_update_comment_reaction_duplicate_type_conflict(
  connection: api.IConnection,
) {
  // 1. Create member
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "securePassw0rd!",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create two comments (using different post/thread IDs)
  const postId1 = typia.random<string & tags.Format<"uuid">>();
  const threadId1 = typia.random<string & tags.Format<"uuid">>();
  const comment1 = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: postId1,
      thread_id: threadId1,
      author_id: member.id,
      body: "First comment content",
      depth: 0,
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment1);

  const postId2 = typia.random<string & tags.Format<"uuid">>();
  const threadId2 = typia.random<string & tags.Format<"uuid">>();
  const comment2 = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: postId2,
      thread_id: threadId2,
      author_id: member.id,
      body: "Second comment content",
      depth: 0,
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment2);

  // 3. Create two different reactions by the same member to different comments
  const reaction1 = await api.functional.discussionBoard.commentReactions.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      discussionboard_comment_id: comment1.id,
      reaction_type: "like",
    } satisfies IDiscussionBoardCommentReaction.ICreate,
  });
  typia.assert(reaction1);

  const reaction2 = await api.functional.discussionBoard.commentReactions.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      discussionboard_comment_id: comment2.id,
      reaction_type: "dislike",
    } satisfies IDiscussionBoardCommentReaction.ICreate,
  });
  typia.assert(reaction2);

  // 4. Attempt to update reaction2's type to "like", creating a conflicting tuple with reaction1
  await TestValidator.error("duplicate reaction tuple should fail")(
    async () => {
      await api.functional.discussionBoard.commentReactions.putById(connection, {
        id: reaction2.id,
        body: {
          reaction_type: "like",
        } satisfies IDiscussionBoardCommentReaction.IUpdate,
      });
    },
  );
}

