/**
 * Validate that only the creator (owner) of a comment reaction, or a privileged staff (moderator/admin), can delete a comment reaction.
 *
 * This test ensures that unauthorized members (those who are not the creator nor a staff) are forbidden from deleting another member's comment reaction.
 *
 * Workflow:
 * 1. Register two members (memberA and memberB).
 * 2. MemberA creates a comment (as the reaction target).
 * 3. MemberA reacts to their own comment (creates a reaction).
 * 4. MemberB (who is neither the creator nor a staff) attempts to delete the reaction of MemberA.
 * 5. The system must return an authorization/permission error for MemberB's delete attempt.
 */
export async function test_api_discussionBoard_test_delete_comment_reaction_by_non_owner_forbidden(connection: api.IConnection) {
  // 1. Register memberA (who will own the reaction)
  const memberA = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "Password1!"
    }
  });
  typia.assert(memberA);

  // 1. Register memberB (unauthorized user)
  const memberB = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "Password1!"
    }
  });
  typia.assert(memberB);

  // 2. MemberA creates a comment
  const comment = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: typia.random<string & tags.Format<"uuid">>(),
      thread_id: typia.random<string & tags.Format<"uuid">>(),
      author_id: memberA.id,
      body: RandomGenerator.content()()(),
      depth: 0
    }
  });
  typia.assert(comment);

  // 3. MemberA adds a reaction to the comment
  const reaction = await api.functional.discussionBoard.commentReactions.post(connection, {
    body: {
      discussionboard_member_id: memberA.id,
      discussionboard_comment_id: comment.id,
      reaction_type: "like"
    }
  });
  typia.assert(reaction);

  // 4. MemberB (not owner or staff) attempts to delete the reaction
  // (Assume connection now reflects memberB's authentication. For this test system, direct switch by context is assumed on registration.)
  // The action should fail with an authorization/permission error.
  // We use TestValidator.error to assert that an error is thrown.
  TestValidator.error("Non-owner should not be able to delete another member's comment reaction")(async () => {
    await api.functional.discussionBoard.commentReactions.eraseById(connection, {
      id: reaction.id
    });
  });
}

