import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { DiscussionBoardNotificationPreferences } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardNotificationPreferences";
import type { DiscussionBoardPageNotificationPreferences } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardPageNotificationPreferences";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Verify admin paginated and sorted retrieval of all notification preferences in the system.
 *
 * This test covers the end-to-end workflow for an administrator to access a paginated and sorted list of all notification preference records. It ensures elevated role access allows searching across all members, and confirms that pagination/sorting works as expected.
 *
 * Test steps:
 * 1. Create two distinct member accounts.
 * 2. Assign the admin role to the first member (elevated privileges).
 * 3. For each member, create a notification preference record with intentionally different settings.
 * 4. As the admin, request a paged and sorted list (simulate updated_at descending).
 * 5. Assert that the response contains both preference records in the correct order, and pagination information is accurate.
 */
export async function test_api_discussionBoard_notificationPreferences_test_list_notification_preferences_pagination_and_sorting_as_admin(
  connection: api.IConnection,
) {
  // 1. Create two distinct member accounts
  const member1 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12) as string & tags.Format<"password">,
    },
  });
  typia.assert(member1);

  const member2 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12) as string & tags.Format<"password">,
    },
  });
  typia.assert(member2);

  // 2. Assign the admin role to the first member
  const admin = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: member1.id,
      appointed_by_admin_id: member1.id, // Initial admin appoints self (bootstrap scenario)
    },
  });
  typia.assert(admin);

  // 3. Create notification preferences for both members with different settings
  const pref1 = await api.functional.discussionBoard.notificationPreferences.post(connection, {
    body: {
      member_id: member1.id,
      enable_email: true,
      enable_web_push: false,
      enable_system_announcements: true,
    },
  });
  typia.assert(pref1);

  // Artificial sleep to differentiate updated_at timestamps for sorting
  await new Promise((resolve) => setTimeout(resolve, 1100));

  const pref2 = await api.functional.discussionBoard.notificationPreferences.post(connection, {
    body: {
      member_id: member2.id,
      enable_email: false,
      enable_web_push: true,
      enable_system_announcements: false,
    },
  });
  typia.assert(pref2);

  // 4. Retrieve paginated list as admin (page 1, no filters, default sort: newest updated_at first if system supports)
  const resultPage = await api.functional.discussionBoard.notificationPreferences.patch(connection, {
    body: {
      page: 1,
    },
  });
  typia.assert(resultPage);

  // 5. Check both notification preferences are present in returned data (may ignore order if not sortable)
  const ids = [pref1.id, pref2.id];
  const returnedIds = resultPage.data.map((item) => item.id);
  TestValidator.predicate("Both preferences returned")(ids.every((id) => returnedIds.includes(id)));

  // Pagination should report at least two records
  TestValidator.predicate("Expected record count")(resultPage.pagination.records >= 2);
}

