 * This covers both active (currently valid) and archived (inactive/expired) policies.
 *
 * Steps:
 * 1. Create an active content policy (is_active: true, effective_to: null)
 * 2. Retrieve the content policy by ID and validate all fields
 * 3. Create an inactive (archived) policy (is_active: false, effective_to: set to a past date)
 * 4. Retrieve the archived policy by ID and validate all fields
 */
export async function test_api_discussionBoard_contentPolicies_getById_success(
  connection: api.IConnection,
) {
  // 1. Create an active content policy
  const activeCreate = {
    code: `ACTIVE_${RandomGenerator.alphaNumeric(8)}`,
    title: "Active Policy Title",
