import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardConfiguration";
import type { IPageIDiscussionBoardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardConfiguration";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test validation error responses when listing discussion board configurations with invalid filter or pagination parameters.
 *
 * This test verifies that the API does not accept malformed filter or pagination parameters when listing configuration settings for the discussion board. It sends various types of invalid data (such as a non-numeric page, a negative limit, or insertion of clearly malformed types), and expects the API to return an error rather than configuration data.
 * 
 * Steps:
 * 1. Attempt to request configurations with completely incorrect types (e.g., string where number is expected on 'page' and 'limit')
 * 2. Attempt with negative page or limit numbers
 * 3. Attempt with deeply malformed types for all fields
 * 4. Confirm that each request produces a validation error and does not return unintended configuration data
 * 5. Ensure that sensitive configuration data is not accidentally leaked for any invalid request
 */
export async function test_api_discussionBoard_test_list_configurations_with_invalid_filter_criteria(
  connection: api.IConnection,
) {
  // 1. Non-numeric page and limit
  await TestValidator.error("page/limit as string fails")(() =>
    api.functional.discussionBoard.configurations.patch(connection, {
      body: { page: "abc" as any, limit: "not-a-number" as any },
    })
  );

  // 2. Negative page or limit
  await TestValidator.error("negative page fails")(() =>
    api.functional.discussionBoard.configurations.patch(connection, {
      body: { page: -3, limit: 10 },
    })
  );
  await TestValidator.error("negative limit fails")(() =>
    api.functional.discussionBoard.configurations.patch(connection, {
      body: { page: 1, limit: -10 },
    })
  );

  // 3. Malformed types for all fields
  await TestValidator.error("all fields wrong type")(() =>
    api.functional.discussionBoard.configurations.patch(connection, {
      body: { page: "NaN" as any, limit: null, key: 123 as any, value: [], description: {} },
    })
  );

  // 4. Edge case: extremely large values
  await TestValidator.error("huge values in pagination")(() =>
    api.functional.discussionBoard.configurations.patch(connection, {
      body: { page: 99999999999, limit: 99999999999 },
    })
  );

  // 5. Edge case: attempt SQL-injection style string in key/value field
  await TestValidator.error("sql injection like string in key")(() =>
    api.functional.discussionBoard.configurations.patch(connection, {
      body: { key: "1; DROP TABLE discussionBoard_configurations;" },
    })
  );
}

