 * - Pagination returns the correct number of edits per page.
 * - Pagination metadata (current, limit, records, pages) is accurate.
 * - Only relevant edits appear in the response data.
 *
 * Workflow steps:
 * 1. Register a discussion board member who will be the editor.
 * 2. Create a new board.
 * 3. The member creates a post within the board.
 * 4. The member performs several edits of the post, creating a history.
 * 5. List post edits using PATCH /discussionBoard/postEdits with filters for the post and editor, and pagination (limit=2).
 * 6. Validate that the returned data matches the performed edits, respects pagination, and has correct metadata.
 */
export async function test_api_discussionBoard_test_list_post_edits_with_pagination_and_filter(
  connection: api.IConnection,
) {
  // 1. Register a discussion board member (editor)
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: "user_" + typia.random<string>(),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: "DisplayName_" + typia.random<string>(),
      password: "Test1234!@#" as string & tags.Format<"password">,
    },
  });
  typia.assert(member);

  // 2. Create a new board
  const board = await api.functional.discussionBoard.boards.post(connection, {
    body: {
      title: "Test Board - " + typia.random<string>(),
      slug: "test-board-" + typia.random<string>(),
      description: "Board Description " + typia.random<string>(),
    },
  });
  typia.assert(board);

  // 3. Member creates a post
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: board.id,
      author_id: member.id,
      title: "Test Post Title " + typia.random<string>(),
      body: "This is the original post content. " + typia.random<string>(),
    },
  });
  typia.assert(post);

  // 4. Member performs several edits
  const editPayloads = [
    {
      edit_summary: "Edit 1: typo fix",
      body_after_edit: post.body + " (typo fixed)",
    },
    {
      edit_summary: "Edit 2: improved clarity",
      body_after_edit: post.body + " (clarity improved)",
    },
    {
      edit_summary: "Edit 3: added example",
      body_after_edit: post.body + " (example added)",
    },
  ];
  const edits = [];
  for (const payload of editPayloads) {
    const edit = await api.functional.discussionBoard.postEdits.post(connection, {
      body: {
        post_id: post.id,
        editor_id: member.id,
        edit_summary: payload.edit_summary,
        body_after_edit: payload.body_after_edit,
      },
    });
    typia.assert(edit);
    edits.push(edit);
  }

  // 5. List post edits with patch endpoint, filtering by post_id and editor_id, page 1 with limit 2
  const pageLimit = 2;
  const page1 = await api.functional.discussionBoard.postEdits.patch(connection, {
    body: {
      post_id: post.id,
      editor_id: member.id,
      page: 1,
      limit: pageLimit,
    },
  });
  typia.assert(page1);

  // 6. Validate response contains only the expected edits (paginated)
  TestValidator.equals("pagination limit matches")(page1.pagination.limit)(pageLimit);
  TestValidator.equals("pagination current page")(page1.pagination.current)(1);
  TestValidator.predicate("total records count >= 3")(page1.pagination.records >= 3);
  TestValidator.predicate("data length matches limit or record count")(page1.data.length <= pageLimit && page1.data.length > 0);
  for (const edit of page1.data) {
    TestValidator.equals("post_id matches")(edit.post_id)(post.id);
    TestValidator.equals("editor_id matches")(edit.editor_id)(member.id);
  }
  if (page1.pagination.pages > 1) {
    const page2 = await api.functional.discussionBoard.postEdits.patch(connection, {
      body: {
        post_id: post.id,
        editor_id: member.id,
        page: 2,
        limit: pageLimit,
      },
    });
    typia.assert(page2);
    TestValidator.equals("pagination current page")(page2.pagination.current)(2);
    TestValidator.predicate("data length matches limit or remainder")(page2.data.length <= pageLimit && page2.data.length > 0);
    for (const edit of page2.data) {
      TestValidator.equals("post_id matches")(edit.post_id)(post.id);
      TestValidator.equals("editor_id matches")(edit.editor_id)(member.id);
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSection";
import type { IPageIDiscussionBoardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSection";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for fetching a paginated and searchable list of discussion board sections.
 *
 * This function validates the core discoverability flow for sections in the discussion board. An authenticated member attempts to retrieve the section list using pagination and search filters. This test ensures:
 *
 * 1. Fetch with default pagination (no filters): Should return paginated list of non-deleted sections and valid pagination metadata.
 * 2. Fetch with a search filter by section name: Only matching and non-deleted sections should be returned.
 * 3. Fetch with a search filter by section description: Only matching and non-deleted sections should be returned.
 * 4. Fetch with a valid channel UUID: Only sections from the specified channel should be returned.
 * 5. Fetch with explicit page/limit: Pagination metadata should reflect request and page size should be correct.
 * 6. Request with negative/invalid pagination params: Should result in an error response.
 * 7. Unauthenticated access attempt: Should be denied.
 *
 * Ensures normal user discoverability, working filtering, pagination accuracy, and error enforcement.
 */
export async function test_api_discussionBoard_test_list_sections_with_pagination_and_search(connection: api.IConnection) {
  // 1. Fetch sections (no filters, default pagination)
  const defaultOutput = await api.functional.discussionBoard.sections.patch(connection, {
    body: {},
  });
  typia.assert(defaultOutput);
  TestValidator.predicate("pagination present")(!!defaultOutput.pagination);
  TestValidator.predicate("data array present")(Array.isArray(defaultOutput.data));

  // 2. Search by section name (if any results exist)
  const searchName = defaultOutput.data.length > 0 ? defaultOutput.data[0].name : "Test";
  const filteredByName = await api.functional.discussionBoard.sections.patch(connection, {
    body: { name: searchName },
  });
  typia.assert(filteredByName);
  TestValidator.predicate("sections match name query")(
    filteredByName.data.every(section => section.name.includes(searchName))
  );

  // 3. Search by description (if description exists)
  const searchDescription = defaultOutput.data.length > 0 && defaultOutput.data[0].description
    ? defaultOutput.data[0].description
    : "";
  if (searchDescription) {
    const filteredByDesc = await api.functional.discussionBoard.sections.patch(connection, {
      body: { description: searchDescription },
    });
    typia.assert(filteredByDesc);
    TestValidator.predicate("sections match description query")(
      filteredByDesc.data.every(section => (section.description ?? "").includes(searchDescription))
    );
  }

  // 4. Filter by channel UUID (if any section exists)
  const filterChannelId = defaultOutput.data.length > 0 ? defaultOutput.data[0].discussionboard_channel_id : undefined;
  if (filterChannelId) {
    const filteredByChannel = await api.functional.discussionBoard.sections.patch(connection, {
      body: { discussionboard_channel_id: filterChannelId },
    });
    typia.assert(filteredByChannel);
    TestValidator.predicate("sections match channel filter")(
      filteredByChannel.data.every(section => section.discussionboard_channel_id === filterChannelId)
    );
  }

  // 5. Pagination: explicit page/limit settings
  const pagedOutput = await api.functional.discussionBoard.sections.patch(connection, {
    body: {
      page: 2,
      limit: 1,
    },
  });
  typia.assert(pagedOutput);
  TestValidator.equals("limit respected")(pagedOutput.data.length)(1);
  TestValidator.equals("pagination current page")(pagedOutput.pagination.current)(2);

  // 6. Malformed pagination request (negative page)
  await TestValidator.error("negative page forbidden")(async () => {
    await api.functional.discussionBoard.sections.patch(connection, {
      body: {
        page: -1,
      },
    });
  });

  // 7. Unauthorized access (drop Authorization header)
  const unauthConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("unauthenticated member denied")(async () => {
    await api.functional.discussionBoard.sections.patch(unauthConnection, {
      body: {},
    });
  });
}

