import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPolicyChangeLogs } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPolicyChangeLogs";

/**
 * Test retrieving full details for a specific policy change log by its unique ID as an authenticated admin.
 *
 * 1. Create a new policy change log using the POST endpoint as an authenticated admin and save the returned ID.
 * 2. Fetch the detail for this policy change log using GET by ID as an authenticated admin. Validate all expected fields (actor_admin_id, change_type, before_value, after_value, changed_at, reference fields changed_policy_id/changed_rule_id) are present and match the creation payload where applicable.
 * 3. Attempt to retrieve the same policy change log as a non-admin (simulate a connection with no admin privileges). Expect a 403 Forbidden error.
 * 4. Attempt to retrieve a non-existent policy change log as an admin, using a random UUID. Expect a 404 Not Found error.
 */
export async function test_api_discussionBoard_test_retrieve_policy_change_log_detail_by_id_as_admin(
  connection: api.IConnection,
) {
  // 1. Create a new policy change log as admin
  const policyLogCreate: IDiscussionBoardPolicyChangeLogs.ICreate = {
    actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
    // choose either changed_policy_id or changed_rule_id, others null
    changed_policy_id: typia.random<string & tags.Format<"uuid">>(),
    changed_rule_id: null,
    change_type: "ADD",
    before_value: null,
    after_value: JSON.stringify({ foo: "bar" }),
    changed_at: new Date().toISOString(),
  };
  const createdLog = await api.functional.discussionBoard.policyChangeLogs.post(connection, { body: policyLogCreate });
  typia.assert(createdLog);

  // 2. Retrieve the policy change log by its ID as admin
  const retrievedLog = await api.functional.discussionBoard.policyChangeLogs.getById(connection, { id: createdLog.id });
  typia.assert(retrievedLog);
  TestValidator.equals("ID matches")(retrievedLog.id)(createdLog.id);
  TestValidator.equals("admin actor matches")(retrievedLog.actor_admin_id)(policyLogCreate.actor_admin_id);
  TestValidator.equals("change type matches")(retrievedLog.change_type)(policyLogCreate.change_type);
  TestValidator.equals("after value matches")(retrievedLog.after_value)(policyLogCreate.after_value);
  TestValidator.equals("changed_policy_id matches")(retrievedLog.changed_policy_id)(policyLogCreate.changed_policy_id);
  TestValidator.equals("changed_rule_id matches")(retrievedLog.changed_rule_id)(policyLogCreate.changed_rule_id);
  TestValidator.equals("changed_at matches")(retrievedLog.changed_at)(policyLogCreate.changed_at);

  // 3. Try to retrieve as non-admin (simulate: clear or remove admin privileges)
  const connectionNonAdmin = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("Non-admin forbidden")(() =>
    api.functional.discussionBoard.policyChangeLogs.getById(connectionNonAdmin, { id: createdLog.id })
  );

  // 4. Attempt retrieval of non-existent ID as admin (use random UUID)
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Not found for non-existent policy log")(() =>
    api.functional.discussionBoard.policyChangeLogs.getById(connection, { id: randomId })
  );
}

