  TestValidator.equals("pagination.current")(result.pagination.current)(1);
  TestValidator.equals("pagination.limit")(result.pagination.limit)(3);
  // 총 회원 수가 (members + 관리자 1명)
  TestValidator.equals("pagination.records, 총 회원 수")(
    result.pagination.records,
  )(members.length + 1);

  // (b) username 부분일치(autotest_member_0) 검색 (page=1, limit=10)
  result = await api.functional.discussionBoard.members.patch(connection, {
    body: { page: 1, limit: 10, username: "autotest_member_0" },
  });
  typia.assert(result);
  // username에 "autotest_member_0" 포함된 회원만 반환
  for (const u of result.data) {
    TestValidator.predicate("username 부분일치 검색 결과 필터")(
      u.username.includes("autotest_member_0"),
    );
  }

  // (c) email 전체일치 검색
  const targetEmail = members[3].email;
  result = await api.functional.discussionBoard.members.patch(connection, {
    body: { page: 1, limit: 10, email: targetEmail },
  });
  typia.assert(result);
  TestValidator.equals("email 전체일치 사용자 단 1인 반환됨")(
    result.data.length,
  )(1);
  TestValidator.equals("반환 email값 매칭")(
    result.data[0].email,
  )(targetEmail);

  // (d) 존재하지 않는 display_name 검색(빈 결과)
  result = await api.functional.discussionBoard.members.patch(connection, {
    body: { page: 1, limit: 10, display_name: "__존재하지않음__" },
  });
  typia.assert(result);
  TestValidator.equals("display_name 불일치 검색 결과, 비어있음")(
    result.data.length,
  )(0);

  // (e) invalid page, limit(0/음수 등) → 에러 확인
  for (const params of [ { page: 0, limit: 3 }, { page: -1, limit: 2 }, { page: 2, limit: 0 } ]) {
    await TestValidator.error(`잘못된 page/limit: ${JSON.stringify(params)}`)(
      async () => {
        await api.functional.discussionBoard.members.patch(connection, {
          body: params,
        });
      },
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * Validate permission enforcement when a non-author member attempts to update a post.
 *
 * This test simulates two different member registrations. The first member will create an actual post
 * associated with a new board. Then the scenario attempts to update that post using the credentials
 * of the second member, who is not the original author. The expectation is that this update operation
 * will be forbidden and the API will respond with a 403 Forbidden error (no moderator or admin privilege
 * involved).
 *
 * Step-by-step process:
 * 1. Register the first member (author)
 * 2. Register the second member (non-author, will attempt the forbidden update)
 * 3. Create a new board
 * 4. Create a post in the new board as the first member
 * 5. Attempt to update the post as the second (non-author) member, expecting a 403 Forbidden error
 */
export async function test_api_discussionBoard_test_update_post_by_non_author_forbidden(connection: api.IConnection) {
  // 1. Register the first member (author)
  const member1Data = {
    username: RandomGenerator.alphabets(12),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "AuthorPass123!" as string & tags.Format<"password">,
  };
  const member1 = await api.functional.discussionBoard.members.post(connection, { body: member1Data });
  typia.assert(member1);

  // 2. Register the second member (non-author)
  const member2Data = {
    username: RandomGenerator.alphabets(12),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "NonAuthorPass456!" as string & tags.Format<"password">,
  };
  const member2 = await api.functional.discussionBoard.members.post(connection, { body: member2Data });
  typia.assert(member2);

  // 3. Create a new board
  const boardData = {
    title: RandomGenerator.paragraph()(1, 2),
    slug: RandomGenerator.alphabets(10).toLowerCase(),
    description: RandomGenerator.paragraph()(1, 2),
  };
  const board = await api.functional.discussionBoard.boards.post(connection, { body: boardData });
  typia.assert(board);

  // 4. Create a post as member1 (the author)
  const postData = {
    board_id: board.id,
    author_id: member1.id,
    title: RandomGenerator.paragraph()(1, 2),
    body: RandomGenerator.content()(1, 2, 64, 128),
  };
  const post = await api.functional.discussionBoard.posts.post(connection, { body: postData });
  typia.assert(post);

  // 5. Attempt to update the post as member2 (non-author), expecting a 403 error
  //
  // Note: In a real auth environment, the connection should be re-authenticated as member2 before this step.
  // Here, we assume the connection context is for member2, or that such authentication switching is managed elsewhere.
  const updateData = {
    title: RandomGenerator.paragraph()(1, 2),
    body: RandomGenerator.content()(1, 2, 64, 128),
    is_locked: false,
  };
  await TestValidator.error("Non-author cannot update post - should be forbidden")(
    async () => {
      await api.functional.discussionBoard.posts.putById(connection, {
        id: post.id,
        body: updateData,
      });
    }
  );
}

