import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";
import type { IPageIDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotificationSetting";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates paginated, filtered listing of discussion board notification settings as administrator (plus negative and edge cases).
 *
 * Ensures the following business rules:
 *  1. Only admins can list all (including potentially sensitive) notification settings.
 *  2. Supports filters by key, value, description, and creation timestamp.
 *  3. Pagination works: page and limit affect results and metadata as documented.
 *  4. Robust to edge cases: empty result set, page overflow, malformed pagination input.
 *  5. Unauthorized access is blocked.
 *
 * Steps:
 * 1. Create notification settings (with randomized keys/values/descriptions) as admin.
 * 2. Admin fetches with page/limit, validates response metadata and page contents.
 * 3. Admin filters by key, value, description, and date range; confirms filtering correctness.
 * 4. Admin attempts a filter that yields zero results, checks response.
 * 5. Admin requests an out-of-range page, verifies response is empty dataset, correct metadata.
 * 6. Negative: send PATCH with invalid page (0), expect error.
 * 7. Negative: unauthorized connection, expect error.
 */
export async function test_api_discussionBoard_notificationSettings_test_list_notification_settings_with_pagination_and_filters_by_admin(
  connection: api.IConnection,
) {
  // Step 1: Create test notification settings as admin
  const createdSettings: IDiscussionBoardNotificationSetting[] = [];
  for (let i = 0; i < 5; ++i) {
    const setting = await api.functional.discussionBoard.notificationSettings.post(connection, {
      body: {
        key: `key_${RandomGenerator.alphaNumeric(10)}`,
        value: `val_${RandomGenerator.alphaNumeric(8)}`,
        description: `desc ${RandomGenerator.alphabets(12)} for test ${i}`,
      } satisfies IDiscussionBoardNotificationSetting.ICreate,
    });
    typia.assert(setting);
    createdSettings.push(setting);
  }

  // Step 2: Admin fetches settings, page/limit (page=1, limit=3)
  const paginated = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      page: 1,
      limit: 3,
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(paginated);
  TestValidator.equals("records >= created")(paginated.pagination.records >= 5)(true);
  TestValidator.equals("page 1 limit respected")(paginated.data.length)(3);
  TestValidator.equals("page index")(paginated.pagination.current)(1);
  TestValidator.equals("page count formula")(paginated.pagination.pages)(Math.ceil(paginated.pagination.records / paginated.pagination.limit));

  // Step 3a: Filter by key
  const filterKey = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      key: createdSettings[2].key,
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(filterKey);
  TestValidator.equals("key filter result 1")(filterKey.data.length)(1);
  TestValidator.equals("filtered key matches")(filterKey.data[0].key)(createdSettings[2].key);

  // Step 3b: Filter by value
  const filterValue = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      value: createdSettings[4].value,
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(filterValue);
  TestValidator.equals("value filter result 1")(filterValue.data.length)(1);
  TestValidator.equals("filtered value matches")(filterValue.data[0].value)(createdSettings[4].value);

  // Step 3c: Filter by description substring
  const descTerm = createdSettings[1].description?.slice(0, 6) ?? "desc";
  const filterDesc = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      description: descTerm,
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(filterDesc);
  TestValidator.predicate("description filter includes at least one")(filterDesc.data.some(d => d.description?.includes(descTerm)));

  // Step 3d: Filter by created_at_from/created_at_to
  const { created_at } = createdSettings[0];
  const filterCreated = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      created_at_from: created_at,
      created_at_to: created_at,
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(filterCreated);
  TestValidator.predicate("created_at filter >= 1")(filterCreated.data.length >= 1);
  TestValidator.equals("created_at match")(filterCreated.data[0].created_at)(created_at);

  // Step 4: Filter with no results (invalid key)
  const empty = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      key: "no_such_key_" + RandomGenerator.alphaNumeric(10),
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(empty);
  TestValidator.equals("empty filter result")(empty.data.length)(0);

  // Step 5: Fetch page out of bounds (page very high)
  const outOfRange = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      page: 99,
      limit: 10,
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(outOfRange);
  TestValidator.equals("out of bounds is empty")(outOfRange.data.length)(0);

  // Step 6: Negative - invalid pagination (page 0)
  await TestValidator.error("page min constraint")(async () => {
    await api.functional.discussionBoard.notificationSettings.patch(connection, {
      body: {
        page: 0,
      } satisfies IDiscussionBoardNotificationSetting.IRequest,
    });
  });

  // Step 7: Negative - unauthorized (simulate missing admin)
  const noAuthConnection: api.IConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("unauthorized user")(async () => {
    await api.functional.discussionBoard.notificationSettings.patch(noAuthConnection, {
      body: {},
    });
  });
}

