import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IPageIDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated, filtered, and permissioned search of moderator assignments with varied filters.
 *
 * This E2E test ensures:
 * - Creation of multiple admins and regular members
 * - Assignment of moderator roles by different admins
 * - Varied assignment states (active/revoked)
 * - Accurate filtering by status, admins, member, assignment date ranges
 * - Pagination correctness
 * - Proper authorization: only admins/moderators can retrieve
 * - Error/edge cases: insufficient permissions, garbage filters, empty results
 *
 * Process:
 * 1. Create two admins (adminA, adminB)
 * 2. Create four regular members
 * 3. Assign moderator roles for all members (mix admins and status)
 * 4. Simulate revocation for one moderator (set revoked_at field)
 * 5. Test listing all moderators, filter by status, admin, member, date, pagination
 * 6. Validate permission enforcement for unauthorized access
 * 7. Test invalid filter input yields empty results
 */
export async function test_api_discussionBoard_test_list_moderators_with_varied_filters(connection: api.IConnection) {
  // 1. Create two admin candidate members
  const adminA = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "StrongPassword!1",
    },
  });
  typia.assert(adminA);
  const adminB = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "StrongPassword!1",
    },
  });
  typia.assert(adminB);

  // 2. Create 4 regular members
  const users = await ArrayUtil.asyncRepeat(4)(async () => {
    const user = await api.functional.discussionBoard.members.post(connection, {
      body: {
        username: RandomGenerator.alphabets(8),
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(),
        password: "UserPassword!1",
      },
    });
    typia.assert(user);
    return user;
  });

  // 3. Assign moderator roles
  const assignments: IDiscussionBoardModerator[] = [
    await api.functional.discussionBoard.moderators.post(connection, {
      body: {
        member_id: users[0].id,
        promoted_by_admin_id: adminA.id,
      },
    }),
    await api.functional.discussionBoard.moderators.post(connection, {
      body: {
        member_id: users[1].id,
        promoted_by_admin_id: adminA.id,
      },
    }),
    await api.functional.discussionBoard.moderators.post(connection, {
      body: {
        member_id: users[2].id,
        promoted_by_admin_id: adminB.id,
      },
    }),
    await api.functional.discussionBoard.moderators.post(connection, {
      body: {
        member_id: users[3].id,
        promoted_by_admin_id: adminB.id,
      },
    }),
  ];
  assignments.forEach(typia.assert);

  // 4. Simulate revocation for user4 (cannot do via API, so mimic by changing field for test purpose)
  assignments[3].revoked_at = new Date(Date.now() + 1000).toISOString();

  // 5. List all moderators (no filters)
  let res = await api.functional.discussionBoard.moderators.patch(connection, {
    body: {},
  });
  typia.assert(res);
  TestValidator.predicate("all moderator assignments")(res.data.length >= 4);

  // status = "active"
  res = await api.functional.discussionBoard.moderators.patch(connection, {
    body: { status: "active" },
  });
  typia.assert(res);
  TestValidator.predicate("active only")(res.data.every((m) => m.revoked_at == null));
  TestValidator.equals("active count")(res.data.length)(3);

  // status = "revoked"
  res = await api.functional.discussionBoard.moderators.patch(connection, {
    body: { status: "revoked" },
  });
  typia.assert(res);
  TestValidator.predicate("revoked only")(res.data.every((m) => m.revoked_at != null));
  TestValidator.equals("revoked count")(res.data.length)(1);

  // promoted_by_admin_id = adminA
  res = await api.functional.discussionBoard.moderators.patch(connection, {
    body: { promoted_by_admin_id: adminA.id },
  });
  typia.assert(res);
  TestValidator.equals("adminA assignments")(res.data.length)(2);
  TestValidator.predicate("all adminA")(res.data.every((m) => m.promoted_by_admin_id === adminA.id));

  // promoted_by_admin_id = adminB
  res = await api.functional.discussionBoard.moderators.patch(connection, {
    body: { promoted_by_admin_id: adminB.id },
  });
  typia.assert(res);
  TestValidator.equals("adminB assignments")(res.data.length)(2);
  TestValidator.predicate("all adminB")(res.data.every((m) => m.promoted_by_admin_id === adminB.id));

  // member_id = user3
  res = await api.functional.discussionBoard.moderators.patch(connection, {
    body: { member_id: users[2].id },
  });
  typia.assert(res);
  TestValidator.equals("user3 assignment count")(res.data.length)(1);
  TestValidator.equals("user3 member_id")(res.data[0].member_id)(users[2].id);

  // assigned_from/assigned_to: Only assignments within this range
  const from = assignments[1].assigned_at;
  const to = assignments[2].assigned_at;
  res = await api.functional.discussionBoard.moderators.patch(connection, {
    body: { assigned_from: from, assigned_to: to },
  });
  typia.assert(res);
  TestValidator.predicate("assignments in range")(res.data.every((m) => m.assigned_at >= from && m.assigned_at <= to));

  // Pagination: limit = 2
  res = await api.functional.discussionBoard.moderators.patch(connection, {
    body: { limit: 2 },
  });
  typia.assert(res);
  TestValidator.equals("pagination size")(res.data.length)(2);

  // Pagination: next page
  res = await api.functional.discussionBoard.moderators.patch(connection, {
    body: { limit: 2, page: 2 },
  });
  typia.assert(res);
  TestValidator.predicate("next page")(res.data.length >= 1);

  // Try with a non-privileged user: access denied (simulate by passing user connection)
  await TestValidator.error("member cannot list moderators")(async () => {
    await api.functional.discussionBoard.moderators.patch(connection, {
      body: { status: "active", member_id: users[0].id },
    });
  });

  // Invalid filter (invalid member_id)
  res = await api.functional.discussionBoard.moderators.patch(connection, {
    body: { member_id: "00000000-1234-1234-1234-000000000000" },
  });
  typia.assert(res);
