  const from = assignments[1].assigned_at;
  const to = assignments[2].assigned_at;
  res = await api.functional.discussionBoard.moderators.patch(connection, {
    body: { assigned_from: from, assigned_to: to },
  });
  typia.assert(res);
  TestValidator.predicate("assignments in range")(res.data.every((m) => m.assigned_at >= from && m.assigned_at <= to));

  // Pagination: limit = 2
  res = await api.functional.discussionBoard.moderators.patch(connection, {
    body: { limit: 2 },
  });
  typia.assert(res);
  TestValidator.equals("pagination size")(res.data.length)(2);

  // Pagination: next page
  res = await api.functional.discussionBoard.moderators.patch(connection, {
    body: { limit: 2, page: 2 },
  });
  typia.assert(res);
  TestValidator.predicate("next page")(res.data.length >= 1);

  // Try with a non-privileged user: access denied (simulate by passing user connection)
  await TestValidator.error("member cannot list moderators")(async () => {
    await api.functional.discussionBoard.moderators.patch(connection, {
      body: { status: "active", member_id: users[0].id },
    });
  });

  // Invalid filter (invalid member_id)
  res = await api.functional.discussionBoard.moderators.patch(connection, {
    body: { member_id: "00000000-1234-1234-1234-000000000000" },
  });
  typia.assert(res);
  TestValidator.equals("invalid filter results")(res.data.length)(0);
}

