  const filterValue = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      value: createdSettings[4].value,
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(filterValue);
  TestValidator.equals("value filter result 1")(filterValue.data.length)(1);
  TestValidator.equals("filtered value matches")(filterValue.data[0].value)(createdSettings[4].value);

  // Step 3c: Filter by description substring
  const descTerm = createdSettings[1].description?.slice(0, 6) ?? "desc";
  const filterDesc = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      description: descTerm,
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(filterDesc);
  TestValidator.predicate("description filter includes at least one")(filterDesc.data.some(d => d.description?.includes(descTerm)));

  // Step 3d: Filter by created_at_from/created_at_to
  const { created_at } = createdSettings[0];
  const filterCreated = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      created_at_from: created_at,
      created_at_to: created_at,
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(filterCreated);
  TestValidator.predicate("created_at filter >= 1")(filterCreated.data.length >= 1);
  TestValidator.equals("created_at match")(filterCreated.data[0].created_at)(created_at);

  // Step 4: Filter with no results (invalid key)
  const empty = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      key: "no_such_key_" + RandomGenerator.alphaNumeric(10),
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(empty);
  TestValidator.equals("empty filter result")(empty.data.length)(0);

  // Step 5: Fetch page out of bounds (page very high)
  const outOfRange = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      page: 99,
      limit: 10,
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(outOfRange);
  TestValidator.equals("out of bounds is empty")(outOfRange.data.length)(0);

  // Step 6: Negative - invalid pagination (page 0)
  await TestValidator.error("page min constraint")(async () => {
    await api.functional.discussionBoard.notificationSettings.patch(connection, {
      body: {
        page: 0,
      } satisfies IDiscussionBoardNotificationSetting.IRequest,
    });
  });

  // Step 7: Negative - unauthorized (simulate missing admin)
  const headersNoAuth = { ...connection.headers };
  delete headersNoAuth.Authorization;
  const noAuthConnection: api.IConnection = { ...connection, headers: headersNoAuth };
  await TestValidator.error("unauthorized user")(async () => {
    await api.functional.discussionBoard.notificationSettings.patch(noAuthConnection, {
      body: {},
    });
  });
}

