import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";

/**
 * 관리자 권한으로 알림 설정 상세 조회 API를 테스트한다.
 *
 * 성공 케이스:
 *   - 이미 생성된 알림 설정 ID를 이용해 상세 조회 시, 모든 주요 필드(key, value, description, 생성/수정일 등)가 정확하게 반환되는지 확인
 *
 * 실패(비정상) 케이스:
 *   - 존재하지 않는 ID로 조회 시 404 not found 오류가 발생하는지 확인
 *   - (선택) 관리자가 아닌 일반 권한 또는 비로그인으로 접근할 경우 권한 오류가 발생하는지 확인 (connection 전환/권한 분리 환경 제공 가능 시에만)
 *
 * 테스트 단계
 * 1. 사전: 알림 설정 데이터를 생성한다(POST /discussionBoard/notificationSettings)
 * 2. 성공: 방금 생성한 알림 설정 ID로 상세 조회. 반환 필드와 값 일치 여부 비교
 * 3. 실패a: 존재하지 않는 무작위 uuid로 조회 시도 후 404 발생 확인
 * 4. 실패b: (선택) 비관리자/일반 사용자 connection에서 접근 시 권한 거부 오류 발생 확인 (시스템이 이를 지원할 경우만)
 */
export async function test_api_discussionBoard_notificationSettings_getById(
  connection: api.IConnection,
) {
  // 1. 알림 설정 데이터 생성(사전 준비)
  const createBody = {
    key: `unit_test_key_${RandomGenerator.alphaNumeric(8)}`,
    value: "immediate",
    description: "테스트용 알림 설정 설명입니다.",
  } satisfies IDiscussionBoardNotificationSetting.ICreate;
  const created = await api.functional.discussionBoard.notificationSettings.post(connection, { body: createBody });
  typia.assert(created);

  // 2. 성공 - 생성된 ID로 상세 조회 및 값 비교
  const fetched = await api.functional.discussionBoard.notificationSettings.getById(connection, { id: created.id });
  typia.assert(fetched);
  TestValidator.equals("id 일치")(fetched.id)(created.id);
  TestValidator.equals("key 일치")(fetched.key)(createBody.key);
  TestValidator.equals("value 일치")(fetched.value)(createBody.value);
  TestValidator.equals("description 일치")(fetched.description)(createBody.description ?? null);
  // created_at, updated_at 등은 서버에서 자동 생성이므로 단순 존재(assert)만 수행
  TestValidator.predicate("created_at valid")(!!fetched.created_at);
  TestValidator.predicate("updated_at valid")(!!fetched.updated_at);

  // 3. 실패a - 존재하지 않는 uuid로 조회 시도 시 404
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("존재하지 않는 ID는 404")(async () => {
    await api.functional.discussionBoard.notificationSettings.getById(connection, { id: nonExistentId });
  });

  // 4. 실패b - 비관리자 connection 권한(옵션, 시스템 지원 시)
  // 예시)
  // const userConnection = ... // 일반 사용자 권한 값 세팅(로그인 등)
  // TestValidator.error("비관리자 접근 시 권한 거부")(
  //   async () => {
  //     await api.functional.discussionBoard.notificationSettings.getById(userConnection, { id: created.id });
  //   },
  // );
}

