import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";

/**
 * Tests admin creation of discussion board notification settings.
 *
 * This test covers comprehensive business logic and input validation:
 *   1. Create a new notification setting with a unique key and optional description (success case)
 *   2. Validate that the created record returns correct metadata (id, created_at, updated_at, etc), required fields, and optional fields
 *   3. Attempt to create another notification setting with the same key (should fail with duplicate key error)
 *   4. Attempt to create a setting omitting required fields (should fail validation)
 */
export async function test_api_discussionBoard_test_create_notification_setting_with_unique_key_and_duplicate_key_error(
  connection: api.IConnection,
) {
  // 1. Create setting with a unique key, value, and description (expect success)
  const uniqueKey = `notif_${RandomGenerator.alphabets(8)}`;
  const value = "immediate";
  const description = RandomGenerator.paragraph()();
  const createInput = {
    key: uniqueKey,
    value,
    description,
  } satisfies IDiscussionBoardNotificationSetting.ICreate;

  const created = await api.functional.discussionBoard.notificationSettings.post(connection, { body: createInput });
  typia.assert(created);

  // Field-level checks for created record
  TestValidator.equals("key matches input")(created.key)(uniqueKey);
  TestValidator.equals("value matches input")(created.value)(value);
  TestValidator.equals("description matches input")(created.description)(description);
  TestValidator.predicate("id is uuid")(
    typeof created.id === "string" && created.id.length > 0
  );
  TestValidator.predicate("created_at is date-time")(
    !!Date.parse(created.created_at)
  );
  TestValidator.predicate("updated_at is date-time")(
    !!Date.parse(created.updated_at)
  );
  TestValidator.equals("deleted_at should be null when just created")(created.deleted_at)(null);

  // 2. Duplicate key creates error
  await TestValidator.error("duplicate notification key errors out")(
    () =>
      api.functional.discussionBoard.notificationSettings.post(connection, {
        body: {
          key: uniqueKey,
          value: "daily",
          description: "Duplicate should fail",
        } satisfies IDiscussionBoardNotificationSetting.ICreate,
      })
  );

  // 3. Missing required 'key' field (should throw validation error)
  await TestValidator.error("missing key field works")(
    () =>
      api.functional.discussionBoard.notificationSettings.post(connection, {
        body: {
          // key omitted intentionally
          value: "immediate",
        } as any, // purposely invalid input for runtime validator
      })
  );

  // 4. Missing required 'value' field (should throw validation error)
  await TestValidator.error("missing value field triggers validation error")(
    () =>
      api.functional.discussionBoard.notificationSettings.post(connection, {
        body: {
          key: `k_${RandomGenerator.alphabets(6)}`,
          // value omitted intentionally
        } as any,
      })
  );
}

