import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";

/**
 * Validate retrieval of an admin assignment record by ID, including business logic success and failure scenarios.
 *
 * This test verifies:
 * 1. Successful retrieval by ID as an admin returns full assignment record with valid metadata.
 * 2. Retrieval by an invalid/non-existent ID yields 404 Not Found.
 * 3. Attempt to access by a non-admin results in permission denial (403 Forbidden).
 *
 * Steps:
 * 1. Register two members (A = first admin, B = will be promoted).
 * 2. Appoint A as an admin (self-appointment, for initial admin scenario).
 * 3. As admin A, appoint member B as admin.
 * 4. Retrieve B's admin assignment record by ID as admin; validate data integrity.
 * 5. Retrieve with a non-existent/random UUID; check for 404 error.
 * 6. Register member C (non-admin); attempt to retrieve; check for 403 forbidden (conceptually—actual connection role change requires authentication API, not exposed here).
 * 7. Optional: Skipped – revocation test skipped due to lack of explicit API to revoke admin.
 */
export async function test_api_discussionBoard_test_get_admin_assignment_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Register two members (A: initial admin, B: to promote)
  const memberA = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.alphabets(10),
      password: typia.random<string & tags.Format<'password'>>()
    }
  });
  typia.assert(memberA);

  const memberB = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.alphabets(10),
      password: typia.random<string & tags.Format<'password'>>()
    }
  });
  typia.assert(memberB);

  // 2. Appoint A as admin (self-appointment for initial case)
  const adminAssignA = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: memberA.id,
      appointed_by_admin_id: memberA.id
    }
  });
  typia.assert(adminAssignA);

  // 3. As admin, appoint member B as admin
  const adminAssignB = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: memberB.id,
      appointed_by_admin_id: memberA.id
    }
  });
  typia.assert(adminAssignB);

  // 4. Retrieve B's admin assignment record by ID as admin
  const getAdminB = await api.functional.discussionBoard.admins.getById(connection, {
    id: adminAssignB.id
  });
  typia.assert(getAdminB);
  TestValidator.equals('admin assignment id')(getAdminB.id)(adminAssignB.id);
  TestValidator.equals('member_id')(getAdminB.member_id)(memberB.id);
  TestValidator.equals('appointed_by_admin_id')(getAdminB.appointed_by_admin_id)(adminAssignB.appointed_by_admin_id);
  TestValidator.equals('appointed_at')(getAdminB.appointed_at)(adminAssignB.appointed_at);
  TestValidator.equals('revoked_at')(getAdminB.revoked_at)(adminAssignB.revoked_at);

  // 5. Try retrieving with a non-existent/random UUID; expect 404
  await TestValidator.error('404 on non-existent ID')(async () => {
    await api.functional.discussionBoard.admins.getById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>()
    });
  });

  // 6. Register non-admin member C
  const memberC = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.alphabets(10),
      password: typia.random<string & tags.Format<'password'>>()
    }
  });
  typia.assert(memberC);

  // (Conceptual) Attempt by non-admin (memberC) to access admin assignment: expect forbidden (403)
  // Note: Actual per-user authentication cannot be simulated without an explicit auth API.
  await TestValidator.error('Forbidden for non-admin')(async () => {
    // In a complete system, would use a connection authenticated as memberC.
    await api.functional.discussionBoard.admins.getById(connection, {
      id: adminAssignB.id
    });
  });

  // 7. (Optional) Skipping admin revocation/revoked_at handling due to lack of supporting API.
}

