/**
 * E2E test for deleting (revoking) an admin assignment from the discussion board system with full permission and audit logic verification.
 *
 * This test ensures:
 * 1. An authorized admin can delete (revoke) a given administrator assignment record by its ID; deletion marks it as soft-deleted.
 * 2. The deleted assignment is audit-logged (if verifiable via available APIs).
 * 3. Deleting with an invalid or already-deleted (revoked) ID returns the proper error response.
 * 4. Only implementable/observable behaviors are validated (listing and permission checks omitted if not possible).
 *
 * Steps:
 * 1. Register three members (admin assigner, admin target, and third non-admin user).
 * 2. Bootstrap admin assignment to memberA (first admin, self-appoint).
 * 3. Assign admin to memberB via memberA (creates assignment we can later delete).
 * 4. As admin, revoke memberB's admin assignment by ID (delete endpoint).
 * 5. Try to delete the same admin assignment again (should fail as already revoked).
 * 6. Try to delete a non-existent/invalid admin assignment (should fail).
 * 7. Permission check for non-admin user omitted due to SDK limitations.
 */
export async function test_api_discussionBoard_test_delete_admin_assignment_with_audit_and_permission_checks(
  connection: api.IConnection,
) {
  // 1. Register three members: memberA (admin assigner), memberB (admin target), and memberC (non-admin)
  const memberA = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    },
  });
  typia.assert(memberA);

  const memberB = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    },
  });
  typia.assert(memberB);

  const memberC = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    },
  });
  typia.assert(memberC);

  // 2. Bootstrap admin privilege by self-appointing memberA (first admin)
  const adminA = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: memberA.id,
      appointed_by_admin_id: memberA.id,
    },
  });
  typia.assert(adminA);

  // 3. Assign admin role to memberB using memberA
  const adminB = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: memberB.id,
      appointed_by_admin_id: memberA.id,
    },
