  // 5. Attempt to delete again — expect error (already revoked)
  await TestValidator.error("Deleting already-revoked admin assignment should fail")(async () => {
    await api.functional.discussionBoard.admins.eraseById(connection, {
      id: adminB.id,
    });
  });

  // 6. Attempt to delete with an invalid random UUID (should fail)
  await TestValidator.error("Deleting with invalid admin assignment ID should fail")(async () => {
    await api.functional.discussionBoard.admins.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });
  // 7. Permission check for non-admin context is omitted due to SDK limitation (no login/user context API).
}

