import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerationAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAppeal";
import type { DiscussionBoardAppealDecision } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAppealDecision";
import type { PageDiscussionBoardAppealDecision } from "@ORGANIZATION/PROJECT-api/lib/structures/PageDiscussionBoardAppealDecision";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test: List appeal decisions with filter, pagination, and authorization controls.
 *
 * 1. Prepare appeals: Create multiple moderation appeals with unique actions and member IDs
 * 2. Prepare decisions: For each appeal, create corresponding appeal decisions; vary moderators/admins and outcomes
 * 3. Filter tests:
 *   a. Query by each unique outcome (decision_outcome) and assert correct filtering
 *   b. Query using moderator_id/admin_id and assert only their relevant decisions returned
 *   c. Query by single appeal_id and check correct linkage
 *   d. Use date filters (created_after, created_before) and check boundaries
 * 4. Pagination tests:
 *   a. Query with small limit, multiple pages, assert result counts and non-overlap
 *   b. Query out-of-bounds page, assert empty result
 * 5. Edge/negative tests:
 *   a. Filtering with non-existent values (UUIDs/outcomes) must return empty result list
 *   b. Submit malformed parameters (wrong types, missing required fields) and confirm error response
 * 6. Authorization:
 *   a. As moderator/admin: access is allowed
 *   b. As normal member: access must be denied (simulate by using their connection)
 */
export async function test_api_discussionBoard_test_list_appeal_decisions_with_various_filters_and_paginations(
  connection: api.IConnection,
) {
  // Preparation: create several appeals/actions/users (mocked prerequisites where needed)

  // 1. Create appeals
  const appeals = await ArrayUtil.asyncRepeat(3)(async () => {
    const appeal = await api.functional.discussionBoard.moderationAppeals.post(connection, {
      body: {
        moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
        member_id: typia.random<string & tags.Format<"uuid">>(),
        appeal_reason: RandomGenerator.paragraph()(),
      },
    });
    typia.assert(appeal);
    return appeal;
  });

  // 2. Create decisions for each appeal, with various actors and outcomes
  const outcomes = ["upheld", "overturned", "modified"];
  const moderator_id = typia.random<string & tags.Format<"uuid">>();
  const admin_id = typia.random<string & tags.Format<"uuid">>();

  const decisions = await ArrayUtil.asyncMap(appeals)(async (appeal, idx) => {
    const outcome = outcomes[idx % outcomes.length];
    const actor = idx % 2 === 0 ? { moderator_id } : { admin_id };
    const decision = await api.functional.discussionBoard.appealDecisions.post(connection, {
      body: {
        appeal_id: appeal.id,
        ...actor,
        decision_outcome: outcome,
        decision_rationale: RandomGenerator.paragraph()(),
      },
    });
    typia.assert(decision);
    return decision;
  });

  // 3a. Filter: by decision_outcome
  for (const outcome of outcomes) {
    const filtered = await api.functional.discussionBoard.appealDecisions.patch(connection, {
      body: { decision_outcome: outcome },
    });
    typia.assert(filtered);
    TestValidator.predicate(`all decisions have outcome='${outcome}'`)(
      filtered.data.every((d) => d.decision_outcome === outcome),
    );
  }

  // 3b. Filter: by moderator_id and admin_id
  {
    const filteredByMod = await api.functional.discussionBoard.appealDecisions.patch(connection, { body: { moderator_id } });
    typia.assert(filteredByMod);
    TestValidator.predicate("all moderator decisions match")(
      filteredByMod.data.every((d) => d.moderator_id === moderator_id),
    );
    const filteredByAdmin = await api.functional.discussionBoard.appealDecisions.patch(connection, { body: { admin_id } });
    typia.assert(filteredByAdmin);
    TestValidator.predicate("all admin decisions match")(
      filteredByAdmin.data.every((d) => d.admin_id === admin_id),
    );
  }

  // 3c. Filter: by appeal_id
  for (const appeal of appeals) {
    const byAppeal = await api.functional.discussionBoard.appealDecisions.patch(connection, {
      body: { appeal_id: appeal.id },
    });
    typia.assert(byAppeal);
    TestValidator.predicate("all have correct appeal_id")(
      byAppeal.data.every((d) => d.appeal_id === appeal.id),
    );
  }

  // 3d. Date filters: created_after, created_before
  {
    const picked = decisions[0];
    const after = await api.functional.discussionBoard.appealDecisions.patch(connection, {
      body: { created_after: picked.created_at },
    });
    typia.assert(after);
    TestValidator.predicate("created_after filter works")(
      after.data.every((d) => new Date(d.created_at) > new Date(picked.created_at)),
    );
    const before = await api.functional.discussionBoard.appealDecisions.patch(connection, {
      body: { created_before: picked.created_at },
    });
    typia.assert(before);
    TestValidator.predicate("created_before filter works")(
      before.data.every((d) => new Date(d.created_at) < new Date(picked.created_at)),
    );
  }

  // 4a. Pagination: multiple pages
  {
    const limit = 1;
    const page0 = await api.functional.discussionBoard.appealDecisions.patch(connection, { body: { limit, page: 0 } });
    const page1 = await api.functional.discussionBoard.appealDecisions.patch(connection, { body: { limit, page: 1 } });
    typia.assert(page0);
    typia.assert(page1);
    TestValidator.notEquals("no overlap between pages")(
      page0.data[0]?.id,
    )(page1.data[0]?.id);
  }

  // 4b. Out-of-bounds: large page index returns empty result
  {
    const oob = await api.functional.discussionBoard.appealDecisions.patch(connection, { body: { page: 1000, limit: 1 } });
    typia.assert(oob);
    TestValidator.equals("out-of-bounds page is empty")(
      oob.data.length,
    )(0);
  }

  // 5a. Filter by non-existent UUID/outcome
  {
    const norecords = await api.functional.discussionBoard.appealDecisions.patch(connection, { body: { appeal_id: typia.random<string & tags.Format<"uuid">>() } });
    typia.assert(norecords);
    TestValidator.equals("non-existent appeal id, empty results")(
      norecords.data.length,
    )(0);
    const badOutcome = await api.functional.discussionBoard.appealDecisions.patch(connection, { body: { decision_outcome: "not_a_real_outcome" } });
    typia.assert(badOutcome);
    TestValidator.equals("non-existent outcome, empty results")(
      badOutcome.data.length,
    )(0);
  }

  // 5b. Malformed filter param triggers error (page as string)
  await TestValidator.error("malformed filter param")(
    async () => {
      await api.functional.discussionBoard.appealDecisions.patch(connection, { body: { page: "wrong_type" as any } });
    }
  );

  // 6. Authorization negative (should be denied for normal member, but switching simulated accounts is infra-dependent)
  // Not implemented due to lack of user/session context in API inputs.
}

