/**
 * Validate role-based access control for fetching a specific moderation appeal decision by ID.
 *
 * This test ensures that:
 * 1. The appealing member can retrieve their own appeal decision.
 * 2. The assigned moderator or admin on the decision can retrieve it (in data, not identity — as real role simulation via auth is not available).
 * 3. Attempting to fetch a non-existent appeal decision returns an error.
 *
 * NOTES:
 * - Since there are no authentication or account-creation APIs available in the test materials, actor switching and true role-based access control cannot be simulated. Instead, we validate access solely by data linkage: the appealing member, moderator, and admin IDs used during record creation.
 * - Negative/failure tests for proper forbidden/unauthorized responses as a different user are omitted, as such access control cannot be verified without authentication mechanisms.
 *
 * Steps:
 * 1. Create a moderation appeal. Record the used member_id.
 * 2. Create an appeal decision, linked to the created appeal. Supply either moderator_id or admin_id (simulate both to verify both cases work).
 * 3. Fetch the decision by its ID and validate that all fields/data correspond to what was provided (i.e. assigned participant relationships are correct).
 * 4. Attempt to fetch a non-existent appeal decision ID and assert that it returns an error.
 */
export async function test_api_discussionBoard_test_get_appeal_decision_by_id_with_role_access_control(
  connection: api.IConnection,
) {
  // 1. Create a moderation appeal (simulate appealing member ID)
  const appealingMemberId = typia.random<string & tags.Format<"uuid">>();
  const moderationActionId = typia.random<string & tags.Format<"uuid">>();
  const appeal = await api.functional.discussionBoard.moderationAppeals.post(
    connection,
    {
      body: {
        moderation_action_id: moderationActionId,
        member_id: appealingMemberId,
        appeal_reason: "I believe the moderation action was incorrect because...",
      } satisfies IDiscussionBoardModerationAppeal.ICreate,
    },
  );
  typia.assert(appeal);
  TestValidator.equals("appealing member linkage")(appeal.member_id)(appealingMemberId);
  TestValidator.equals("moderation action linkage")(appeal.moderation_action_id)(moderationActionId);

  // 2. Create the appeal decision as MODERATOR (simulate an assigned moderator ID)
  const moderatorId = typia.random<string & tags.Format<"uuid">>();
  const appealDecisionModerator = await api.functional.discussionBoard.appealDecisions.post(
    connection,
    {
      body: {
        appeal_id: appeal.id,
        moderator_id: moderatorId,
        admin_id: undefined,
        decision_outcome: "upheld",
        decision_rationale: "Review found the appeal not persuasive.",
      } satisfies DiscussionBoardAppealDecision.ICreate,
    },
  );
  typia.assert(appealDecisionModerator);
  TestValidator.equals("linkage to appeal")(appealDecisionModerator.appeal_id)(appeal.id);
  TestValidator.equals("assigned moderator linkage")(appealDecisionModerator.moderator_id)(moderatorId);
  TestValidator.equals("admin ID should be undefined")(appealDecisionModerator.admin_id)(undefined);
  TestValidator.equals("decision rationale")(appealDecisionModerator.decision_rationale)("Review found the appeal not persuasive.");

  // 3. Fetch the decision by its ID as the creator (executor acting as any user)
  const fetchedModeratorDecision = await api.functional.discussionBoard.appealDecisions.getById(
    connection,
    {
      id: appealDecisionModerator.id,
    },
  );
  typia.assert(fetchedModeratorDecision);
  TestValidator.equals("decision ID fetch matches created moderator decision")(
    fetchedModeratorDecision.id,
  )(appealDecisionModerator.id);

  // 4. Create the appeal decision as ADMIN (simulate an assigned admin ID)
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const appealDecisionAdmin = await api.functional.discussionBoard.appealDecisions.post(
    connection,
    {
      body: {
        appeal_id: appeal.id,
        moderator_id: undefined,
        admin_id: adminId,
        decision_outcome: "overturned",
        decision_rationale: "Upon review, the appeal was granted.",
      } satisfies DiscussionBoardAppealDecision.ICreate,
    },
  );
  typia.assert(appealDecisionAdmin);
  TestValidator.equals("linkage to appeal")(appealDecisionAdmin.appeal_id)(appeal.id);
  TestValidator.equals("assigned admin linkage")(appealDecisionAdmin.admin_id)(adminId);
  TestValidator.equals("moderator ID should be undefined")(appealDecisionAdmin.moderator_id)(undefined);
  TestValidator.equals("decision rationale")(appealDecisionAdmin.decision_rationale)("Upon review, the appeal was granted.");

  // 5. Fetch the decision by its ID as the creator (executor acting as any user)
  const fetchedAdminDecision = await api.functional.discussionBoard.appealDecisions.getById(
    connection,
