  typia.assert(fetchedAdminDecision);
  TestValidator.equals("decision ID fetch matches created admin decision")(
    fetchedAdminDecision.id,
  )(appealDecisionAdmin.id);

  // 6. Attempt to fetch a non-existent appeal decision
  await TestValidator.error("fetching non-existent appeal decision should fail")(async () => {
    await api.functional.discussionBoard.appealDecisions.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

