import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerationAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAppeal";
import type { DiscussionBoardAppealDecision } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardAppealDecision";

/**
 * Validate creating a new appeal decision for moderation appeals.
 *
 * This test validates the following business logic:
 * 1. An authorized moderator or admin can create a decision for a currently undecided (open) appeal.
 * 2. If a decision has already been made for an appeal, subsequent attempts should result in an error (duplicate/decided appeal).
 * 3. Input validation is enforced: required fields must be present and enum values for the decision outcome must be valid.
 *
 * Workflow:
 * 1. Create a new undecided moderation appeal.
 * 2. Create a decision for the appeal as an authorized actor.
 * 3. Attempt to create a duplicate decision for the same appeal, and verify error thrown.
 * 4. Attempt to create a decision with an invalid value for decision_outcome, and verify error thrown.
 * 5. On successful decision creation, verify the returned record references the correct appeal and actor.
 * 6. (If system supports notification) Optionally, check that a notification/event is triggered for the appealant.
 */
export async function test_api_discussionBoard_test_create_appeal_decision_with_valid_and_duplicate_constraints(
  connection: api.IConnection,
) {
  // 1. Create a new undecided moderation appeal.
  const appealInput: IDiscussionBoardModerationAppeal.ICreate = {
    moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
    member_id: typia.random<string & tags.Format<"uuid">>(),
    appeal_reason: "I believe the moderation action was in error. Please review.",
  };
  const appeal = await api.functional.discussionBoard.moderationAppeals.post(connection, { body: appealInput });
  typia.assert(appeal);
  TestValidator.equals("appeal status should be initially undecided or pending")(appeal.appeal_status)("pending");

  // 2. Create a decision for the appeal as a moderator (using moderator_id).
  const moderatorId: string = typia.random<string & tags.Format<"uuid">>();
  const validDecisionOutcome = "upheld"; // Acceptable outcome string per scenario, not strictly enforced in DTO.
  const decisionInput: DiscussionBoardAppealDecision.ICreate = {
    appeal_id: appeal.id,
    moderator_id: moderatorId,
    decision_outcome: validDecisionOutcome,
    decision_rationale: "Appeal reviewed thoroughly; original action is confirmed as appropriate.",
  };
  const decision = await api.functional.discussionBoard.appealDecisions.post(connection, { body: decisionInput });
  typia.assert(decision);
  TestValidator.equals("decision should target correct appeal")(decision.appeal_id)(appeal.id);
  TestValidator.equals("moderator identity matches")(decision.moderator_id)(moderatorId);
  TestValidator.equals("decision outcome is set")(decision.decision_outcome)(validDecisionOutcome);
  TestValidator.equals("decision rationale matches")(decision.decision_rationale)(decisionInput.decision_rationale);

  // 3. Attempt to create a duplicate decision for the same appeal (should error)
  await TestValidator.error("duplicate appeal decision")(async () => {
    await api.functional.discussionBoard.appealDecisions.post(connection, { body: decisionInput });
  });

  // 4. Attempt to create a decision with invalid enum value for decision_outcome
  await TestValidator.error("invalid value in decision outcome")(async () => {
    await api.functional.discussionBoard.appealDecisions.post(connection, {
      body: {
        appeal_id: appeal.id,
        moderator_id: moderatorId,
        decision_outcome: "INVALID_ENUM_VALUE_SHOULD_FAIL",
        decision_rationale: "Improper value provided.",
      },
    });
  });
  // 5. (Optional) System notification/event for appealant - system-dependent and skipped if not observable via API.
}

