import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";

/**
 * E2E test: Create a new comment (root-level and reply) on a board post as an authenticated user.
 *
 * This test verifies the following workflow:
 * 1. Register a new discussion board user (member).
 * 2. Create a discussion board.
 * 3. Create a post within the created board, attributed to the member.
 * 4. Create a root-level comment on the post (depth 0, thread_id = its own id after creation).
 * 5. Create a reply comment under the root (depth 1, thread_id = root comment id).
 * 6. Validate that both comments are created successfully, and that edit/deleted flags are set to default (false/null).
 * 7. Attempt to create a comment where referenced post, thread, or author don't exist -- expect errors.
 * 8. Attempt to create a comment with a blank/invalid body -- expect error (content policy violation).
 */
export async function test_api_discussionBoard_test_create_comment_with_valid_data(connection: api.IConnection) {
  // 1. Register a new member (author)
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.alphabets(8),
      password: "SecureP@ssw0rd123"
    } satisfies IDiscussionBoardMember.ICreate
  });
  typia.assert(member);

  // 2. Create a board
  const board = await api.functional.discussionBoard.boards.post(connection, {
    body: {
      title: RandomGenerator.paragraph()(),
      slug: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(),
    } satisfies IDiscussionBoardBoard.ICreate
  });
  typia.assert(board);

  // 3. Create a post in the board
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: board.id,
      author_id: member.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate
  });
  typia.assert(post);

  // 4. Create a root-level comment (depth 0)
  // Since thread_id needs a UUID (typically self-referential for roots after creation),
  // use a temporary random UUID, and test that API response resolves thread_id properly.
  const tempThreadId = typia.random<string & tags.Format<"uuid">>();
  const rootCreate = {
    post_id: post.id,
    thread_id: tempThreadId,
    author_id: member.id,
    body: "Root level comment content.",
    depth: 0,
  } satisfies IDiscussionBoardComment.ICreate;
  const rootComment = await api.functional.discussionBoard.comments.post(connection, {
    body: rootCreate
  });
  typia.assert(rootComment);
  // For root: API should set thread_id to its own id (may override random request value)
  TestValidator.equals("root comment depth")(rootComment.depth)(0);
  TestValidator.equals("not edited")(rootComment.is_edited)(false);
  TestValidator.equals("not deleted")(rootComment.deleted_at)(null);
  TestValidator.equals("post linkage")(rootComment.post_id)(post.id);
  TestValidator.equals("thread linkage")(rootComment.thread_id)(rootComment.id);

  // 5. Create a reply comment to the root (depth 1, thread_id = rootComment.id)
  const replyCreate = {
    post_id: post.id,
    thread_id: rootComment.id,
    author_id: member.id,
    body: "Reply comment content.",
    depth: 1,
  } satisfies IDiscussionBoardComment.ICreate;
  const replyComment = await api.functional.discussionBoard.comments.post(connection, {
    body: replyCreate
  });
  typia.assert(replyComment);
  TestValidator.equals("reply depth")(replyComment.depth)(1);
  TestValidator.equals("not edited")(replyComment.is_edited)(false);
  TestValidator.equals("not deleted")(replyComment.deleted_at)(null);
  TestValidator.equals("reply thread linkage")(replyComment.thread_id)(rootComment.id);
  TestValidator.equals("reply post linkage")(replyComment.post_id)(post.id);

  // 6. Error: Try adding a comment to a non-existent post
  await TestValidator.error("comment on non-existent post")(async () => {
    await api.functional.discussionBoard.comments.post(connection, {
      body: {
        post_id: typia.random<string & tags.Format<"uuid">>(),
        thread_id: rootComment.id,
        author_id: member.id,
        body: "Should error: invalid post",
        depth: 1,
      } satisfies IDiscussionBoardComment.ICreate
    });
  });

  // 7. Error: Try adding a comment to a non-existent thread
  await TestValidator.error("comment with non-existent thread")(async () => {
    await api.functional.discussionBoard.comments.post(connection, {
      body: {
        post_id: post.id,
        thread_id: typia.random<string & tags.Format<"uuid">>(),
        author_id: member.id,
        body: "Should error: invalid thread",
        depth: 1,
      } satisfies IDiscussionBoardComment.ICreate
    });
  });

  // 8. Error: Try adding a comment with non-existent author
  await TestValidator.error("comment with non-existent author")(async () => {
    await api.functional.discussionBoard.comments.post(connection, {
      body: {
        post_id: post.id,
        thread_id: rootComment.id,
        author_id: typia.random<string & tags.Format<"uuid">>(),
        body: "Should error: invalid author",
        depth: 1,
      } satisfies IDiscussionBoardComment.ICreate
    });
  });

  // 9. Error: Content violation (blank body)
  await TestValidator.error("comment with blank body")(async () => {
    await api.functional.discussionBoard.comments.post(connection, {
      body: {
        post_id: post.id,
        thread_id: rootComment.id,
        author_id: member.id,
        body: "",
        depth: 1,
      } satisfies IDiscussionBoardComment.ICreate
    });
  });
}

