import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDeleteResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IDeleteResult";

/**
 * 테스트: 댓글을 작성자와 관리자가 소프트 삭제(erase)할 수 있는지 검증
 *
 * 시나리오:
 * 1. 일반 사용자(작성자)와 관리자를 등록한다.
 * 2. 관리자로 게시판을 생성한다.
 * 3. 작성자가 해당 게시판에 게시글을 작성한다.
 * 4. 작성자가 댓글을 단다.
 * 5. 댓글 작성자가 댓글을 삭제(소프트 삭제)한다. → 성공해야 함.
 * 6. 이미 삭제된 댓글을 다시 삭제 시도 → 실패(오류)해야 함.
 * 7. 다른 사용자가 댓글 지우기 시도 → 실패(오류)해야 함.
 * 8. (가능할 경우) 관리자가 댓글 삭제 시도 → 허용 시 성공, 불가 시 오류
 * 9. 존재하지 않는 댓글 id로 삭제 시도 → 실패(오류)해야 함.
 *
 * 검증 포인트:
 * - 각 삭제 결과의 success 필드/실패 시 오류 발생 여부
 * - 댓글의 deleted_at이 설정되는지(실제 검사 불가: 조회 API 미제공)
 * - 본인/관리자만 삭제 가능 비즈니스 룰 적용 여부
 *
 * 주의: 인증 전환(로그인/역할 변경)·댓글 목록/상세 조회·로그 검증·이벤트 발생 등은 현재 제공된 SDK/DTO만으로는 구현 불가하므로 코드에서 테스트 불가.
 */
export async function test_api_discussionBoard_test_delete_comment_as_owner_and_admin(
  connection: api.IConnection,
) {
  // 1. 댓글 작성자(일반 사용자)와 관리자, 그리고 또 다른 사용자를 회원으로 등록
  const author = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.name(),
      password: '1234' as string & tags.Format<'password'>,
    },
  });
  typia.assert(author);
  const admin = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.name(),
      password: '1234' as string & tags.Format<'password'>,
    },
  });
  typia.assert(admin);
  const another = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.name(),
      password: '1234' as string & tags.Format<'password'>,
    },
  });
  typia.assert(another);

  // 2. 관리자가 게시판 생성
  const board = await api.functional.discussionBoard.boards.post(connection, {
    body: {
      title: RandomGenerator.paragraph()(1),
      slug: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(board);

  // 3. 작성자가 게시글 작성
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: board.id,
      author_id: author.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 4. 댓글 작성(작성자)
  const comment = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: post.id,
      thread_id: post.id,
      author_id: author.id,
      body: RandomGenerator.content()()(),
      depth: 0,
    },
  });
  typia.assert(comment);

  // 5. 댓글 작성자가 본인 댓글 삭제(성공)
  const deleteResult = await api.functional.discussionBoard.comments.eraseById(connection, {
    id: comment.id,
  });
  typia.assert(deleteResult);
  TestValidator.predicate('본인 댓글 삭제 성공')(deleteResult.success === true);

  // 6. 이미 삭제된 댓글을 재삭제 시도(실패)
  await TestValidator.error('이미 삭제됨 - 중복 삭제 실패')(async () => {
    await api.functional.discussionBoard.comments.eraseById(connection, { id: comment.id });
  });

  // 7. 새로운 댓글 작성 후 다른 이용자(본인 아님)가 삭제 시도 (실패해야 함)
  const otherComment = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: post.id,
      thread_id: post.id,
      author_id: author.id,
      body: RandomGenerator.content()()(),
      depth: 0,
    },
  });
  typia.assert(otherComment);
  // (실제 인증 전환 없이 테스트 블록으로 롤 분리 simulation)
  await TestValidator.error('타인 댓글 삭제 불가')(async () => {
    await api.functional.discussionBoard.comments.eraseById(connection, { id: otherComment.id });
  });

  // 8. (가능하다면) 관리자 권한으로 댓글 삭제 허용 여부 (SDK 인증 전환 미제공, 직접 검증 불가)
  // 참고: 인증/역할 변환 API가 없으므로 스킵

  // 9. 무작위 존재하지 않는 UUID로 삭제 시도(실패)
  await TestValidator.error('존재하지 않는 댓글 삭제 실패')(async () => {
    await api.functional.discussionBoard.comments.eraseById(connection, { id: typia.random<string & tags.Format<'uuid'>>() });
  });
}

