import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for filtering and sorting discussion board posts.
 *
 * This test covers advanced search/list functionality for discussion posts with various filters and sorting, thoroughly validating both business rules and core response contract. It ensures posts can be filtered by board, author, and basic pagination, and that invalid filters are handled correctly.
 *
 * **Test Workflow:**
 * 1. Create multiple discussion boards (different slugs/titles).
 * 2. Register multiple members (writers).
 * 3. Each member posts to multiple boards—diverse attributes/timestamps established via a matrix.
 * 4. Query post listing by:
 *    - Only board ID
 *    - Only author ID
 *    - Both board and author
 *    - Title filter (fuzzy search)
 *    - No filters (all posts)
 *    - Pagination (limit)
 *    - Sorting by created_at descending (using returned order)
 * 5. Check:
 *    - All filtered posts match filter values (board, author, title)
 *    - Pagination respected
 *    - Sorting order is descending by created_at
 * 6. Error paths: malformed board/author UUIDs result in error
 *
 * Relies only on provided SDK/DTO contracts and scenario; all token/context handled via standard API functions.
 */
export async function test_api_discussionBoard_test_search_posts_with_filters_and_sorting(
  connection: api.IConnection,
) {
  // 1. Create distinct boards
  const boards = await ArrayUtil.asyncRepeat(2)(async (i) => {
    const board = await api.functional.discussionBoard.boards.post(connection, {
      body: {
        title: `Board ${i + 1}`,
        slug: `board-${i + 1}-${RandomGenerator.alphaNumeric(8)}`,
        description: `Description for board ${i + 1}`,
      },
    });
    typia.assert(board);
    return board;
  });

  // 2. Register members
  const members = await ArrayUtil.asyncRepeat(2)(async (i) => {
    const member = await api.functional.discussionBoard.members.post(connection, {
      body: {
        username: `member_${i + 1}_${RandomGenerator.alphabets(5)}`,
        email: typia.random<string & tags.Format<"email">>(),
        display_name: `DisplayName${i + 1}`,
        password: "password123!@#",
      },
    });
    typia.assert(member);
    return member;
  });

  // 3. Create posts - each member posts to every board
  const postMatrix: IDiscussionBoardPost[][] = [];
  for (let memberIdx = 0; memberIdx < members.length; ++memberIdx) {
    const row: IDiscussionBoardPost[] = [];
    for (let boardIdx = 0; boardIdx < boards.length; ++boardIdx) {
      const post = await api.functional.discussionBoard.posts.post(connection, {
        body: {
          board_id: boards[boardIdx].id,
          author_id: members[memberIdx].id,
          title: `Title ${memberIdx + 1}-${boardIdx + 1}`,
          body: `Body for post ${memberIdx + 1}-${boardIdx + 1}`,
        },
      });
      typia.assert(post);
      row.push(post);
      // Delay ensures different timestamps (for sorting checks)
      await new Promise((r) => setTimeout(r, 10));
    }
    postMatrix.push(row);
  }
  const allPosts = postMatrix.flat();

  // 4. Filtering: board only
  const byBoard = await api.functional.discussionBoard.posts.patch(connection, {
    body: { board_id: boards[0].id },
  });
  typia.assert(byBoard);
  TestValidator.predicate("all posts match board")(byBoard.data.every((post) => post.board_id === boards[0].id));

  // Filtering: author only
  const byAuthor = await api.functional.discussionBoard.posts.patch(connection, {
    body: { author_id: members[1].id },
  });
  typia.assert(byAuthor);
  TestValidator.predicate("all posts match author")(byAuthor.data.every((post) => post.author_id === members[1].id));

  // Filtering: both board & author (matrix intersection)
  const byBoth = await api.functional.discussionBoard.posts.patch(connection, {
    body: { board_id: boards[1].id, author_id: members[0].id },
  });
  typia.assert(byBoth);
  TestValidator.equals("filtered post count")(byBoth.data.length)(1);
  TestValidator.equals("matching post's board")(byBoth.data[0].board_id)(boards[1].id);
  TestValidator.equals("matching post's author")(byBoth.data[0].author_id)(members[0].id);

  // Filtering: title (partial match)
  const byTitle = await api.functional.discussionBoard.posts.patch(connection, {
    body: { title: "Title " },
  });
  typia.assert(byTitle);
  TestValidator.predicate("title filter present")(byTitle.data.length > 0);
  TestValidator.predicate("filtered titles include search term")(byTitle.data.every((p) => p.title.includes("Title ")));

  // Pagination test: limit param
  const byLimit = await api.functional.discussionBoard.posts.patch(connection, {
    body: { limit: 1 },
  });
  typia.assert(byLimit);
  TestValidator.equals("limit respected")(byLimit.data.length)(1);
  TestValidator.predicate("pagination metadata honored")(byLimit.pagination.limit === 1);

  // Sorting: created_at descending (based on postMatrix timing/delays)
  const byDesc = await api.functional.discussionBoard.posts.patch(connection, {
    body: {},
  });
  typia.assert(byDesc);
  TestValidator.predicate("order is created_at desc")(
    byDesc.data.every((post, i, arr) => i === 0 || post.created_at <= arr[i - 1].created_at),
  );

  // 5. Error: invalid board_id (malformed UUID string)
  await TestValidator.error("invalid board_id")(() =>
    api.functional.discussionBoard.posts.patch(connection, {
      body: { board_id: "not-a-uuid" as any },
    }),
  );

  // Error: invalid author_id (malformed UUID string)
  await TestValidator.error("invalid author_id")(() =>
    api.functional.discussionBoard.posts.patch(connection, {
      body: { author_id: "bad-uuid" as any },
    }),
  );
}

