/**
 * Validate soft deletion of a discussion post by its author (member).
 *
 * This test exercises the soft-deletion workflow:
 *   1. Register a new member (who will be the author)
 *   2. Create a new board
 *   3. Create a discussion post as the member (attach to this board)
 *   4. Soft-delete the post using the post's ID and author's access
 *   5. Validate the returned object has a populated 'deleted_at' field (date-time string)
 *   6. Attempting to delete the already-deleted post again should result in an error (verifies appropriate error handling after soft deletion).
 *
 * Limitations:
 *   - Verification of post invisibility/inaccessibility in list or get APIs is not implemented, as such APIs are not provided in the SDK/materials.
 *
 * The test confirms:
 *   - Author is able to delete their own post
 *   - 'deleted_at' is set upon deletion
 *   - Post object is returned in correct schema
 *   - Error occurs when attempting to delete the same post again
 */
export async function test_api_discussionBoard_test_delete_post_by_author(
  connection: api.IConnection,
) {
  // 1. Register member (author)
  const memberInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: RandomGenerator.alphaNumeric(10),
  };
  const member = await api.functional.discussionBoard.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create board
  const boardInput: IDiscussionBoardBoard.ICreate = {
    title: "Test Board " + RandomGenerator.alphaNumeric(4),
    slug: RandomGenerator.alphaNumeric(12),
    description: "Temporary board for E2E deletion test.",
  };
  const board = await api.functional.discussionBoard.boards.post(connection, { body: boardInput });
  typia.assert(board);

  // 3. Create post as the member
  const postInput: IDiscussionBoardPost.ICreate = {
    board_id: board.id,
    author_id: member.id,
    title: "Delete me! " + RandomGenerator.alphaNumeric(5),
    body: RandomGenerator.paragraph()(),
  };
  const post = await api.functional.discussionBoard.posts.post(connection, { body: postInput });
  typia.assert(post);

  // 4. Author (member) soft-deletes the post
  const deleted = await api.functional.discussionBoard.posts.eraseById(connection, { id: post.id });
  typia.assert(deleted);

  // 5. Validate deletion: 'deleted_at' is set (ISO date-time string)
  TestValidator.predicate("deleted_at is set as ISO datetime")(!!deleted.deleted_at && typeof deleted.deleted_at === "string" && !isNaN(Date.parse(deleted.deleted_at)));

  // 6. Validate post cannot be deleted again by member (should error)
  TestValidator.error("cannot delete again")(async () => {
    await api.functional.discussionBoard.posts.eraseById(connection, { id: post.id });
  });
}

