/**
 * E2E: Test revoking (soft-deleting) a moderator assignment in various scenarios
 *
 * 1. Register two members: one will be admin, one will be assigned as moderator.
 * 2. (Precondition) Manually elevate the first member to admin state by creating DISCUSSIONBOARD_ADMIN (as system, pre-insert test context).
 * 3. As admin, assign the second member as moderator using `moderators.post` (keep assignment id).
 * 4. As admin, call `moderators.eraseById` to revoke (soft delete) the moderator assignment.
 * 5. Confirm that:
 *    - The moderator record would now be considered revoked (ideally, verify by attempting re-assign or if audit log were accessible).
 * 6. Try to delete again – must receive error (cannot revoke twice), check correct error is thrown.
 * 7. Attempt to revoke with an invalid UUID, and as a non-admin (happy path = proper authorization error).
 *
 * Limitations:
 * - As there are no downstream/privilege-checking APIs available, full privilege loss audit is not empirically checkable here. However, we will ensure revocation and error workflow are covered.
 */
export async function test_api_discussionBoard_test_delete_revoke_moderator_assignment_various_conditions(
  connection: api.IConnection,
) {
  // 1. Register the admin and moderator candidates
  const adminInput = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "AdminPass1!",
  } satisfies IDiscussionBoardMember.ICreate;
  const adminMember = await api.functional.discussionBoard.members.post(connection, { body: adminInput });
  typia.assert(adminMember);

  const modInput = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "ModPass2!",
  } satisfies IDiscussionBoardMember.ICreate;
  const modMember = await api.functional.discussionBoard.members.post(connection, { body: modInput });
  typia.assert(modMember);

  // 2. (Precondition) System-inject admin role for adminMember (test bootstrapping assumed)
  //  -- This step CANNOT be performed with available APIs. ASSUMED: adminMember is admin for the remainder of test.

  // 3. Assign moderator role to the moderator candidate as admin
  const modAssignInput = {
    member_id: modMember.id,
    promoted_by_admin_id: adminMember.id,
  } satisfies IDiscussionBoardModerator.ICreate;
  const modAssignment = await api.functional.discussionBoard.moderators.post(connection, { body: modAssignInput });
  typia.assert(modAssignment);

  // 4. Revoke the moderator assignment as admin
  await api.functional.discussionBoard.moderators.eraseById(connection, { id: modAssignment.id });

  // 5. (If accessible, check that the modAssignment is now revoked - no accessible read API, so skipped)

  // 6. Attempt to revoke again (should trigger a proper error)
  await TestValidator.error("Revoking already-revoked moderator assignment fails")(
    async () => {
      await api.functional.discussionBoard.moderators.eraseById(connection, { id: modAssignment.id });
    },
  );

  // 7. Attempt to revoke a random invalid id (should trigger not found/validation error)
  await TestValidator.error("Revoking with invalid/non-existent id fails")(
    async () => {
      await api.functional.discussionBoard.moderators.eraseById(connection, { id: typia.random<string & tags.Format<"uuid">>() });
    },
  );

  // 8. (Simulate as unauthorized user: No authentication API, so cannot test privilege error end-to-end here)
  // Limitation: Role/permission switching not exposed in available APIs.
}

