import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IPageIDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardChannel";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 토론 게시판 채널 목록 조회(PATCH) E2E 테스트
 *
 * - 다양한 채널 생성 후, 페이징, 검색, 필터, 정렬, 잘못된 파라미터 등 실 운영에 필요한 목록 조회 검증을 모두 포함
 * - 일반 사용자가 채널 목록을 조회하는 시나리오(soft delete 항목 미포함, active 정보만)
 *
 * #### 주요 테스트 시나리오
 * 1. 여러 개 채널 생성 (name/description 다양)
 * 2. 전체 목록 조회(soft delete 제외), 응답 데이터 count 및 각 필드 값 확인
 * 3. name 으로 부분 검색 (sub-string match 확인)
 * 4. description 으로 부분 검색
 * 5. 페이지네이션: page/limit에 따른 분리와 응답 데이터 검증
 * 6. 정렬: 기본 생성일 정렬(아이디/created_at 변별)
 * 7. 잘못된 파라미터(page 음수, limit 한도초과, 문자열 입력 등) 오류 응답 검증
 */
export async function test_api_discussionBoard_test_list_channels_with_pagination_and_search_filters(
  connection: api.IConnection,
) {
  // 1. 다양한 이름/설명으로 채널 6개 생성
  const createdChannels = await Promise.all(ArrayUtil.repeat(6)(async () => {
    const name = RandomGenerator.alphabets(5);
    const description = RandomGenerator.paragraph()();
    const ch = await api.functional.discussionBoard.channels.post(connection, {
      body: { name, description } satisfies IDiscussionBoardChannel.ICreate,
    });
    typia.assert(ch);
    return ch;
  }));

  // 2. 전체 목록 조회: 삭제 안된(soft delete 제외) 채널만 노출
  const allList = await api.functional.discussionBoard.channels.patch(connection, {
    body: {} satisfies IDiscussionBoardChannel.IRequest,
  });
  typia.assert(allList);
  TestValidator.predicate("soft delete 제외, 반환된 것은 모두 deleted_at null")(
    allList.data.every((item) => item.id && (item as any).deleted_at === undefined)
  );

  // 3. name 부분검색: 첫번째 채널명 일부를 검색어로
  const partialName = createdChannels[0].name.slice(1, 4);
  const searchByName = await api.functional.discussionBoard.channels.patch(connection, {
    body: { name: partialName } satisfies IDiscussionBoardChannel.IRequest,
  });
  typia.assert(searchByName);
  TestValidator.predicate("name 부분검색 결과가 query substring 포함")(
    searchByName.data.length > 0 &&
    searchByName.data.every((item) => item.name.includes(partialName))
  );

  // 4. description 부분검색: 두번째 채널 description 일부로
  const descToken = createdChannels[1].description?.slice(0, 7) ?? "";
  const searchByDesc = await api.functional.discussionBoard.channels.patch(connection, {
    body: { description: descToken } satisfies IDiscussionBoardChannel.IRequest,
  });
  typia.assert(searchByDesc);
  TestValidator.predicate("description 부분검색 결과가 substring 포함")(
    searchByDesc.data.length > 0 &&
    searchByDesc.data.every((item) => (item.description ?? "").includes(descToken))
  );

  // 5. 페이지네이션: 2개씩 끊어서 2페이지 조회
  const paged1 = await api.functional.discussionBoard.channels.patch(connection, {
    body: { page: 1, limit: 2 } satisfies IDiscussionBoardChannel.IRequest,
  });
  typia.assert(paged1);
  TestValidator.equals("페이지1 데이터 개수")(paged1.data.length)(2);

  const paged2 = await api.functional.discussionBoard.channels.patch(connection, {
    body: { page: 2, limit: 2 } satisfies IDiscussionBoardChannel.IRequest,
  });
  typia.assert(paged2);
  TestValidator.equals("페이지2 데이터 개수")(paged2.data.length)(2);
  TestValidator.notEquals("1,2페이지 결과 아이디 겹치지 않음")(paged1.data[0]?.id)(paged2.data[0]?.id);

  // 6. 정렬(생성일순 예상): id 또는 created_at 등 오름차순 여부(생성 시각 가정)
  TestValidator.predicate("정렬: id 또는 created_at 오름차순, 변별력 만족")(
    paged1.data.length < 2 ||
      paged1.data[0].id !== paged1.data[1].id
  );

  // 7. 잘못된 파라미터: 음수 page, limit 오버, 문자열 limit 등
  await TestValidator.error("page 음수")(() =>
    api.functional.discussionBoard.channels.patch(connection, {
      body: { page: -1 } as any,
    }),
  );
  await TestValidator.error("limit 크게")(() =>
    api.functional.discussionBoard.channels.patch(connection, {
      body: { limit: 999999 } as any,
    }),
  );
  await TestValidator.error("limit에 문자열")(() =>
    api.functional.discussionBoard.channels.patch(connection, {
      body: { limit: "str" as any } as any,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";
import type { IPageIDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardChannel";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate visibility of soft-deleted channels and proper enforcement of role-based permissions when listing channels.
 *
 * This test ensures the following business rules for the /discussionBoard/channels PATCH endpoint:
 *   1. Regular users do NOT see soft-deleted channels when listing channels—only active (non-deleted) channels appear to them.
 *   2. Admin users, after soft-deleting a channel, can retrieve both active AND soft-deleted channels (since admins can see all) in paginated results.
 *   3. There are no admin-only filters in the current request DTO, so attempts by users to access deleted channels via parameters cannot be tested—such test is omitted.
 *
 * Test process:
 *   1. As admin, create two channels (one will remain active, one will be soft-deleted).
 *   2. As admin, soft-delete the second channel (set deleted_at).
 *   3. As a regular user, list channels and verify only the active channel is visible.
 *   4. As an admin, list channels and verify both the active and the soft-deleted channel are visible (admins can see all).
 */
export async function test_api_discussionBoard_test_list_channels_permissions_for_soft_deleted_channels(
  connection: api.IConnection,
) {
  // 1. Create two channels as admin
  const channelActive = await api.functional.discussionBoard.channels.post(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(),
    } satisfies IDiscussionBoardChannel.ICreate,
  });
  typia.assert(channelActive);

  const channelToDelete = await api.functional.discussionBoard.channels.post(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(),
    } satisfies IDiscussionBoardChannel.ICreate,
  });
  typia.assert(channelToDelete);

  // 2. As admin, soft-delete the second channel (set deleted_at)
  const deletedChannel = await api.functional.discussionBoard.channels.eraseById(connection, {
    id: channelToDelete.id,
  });
  typia.assert(deletedChannel);
  TestValidator.predicate("deleted_at is set")(!!deletedChannel.deleted_at);

  // 3. As a regular user, list channels—should only see the active channel
  // NOTE: Proper role switching should use real login/user context. For this test, assume `connection` is downgraded to regular user authority.
  // In real test harness, swap connection or use a user session here; we proceed for demonstration.
  const resultUser = await api.functional.discussionBoard.channels.patch(connection, {
    body: {
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardChannel.IRequest,
  });
  typia.assert(resultUser);
  const userVisibleIds = resultUser.data.map((v) => v.id);
  TestValidator.predicate("soft-deleted channel hidden from user")(!userVisibleIds.includes(channelToDelete.id));
  TestValidator.predicate("active channel shown to user")(userVisibleIds.includes(channelActive.id));

  // 4. As admin, list channels—should see both channels (including soft-deleted)
  // (Assume connection carries admin authority again, or never lost it)
  const resultAdmin = await api.functional.discussionBoard.channels.patch(connection, {
    body: {
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardChannel.IRequest,
  });
  typia.assert(resultAdmin);
  const adminVisibleIds = resultAdmin.data.map((v) => v.id);
  TestValidator.predicate("soft-deleted channel visible to admin")(adminVisibleIds.includes(channelToDelete.id));
  TestValidator.predicate("active channel visible to admin")(adminVisibleIds.includes(channelActive.id));
}

