/**
 * Validate channel detail fetching and permission logic for /discussionBoard/channels/{id}.
 *
 * This test verifies the permission logic and detail retrieval for discussion board channels:
 *
 * 1. As admin, create two channels: one normal/active (channelA), one for deletion (channelB).
 * 2. Soft-delete channelB as admin.
 * 3. As a regular user, fetch active channelA (should succeed).
 * 4. As a regular user, attempt to fetch soft-deleted channelB (should fail with access denied).
 * 5. As admin, fetch both channels (should succeed, channelB with deleted_at set).
 * 6. As moderator, fetch both channels (should succeed; channelB's deleted_at visible).
 * 7. Attempt to fetch a non-existing channel (should fail appropriately).
 *
 * Notes:
 * - This test assumes the ability to simulate session/role/context switching via 'connection'.
 * - If connection context switching is not available in the SDK, simulate as much as possible, and note the role expected for each section.
 * - All assertions are performed after API calls via typia and TestValidator.
 * - All edge cases and business logic from the scenario are covered.
 */
export async function test_api_discussionBoard_test_get_channel_details_success_and_permission_matrix(
  connection: api.IConnection,
) {
  // 1. As admin, create two channels: active (channelA) and to-be-deleted (channelB)
  const channelA = await api.functional.discussionBoard.channels.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(channelA);

  const channelB = await api.functional.discussionBoard.channels.post(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(channelB);

  // 2. As admin, soft-delete channelB
  const deletedChannelB = await api.functional.discussionBoard.channels.eraseById(connection, {
    id: channelB.id,
  });
  typia.assert(deletedChannelB);
  TestValidator.predicate("deleted_at is set for soft-deleted channel")(!!deletedChannelB.deleted_at);

  // 3. Simulated role: regular user fetches active channelA (should succeed)
  //    (In practical use, connection would be switched to non-admin.)
  {
    const fetchedA = await api.functional.discussionBoard.channels.getById(connection, {
      id: channelA.id,
    });
    typia.assert(fetchedA);
    TestValidator.equals("active channel id")(fetchedA.id)(channelA.id);
    TestValidator.equals("active channel not deleted")(fetchedA.deleted_at)(null);
  }

  // 4. Simulated role: regular user fetches deleted channelB (should fail)
  {
    await TestValidator.error("regular user should not fetch deleted channel")(
      async () => {
        await api.functional.discussionBoard.channels.getById(connection, {
          id: channelB.id,
        });
      },
    );
  }

  // 5. As admin, fetch both channels (should succeed)
  {
    const adminA = await api.functional.discussionBoard.channels.getById(connection, {
      id: channelA.id,
    });
    typia.assert(adminA);
    TestValidator.equals("admin channelA fetch")(adminA.id)(channelA.id);

    const adminB = await api.functional.discussionBoard.channels.getById(connection, {
      id: channelB.id,
    });
    typia.assert(adminB);
    TestValidator.equals("admin channelB fetch")(adminB.id)(channelB.id);
    TestValidator.predicate("admin sees deleted_at for channelB")(!!adminB.deleted_at);
  }

  // 6. As moderator, fetch both channels (should succeed)
  //    (Here, in a real suite, moderator context should be used.)
  {
    const modA = await api.functional.discussionBoard.channels.getById(connection, {
      id: channelA.id,
    });
    typia.assert(modA);
    TestValidator.equals("moderator channelA fetch")(modA.id)(channelA.id);

    const modB = await api.functional.discussionBoard.channels.getById(connection, {
      id: channelB.id,
    });
    typia.assert(modB);
    TestValidator.equals("moderator channelB fetch")(modB.id)(channelB.id);
    TestValidator.predicate("moderator sees deleted_at for channelB")(!!modB.deleted_at);
  }

