 *
 * This E2E test ensures that an administrative user can create a new discussion board channel
 * with a unique name and valid data. It verifies that:
 * - The channel is created with the unique name and specified description
 * - All required fields are populated and type correct
 * - The channel is initialized as active (not deleted)
 * - Correct metadata (created_at, updated_at, id as UUID) is present
 *
 * Test steps:
 * 1. Compose a unique channel name and a description.
 * 2. Call the API (as admin) to create the new channel.
 * 3. Validate all fields on the returned entity, confirm required fields and metadata.
 * 4. Confirm `deleted_at` is null/undefined (not deleted) and timestamps are ISO8601.
 */
export async function test_api_discussionBoard_test_create_channel_with_unique_name_by_admin(
  connection: api.IConnection,
) {
  // 1. Compose unique channel name and description
  const uniqueName: string = `Test Channel ${Date.now()}-${Math.random()}`;
  const description: string = `E2E channel creation test at ${new Date().toISOString()}`;
  const createInput: IDiscussionBoardChannel.ICreate = {
    name: uniqueName,
    description,
  };

  // 2. Call the API to create the channel (assume admin connection)
  const channel: IDiscussionBoardChannel = await api.functional.discussionBoard.channels.post(
    connection,
    { body: createInput }
  );
