  // 3. Validate required fields
  TestValidator.equals("Channel name matches")(channel.name)(uniqueName);
  TestValidator.equals("Description matches")(channel.description)(description);

  // 4. Confirm new channel is not deleted (soft-delete marker not set)
  TestValidator.equals("deleted_at is null or undefined")(
    channel.deleted_at === null || channel.deleted_at === undefined
  )(true);

  // 5. Check for valid ISO8601 timestamps in created_at and updated_at
  TestValidator.predicate("created_at/updated_at are ISO8601")(
    typeof channel.created_at === "string" &&
      !isNaN(Date.parse(channel.created_at)) &&
    typeof channel.updated_at === "string" &&
      !isNaN(Date.parse(channel.updated_at))
  );
  // 6. Check id is non-empty UUID string
  TestValidator.predicate("id is a non-empty UUID string")(
    typeof channel.id === "string" && channel.id.length > 10
  );
}

