 *
 * This function validates the core discoverability flow for sections in the discussion board. An authenticated member attempts to retrieve the section list using pagination and search filters. This test ensures:
 *
 * 1. Fetch with default pagination (no filters): Should return paginated list of non-deleted sections and valid pagination metadata.
 * 2. Fetch with a search filter by section name: Only matching and non-deleted sections should be returned.
 * 3. Fetch with a search filter by section description: Only matching and non-deleted sections should be returned.
 * 4. Fetch with a valid channel UUID: Only sections from the specified channel should be returned.
 * 5. Fetch with explicit page/limit: Pagination metadata should reflect request and page size should be correct.
 * 6. Request with negative/invalid pagination params: Should result in an error response.
 * 7. Unauthenticated access attempt: Should be denied.
 *
 * Ensures normal user discoverability, working filtering, pagination accuracy, and error enforcement.
 */
export async function test_api_discussionBoard_test_list_sections_with_pagination_and_search(connection: api.IConnection) {
  // 1. Fetch sections (no filters, default pagination)
  const defaultOutput = await api.functional.discussionBoard.sections.patch(connection, {
    body: {},
  });
  typia.assert(defaultOutput);
  TestValidator.predicate("pagination present")(!!defaultOutput.pagination);
  TestValidator.predicate("data array present")(Array.isArray(defaultOutput.data));

  // 2. Search by section name (if any results exist)
  const searchName = defaultOutput.data.length > 0 ? defaultOutput.data[0].name : "Test";
  const filteredByName = await api.functional.discussionBoard.sections.patch(connection, {
    body: { name: searchName },
  });
  typia.assert(filteredByName);
  TestValidator.predicate("sections match name query")(
    filteredByName.data.every(section => section.name.includes(searchName))
  );

  // 3. Search by description (if description exists)
  const searchDescription = defaultOutput.data.length > 0 && defaultOutput.data[0].description
    ? defaultOutput.data[0].description
    : "";
  if (searchDescription) {
    const filteredByDesc = await api.functional.discussionBoard.sections.patch(connection, {
      body: { description: searchDescription },
    });
    typia.assert(filteredByDesc);
    TestValidator.predicate("sections match description query")(
      filteredByDesc.data.every(section => (section.description ?? "").includes(searchDescription))
    );
  }

  // 4. Filter by channel UUID (if any section exists)
  const filterChannelId = defaultOutput.data.length > 0 ? defaultOutput.data[0].discussionboard_channel_id : undefined;
  if (filterChannelId) {
    const filteredByChannel = await api.functional.discussionBoard.sections.patch(connection, {
      body: { discussionboard_channel_id: filterChannelId },
    });
    typia.assert(filteredByChannel);
    TestValidator.predicate("sections match channel filter")(
      filteredByChannel.data.every(section => section.discussionboard_channel_id === filterChannelId)
    );
  }

  // 5. Pagination: explicit page/limit settings
  const pagedOutput = await api.functional.discussionBoard.sections.patch(connection, {
    body: {
      page: 2,
      limit: 1,
    },
  });
  typia.assert(pagedOutput);
  TestValidator.equals("limit respected")(pagedOutput.data.length)(1);
  TestValidator.equals("pagination current page")(pagedOutput.pagination.current)(2);

  // 6. Malformed pagination request (negative page)
  await TestValidator.error("negative page forbidden")(async () => {
    await api.functional.discussionBoard.sections.patch(connection, {
      body: {
        page: -1,
      },
    });
  });

  // 7. Unauthorized access (drop Authorization header)
  const unauthConnection = { ...connection, headers: { ...connection.headers } };
  delete unauthConnection.headers.Authorization;
  await TestValidator.error("unauthenticated member denied")(async () => {
    await api.functional.discussionBoard.sections.patch(unauthConnection, {
      body: {},
    });
  });
}

