  // 2. Create first section with a unique name in the channel
  const section1 = await api.functional.discussionBoard.sections.post(connection, {
    body: {
      discussionboard_channel_id: channel.id,
      name: `Intro / ${RandomGenerator.alphaNumeric(6)}`,
      description: Math.random() > 0.5 ? RandomGenerator.paragraph()() : null,
    },
  });
