  // 3. Create second section with another unique name
  const section2 = await api.functional.discussionBoard.sections.post(connection, {
    body: {
      discussionboard_channel_id: channel.id,
      name: `Details / ${RandomGenerator.alphaNumeric(6)}`,
      description: Math.random() > 0.5 ? RandomGenerator.paragraph()() : null,
    },
  });
  typia.assert(section2);

  // 4. Attempt to update second section's name to that of the first section → conflict error
  await TestValidator.error("update section to duplicate name: should fail")(
    async () => {
      await api.functional.discussionBoard.sections.putById(connection, {
        id: section2.id,
        body: {
          name: section1.name,
        },
      });
    },
  );
}

