import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * Tests reporting inappropriate content (post or comment) on the discussion board platform.
 *
 * Validates the following scenarios:
 * 1. Successfully submitting a report for a post with valid input as an authenticated member.
 * 2. Ensures the report is returned in the response and that all fields are valid.
 * 3. Checks duplicate report submission on the same content is rejected.
 * 4. Tests reporting non-existent content is rejected.
 * 5. Submitting a report with missing/invalid required fields leads to validation error.
 * 6. Unauthenticated or unauthorized roles are denied access.
 *
 * Steps:
 * 1. Register a new member who will act as the reporting user.
 * 2. Create a new post as the report target.
 * 3. Submit a valid report for the created post as the authenticated member.
 * 4. Confirm output structure is as expected.
 * 5. Attempt to submit a duplicate report on the same post with same parameters, expect failure.
 * 6. Try to submit a report on a non-existent post, expect error.
 * 7. Submit a report missing required fields, expect validation error.
 * 8. Attempt to submit a report as an unauthenticated user, expect permission error.
 */
export async function test_api_discussionBoard_test_create_report_for_inappropriate_content_valid_and_duplicate(connection: api.IConnection) {
  // 1. Register a new member
  const memberInput = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: RandomGenerator.alphaNumeric(10),
  } satisfies IDiscussionBoardMember.ICreate;
  const member = await api.functional.discussionBoard.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a post owned by this member
  const postInput = {
    board_id: typia.random<string & tags.Format<"uuid">>(),
    author_id: member.id,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
  } satisfies IDiscussionBoardPost.ICreate;
  const post = await api.functional.discussionBoard.posts.post(connection, { body: postInput });
  typia.assert(post);

  // 3. Submit a valid report as the member
  const reportInput = {
    reported_by_member_id: member.id,
    report_category_id: typia.random<string & tags.Format<"uuid">>(),
    target_post_id: post.id,
    target_comment_id: null,
    description: RandomGenerator.paragraph()(),
  } satisfies IDiscussionBoardReport.ICreate;
  const report = await api.functional.discussionBoard.reports.post(connection, { body: reportInput });
  typia.assert(report);
  TestValidator.equals("report - member association")(report.reported_by_member_id)(member.id);
  TestValidator.equals("report - post association")(report.target_post_id)(post.id);
  TestValidator.equals("report - description")(report.description)(reportInput.description);

  // 4. Submit a duplicate report (should fail - expect error)
  await TestValidator.error("duplicate report should be rejected")(
    async () => {
      await api.functional.discussionBoard.reports.post(connection, { body: reportInput });
    }
  );

  // 5. Attempt to report non-existent post
  const fakeReport = {
    reported_by_member_id: member.id,
    report_category_id: typia.random<string & tags.Format<"uuid">>(),
    target_post_id: typia.random<string & tags.Format<"uuid">>(),
    target_comment_id: null,
    description: RandomGenerator.paragraph()(),
  } satisfies IDiscussionBoardReport.ICreate;
  await TestValidator.error("report on non-existent post should fail")(
    async () => {
      await api.functional.discussionBoard.reports.post(connection, { body: fakeReport });
    }
  );

  // 6. Submit with invalid (missing) required fields
  const invalidReport = {
    // Intentionally missing required fields
    description: RandomGenerator.paragraph()(),
  } as any;
  await TestValidator.error("validation error for missing fields")(
    async () => {
      await api.functional.discussionBoard.reports.post(connection, { body: invalidReport });
    }
  );

  // 7. Attempt as unauthenticated user
  const unauthenticatedConnection = { ...connection, headers: {} };
  await TestValidator.error("permission denied for unauthenticated user")(
    async () => {
      await api.functional.discussionBoard.reports.post(unauthenticatedConnection, { body: reportInput });
    }
  );
}

