import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCommentThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentThread";
import type { IPageIDiscussionBoardCommentThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentThread";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test retrieval of paginated comment threads filtered by post ID.
 *
 * This scenario verifies that the comment thread list API (patch) returns only threads belonging to the requested post, supports correct pagination, and handles edge cases (empty results for posts without any threads).
 *
 * Steps:
 * 1. Register a new discussion board member to serve as post author and thread creator.
 * 2. Create a new discussion board post, assigning a valid random board ID.
 * 3. Create several comment threads (5 root threads, 1 child thread under first root) linked to the post.
 * 4. Fetch the comment thread list using post_id filter and test pagination (page 1 and 2 with limit 2).
 * 5. Assert that each returned thread's post_id matches the expected post, and that pagination metadata is correct.
 * 6. Test edge case: Query with a random post_id that has no threads—should return empty data and valid pagination meta.
 */
export async function test_api_discussionBoard_test_list_comment_threads_with_post_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register member
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "password123!",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a new post
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: boardId,
      author_id: member.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Create 5 root threads + 1 child for a variety of pagination content
  const createdThreads: IDiscussionBoardCommentThread[] = [];
  for (let i = 0; i < 5; ++i) {
    const thread = await api.functional.discussionBoard.commentThreads.post(connection, {
      body: {
        post_id: post.id,
        parent_thread_id: null,
        depth: 0,
      } satisfies IDiscussionBoardCommentThread.ICreate,
    });
    typia.assert(thread);
    createdThreads.push(thread);
  }
  // Add a child thread to the first root (depth = 1)
  const childThread = await api.functional.discussionBoard.commentThreads.post(connection, {
    body: {
      post_id: post.id,
      parent_thread_id: createdThreads[0].id,
      depth: 1,
    } satisfies IDiscussionBoardCommentThread.ICreate,
  });
  typia.assert(childThread);
  createdThreads.push(childThread);

  // 4. Page 1: limit 2
  const page1 = await api.functional.discussionBoard.commentThreads.patch(connection, {
    body: {
      post_id: post.id,
      page: 1,
      limit: 2,
    } satisfies IDiscussionBoardCommentThread.IRequest,
  });
  typia.assert(page1);
  TestValidator.equals("page 1 thread count")(page1.data.length)(2);
  TestValidator.equals("pagination meta - page")(page1.pagination.current)(1);
  TestValidator.equals("pagination meta - limit")(page1.pagination.limit)(2);
  // All returned threads must have correct post_id
  for (const thread of page1.data) {
    TestValidator.equals("post filter")(thread.post_id)(post.id);
  }

  // 5. Page 2
  const page2 = await api.functional.discussionBoard.commentThreads.patch(connection, {
    body: {
      post_id: post.id,
      page: 2,
      limit: 2,
    } satisfies IDiscussionBoardCommentThread.IRequest,
  });
  typia.assert(page2);
  TestValidator.equals("pagination meta - page2")(page2.pagination.current)(2);
  // All returned threads must have correct post_id
  for (const thread of page2.data) {
    TestValidator.equals("post filter 2")(thread.post_id)(post.id);
  }

  // 6. Edge case: unrelated random post (should return 0 data)
  const unrelatedPage = await api.functional.discussionBoard.commentThreads.patch(connection, {
    body: {
      post_id: typia.random<string & tags.Format<"uuid">>(),
      page: 1,
      limit: 5,
    } satisfies IDiscussionBoardCommentThread.IRequest,
  });
  typia.assert(unrelatedPage);
  TestValidator.equals("empty for unknown post")(unrelatedPage.data.length)(0);
  TestValidator.equals("pagination meta - empty current")(unrelatedPage.pagination.current)(1);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCommentThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentThread";
import type { IPageIDiscussionBoardCommentThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentThread";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDeleteResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IDeleteResult";

/**
 * Validates that admin users can see all comment threads (including soft-deleted) but regular members can only see active threads.
 *
 * This test verifies the visibility of comment threads depending on user role:
 * - Admins are expected to see both active and soft-deleted threads when searching.
 * - Regular members must only see active (non-deleted) threads, excluding soft-deleted ones.
 *
 * Process:
 * 1. Register a regular member (member1).
 * 2. Create another member (member2) and promote them to admin.
 * 3. As member1 (basic user), create a post in a random board.
 * 4. As member1, create two comment threads for this post.
 * 5. As admin, soft-delete one of the threads.
 * 6. As admin, patch (list) comment threads and validate both, including the deleted, are visible.
 * 7. As regular member, patch (list) threads and validate only the non-deleted remains visible.
 *
 * Assert correct thread counts and presence/absence as per expected outcome.
 */
export async function test_api_discussionBoard_test_list_comment_threads_as_admin_with_deleted_threads_included(
  connection: api.IConnection,
) {
  // Step 1: Register member1 (regular user)
  const member1Email = typia.random<string & tags.Format<"email">>();
  const member1 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: member1Email,
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member1);

  // Step 2: Register member2 (to become admin)
  const member2Email = typia.random<string & tags.Format<"email">>();
  const member2 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: member2Email,
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member2);

  // Step 3: Promote member2 to admin (use member2 as their own appointing admin for isolated test)
  const admin = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: member2.id,
      appointed_by_admin_id: member2.id,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(admin);

  // Step 4: As member1, create a post
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: boardId,
      author_id: member1.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()(1)(1),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // Step 5: As member1, create two comment threads
  const thread1 = await api.functional.discussionBoard.commentThreads.post(connection, {
    body: {
      post_id: post.id,
      parent_thread_id: null,
      depth: 0,
    } satisfies IDiscussionBoardCommentThread.ICreate,
  });
  typia.assert(thread1);

  const thread2 = await api.functional.discussionBoard.commentThreads.post(connection, {
    body: {
      post_id: post.id,
      parent_thread_id: null,
      depth: 0,
    } satisfies IDiscussionBoardCommentThread.ICreate,
  });
  typia.assert(thread2);

  // Step 6: As admin, soft-delete thread2
  const deleteResult = await api.functional.discussionBoard.commentThreads.eraseById(connection, {
    id: thread2.id,
  });
  typia.assert(deleteResult);
  TestValidator.predicate("Soft delete confirmed")(deleteResult.success === true);

  // Step 7: As admin, patch (list) comment threads for the post (should include both threads)
  const adminThreadsPage = await api.functional.discussionBoard.commentThreads.patch(connection, {
    body: {
      post_id: post.id,
    } satisfies IDiscussionBoardCommentThread.IRequest,
  });
  typia.assert(adminThreadsPage);
  const adminThreadIds = adminThreadsPage.data.map((t) => t.id);
  TestValidator.predicate("Admin sees both threads")(
    adminThreadIds.includes(thread1.id) && adminThreadIds.includes(thread2.id)
  );

  // Step 8: As regular member, patch (list) comment threads (should only include the active thread)
  const memberThreadsPage = await api.functional.discussionBoard.commentThreads.patch(connection, {
    body: {
      post_id: post.id,
    } satisfies IDiscussionBoardCommentThread.IRequest,
  });
  typia.assert(memberThreadsPage);
  const memberThreadIds = memberThreadsPage.data.map((t) => t.id);
  TestValidator.predicate("Member sees only active thread")(
    memberThreadIds.includes(thread1.id) && !memberThreadIds.includes(thread2.id)
  );
}

