    body: {
      board_id,
      author_id: member.id,
      title: post_title,
      body: post_body,
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Create root comment thread (depth 0, no parent_thread_id)
  const rootThread = await api.functional.discussionBoard.commentThreads.post(connection, {
    body: {
      post_id: post.id,
      parent_thread_id: null,
      depth: 0,
    } satisfies IDiscussionBoardCommentThread.ICreate,
  });
  typia.assert(rootThread);
  TestValidator.equals("root thread has depth 0")(rootThread.depth)(0);
  TestValidator.equals("root thread has no parent")(rootThread.parent_thread_id)(null);

  // 4. Create child (nested) thread (depth 1)
  const childThread = await api.functional.discussionBoard.commentThreads.post(connection, {
