import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardCommentThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentThread";

/**
 * Test updating the parent and depth of a comment thread in the discussion board.
 *
 * This test verifies that a comment thread's parent and depth can be updated according to board rules. It covers both reparenting (moving a child under a new parent) and changing the nesting depth. Business rules prohibit cycles (a thread cannot become its own ancestor or descendant) and enforce proper depth bounds.
 *
 * Test Steps:
 * 1. Register a board member (who will create the post and threads).
 * 2. Create a new post for the threads.
 * 3. Create a root thread (depth 0) on that post.
 * 4. Create a child thread (depth 1), child of the root.
 * 5. Attempt to reparent the child thread to become a root (parent = null, depth=0). Check structure updated correctly.
 * 6. Attempt an illegal operation: set the root's parent to be the child (should create a cycle). Confirm error is thrown.
 * 7. Attempt another illegal depth (e.g., set depth > allowed, if such a rule exists). Confirm error is thrown or response as per spec.
 *
 * Business value: Ensures data integrity of thread hierarchies and correct handling of edge cases for moderation/admin tools.
 */
export async function test_api_discussionBoard_test_update_comment_thread_change_parent_and_depth(
  connection: api.IConnection,
) {
  // 1. Register a board member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: memberEmail,
      display_name: RandomGenerator.name(),
      password: "Password123!"
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a post
  const post: IDiscussionBoardPost = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: typia.random<string & tags.Format<"uuid">>(),
      author_id: member.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.paragraph()(2)
    } satisfies IDiscussionBoardPost.ICreate
  });
  typia.assert(post);

  // 3. Create a root thread for the post
  const rootThread: IDiscussionBoardCommentThread = await api.functional.discussionBoard.commentThreads.post(connection, {
    body: {
      post_id: post.id,
      parent_thread_id: null,
      depth: 0
    } satisfies IDiscussionBoardCommentThread.ICreate
  });
  typia.assert(rootThread);

  // 4. Create child thread with root as parent
  const childThread: IDiscussionBoardCommentThread = await api.functional.discussionBoard.commentThreads.post(connection, {
    body: {
      post_id: post.id,
      parent_thread_id: rootThread.id,
      depth: 1
    } satisfies IDiscussionBoardCommentThread.ICreate
  });
  typia.assert(childThread);

  // 5. Move child thread to root (parent = null, depth = 0)
  const reparentedChild: IDiscussionBoardCommentThread = await api.functional.discussionBoard.commentThreads.putById(connection, {
    id: childThread.id,
    body: {
      parent_thread_id: null,
      depth: 0
    } satisfies IDiscussionBoardCommentThread.IUpdate
  });
  typia.assert(reparentedChild);
  TestValidator.equals("child is now root")(reparentedChild.parent_thread_id)(null);
  TestValidator.equals("depth is 0")(reparentedChild.depth)(0);

  // 6. Invalid op: set root's parent to the (now root) child (cycle)
  await TestValidator.error("cycle is invalid")(async () => {
    await api.functional.discussionBoard.commentThreads.putById(connection, {
      id: rootThread.id,
      body: {
        parent_thread_id: childThread.id,
