      email: member1Email,
      display_name: RandomGenerator.name(),
      password: "Password1!"
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member1);

  // STEP 2: Create Member 2
  const member2Email = typia.random<string & tags.Format<"email">>();
  const member2: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(6),
      email: member2Email,
      display_name: RandomGenerator.name(),
      password: "Password1!"
    } satisfies IDiscussionBoardMember.ICreate,
  });
