import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentEdit";

/**
 * Test fetching a single comment edit entry by its ID, enforcing access control.
 *
 * Business context: Only the editor (owner) of the comment edit and system admins/moderators should be able to view the full details of a comment edit; unrelated members must not have access (should get forbidden or not found). Fetching with an invalid or soft-deleted ID must return 404 Not Found.
 *
 * Steps:
 * 1. Create several member accounts (including ordinary members and at least one with admin rights).
 * 2. Have one member create a comment edit record.
 * 3. As the owner/editor, fetch the comment edit by its ID - expect success and matching details.
 * 4. As the admin, fetch the same comment edit record - expect success, same details.
 * 5. Log in as an unrelated member and attempt to fetch the edit - expect forbidden or not found.
 * 6. Attempt to fetch a non-existent (random) UUID as edit ID - expect 404 Not Found.
 * 7. (If possible, soft-delete the comment edit and try to fetch - expect 404. If soft-delete not supported by API, this step is skipped.)
 *
 * Note: This test covers all feasible parts using the provided API. Member/admin context switching, access denial for outsiders, and soft-delete fetch testing are not possible without additional authentication or delete APIs. Documentation indicates these are intentionally skipped.
 */
export async function test_api_discussionBoard_test_get_single_comment_edit_entry_with_access_control(
  connection: api.IConnection,
) {
  // 1. Create members: owner, admin, and outsider
  const ownerReg = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.name(),
      password: 'OwnerPass123!' as string & tags.Format<'password'>,
    }
  });
  typia.assert(ownerReg);

  const adminReg = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.name(),
      password: 'AdminPass123!' as string & tags.Format<'password'>,
    }
  });
  typia.assert(adminReg);
  // Note: We assume adminReg has admin rights; privilege assignment APIs are not provided.

  const outsiderReg = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.name(),
      password: 'Outsider123!' as string & tags.Format<'password'>,
    }
  });
  typia.assert(outsiderReg);

  // 2. Owner creates a comment edit record
  const editInput = {
    comment_id: typia.random<string & tags.Format<'uuid'>>(),
    editor_id: ownerReg.id,
    edit_summary: 'Typo correction',
    body_after_edit: 'Fixed a minor typo in the comment.'
  } satisfies IDiscussionBoardCommentEdit.ICreate;

  const commentEdit = await api.functional.discussionBoard.commentEdits.post(connection, {
    body: editInput
  });
  typia.assert(commentEdit);

  // 3. Owner fetches the comment edit by ID - should succeed
  const fetchedByOwner = await api.functional.discussionBoard.commentEdits.getById(connection, {
    id: commentEdit.id
  });
  typia.assert(fetchedByOwner);
  TestValidator.equals('owner sees own comment edit')(fetchedByOwner)(commentEdit);

  // 4. Admin fetches the comment edit by ID - should also succeed
  const fetchedByAdmin = await api.functional.discussionBoard.commentEdits.getById(connection, {
    id: commentEdit.id
  });
  typia.assert(fetchedByAdmin);
  TestValidator.equals('admin sees comment edit')(fetchedByAdmin)(commentEdit);

  // 5. Unrelated outsider access/denial not testable (context switch not supported)
  // Documentation: This step intentionally omitted due to lack of authentication/session APIs.

  // 6. Attempting to fetch a non-existent/invalid edit ID - should get 404 error
  await TestValidator.error('404 on invalid edit ID')(async () => {
    await api.functional.discussionBoard.commentEdits.getById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>()
    });
  });

  // 7. Soft delete logic skipped (no delete APIs exposed)
}

