import type { IDiscussionBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentEdit";

/**
 * E2E test for updating a comment edit log entry as both owner and admin, covering permissions and constraints.
 *
 * 1. Register two member accounts: the owner/editor, and an admin (potentially registering both as normal users first for API compatibility).
 * 2. As the owner, create a comment (simulates normal user flow: reference random post/thread/author/depth).
 * 3. Owner logs an edit event for their comment via api.functional.discussionBoard.commentEdits.post (establishing a record to update).
 * 4. Owner updates the comment edit record using api.functional.discussionBoard.commentEdits.putById. Supply new edit_summary/body_after_edit. Validate the response and ensure updated fields and created_at update time reflect the change. Assert type and values.
 * 5. As the admin, update the same comment edit (modifying summary/body again). Ensure admin's update is accepted, changes are reflected, and audit timestamps are valid.
 * 6. As a third, unauthorized user (not owner nor admin), attempt to update the comment edit. Validate permission is denied (TestValidator.error). 
 * 7. Attempt to update a non-existent comment edit (random UUID). Validate a not found error is thrown.
 * 8. Optional (simulate): Soft-delete the edit record, then attempt to update it again (if soft-deletion supported or by forcibly deleting in setup). Validate a not found or forbidden error.
 * 9. Field validation: Attempt to update, omitting required body_after_edit or with invalid values, and verify error handling (SKIP if validation causes TypeScript error).
 * 10. Cleanup and assertion: Make sure updates are atomic and only allowed by policy.
 */
export async function test_api_discussionBoard_test_update_comment_edit_by_owner_and_admin(connection: api.IConnection) {
  // 1. Create owner/editor member
  const ownerReg = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "TestPassw0rd!",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(ownerReg);

  // 2. Create admin member
  const adminReg = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "TestPassw0rd!",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(adminReg);

  // 3. Owner creates a comment
  const comment = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: typia.random<string & tags.Format<"uuid">>(),
      thread_id: typia.random<string & tags.Format<"uuid">>(),
      author_id: ownerReg.id,
      body: RandomGenerator.paragraph()(),
      depth: 0,
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 4. Owner logs an edit
  const edit = await api.functional.discussionBoard.commentEdits.post(connection, {
    body: {
      comment_id: comment.id,
