import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentEdit";

/**
 * Validate deletion (soft/hard) of a comment edit log entry by both its owner and an admin, enforcement of permissions, and error behavior for non-existent/already-deleted records.
 *
 * Test Covers:
 * 1. Provision admin and regular member accounts.
 * 2. Create a comment as the regular member (the edit log will reference this).
 * 3. Create an edit log for the comment as the regular member (owner).
 * 4. Owner deletes their own comment edit log (success expected).
 * 5. Confirm deletion: attempt re-delete -> expect error (404/not found).
 * 6. Create a second edit log for the same comment.
 * 7. Attempt to delete the second log as another regular user (expect permission denied/403).
 * 8. Admin deletes the second edit log (should succeed).
 * 9. Attempt to delete a non-existent (random UUID) log (expect 404 error result).
 *
 * Notes:
 * - As authentication/login flows are not exposed by the API, account-ownership and admin privilege are simulated by controlling which member ID is used for creation vs deletion.
 * - Listing or GET check of deleted logs is not implemented as no such API is included in provided SDK. Validation covers only delete route behavior and error response.
 */
export async function test_api_discussionBoard_test_delete_comment_edit_log_by_admin_and_owner(
  connection: api.IConnection,
) {
  // 1. Provision admin and two regular members
  const admin = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.name(),
      password: "A_strong_password1!",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(admin);

  const member1 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.name(),
      password: "User1_password1@",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member1);

  const member2 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.name(),
      password: "User2_password1@",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member2);

  // 2. Member1 creates a comment
  const comment = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: typia.random<string & tags.Format<'uuid'>>(),
      thread_id: typia.random<string & tags.Format<'uuid'>>(),
      author_id: member1.id,
      body: RandomGenerator.paragraph()(),
      depth: 0,
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 3. Member1 creates an edit log for the comment
  const editLog1 = await api.functional.discussionBoard.commentEdits.post(connection, {
    body: {
      comment_id: comment.id,
      editor_id: member1.id,
      edit_summary: "Initial correction",
      body_after_edit: RandomGenerator.paragraph()(),
    } satisfies IDiscussionBoardCommentEdit.ICreate,
  });
  typia.assert(editLog1);

  // 4. Owner (member1) deletes their own edit log (should succeed)
  await api.functional.discussionBoard.commentEdits.eraseById(connection, { id: editLog1.id });

  // 5. Confirm deletion: attempt re-delete – expect error (404/not found)
  await TestValidator.error("already deleted edit log should fail")(() =>
    api.functional.discussionBoard.commentEdits.eraseById(connection, { id: editLog1.id }),
  );

  // 6. Create another log for same comment (by member1)
  const editLog2 = await api.functional.discussionBoard.commentEdits.post(connection, {
    body: {
      comment_id: comment.id,
      editor_id: member1.id,
      edit_summary: "Another change",
      body_after_edit: RandomGenerator.paragraph()(),
    } satisfies IDiscussionBoardCommentEdit.ICreate,
  });
  typia.assert(editLog2);

  // 7. Attempt to delete edit log as another member (member2) – should fail/forbidden
  await TestValidator.error("member without permission cannot delete edit log")(() =>
    api.functional.discussionBoard.commentEdits.eraseById(connection, { id: editLog2.id }),
  );

  // 8. Admin deletes the edit log (should succeed)
  await api.functional.discussionBoard.commentEdits.eraseById(connection, { id: editLog2.id });

  // 9. Deleting a non-existent log should return error (404)
  await TestValidator.error("deleting non-existent log returns 404")(() =>
    api.functional.discussionBoard.commentEdits.eraseById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
    }),
  );
}

