import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { DiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardNotification";
import type { PageDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/PageDiscussionBoardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate retrieval of a paginated, filterable list of notifications for an authenticated member.
 *
 * This test ensures that the /discussionBoard/notifications PATCH endpoint properly lists paginated notification records for the current user with advanced filter options, and strictly does not expose notifications belonging to other users. It also checks pagination metadata integrity and error handling for bad filters and permissions.
 *
 * Steps:
 * 1. Create a discussion board member (user) to act as the authenticated context.
 * 2. Generate several notification records for this user, mixing types, read/unread status, and delivery/creation timestamps.
 * 3. Create at least one notification for a different recipient to confirm isolation.
 * 4. Attempt to list with various filter sets:
 *    - No filters: should receive all notifications for the test user only
 *    - Type filter: should only return notifications matching that type
 *    - Read/unread filter: filter by whether notifications have read_at set
 *    - Delivery window: filter by delivered_after/delivered_before
 *    - Pagination controls: request specific pages/limits, check correctness
 * 5. Verify result data arrays contain only notifications belonging to the test user, filters are respected, and pagination metadata matches result size.
 * 6. Validate that malformed filter input (e.g., negative page, invalid dates) returns proper error.
 * 7. (If possible) As a non-admin user, attempt to query another member's notifications by setting recipient_member_id; should be denied or return empty result.
 */
export async function test_api_discussionBoard_test_list_notifications_for_authenticated_user_with_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a member (user)
  const registration = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: RandomGenerator.alphaNumeric(12),
  } satisfies IDiscussionBoardMember.ICreate;
  const user = await api.functional.discussionBoard.members.post(connection, { body: registration });
  typia.assert(user);

  // 2. Generate notifications for this user
  const notificationTypes = ["mention","reply","like","system_announcement"];
  const now = new Date();
  const notificationData = [
    {
      recipient_member_id: user.id,
      type: notificationTypes[0],
      delivered_at: new Date(now.getTime() - 60 * 1000 * 10).toISOString(), // 10 min ago
    },
    {
      recipient_member_id: user.id,
      type: notificationTypes[1],
      delivered_at: new Date(now.getTime() - 60 * 1000 * 5).toISOString(), // 5 min ago
      read_at: new Date(now.getTime() - 60 * 1000 * 3).toISOString(), // Read 3 min ago
    },
    {
      recipient_member_id: user.id,
      type: notificationTypes[2],
      delivered_at: now.toISOString(),
    },
    {
      recipient_member_id: user.id,
      type: notificationTypes[3],
      delivered_at: now.toISOString(),
    },
  ].map(n => ({
    ...n,
    trigger_actor_id: null,
    target_post_id: null,
    target_comment_id: null,
    target_report_id: null,
    target_section_id: null,
  })) as DiscussionBoardNotification.ICreate[];
  const createdNotifications = [] as DiscussionBoardNotification[];
  for (const data of notificationData) {
    const notif = await api.functional.discussionBoard.notifications.post(connection, { body: data });
    typia.assert(notif);
    createdNotifications.push(notif);
  }

  // 3. Generate notification for another (random) user
  const otherUser = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(otherUser);
  await api.functional.discussionBoard.notifications.post(connection, {
    body: {
      recipient_member_id: otherUser.id,
      type: "mention",
      delivered_at: now.toISOString(),
      trigger_actor_id: null,
      target_post_id: null,
      target_comment_id: null,
      target_report_id: null,
      target_section_id: null,
    } satisfies DiscussionBoardNotification.ICreate,
  });

  // 4a. No filters: should list only this user's notifications
  let result = await api.functional.discussionBoard.notifications.patch(connection, { body: {} });
  typia.assert(result);
  for (const notif of result.data) {
    TestValidator.equals("recipient matches user")(notif.recipient_member_id)(user.id);
  }
  TestValidator.predicate("pagination length matches")(result.data.length <= result.pagination.limit);

  // 4b. Type filter
  result = await api.functional.discussionBoard.notifications.patch(connection, { body: { type: notificationTypes[1] } });
  typia.assert(result);
  for (const notif of result.data) {
    TestValidator.equals("type matches")(notif.type)(notificationTypes[1]);
    TestValidator.equals("recipient matches user")(notif.recipient_member_id)(user.id);
  }

  // 4c. Read/unread filter (read)
  result = await api.functional.discussionBoard.notifications.patch(connection, { body: { read: true } });
  typia.assert(result);
  for (const notif of result.data) {
    TestValidator.predicate("read_at set")(!!notif.read_at);
    TestValidator.equals("recipient matches user")(notif.recipient_member_id)(user.id);
  }

  // 4d. Read/unread filter (unread)
  result = await api.functional.discussionBoard.notifications.patch(connection, { body: { read: false } });
  typia.assert(result);
  for (const notif of result.data) {
    TestValidator.equals("recipient matches user")(notif.recipient_member_id)(user.id);
    TestValidator.predicate("read_at null")(notif.read_at == null);
  }

  // 4e. Delivery date window filter
  const deliveredAfter = new Date(now.getTime() - 60 * 1000 * 6).toISOString();
  result = await api.functional.discussionBoard.notifications.patch(connection, { body: { delivered_after: deliveredAfter } });
  typia.assert(result);
  for (const notif of result.data) {
    TestValidator.equals("recipient matches user")(notif.recipient_member_id)(user.id);
    TestValidator.predicate("delivered_after respected")(notif.delivered_at >= deliveredAfter);
  }

  // 4f. Pagination params
  result = await api.functional.discussionBoard.notifications.patch(connection, { body: { page: 0, limit: 2 } });
  typia.assert(result);
  TestValidator.equals("limit respected")(result.data.length)(Math.min(result.pagination.limit, createdNotifications.length));
  TestValidator.equals("page index")(result.pagination.current)(0);

  // 5. Malformed filter error (negative page)
  await TestValidator.error("negative page should fail")(async () => {
    await api.functional.discussionBoard.notifications.patch(connection, { body: { page: -1 } });
  });

  // 6. Attempt to retrieve another user's notifications as our test user
  result = await api.functional.discussionBoard.notifications.patch(connection, { body: { recipient_member_id: otherUser.id } });
  typia.assert(result);
  // Should not leak others' data (result set should be empty or access denied)
  TestValidator.equals("other user results empty")(result.data.length)(0);
}

