import type { DiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardNotification";

/**
 * Validates creation of a new notification entity by an admin.
 *
 * This test covers the notification workflow where:
 * - A recipient user (member) must exist;
 * - An admin is required in the system context;
 * - A POST is made to /discussionBoard/notifications with well-structured payload.
 *
 * Steps:
 * 1. Create a member to be the notification recipient (using /discussionBoard/members).
 * 2. Create a second member for admin assignment.
 * 3. Assign the second member as an admin using /discussionBoard/admins (appointed_by_admin_id = self, for test purposes).
 * 4. Create a notification as admin, with valid type (e.g., 'system_announcement'), required date fields, and reference to the recipient.
 * 5. Assert that the returned object is correct and all links/fields match the input.
 */
export async function test_api_discussionBoard_test_create_notification_as_admin_with_valid_payload(
  connection: api.IConnection,
) {
  // 1. Create a member (recipient)
  const recipientMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(recipientMember);

  // 2. Create a second member for admin
  const adminMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(adminMember);

  // 3. Assign admin rights, appoint self for test simplicity
  const adminAssignment = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: adminMember.id,
