  TestValidator.equals("notification type")(notification.type)("system_announcement");
  TestValidator.equals("delivered_at")(notification.delivered_at)(now);
  TestValidator.equals("target_post_id")(notification.target_post_id)(null);
  TestValidator.equals("target_comment_id")(notification.target_comment_id)(null);
  TestValidator.equals("target_report_id")(notification.target_report_id)(null);
  TestValidator.equals("target_section_id")(notification.target_section_id)(null);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { DiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardNotification";

/**
 * 테스트 목적: 논쟁토론장 알림 생성 시 유효하지 않은 참조(존재하지 않는 게시글/댓글 등)를 지정할 경우 올바른 에러가 반환되는지 검증합니다.
 *
 * 비즈니스 배경:
 * 논쟁토론장에서는 알림(Notification) 생성을 위해 반드시 존재하는 게시글(post)이나 댓글(comment) 등 타깃 리소스를 지정해야 합니다. 만약 존재하지 않는 post ID 등을 참조할 경우, 시스템은 관련 오류(Validation error/NotFound error)를 반환해야 하며, 알림이 DB에 생성되어서는 안 됩니다.
 *
 * 테스트 순서:
 * 1. 알림 수신자로 사용할 일반 회원을 생성합니다.
 * 2. 관리자 권한을 가진 사용자를 생성하여 인증(세션/토큰 발급)합니다.
 * 3. (관리자 인증 상태에서) 존재하지 않는 게시글 ID(랜덤 UUID 등)를 target_post_id로 하여 notification을 생성 시도합니다.
 * 4. 해당 요청은 반드시 ValidationError 또는 NotFound와 같은 에러가 발생하며, 알림이 DB에 실제로 저장되지 않았음을 검증합니다.
 *
 * 검증 포인트:
 * - 유효하지 않은 참조로 알림 생성 시도 시 올바른 오류 응답을 반환하는지
 * - 불필요한 알림 생성(데이터베이스 저장)이 발생하지 않는지
 */
export async function test_api_discussionBoard_test_create_notification_with_invalid_target_returns_error(connection: api.IConnection) {
  // 1. 알림 수신자용 회원 계정 생성
  const recipient = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: typia.random<string & tags.Format<"password">>(),
    },
  });
  typia.assert(recipient);

  // 2. 관리자 계정 + 관리자 역할 등록 (관리자 인증 상태 처리)
  const admin_member = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: typia.random<string & tags.Format<"password">>(),
    },
  });
  typia.assert(admin_member);
  const admin = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: admin_member.id,
      appointed_by_admin_id: admin_member.id,
    },
  });
  typia.assert(admin);

  // (관리자 인증 상태, 즉 admin_member가 인증된 상황이라고 가정)

  // 3. 존재하지 않는 게시글 ID로 notification 생성 요청 (target_post_id에 랜덤 UUID)
  const bogus_post_id = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("존재하지 않는 게시글을 알림 타깃으로 지정 시 에러 반환")(() =>
    api.functional.discussionBoard.notifications.post(connection, {
      body: {
        recipient_member_id: recipient.id,
        trigger_actor_id: admin_member.id,
        type: "mention",
        target_post_id: bogus_post_id,
        target_comment_id: null,
        target_report_id: null,
        target_section_id: null,
        delivered_at: new Date().toISOString() as string & tags.Format<"date-time">,
      },
    }),
  );
}

