import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { DiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardNotification";

/**
 * E2E test for marking a discussion board notification as read by the recipient.
 *
 * This test covers the workflow where a user receives a notification and then marks it as read via the update endpoint. It validates that:
 * - The member creation and notification creation work as expected.
 * - The recipient of the notification can update the notification's `read_at` field.
 * - The updated notification reflects the change in `read_at`.
 * - Only the recipient (or admin) would be permitted to perform this update (though only recipient test is implemented here).
 *
 * Steps:
 * 1. Create a new discussion board member (recipient)
 * 2. Create a notification targeted to this member
 * 3. As the recipient, perform the update/mark as read action using the notification update endpoint, setting `read_at`.
 * 4. Assert that the returned entity has the correct `read_at` timestamp and that the fields match as expected.
 */
export async function test_api_discussionBoard_test_update_notification_mark_as_read_by_recipient(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board member (recipient)
  const memberCreateInput = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "password1234!",
  } satisfies IDiscussionBoardMember.ICreate;
  const member = await api.functional.discussionBoard.members.post(connection, { body: memberCreateInput });
  typia.assert(member);

  // 2. Create a notification for this member (recipient)
  const notificationCreateInput = {
    recipient_member_id: member.id,
    trigger_actor_id: null,
    type: "mention",
    delivered_at: new Date().toISOString(),
  } satisfies DiscussionBoardNotification.ICreate;
  const notification = await api.functional.discussionBoard.notifications.post(connection, { body: notificationCreateInput });
  typia.assert(notification);

  // 3. As the recipient, mark the notification as read
  const readAtValue = new Date().toISOString();
  const updateInput = {
    read_at: readAtValue,
  } satisfies DiscussionBoardNotification.IUpdate;
  const updated = await api.functional.discussionBoard.notifications.putById(connection, { id: notification.id, body: updateInput });
  typia.assert(updated);

  // 4. Assert updated entity
  TestValidator.equals("notification ID")(updated.id)(notification.id);
  TestValidator.equals("read_at timestamp")(updated.read_at)(readAtValue);
  TestValidator.equals("recipient")(updated.recipient_member_id)(notification.recipient_member_id);
  TestValidator.predicate("read_at should be date-time string")(!!updated.read_at && typeof updated.read_at === "string");
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
