import type { DiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardNotification";

/**
 * Validates that a notification cannot be updated by a non-recipient non-admin user (forbidden).
 *
 * This test ensures that the API restricts notification updates (e.g., marking as read) to only the notification's recipient or an admin,
 * and prevents unauthorized users from modifying notifications they do not own. This is important to enforce security and privacy boundaries.
 *
 * Workflow:
 * 1. Register two users (memberA, memberB) via discussionBoard.members.post
 * 2. Create a notification for memberA (recipient) via discussionBoard.notifications.post
 * 3. As memberB, attempt to update (PUT) the notification record belonging to memberA
 * 4. The API must reject the operation and return a forbidden/error response (error validation)
 *
 * Steps:
 *   - Step 1: Register memberA
 *   - Step 2: Register memberB
 *   - Step 3: Send notification to memberA
 *   - Step 4: As memberB, try to update the notification; confirm forbidden error
 */
export async function test_api_discussionBoard_test_update_notification_by_non_owner_forbidden(
  connection: api.IConnection,
) {
  // 1. Register memberA (recipient of the notification)
  const memberACreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "Password#123!",
  } satisfies IDiscussionBoardMember.ICreate;
  const memberA = await api.functional.discussionBoard.members.post(connection, { body: memberACreate });
  typia.assert(memberA);

  // 2. Register memberB (unauthorized user)
  const memberBCreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "AnotherPassword#456!",
  } satisfies IDiscussionBoardMember.ICreate;
  const memberB = await api.functional.discussionBoard.members.post(connection, { body: memberBCreate });
  typia.assert(memberB);

  // 3. Create notification for memberA (recipient), triggered by memberB
  const notificationCreate = {
    recipient_member_id: memberA.id,
    trigger_actor_id: memberB.id,
    type: "mention",
    delivered_at: new Date().toISOString(),
  } satisfies DiscussionBoardNotification.ICreate;
  const notification = await api.functional.discussionBoard.notifications.post(connection, { body: notificationCreate });
  typia.assert(notification);

  // 4. Attempt to update notification as memberB (should be forbidden)
  // (E2E infra must set authentication context to memberB here if required - typically via login or token injection)
  await TestValidator.error("forbidden: non-recipient cannot update notification")(async () => {
    await api.functional.discussionBoard.notifications.putById(connection, {
      id: notification.id,
      body: { read_at: new Date().toISOString() } satisfies DiscussionBoardNotification.IUpdate,
    });
  });
}

