import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardRoleChangeLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardRoleChangeLog";

/**
 * 검증: 관리자 계정으로 특정 역할 변경 로그(ID 기준)를 조회한다.
 *
 * - 1) 관리자는 유효한 역할 변경 로그 ID로 조회 시, actor(실행자), affected_member(대상), 이전/이후 moderator/admin, 변경 타입, 사유, 변경 시점 등 상세 정보가 정확히 반환되어야 한다.
 * - 2) 관리자가 아닌 계정(권한 없는 일반 회원 등)이 접근할 때는 권한 에러 등 정상적으로 접근이 제한되는지 검증한다.
 * - 3) 존재하지 않는 ID로 조회 시 404 에러 등의 적절한 응답이 반환되는지 확인한다.
 *
 * 절차:
 * 1. (준비) 테스트용 member/admin/moderator UUID 등 값 준비
 * 2. (등록) 역할 변경 로그를 생성하여, 반환된 로그의 id 확보한다.
 * 3. (정상: 관리자) 생성한 로그 ID로 getById 조회 → 각 상세 필드 정확 매칭 검증
 * 4. (실패: 비관리자) 권한 없는 connection(샘플)으로 동일 id로 접근 시 에러 반환 확인
 * 5. (실패: 미존재 id) 임의 uuid로 접근 시 에러 반환 확인
 */
export async function test_api_discussionBoard_roleChangeLogs_getById(
  connection: api.IConnection,
) {
  // 1. 테스트용 UUID 값 준비
  const affected_member_id = typia.random<string & tags.Format<"uuid">>();
  const actor_admin_id = typia.random<string & tags.Format<"uuid">>();
  const from_moderator_id = typia.random<string & tags.Format<"uuid">>();
  const to_moderator_id = typia.random<string & tags.Format<"uuid">>();
  const from_admin_id = typia.random<string & tags.Format<"uuid">>();
  const to_admin_id = typia.random<string & tags.Format<"uuid">>();
  const change_type = "promote_to_admin";
  const change_reason = "관리자 승진 테스트 케이스";
  const changed_at = new Date().toISOString();

  // 2. 역할 변경 로그 등록
  const log = await api.functional.discussionBoard.roleChangeLogs.post(connection, {
    body: {
      affected_member_id,
      actor_admin_id,
      from_moderator_id,
      to_moderator_id,
      from_admin_id,
      to_admin_id,
      change_type,
      change_reason,
      changed_at,
    } satisfies IDiscussionBoardRoleChangeLog.ICreate,
  });
  typia.assert(log);

  // 3. 관리자(getById) 정상 조회 및 상세 정보 일치 검증
  const output = await api.functional.discussionBoard.roleChangeLogs.getById(connection, {
    id: log.id,
  });
  typia.assert(output);
  TestValidator.equals("affected_member_id")(output.affected_member_id)(affected_member_id);
  TestValidator.equals("actor_admin_id")(output.actor_admin_id)(actor_admin_id);
  TestValidator.equals("from_moderator_id")(output.from_moderator_id)(from_moderator_id);
  TestValidator.equals("to_moderator_id")(output.to_moderator_id)(to_moderator_id);
  TestValidator.equals("from_admin_id")(output.from_admin_id)(from_admin_id);
  TestValidator.equals("to_admin_id")(output.to_admin_id)(to_admin_id);
  TestValidator.equals("change_type")(output.change_type)(change_type);
  TestValidator.equals("change_reason")(output.change_reason)(change_reason);
  TestValidator.equals("changed_at")(output.changed_at)(changed_at);

  // 4. (실패: 권한 없는 일반 회원 등) 샘플: Authorization 헤더 토큰 교체
  const nonAdminConnection = { ...connection, headers: { ...connection.headers, Authorization: "Bearer non-admin-token" } };
  await TestValidator.error("권한 없는 사용자는 조회 불가")(
    async () => {
      await api.functional.discussionBoard.roleChangeLogs.getById(nonAdminConnection, { id: log.id });
    },
  );

  // 5. (실패: 미존재 id)
  const nonExistId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("존재하지 않는 로그 ID")(
    async () => {
      await api.functional.discussionBoard.roleChangeLogs.getById(connection, { id: nonExistId });
    },
  );
}

