import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardRoleChangeLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardRoleChangeLog";

/**
 * Validate creation of a new discussion board role change log as an admin.
 *
 * This test ensures that an authenticated admin can create a role change log entry with valid data. The entry must include the affected member, acting admin, change type, change reason, and event timestamp. It also tests that optional previous and target moderator/admin references are handled correctly for both UUID and null values. Error cases are checked for obviously invalid UUID formats.
 *
 * Steps:
 * 1. Generate valid UUIDs for affected member and actor admin (simulate their existence).
 * 2. Prepare a role change log creation payload, populating all required and optional fields (including both with UUIDs and nulls for optionals).
 * 3. Call the API endpoint as an admin to create the log with full random data.
 * 4. Call the API endpoint again, this time setting all nullable optionals to null, to ensure null propagation is handled.
 * 5. For both, verify the returned log matches the input for every field, and result includes a generated log id and valid timestamps.
 * 6. Error validation: Send a clearly invalid UUID string as a required field, and confirm the API rejects it.
 */
export async function test_api_discussionBoard_test_create_role_change_log_with_valid_data_as_admin(
  connection: api.IConnection,
) {
  // 1. Valid simulated IDs
  const affectedMemberId = typia.random<string & tags.Format<"uuid">>();
  const actorAdminId = typia.random<string & tags.Format<"uuid">>();
  const fromModeratorId = typia.random<string & tags.Format<"uuid">>();
  const toModeratorId = typia.random<string & tags.Format<"uuid">>();
  const fromAdminId = typia.random<string & tags.Format<"uuid">>();
  const toAdminId = typia.random<string & tags.Format<"uuid">>();
  const now: string & tags.Format<"date-time"> = new Date().toISOString() as string & tags.Format<"date-time">;

  // 2. Create role change log with all fields populated
  const payload: IDiscussionBoardRoleChangeLog.ICreate = {
    affected_member_id: affectedMemberId,
    actor_admin_id: actorAdminId,
    from_moderator_id: fromModeratorId,
    to_moderator_id: toModeratorId,
    from_admin_id: fromAdminId,
    to_admin_id: toAdminId,
    change_type: "promote_to_admin",
    change_reason: "Promoting member to admin for audit.",
    changed_at: now,
  };
  const output = await api.functional.discussionBoard.roleChangeLogs.post(connection, { body: payload });
  typia.assert(output);
  TestValidator.equals("affected_member_id echoed")(output.affected_member_id)(payload.affected_member_id);
  TestValidator.equals("actor_admin_id echoed")(output.actor_admin_id)(payload.actor_admin_id);
  TestValidator.equals("from_moderator_id echoed")(output.from_moderator_id)(payload.from_moderator_id);
  TestValidator.equals("to_moderator_id echoed")(output.to_moderator_id)(payload.to_moderator_id);
  TestValidator.equals("from_admin_id echoed")(output.from_admin_id)(payload.from_admin_id);
  TestValidator.equals("to_admin_id echoed")(output.to_admin_id)(payload.to_admin_id);
  TestValidator.equals("change_type echoed")(output.change_type)(payload.change_type);
  TestValidator.equals("change_reason echoed")(output.change_reason)(payload.change_reason);
  TestValidator.equals("changed_at echoed")(output.changed_at)(payload.changed_at);
  TestValidator.predicate("returned id is uuid")(typeof output.id === "string" && output.id.length > 0);

  // 3. Create role change log again but with all optional fields as null
  const payloadNulls: IDiscussionBoardRoleChangeLog.ICreate = {
    affected_member_id: typia.random<string & tags.Format<"uuid">>(),
    actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
    from_moderator_id: null,
    to_moderator_id: null,
    from_admin_id: null,
    to_admin_id: null,
    change_type: "demote_from_admin",
    change_reason: null,
    changed_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const resultNulls = await api.functional.discussionBoard.roleChangeLogs.post(connection, { body: payloadNulls });
  typia.assert(resultNulls);
  TestValidator.equals("from_moderator_id is null")(resultNulls.from_moderator_id)(null);
  TestValidator.equals("to_moderator_id is null")(resultNulls.to_moderator_id)(null);
  TestValidator.equals("from_admin_id is null")(resultNulls.from_admin_id)(null);
  TestValidator.equals("to_admin_id is null")(resultNulls.to_admin_id)(null);
  TestValidator.equals("change_reason is null")(resultNulls.change_reason)(null);

  // 4. Error case: invalid uuid for affected_member_id is rejected
  await TestValidator.error("invalid UUID rejected")(
    async () =>
      await api.functional.discussionBoard.roleChangeLogs.post(connection, {
        body: {
          ...payload,
          affected_member_id: "BAD-UUID" as string & tags.Format<"uuid">,
        },
      }),
  );
}

