/**
 * Validate updating role change log explanatory notes by admin.
 *
 * Purpose: This test ensures that administrative users can update the explanation/details of a role change log for compliance, audit, or correction purposes. The test covers:
 * - Adding or correcting the change_reason field for a log
 * - Confirming that only mutable fields (change_reason) can be updated, while immutable structural fields remain unchanged
 * - Ensuring that changes are auditable and linked to the correct log record
 * - Verifying that attempts to update a non-existent log fail with an error
 *
 * Test Steps:
 * 1. Create a role change log as a prerequisite
 * 2. Update the change_reason field with clarified/corrected information using the log ID
 * 3. Confirm the update returns the log with the updated change_reason and all other fields unchanged
 * 4. Check that audit/compliance requirements for updates are met (field is updated, linkage is intact)
 * 5. Attempt to update a non-existent log ID and ensure error response (not found)
 */
export async function test_api_discussionBoard_roleChangeLogs_test_update_role_change_log_details_for_correction_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a role change log
  const createdLog = await api.functional.discussionBoard.roleChangeLogs.post(connection, {
    body: {
      affected_member_id: typia.random<string & tags.Format<"uuid">>(),
      actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
      from_moderator_id: null,
      to_moderator_id: null,
      from_admin_id: null,
      to_admin_id: null,
      change_type: "promote_to_admin",
      change_reason: "Initial promotion based on merit.",
      changed_at: new Date().toISOString() as string & tags.Format<"date-time">,
    } satisfies IDiscussionBoardRoleChangeLog.ICreate,
  });
  typia.assert(createdLog);

  // 2. Update the change_reason to add details or correct information
  const newReason = "Correction: Promotion due to exemplary contribution and review of compliance documents.";
  const updatedLog = await api.functional.discussionBoard.roleChangeLogs.putById(connection, {
    id: createdLog.id,
    body: {
      change_reason: newReason,
    } satisfies IDiscussionBoardRoleChangeLog.IUpdate,
  });
  typia.assert(updatedLog);

  // 3. Confirm that only change_reason is updated, and all the immutable fields are unchanged
  TestValidator.equals("change_reason updated")(updatedLog.change_reason)(newReason);
  TestValidator.equals("affected_member_id unchanged")(updatedLog.affected_member_id)(createdLog.affected_member_id);
  TestValidator.equals("actor_admin_id unchanged")(updatedLog.actor_admin_id)(createdLog.actor_admin_id);
  TestValidator.equals("from_moderator_id unchanged")(updatedLog.from_moderator_id)(createdLog.from_moderator_id);
  TestValidator.equals("to_moderator_id unchanged")(updatedLog.to_moderator_id)(createdLog.to_moderator_id);
  TestValidator.equals("from_admin_id unchanged")(updatedLog.from_admin_id)(createdLog.from_admin_id);
  TestValidator.equals("to_admin_id unchanged")(updatedLog.to_admin_id)(createdLog.to_admin_id);
  TestValidator.equals("change_type unchanged")(updatedLog.change_type)(createdLog.change_type);
  TestValidator.equals("changed_at unchanged")(updatedLog.changed_at)(createdLog.changed_at);

  // 4. Ensure log remains linked by ID
  TestValidator.equals("log id")(updatedLog.id)(createdLog.id);

  // 5. Attempt to update a non-existent log and verify error thrown
  await TestValidator.error("non-existent log update fails")(async () => {
    await api.functional.discussionBoard.roleChangeLogs.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // random (likely not matching any existing record)
      body: { change_reason: "Should fail." },
    });
  });
}

