import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { DiscussionBoardContentPolicies } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardContentPolicies";
import type { IDiscussionBoardBusinessRules } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBusinessRules";
import type { IDiscussionBoardPolicyChangeLogs } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPolicyChangeLogs";

/**
 * Test creation of a policy change log with valid and invalid data
 *
 * Business context: Policy change logs are essential for audit, compliance, and traceability of administrative actions related to content policies and business rules in the discussion board platform. Only admins are authorized to create such logs, which must reference either a policy or a business rule, indicate the actor, specify the change type, and include before/after snapshots with a timestamp.
 *
 * This function validates API behavior for successful creation and multiple failure scenarios (missing fields, invalid references, insufficient privileges).
 *
 * Steps:
 * 1. Create a valid admin assignment, capturing admin and member IDs.
 * 2. Create a content policy and a business rule for valid references.
 * 3. Attempt a successful policy change log creation as the admin, referencing the created content policy.
 *    - Check that the log is persisted and returned with correct details.
 * 4. Attempt a successful policy change log creation as the admin, referencing the created business rule.
 *    - Check that the log is persisted and returned with correct details.
 * 5. Error case: attempt to create a policy change log with a missing required field (e.g., omit change_type).
 *    - Should return a validation or business logic error.
 * 6. Error case: provide invalid references (random non-existent UUIDs for changed_policy_id/changed_rule_id/actor_admin_id).
 *    - Should return a not-found/foreign key violation error.
 * 7. Error case: attempt creation as a non-admin (use random UUID as actor_admin_id that doesn't correspond to an admin).
 *    - Should return an authorization error.
 */
export async function test_api_discussionBoard_test_create_policy_change_log_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create admin (needed for actor_admin_id)
  const admin_member_id: string = typia.random<string & tags.Format<"uuid">>();
  const appointing_admin_id: string = typia.random<string & tags.Format<"uuid">>();

  // First, appoint an appointing_admin so that we can reference a real admin in appointed_by_admin_id
  const appointing_admin = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: appointing_admin_id,
      appointed_by_admin_id: appointing_admin_id, // self-appointed for bootstrap
    },
  });
  typia.assert(appointing_admin);

  // Now, appoint our target admin
  const admin = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: admin_member_id,
      appointed_by_admin_id: appointing_admin.id,
    },
  });
  typia.assert(admin);

  // 2. Create a content policy
  const policy = await api.functional.discussionBoard.contentPolicies.post(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(8),
      title: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(1),
      effective_from: new Date().toISOString(),
      effective_to: null,
      is_active: true,
    },
  });
  typia.assert(policy);

  // Create a business rule
  const rule = await api.functional.discussionBoard.businessRules.post(connection, {
    body: {
      key: RandomGenerator.alphaNumeric(8),
      value: "true",
      description: RandomGenerator.content()()(1),
    },
  });
  typia.assert(rule);

  // Helper utility: valid ISO-8601 timestamp
  const now = new Date().toISOString();

  // 3. Create policy change log referencing content policy (success)
  const log_policy = await api.functional.discussionBoard.policyChangeLogs.post(connection, {
    body: {
      changed_policy_id: policy.id,
      changed_rule_id: null,
      actor_admin_id: admin.id,
      change_type: "EDIT",
      before_value: JSON.stringify({ code: policy.code, is_active: false }),
      after_value: JSON.stringify({ code: policy.code, is_active: true }),
      changed_at: now,
    },
  });
  typia.assert(log_policy);
  TestValidator.equals("changed_policy_id")(log_policy.changed_policy_id)(policy.id);
  TestValidator.equals("actor_admin_id")(log_policy.actor_admin_id)(admin.id);
  TestValidator.equals("change_type")(log_policy.change_type)("EDIT");
  TestValidator.equals("changed_at")(log_policy.changed_at)(now);
  TestValidator.equals("after_value")(log_policy.after_value)(JSON.stringify({ code: policy.code, is_active: true }));

  // 4. Create policy change log referencing a business rule (success)
  const log_rule = await api.functional.discussionBoard.policyChangeLogs.post(connection, {
    body: {
      changed_policy_id: null,
      changed_rule_id: rule.id,
      actor_admin_id: admin.id,
      change_type: "EDIT",
      before_value: JSON.stringify({ value: "false" }),
      after_value: JSON.stringify({ value: "true" }),
      changed_at: now,
    },
  });
  typia.assert(log_rule);
  TestValidator.equals("changed_rule_id")(log_rule.changed_rule_id)(rule.id);
  TestValidator.equals("actor_admin_id")(log_rule.actor_admin_id)(admin.id);
  TestValidator.equals("change_type")(log_rule.change_type)("EDIT");
  TestValidator.equals("changed_at")(log_rule.changed_at)(now);
  TestValidator.equals("after_value")(log_rule.after_value)(JSON.stringify({ value: "true" }));

  // 5. Error: missing required field (change_type omitted/null)
  await TestValidator.error("missing change_type: should error")(() =>
    api.functional.discussionBoard.policyChangeLogs.post(connection, {
      body: {
        changed_policy_id: policy.id,
        changed_rule_id: null,
        actor_admin_id: admin.id,
        // change_type omitted
        before_value: JSON.stringify({ code: policy.code, is_active: false }),
        after_value: JSON.stringify({ code: policy.code, is_active: true }),
        changed_at: now,
      } as any, // purposely violating required property for test error
    }),
  );

  // 6. Error: invalid references (random UUIDs)
  await TestValidator.error("invalid references: non-existent policy and rule ids")(() =>
    api.functional.discussionBoard.policyChangeLogs.post(connection, {
      body: {
        changed_policy_id: typia.random<string & tags.Format<"uuid">>(),
        changed_rule_id: typia.random<string & tags.Format<"uuid">>(),
        actor_admin_id: admin.id,
        change_type: "EDIT",
        before_value: null,
        after_value: null,
        changed_at: now,
      },
    }),
  );

  // 7. Error: actor_admin_id not an admin
  await TestValidator.error("not an admin: should error")(() =>
    api.functional.discussionBoard.policyChangeLogs.post(connection, {
      body: {
        changed_policy_id: policy.id,
        changed_rule_id: null,
        actor_admin_id: typia.random<string & tags.Format<"uuid">>(), // not a real admin
        change_type: "EDIT",
        before_value: JSON.stringify({}),
        after_value: JSON.stringify({}),
        changed_at: now,
      },
    }),
  );
}

