import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerationAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAppeal";
import type { DiscussionBoardModerationAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardModerationAppeal";

/**
 * Test successful update of a moderation appeal by its owner (member).
 *
 * This test validates that a member who is the owner of a moderation appeal can:
 *   - Update their rationale/reason for the appeal while the status is pending
 *   - Withdraw the appeal before a decision is made
 *   - All status/audit fields update accordingly
 *
 * Step-by-step:
 * 1. Create a moderation appeal (POST /discussionBoard/moderationAppeals) as a member.
 * 2. Update that appeal's appeal_reason using PUT /discussionBoard/moderationAppeals/{id} (supply new reason).
 * 3. Confirm the returned entity has the new reason and the status remains 'pending'.
 * 4. Next, update the same appeal's status to 'withdrawn' using PUT (appeal_status: 'withdrawn').
 * 5. Validate appeal_status is updated to 'withdrawn', timestamps update, and all other fields remain correct.
 * 6. (Audit: Not directly testable, but ensure no errors and state transitions follow business rules.)
 */
export async function test_api_discussionBoard_moderationAppeals_test_update_moderation_appeal_success_by_owner(
  connection: api.IConnection,
) {
  // 1. Create a moderation appeal as a member
  const createInput: IDiscussionBoardModerationAppeal.ICreate = {
    moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
    member_id: typia.random<string & tags.Format<"uuid">>(),
    appeal_reason: "Initial explanation for appeal.",
  };
  const created = await api.functional.discussionBoard.moderationAppeals.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Update appeal_reason (edit rationale while pending)
  const updateReason = "Updated rationale by member.";
  const updated1 = await api.functional.discussionBoard.moderationAppeals.putById(connection, {
    id: created.id,
    body: { appeal_reason: updateReason } satisfies DiscussionBoardModerationAppeal.IUpdate,
  });
  typia.assert(updated1);
  TestValidator.equals("appeal_reason updated")(updated1.appeal_reason)(updateReason);
  TestValidator.equals("appeal_status still pending")(updated1.appeal_status)(created.appeal_status);
  TestValidator.predicate("last_updated_at changed")(updated1.last_updated_at !== created.last_updated_at);

  // 3. Withdraw appeal (update appeal_status to 'withdrawn')
  const withdrawnStatus = "withdrawn";
  const updated2 = await api.functional.discussionBoard.moderationAppeals.putById(connection, {
    id: created.id,
    body: { appeal_status: withdrawnStatus } satisfies DiscussionBoardModerationAppeal.IUpdate,
  });
  typia.assert(updated2);
  TestValidator.equals("appeal_status withdrawn")(updated2.appeal_status)(withdrawnStatus);
  TestValidator.equals("appeal_reason kept")(updated2.appeal_reason)(updateReason);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
