/**
 * 검토가 완료(결정/해결)된 이후에는 문의(이의제기)를 수정할 수 없다는 비즈니스 규칙을 검증합니다.
 *
 * 플랫폼 내에서 멤버가 모더레이션 액션에 대해 이의제기를 할 수 있지만, 관리자가 이의를 "결정"(혹은 "해결")했다면 추가 편집은 차단됩니다.
 * 이를 위해 다음 절차를 수행합니다:
 * 1. 모더레이션 대상 액션(moderation_action_id)과 이의제기자인 멤버(member_id)의 UUID를 각각 랜덤으로 준비합니다.
 * 2. 신규 이의제기 레코드를 생성하여, appeal_status가 'pending'인지 확인합니다.
 * 3. PUT 엔드포인트를 활용해 appeal_status를 'decided'로 직접 변경해, 최종 결정 이후 상태로 만듭니다.
 * 4. 이 이후에 appeal_reason을 수정하려 시도하면, 비즈니스 규칙에 의해 업데이트가 거부되고 오류가 반환되어야 합니다.
 * 5. 오류가 발생했음을 확인하고, 만약 조회 엔드포인트가 있다면 실제 appeal의 상태가 변하지 않았는지도 재검증할 수 있습니다(지금은 생략).
 */
export async function test_api_discussionBoard_moderationAppeals_test_update_moderation_appeal_after_decision_forbidden(
  connection: api.IConnection,
) {
  // 1. 모더레이션 액션과 멤버 UUID 준비
  const moderation_action_id = typia.random<string & tags.Format<"uuid">>();
  const member_id = typia.random<string & tags.Format<"uuid">>();

  // 2. 신규 이의제기 등록 (상태: pending)
  const created = await api.functional.discussionBoard.moderationAppeals.post(connection, {
    body: {
      moderation_action_id,
      member_id,
      appeal_reason: "이의제기합니다. 모더레이션 조치에 동의할 수 없습니다.",
    } satisfies IDiscussionBoardModerationAppeal.ICreate,
  });
  typia.assert(created);
  TestValidator.equals("초기 상태는 pending")(created.appeal_status)("pending");

  // 3. appeal_status를 'decided'로 변경하여 결정 완료 상태로 만듦
  const decided = await api.functional.discussionBoard.moderationAppeals.putById(connection, {
    id: created.id,
    body: { appeal_status: "decided" } satisfies DiscussionBoardModerationAppeal.IUpdate,
  });
  typia.assert(decided);
  TestValidator.equals("상태가 decided로 변경됨")(decided.appeal_status)("decided");

  // 4. 결정 이후 appeal_reason 수정 시도(금지되어야 함)
  await TestValidator.error("결정 후 수정 금지 동작 검증")(
    async () => {
      await api.functional.discussionBoard.moderationAppeals.putById(connection, {
        id: created.id,
        body: { appeal_reason: "결정 이후에도 추가 설명을 넣으려고 함" } satisfies DiscussionBoardModerationAppeal.IUpdate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
