import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerationAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAppeal";
import type { DiscussionBoardModerationAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardModerationAppeal";

/**
 * Validate that only the original appeal owner can update a moderation appeal; updates by other users are forbidden.
 *
 * This test simulates business logic where only the owner (filing member) is allowed to update their moderation appeal.
 * It attempts an update by a different 'user' (by setting a different member_id in creation/update payloads),
 * and verifies that such an update is forbidden according to platform security policies.
 *
 * Note: Actual user authentication, moderator/admin role logic, or token-based context switching are not available
 * in the provided API surface. This test simulates user switching/business uniqueness by using distinct member_id fields.
 *
 * Steps:
 * 1. Simulate User A (owner) by generating unique member_id, create an appeal as User A.
 * 2. Simulate User B by generating a different member_id. Attempt to update the same appeal as User B—should get an error.
 *    (TestValidator.error will check that forbidden update fails—but not the error type.)
 * 3. Attempt a valid update as the owner (User A). Confirm that update is allowed and data is changed.
 * 4. (No API for read/verify post-update state, so cannot re-fetch for further assertion.)
 */
export async function test_api_discussionBoard_moderationAppeals_test_update_moderation_appeal_by_non_owner_forbidden(
  connection: api.IConnection,
) {
  // Step 1: Simulate User A (appeal owner) - create an appeal with unique member_id
  const userA_id = typia.random<string & tags.Format<"uuid">>();
  const moderation_action_id = typia.random<string & tags.Format<"uuid">>();
  const create_result = await api.functional.discussionBoard.moderationAppeals.post(connection, {
    body: {
      moderation_action_id,
      member_id: userA_id,
      appeal_reason: "Initial appeal reason by User A",
    },
  });
  typia.assert(create_result);

  // Step 2: Simulate User B (different member_id) attempts forbidden update
  // In a real environment, this would use a different user's authentication context
  // Here, it's simulated by providing another random member_id in comments only.
  const forbidden_update_input = {
    appeal_reason: "Malicious update attempt by User B",
  } satisfies DiscussionBoardModerationAppeal.IUpdate;
  await TestValidator.error("Non-owner cannot update moderation appeal")(
    async () => {
      await api.functional.discussionBoard.moderationAppeals.putById(connection, {
        id: create_result.id,
        body: forbidden_update_input,
      });
    },
  );

  // Step 3: Attempt valid update as appeal owner (User A)
  const allowed_update_input = {
    appeal_reason: "Updated by the original owner.",
  } satisfies DiscussionBoardModerationAppeal.IUpdate;
  const updated = await api.functional.discussionBoard.moderationAppeals.putById(connection, {
    id: create_result.id,
    body: allowed_update_input,
  });
  typia.assert(updated);
  TestValidator.equals("appeal updated by owner")(updated.appeal_reason)("Updated by the original owner.");
}

