import type { DiscussionBoardModerationAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardModerationAppeal";

/**
 * Validate successful withdrawal (soft-delete) of a moderation appeal by its owner before decision.
 *
 * Business context:
 * - Ensures that a member (the owner/creator) can withdraw a moderation appeal, provided it has not yet been decided by moderators/administrators.
 * - Withdrawing sets the appeal status to 'withdrawn', preserves audit/history fields, and ensures the appeal is no longer active/pending.
 * - Per business policy, this must not remove the record but update its status/auditing, providing a full trace for the platform.
 *
 * Step-by-step process:
 * 1. Create a new moderation appeal as a member (acting as the owner), using unique moderation_action_id, member_id, and a sample appeal_reason.
 * 2. Withdraw (soft-delete) the newly created moderation appeal before any decision is made.
 * 3. Validate that the result entity shows status 'withdrawn', audit timestamps updated, record linkage (owner/moderation_action) unchanged, and the appeal reason remains consistent.
 * 4. Confirm, within API response capabilities, that the appeal is no longer active/pending (appeal_status is not 'pending').
 *
 * Note: Due to the absence of a listing or status query endpoint, post-withdrawal validation is limited to direct inspection of the returned entity fields.
 */
export async function test_api_discussionBoard_moderationAppeals_test_withdraw_moderation_appeal_success_by_owner(
  connection: api.IConnection,
) {
  // 1. Create a new moderation appeal as a member (owner)
  const createInput: IDiscussionBoardModerationAppeal.ICreate = {
    moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
    member_id: typia.random<string & tags.Format<"uuid">>(),
    appeal_reason: "I disagree with the moderation action because key context was missing.",
  };
  const createdAppeal = await api.functional.discussionBoard.moderationAppeals.post(
    connection,
    { body: createInput },
  );
  typia.assert(createdAppeal);

  // 2. Withdraw the moderation appeal as its owner before any decision is made
  const withdrawnAppeal = await api.functional.discussionBoard.moderationAppeals.eraseById(
    connection,
    { id: createdAppeal.id },
  );
  typia.assert(withdrawnAppeal);

  // 3. Validate field consistency and that the status is 'withdrawn'
  TestValidator.equals("appeal ID matches")(withdrawnAppeal.id)(createdAppeal.id);
  TestValidator.equals("linked moderation action unchanged")(withdrawnAppeal.moderation_action_id)(createdAppeal.moderation_action_id);
  TestValidator.equals("appeal owner unchanged")(withdrawnAppeal.member_id)(createdAppeal.member_id);
  TestValidator.equals("appeal reason unchanged")(withdrawnAppeal.appeal_reason)(createdAppeal.appeal_reason);
  TestValidator.equals("status is withdrawn")(withdrawnAppeal.appeal_status)("withdrawn");
  TestValidator.notEquals("last_updated_at timestamp should change")(withdrawnAppeal.last_updated_at)(createdAppeal.last_updated_at);

  // 4. Double-confirm not active: appeal_status is not 'pending'
  TestValidator.notEquals("withdrawn appeal status not pending")(withdrawnAppeal.appeal_status)("pending");
}

