import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";
import type { IPageDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardModerationAction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test searching moderation actions with advanced filters by moderator/admin.
 *
 * This E2E test verifies that the /discussionBoard/moderationActions (PATCH) endpoint supports advanced filtering and returns correct paginated moderation actions according to various filter criteria (actor, target member, action type, date range). It also checks behavior with malformed filter values and ensures unauthorized access is (in practice) rejected.
 *
 * Steps:
 * 1. Create diverse moderation actions through the POST endpoint, with different moderator_id, admin_id, action_type ('suspend', 'warn', 'edit'), affected_member_id, and created_at spread across a small date range.
 * 2. As an authorized user, search by moderator_id and verify all returned actions were performed by that moderator.
 * 3. Search by admin_id and verify all returned actions were performed by that admin.
 * 4. Search by affected_member_id and guarantee only moderation actions involving that member are returned.
 * 5. Search by action_type (e.g., 'warn') and check only relevant action types are in the results.
 * 6. Search by date range (from/to) and ensure only actions within that time window are returned.
 * 7. Use multiple filters in one request and validate intersection of results.
 * 8. Try malformed filters (invalid UUID, unrecognized action_type) and expect handling (empty result or error as appropriate).
 * 9. Simulate unauthorized access: try searching without proper auth header/token and expect a permission error (not implemented unless test infra supports unauthenticated connections).
 */
export async function test_api_discussionBoard_test_search_moderation_actions_with_advanced_filters(
  connection: api.IConnection,
) {
  // 1. Create diverse moderation actions (by moderator/admin, different member, action_type, time)
  const moderator_id = typia.random<string & tags.Format<'uuid'>>();
  const admin_id = typia.random<string & tags.Format<'uuid'>>();
  const affected_member_ids = [typia.random<string & tags.Format<'uuid'>>(), typia.random<string & tags.Format<'uuid'>>()];
  const action_types = ['suspend', 'warn', 'edit'];

  const created_actions: IDiscussionBoardModerationAction[] = [];
  for (const action_type of action_types) {
    // By moderator
    const moderator_action = await api.functional.discussionBoard.moderationActions.post(connection, {
      body: {
        moderator_id,
        admin_id: null,
        affected_member_id: affected_member_ids[0],
        action_type,
        action_reason: `Moderator performed ${action_type}`,
      },
    });
    typia.assert(moderator_action);
    created_actions.push(moderator_action);

    // By admin
    const admin_action = await api.functional.discussionBoard.moderationActions.post(connection, {
      body: {
        moderator_id: null,
        admin_id,
        affected_member_id: affected_member_ids[1],
        action_type,
        action_reason: `Admin performed ${action_type}`,
      },
    });
    typia.assert(admin_action);
    created_actions.push(admin_action);
  }

  // 2. Search by moderator_id
  const by_moderator = await api.functional.discussionBoard.moderationActions.patch(connection, {
    body: {
      moderator_id,
      limit: 10,
    },
  });
  typia.assert(by_moderator);
  TestValidator.predicate('All have moderator_id')(
    by_moderator.data.every(x => x.moderator_id === moderator_id)
  );

  // 3. Search by admin_id
  const by_admin = await api.functional.discussionBoard.moderationActions.patch(connection, {
    body: {
      admin_id,
      limit: 10,
    },
  });
  typia.assert(by_admin);
  TestValidator.predicate('All have admin_id')(
    by_admin.data.every(x => x.admin_id === admin_id)
  );

  // 4. Search by affected_member_id
  const by_member = await api.functional.discussionBoard.moderationActions.patch(connection, {
    body: {
      affected_member_id: affected_member_ids[0],
      limit: 10,
    },
  });
  typia.assert(by_member);
  TestValidator.predicate('All have affected_member_id')(
    by_member.data.every(x => x.affected_member_id === affected_member_ids[0])
  );

  // 5. Search by action_type
  const by_type = await api.functional.discussionBoard.moderationActions.patch(connection, {
    body: {
      action_type: 'warn',
      limit: 10,
    },
  });
  typia.assert(by_type);
  TestValidator.predicate('All have action_type warn')(
    by_type.data.every(x => x.action_type === 'warn')
  );

  // 6. Search by date range (created_at_from/to from known test actions)
  const from = created_actions[1].created_at;
  const to = created_actions[3].created_at;
  const by_date = await api.functional.discussionBoard.moderationActions.patch(connection, {
    body: {
      created_at_from: from,
      created_at_to: to,
      limit: 10,
    },
  });
  typia.assert(by_date);
  TestValidator.predicate('All in date range')(
    by_date.data.every(x => x.created_at >= from && x.created_at <= to)
  );

  // 7. Multiple filters (intersection)
  const intersection = await api.functional.discussionBoard.moderationActions.patch(connection, {
    body: {
      moderator_id,
      action_type: 'suspend',
      affected_member_id: affected_member_ids[0],
      limit: 10,
    },
  });
  typia.assert(intersection);
  TestValidator.predicate('Intersection matches')(
    intersection.data.every(x =>
      x.moderator_id === moderator_id &&
      x.action_type === 'suspend' &&
      x.affected_member_id === affected_member_ids[0]
    )
  );

  // 8. Malformed filter values
  await TestValidator.error('Invalid UUID for moderator_id')(
    async () => {
      await api.functional.discussionBoard.moderationActions.patch(connection, {
        body: {
          moderator_id: 'not-a-uuid',
        },
      });
    }
  );
  await TestValidator.error('Unknown action_type value')(
    async () => {
      await api.functional.discussionBoard.moderationActions.patch(connection, {
        body: {
          action_type: 'not-a-real-type',
        },
      });
    }
  );

  // 9. Unauthorized access: not testable unless E2E infra supplies unauthenticated connection.
}

