/**
 * Validate the ability for a moderator or admin to fetch the full details of a moderation action by its UUID.
 *
 * This test simulates the end-to-end workflow:
 * 1. Create a new moderation action via POST /discussionBoard/moderationActions
 *    (acting as a moderator or admin), including all required fields and a cross-reference to a comment.
 * 2. Extract the ID of the created moderation action.
 * 3. Fetch the moderation action by ID using GET /discussionBoard/moderationActions/{id}.
 * 4. Compare creation and fetch results, confirming every field matches (ID, actors, affected member, content links, action type/reason/note).
 * 5. Validate presence and format of the audit field (created_at), and check all cross-references (moderator/admin/member/content) are populated as expected.
 *
 * Business Context:
 * Moderators or admins record actions against posts/comments/members for audit and dispute workflows.
 * This test ensures the record can be precisely retrieved for review/appeal, and all information survives API transit.
 */
export async function test_api_discussionBoard_test_get_moderation_action_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a new moderation action (as a moderator, targeting a comment)
  const createInput = {
    affected_member_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "warn",
    action_reason: "Inappropriate language in comment.",
    action_note: "Test note for audit.",
    moderator_id: typia.random<string & tags.Format<"uuid">>(),
    admin_id: null,
    target_post_id: null,
    target_comment_id: typia.random<string & tags.Format<"uuid">>(),
  } satisfies IDiscussionBoardModerationAction.ICreate;
  const created = await api.functional.discussionBoard.moderationActions.post(connection, { body: createInput });
  typia.assert(created);

  // 2. Fetch by ID
  const fetched = await api.functional.discussionBoard.moderationActions.getById(connection, { id: created.id });
  typia.assert(fetched);

  // 3. Assert all fields match and cross-references are present
  TestValidator.equals("moderation action id")(fetched.id)(created.id);
  TestValidator.equals("moderator id")(fetched.moderator_id)(createInput.moderator_id);
  TestValidator.equals("admin id")(fetched.admin_id)(createInput.admin_id);
  TestValidator.equals("affected_member_id")(fetched.affected_member_id)(createInput.affected_member_id);
  TestValidator.equals("action_type")(fetched.action_type)(createInput.action_type);
  TestValidator.equals("action_reason")(fetched.action_reason)(createInput.action_reason);
  TestValidator.equals("action_note")(fetched.action_note)(createInput.action_note);
  TestValidator.equals("target_post_id")(fetched.target_post_id)(createInput.target_post_id);
  TestValidator.equals("target_comment_id")(fetched.target_comment_id)(createInput.target_comment_id);
  // 4. Audit: created_at is present, ISO format
  TestValidator.predicate("created_at present and ISO string")(!!fetched.created_at && !isNaN(Date.parse(fetched.created_at)));
}

