import type { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";

/**
 * Validate that the system rejects invalid updates to a moderation action record.
 *
 * This test ensures that, when attempting to update a moderation action with invalid input (such as wrong types, nonsensical values, or any attempt to modify fields that may be considered immutable), the system returns a validation error and does not change the stored moderation action.
 *
 * Steps:
 * 1. Create a valid moderation action as the source record.
 * 2. Attempt to update the moderation action with a clearly invalid value (e.g., affecting the required member id with the wrong type or format, or supplying impossible values for action_type).
 * 3. Confirm that an error is thrown and the original record remains unchanged by fetching it again, if possible (although according to available APIs, only create and update are exposed, so only the error can be checked here).
 */
export async function test_api_discussionBoard_test_update_moderation_action_with_invalid_fields_rejected(
  connection: api.IConnection,
) {
  // 1. Create a valid moderation action record
  const original = await api.functional.discussionBoard.moderationActions.post(connection, {
    body: {
      affected_member_id: typia.random<string & tags.Format<"uuid">>(),
      action_type: "warn",
      action_reason: "Test reason for moderation.",
      moderator_id: typia.random<string & tags.Format<"uuid">>(),
      admin_id: null,
      target_post_id: null,
      target_comment_id: null,
      action_note: "Initial note."
    } satisfies IDiscussionBoardModerationAction.ICreate,
  });
  typia.assert(original);

  // 2. Attempt to update with invalid fields: invalid UUID format and empty action_type (should fail server-side validation)
  await TestValidator.error("invalid affected_member_id format should fail")(
    () => api.functional.discussionBoard.moderationActions.putById(connection, {
      id: original.id,
      body: {
        affected_member_id: "not-a-uuid" as any,
        action_type: "",
      } satisfies IDiscussionBoardModerationAction.IUpdate,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
