/**
 * Verify that unauthorized users (regular members) cannot update moderation actions and are denied with forbidden errors.
 *
 * This test covers: Attempting to update a moderation action as a non-privileged discussion board member. The system must refuse the operation, returning an appropriate forbidden error, and must ensure no mutation occurs on the moderation action record.
 *
 * Steps:
 * 1. Create a moderation action (acting as an admin or system so that it exists)
 * 2. Register a regular (non-moderator, non-admin) member
 * 3. Attempt to update the moderation action using the regular member's account
 * 4. Confirm that a forbidden error is returned, and no record modification occurs
 */
export async function test_api_discussionBoard_test_update_moderation_action_by_unauthorized_user(
  connection: api.IConnection,
) {
  // 1. Create a moderation action (as a privileged actor, e.g., admin for this test's setup)
  const actionInput: IDiscussionBoardModerationAction.ICreate = {
    affected_member_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "warn",
    action_reason: "Initial warning for test"
  };
  const moderationAction = await api.functional.discussionBoard.moderationActions.post(
    connection,
    { body: actionInput }
  );
  typia.assert(moderationAction);

  // 2. Register a non-privileged member
  const memberInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "TestPassword123!"
  };
