  const updateBody: IDiscussionBoardModerationAction.IUpdate = {
    action_note: "Trying to alter a record as unauthorized user",
    action_reason: "Attempting forbidden update"
  };
  await TestValidator.error("forbidden error for unauthorized update")(
    async () => {
      await api.functional.discussionBoard.moderationActions.putById(connection, {
        id: moderationAction.id,
        body: updateBody
      });
    }
  );

  // 4. (Recommended) Optionally, if the API allows fetching the moderation action, reload it and assert it was not modified
  // Skipped here as the GET method is not available in input materials.
}

