import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";

/**
 * Test soft deletion of a moderation action record by an admin in the discussion board system.
 *
 * This test ensures that an admin can delete a moderation action record using its ID, and validates
 * that the response is type-safe and references the correct record. Because only create and delete
 * endpoints are available, post-delete fetch validation and explicit soft-delete checks are omitted.
 * The test is written to be easily extensible if further read/list endpoints appear in the API.
 *
 * Process:
 *   1. Create a moderation action record as setup (simulating admin action)
 *   2. Delete the moderation action by its ID
 *   3. Assert the deletion response corresponds to the correct moderation action
 */
export async function test_api_discussionBoard_test_delete_moderation_action_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a moderation action record (setup, as admin)
  const createInput = {
    admin_id: typia.random<string & tags.Format<"uuid">>(),
    moderator_id: null,
    affected_member_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "delete",
    action_reason: "Unit-test: test moderation action deletion.",
    target_post_id: null,
    target_comment_id: null,
    action_note: "Testing admin-triggered moderationAction deletion."
  } satisfies IDiscussionBoardModerationAction.ICreate;

  const moderationAction = await api.functional.discussionBoard.moderationActions.post(connection, {
    body: createInput,
  });
  typia.assert(moderationAction);

  // 2. Delete the moderation action by ID
  const deleted = await api.functional.discussionBoard.moderationActions.eraseById(connection, {
    id: moderationAction.id,
  });
  typia.assert(deleted);

  // 3. Assert the deletion response is for same moderation action
  TestValidator.equals("ID matches deleted moderation action")(deleted.id)(moderationAction.id);

  // Note: No fetch or audit verification step, as there is no GET endpoint defined for moderation actions.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
