import type { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";

/**
 * Test that unauthorized users (regular members or unauthenticated clients) cannot delete discussion board moderation actions.
 *
 * This test ensures the discussion board's permission system does not allow unprivileged deletion of moderation records. It simulates both a logged-in regular member and a completely unauthenticated context attempting to delete a moderation action, confirming both are rejected with errors.
 *
 * Workflow:
 * 1. Create a non-privileged member via the registration endpoint.
 * 2. Create a moderation action using this member as the affected party.
 * 3. Attempt deletion (as the member) – expect rejection.
 * 4. Attempt deletion (unauthenticated) – expect rejection.
 *
 * Note: As there is no GET or LIST endpoint for moderation actions in the provided API functions, we cannot programmatically confirm that the moderation action still exists after failed deletion. This check is therefore omitted, per scenario feasibility rules.
 */
export async function test_api_discussionBoard_test_delete_moderation_action_by_unauthorized_user(
  connection: api.IConnection,
) {
  // 1. Create a regular (non-privileged) member
  const memberInput = {
    username: RandomGenerator.alphabets(12),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "securePassword-1"
  } satisfies IDiscussionBoardMember.ICreate;
  const member = await api.functional.discussionBoard.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a moderation action with this member as the "affected_member_id"
  const moderationActionInput = {
    affected_member_id: member.id,
    action_type: "warn",
    action_reason: "Repeated off-topic posts",
  } satisfies IDiscussionBoardModerationAction.ICreate;
  const moderationAction = await api.functional.discussionBoard.moderationActions.post(connection, { body: moderationActionInput });
  typia.assert(moderationAction);

  // 3. Attempt to delete as the regular member – expect access error
  TestValidator.error("Member cannot delete moderation action")(
    async () => await api.functional.discussionBoard.moderationActions.eraseById(connection, { id: moderationAction.id })
  );

  // 4. Remove authorization headers (simulate unauthenticated client)
  const unauthenticatedConnection = { ...connection, headers: {} };
  TestValidator.error("Unauthenticated client cannot delete moderation action")(
    async () => await api.functional.discussionBoard.moderationActions.eraseById(unauthenticatedConnection, { id: moderationAction.id })
  );
}

