 * 2. Create a configuration entry with an initial value and description.
 * 3. As the admin, update both value and description of the configuration using the PUT endpoint.
 * 4. Assert the response reflects the updated value/description, unchanged key/id, and a refreshed updated_at field.
 * 5. Ensure created_at and deleted_at fields respect invariants (creation time remains constant, not soft-deleted).
 */
export async function test_api_discussionBoard_test_update_configuration_value_and_description_with_admin_role(
  connection: api.IConnection,
) {
  // 1. Create an admin member (here as a regular member; role elevation is assumed due to API limitation)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminUsername: string = RandomGenerator.alphaNumeric(10);
  const adminPassword: string = typia.random<string & tags.Format<"password">>();
