import type { IDiscussionBoardCommentReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentReaction";

/**
 * 댓글 리액션의 작성자가 자신의 reaction_type을 정상적으로 수정할 수 있는지 검증합니다.
 *
 * - 비즈니스 컨텍스트: 게시판 멤버가 댓글에 'like'와 같은 리액션을 등록한 뒤, 작성자 본인이 직접 해당 리액션의 타입(예: 'like' → 'dislike')을 수정할 수 있어야 하며, 반영된 내용 및 감사타임스탬프가 제대로 갱신되는지 확인합니다. 또한 본인이 아닌 계정이 수정 시도 시 권한 오류가 발생함을 추가로 검증합니다.
 *
 * [절차]
 * 1. 신규 멤버(작성자) 등록
 * 2. 테스트용 댓글 생성 (임의 post/thread id 사용)
 * 3. 작성자가 댓글에 'like' 리액션 생성
 * 4. 작성자가 해당 리액션을 'dislike'로 수정
 * 5. 수정 결과 response에서 reaction_type 변경 및 타임스탬프 변화 확인
 * 6. 타인이 해당 리액션을 수정 시도 → 권한 오류 발생 검증
 */
export async function test_api_discussionBoard_test_update_comment_reaction_type_as_owner(
  connection: api.IConnection,
) {
  // 1. 신규 멤버(작성자) 등록
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. 테스트용 댓글 생성 (post_id, thread_id 임의)
  const postId = typia.random<string & tags.Format<"uuid">>();
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const comment = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: postId,
      thread_id: threadId,
      author_id: member.id,
      body: RandomGenerator.paragraph()(),
      depth: 0,
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 3. 작성자가 댓글에 'like' 리액션 생성
  const createdReaction = await api.functional.discussionBoard.commentReactions.post(connection, {
    body: {
      discussionboard_member_id: member.id,
      discussionboard_comment_id: comment.id,
      reaction_type: "like",
    } satisfies IDiscussionBoardCommentReaction.ICreate,
  });
  typia.assert(createdReaction);

  // 4. 작성자가 해당 리액션을 'dislike'로 수정
  const updatedReaction = await api.functional.discussionBoard.commentReactions.putById(connection, {
    id: createdReaction.id,
    body: {
      reaction_type: "dislike",
    } satisfies IDiscussionBoardCommentReaction.IUpdate,
  });
  typia.assert(updatedReaction);

  // 5. reaction_type 변경 및 타임스탬프 변화 확인
  TestValidator.equals("reaction_type 변경됨")(updatedReaction.reaction_type)("dislike");
  // created_at은 생성 시각, updated_at이 있다면 비교하지만 여기선 created_at이 변경값을 대변한다고 간주
  TestValidator.notEquals("created_at 변경됨")(updatedReaction.created_at)(createdReaction.created_at);

  // 6. 타인이 해당 리액션 update 시도 → 권한 오류 확인
  const otherMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(otherMember);
  await TestValidator.error("타인은 댓글 리액션을 수정 불가")(() =>
    api.functional.discussionBoard.commentReactions.putById(connection, {
      id: createdReaction.id,
      body: {
        reaction_type: "like",
      } satisfies IDiscussionBoardCommentReaction.IUpdate,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
