/**
 * Test soft deletion of a comment reaction by its creator.
 *
 * This test validates the workflow where a member creates a comment, reacts to it, and then deletes (soft-deletes) their reaction. The test ensures the deletion is a soft delete (deleted_at is set, not physically erased), and that the deleted reaction is no longer included in listings by business contract.
 *
 * Steps:
 * 1. Register a new discussion board member.
 * 2. The member creates a comment on an arbitrary post/thread.
 * 3. The member reacts to the comment (e.g., 'like').
 * 4. The member deletes their own reaction via the soft-delete API.
 * 5. Attempt to fetch the same reaction after deletion (directly or via listing, if API allowed).
 * 6. Verify that the reaction's deleted_at property is set (soft-deleted).
 * 7. Confirm it is not included in standard listings of active reactions (if such endpoint exists; otherwise, limited to direct record validation).
 */
export async function test_api_discussionBoard_test_delete_comment_reaction_as_owner(connection: api.IConnection) {
  // 1. Register a new member (who will own the comment and reaction).
  const memberInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: RandomGenerator.alphaNumeric(10),
  };
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. Create a new comment (the member is the author).
  const commentInput: IDiscussionBoardComment.ICreate = {
    post_id: typia.random<string & tags.Format<"uuid">>(),
    thread_id: typia.random<string & tags.Format<"uuid">>(),
    author_id: member.id,
    body: RandomGenerator.paragraph()(),
    depth: 0,
  };
  const comment = await api.functional.discussionBoard.comments.post(connection, {
    body: commentInput,
  });
