  // 3. Create a reaction by the member for the comment.
  const reactionInput: IDiscussionBoardCommentReaction.ICreate = {
    discussionboard_member_id: member.id,
    discussionboard_comment_id: comment.id,
    reaction_type: "like",
  };
  const reaction = await api.functional.discussionBoard.commentReactions.post(connection, {
    body: reactionInput,
  });
  typia.assert(reaction);

  // 4. Soft-delete the reaction as the owning member.
  await api.functional.discussionBoard.commentReactions.eraseById(connection, {
    id: reaction.id,
  });

  // 5. (No direct GET endpoint for a single reaction in the provided API. If such existed, would confirm deleted_at is set. Here we rely on contract/spec.)
  // In real scenario, would attempt to fetch and assert soft deletion, but not possible with current SDK.
  // The deletion call completing without error is considered sufficient contract validation here.
}

