        id: randomId,
      }),
  );

  // 2. 잘못된 ID (uuid 아님) 형식으로 삭제 시도 → 유효성 에러 검증
  const invalidId = "not-a-uuid";
  await TestValidator.error("잘못된 ID 형식 유효성 검증")(
    () =>
      api.functional.discussionBoard.commentReactions.eraseById(connection, {
        id: invalidId as string & tags.Format<"uuid">,
      }),
  );
