import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { DiscussionBoardNotificationPreferences } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardNotificationPreferences";
import type { DiscussionBoardPageNotificationPreferences } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardPageNotificationPreferences";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Verify that a logged-in member can retrieve their notification preferences filtered by email.
 *
 * Business context:
 * - Each member can only have a single notification preferences record.
 * - Members should be able to fetch their preferences filtered by enabled notification types.
 * - The filter for enable_email=true should only return the record if that flag is set for the user.
 *
 * Test procedure:
 * 1. Register a new member.
 * 2. [No login is required; authentication is assumed granted upon registration.]
 * 3. Create notification preferences for that member (enable_email: true).
 * 4. Retrieve notification preferences with filter enable_email=true. Assert the member's preferences are returned and email is enabled.
 * 5. Retrieve notification preferences with filter enable_email=false. Assert preferences are not returned (empty data array).
 * 6. Negative: create another member with enable_email=false and confirm they do not appear in email-enabled filtered results.
 */
export async function test_api_discussionBoard_test_list_notification_preferences_for_logged_in_member_with_email_filter(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberAInput = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "P@ssw0rd#1234",
  } satisfies IDiscussionBoardMember.ICreate;
  const memberA = await api.functional.discussionBoard.members.post(connection, { body: memberAInput });
  typia.assert(memberA);

  // 2. Create notification preferences for memberA with email enabled
  const prefsA = await api.functional.discussionBoard.notificationPreferences.post(connection, {
    body: {
      member_id: memberA.id,
      enable_email: true,
      enable_web_push: false,
      enable_system_announcements: false,
    },
  });
  typia.assert(prefsA);

  // 3. Fetch with enable_email=true filter → should find memberA's preferences
  const pageA_emailEnabled = await api.functional.discussionBoard.notificationPreferences.patch(connection, {
    body: {
      member_id: memberA.id,
      enable_email: true,
      enable_web_push: null,
      enable_system_announcements: null,
      page: null,
    },
  });
  typia.assert(pageA_emailEnabled);
  TestValidator.equals("should find one preference record for memberA (email enabled)")(pageA_emailEnabled.data.length)(1);
  for (const rec of pageA_emailEnabled.data) {
    TestValidator.equals("member_id matches")(rec.member_id)(memberA.id);
    TestValidator.equals("enable_email is true")(rec.enable_email)(true);
    TestValidator.equals("enable_web_push is false")(rec.enable_web_push)(false);
    TestValidator.equals("enable_system_announcements is false")(rec.enable_system_announcements)(false);
  }

  // 4. Fetch with enable_email=false filter → should NOT find memberA
  const pageA_emailDisabled = await api.functional.discussionBoard.notificationPreferences.patch(connection, {
    body: {
      member_id: memberA.id,
      enable_email: false,
      enable_web_push: null,
      enable_system_announcements: null,
      page: null,
    },
  });
  typia.assert(pageA_emailDisabled);
  TestValidator.equals("should return empty array for enable_email=false")(pageA_emailDisabled.data.length)(0);

  // 5. Negative: create another member with only email disabled
  const memberBInput = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "P@ssw0rd#1234",
  } satisfies IDiscussionBoardMember.ICreate;
