 *
 * This test ensures that a discussion board member cannot access another user's
 * notification preferences by ID, enforcing strict privacy and access control rules.
 *
 * Test process:
 * 1. Register memberA
 * 2. Register memberB
 * 3. Create a notification preference for memberA
 * 4. Simulate an access attempt by memberB to memberA's notification preference (in a real E2E, this would use memberB's session/auth context)
 * 5. Assert that access is forbidden (permission denied error is thrown)
 *
 * Note: No authentication/login endpoint is present in the API. In typical E2E,
 * auth would switch between user sessions before access attempts. Here, we clarify
 * in comments that connection context should be for the correct member per call.
 */
export async function test_api_discussionBoard_test_get_notification_preference_by_id_permission_denied(
  connection: api.IConnection,
) {
  // 1. Register memberA
  const memberAEmail: string = typia.random<string & tags.Format<"email">>();
  const memberAUsername: string = RandomGenerator.alphaNumeric(10);
  const memberA: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(
    connection,
    {
      body: {
        username: memberAUsername,
        email: memberAEmail,
        display_name: RandomGenerator.name(),
        password: "StrongPassword1!",
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(memberA);

  // 2. Register memberB
  const memberBEmail: string = typia.random<string & tags.Format<"email">>();
  const memberBUsername: string = RandomGenerator.alphaNumeric(10);
  const memberB: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(
    connection,
    {
      body: {
        username: memberBUsername,
        email: memberBEmail,
        display_name: RandomGenerator.name(),
        password: "StrongPassword2!",
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(memberB);

  // 3. Create a notification preference for memberA
  const preferenceA: DiscussionBoardNotificationPreferences = await api.functional.discussionBoard.notificationPreferences.post(
    connection,
    {
      body: {
        member_id: memberA.id,
        enable_email: true,
        enable_web_push: false,
        enable_system_announcements: true,
      } satisfies DiscussionBoardNotificationPreferences.ICreate,
    },
  );
  typia.assert(preferenceA);

  // 4. Simulate access as memberB: with no login/auth endpoint, assume connection is for memberB at this step.
  //    (In real E2E: switch authentication context here.)
  // 5. Attempt access to memberA's notification preference by memberB. Expect forbidden or permission denied error.
  await TestValidator.error("memberB must not access memberA's notification preference")(
