/**
 * Test that a member can delete their own notification preference.
 *
 * This test simulates a full workflow where a member registers, sets their notification preferences, and deletes them by ID. It confirms the deletion is successful by comparing the returned IDs and relationship, while accounting for the absence of a GET endpoint for post-deletion existence check.
 *
 * Steps:
 * 1. Create a member account (with unique username and email)
 * 2. Create notification preferences linked to that member
 * 3. Delete the notification preference by its unique ID
 * 4. Validate the response contains the correct deleted object
 */
export async function test_api_discussionBoard_test_delete_notification_preference_by_owner_success(
  connection: api.IConnection,
) {
  // 1. Create a new member (who becomes the owner of the notification preference)
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "Password1!",
