  // 2. Create notification preferences for this member
  const preference = await api.functional.discussionBoard.notificationPreferences.post(
    connection,
    {
      body: {
        member_id: member.id,
        enable_email: true,
        enable_web_push: false,
        enable_system_announcements: true,
      } satisfies DiscussionBoardNotificationPreferences.ICreate,
    },
  );
  typia.assert(preference);

  // 3. Delete the notification preference by its ID
  const deleted = await api.functional.discussionBoard.notificationPreferences.eraseById(
    connection,
    { id: preference.id },
  );
  typia.assert(deleted);

