import api from "@ORGANIZATION/PROJECT-api";
import type { DiscussionBoardContentPolicies } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardContentPolicies";

/**
 * Validate unique code constraint enforcement when creating discussion board content policies.
 *
 * This test ensures the system prevents the creation of multiple content policies with the same policy code.
 * It first creates a content policy with a unique code, then attempts to create a second policy using the
 * same code but different other fields. The system is expected to reject the second creation with an error
 * due to a uniqueness constraint violation according to business rules.
 *
 * Step-by-step process:
 * 1. Create a content policy with a unique random code value
 * 2. Attempt to create another policy with the identical code but different other data fields
 * 3. Validate that the second creation attempt fails with a unique constraint error
 */
export async function test_api_discussionBoard_test_create_content_policy_with_duplicate_code(
  connection: api.IConnection,
) {
  // 1. Create the first content policy with a unique code
  const code: string = RandomGenerator.alphaNumeric(10);
  const policy = await api.functional.discussionBoard.contentPolicies.post(connection, {
    body: {
      code,
      title: RandomGenerator.paragraph()(),
      description: RandomGenerator.content()()(),
      effective_from: new Date().toISOString(),
      effective_to: null,
      is_active: true,
    } satisfies DiscussionBoardContentPolicies.ICreate,
  });
  typia.assert(policy);

  // 2. Attempt to create another policy with the same code (should fail)
  await TestValidator.error("duplicate content policy code should trigger uniqueness error")(
    async () => {
      await api.functional.discussionBoard.contentPolicies.post(connection, {
        body: {
          code, // duplicate
          title: RandomGenerator.paragraph()(),
          description: RandomGenerator.content()()(),
          effective_from: new Date(Date.now() + 86400000).toISOString(), // different date
          effective_to: null,
          is_active: false,
        } satisfies DiscussionBoardContentPolicies.ICreate,
      });
    },
  );
}

