import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { DiscussionBoardContentPolicies } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardContentPolicies";

/**
 * 관리자 권한으로 토론장 정책(Content Policy)을 수정(putById)하는 기능의 정상 동작을 검증합니다.
 * 
 * 이 테스트는 아래 핵심 시나리오를 다룹니다:
 * 1. 최초로 유니크한 code의 정책을 생성해 테스트 대상을 준비합니다 (선행 의존성).
 * 2. 해당 정책의 title, description, effective_from, is_active 등 주요 속성을 새로운 값들로 수정(putById)합니다.
 * 3. 응답 데이터가 요청한 변경사항으로 정확히 갱신되었는지, updated_at이 증가했는지, code가 유니크하게 잘 반영되는지 확인합니다.
 * 4. 정책 code(유니크키) 변경 시, 기존에 없는 새로운 값으로 잘 반영되는지 검증합니다.
 * 5. 시간값(effective_from<effective_to) 등 비즈니스 제약 위반 시 에러 처리(적어도 런타임 오류)를 확인합니다.
 * 6. 정책의 모든 속성 변경 시, 정상 변경 결과와 함께 감사(Audit/updated_at) 기록의 증가를 확인합니다.
 *
 * [세부 테스트 단계]
 * - 정책 생성: code, title, description, effective_from, is_active 지정해 정책을 생성 후, id 획득
 * - 정책 수정: code, title, description, effective_from, is_active를 모두 수정. 각 값은 기존과 다르게 지정해 적용
 * - 업데이트 응답 검증: 응답 내 값이 변경 요청 내용으로 수정되어 있는지, updated_at이 갱신됐는지 확인
 * - code 유니크 검사: 이미 존재하는 code로 변경하려 하면 런타임 에러 발생 확인
 * - 시간 제약, empty/null/invalid 값 입력 등 기타 주요 비즈니스 룰 위반 시 런타임 에러 처리 확인
 */
export async function test_api_discussionBoard_contentPolicies_test_update_content_policy_success(
  connection: api.IConnection,
) {
  // 1. 정책 생성 - 선행 데이터 준비
  const now = new Date();
  const createBody: DiscussionBoardContentPolicies.ICreate = {
    code: `POLICY_${now.getTime()}`,
    title: `초기정책타이틀_${now.getTime()}`,
    description: `초기설명_${now.toISOString()}`,
    effective_from: now.toISOString(),
    effective_to: null,
    is_active: true,
  };
  const originalPolicy = await api.functional.discussionBoard.contentPolicies.post(connection, {
    body: createBody,
  });
  typia.assert(originalPolicy);

  // 2. 정책 수정 - 일부 필드 새로운 값으로 변경
  const updatedTitle = `수정된정책타이틀_${now.getTime() + 1}`;
  const updatedDescription = `수정된설명_${now.getTime() + 1}`;
  const updateBody: DiscussionBoardContentPolicies.IUpdate = {
    code: `UPDATED_POLICY_${now.getTime() + 2}`,
    title: updatedTitle,
    description: updatedDescription,
    effective_from: new Date(now.getTime() + 3600000).toISOString(), // +1h
    effective_to: null,
    is_active: false,
  };
  const updated = await api.functional.discussionBoard.contentPolicies.putById(connection, {
    id: originalPolicy.id,
    body: updateBody,
  });
  typia.assert(updated);
  // 3. 값 변경 검증
  TestValidator.equals("정책 ID 불변")(updated.id)(originalPolicy.id);
  TestValidator.equals("code 변경")(updated.code)(updateBody.code);
  TestValidator.equals("title 변경")(updated.title)(updateBody.title);
  TestValidator.equals("description 변경")(updated.description)(updateBody.description);
  TestValidator.equals("is_active 변경")(updated.is_active)(updateBody.is_active);
  TestValidator.equals("effective_from 변경")(updated.effective_from)(updateBody.effective_from);
  TestValidator.equals("effective_to null 유지")(updated.effective_to)(null);
  TestValidator.predicate("updated_at time 증가")(new Date(updated.updated_at) > new Date(originalPolicy.updated_at));

  // 4. code 유니크 위반 케이스 에러 처리 (동일 code로 새 정책 만든 뒤, 기존 정책 code를 그 값으로 변경 시도)
  const otherBody: DiscussionBoardContentPolicies.ICreate = {
    code: `DUPLICATE_POLICY_${now.getTime() + 10000}`,
    title: `다른정책타이틀_${now.getTime() + 10000}`,
    description: `설명_${now.getTime() + 10000}`,
    effective_from: new Date(now.getTime() + 7200000).toISOString(), // +2h
    effective_to: null,
    is_active: true,
  };
  const otherPolicy = await api.functional.discussionBoard.contentPolicies.post(connection, { body: otherBody });
  typia.assert(otherPolicy);

  await TestValidator.error("policy code 중복 불가")(() =>
    api.functional.discussionBoard.contentPolicies.putById(connection, {
      id: originalPolicy.id,
      body: { ...updateBody, code: otherPolicy.code },
    }),
  );

  // 5. 시간 제약 위반 등 비즈니스 에러 처리 (효력종료일 < 효력시작일 등)
  await TestValidator.error("effective_to가 effective_from보다 이전이면 에러")(() =>
    api.functional.discussionBoard.contentPolicies.putById(connection, {
      id: originalPolicy.id,
      body: { ...updateBody, effective_to: new Date(now.getTime() - 10000).toISOString() },
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { DiscussionBoardContentPolicies } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardContentPolicies";

/**
 * Validate rejection when attempting to update a content policy’s code to a code already taken by another record.
 *
 * Business Context:
 * A content policy code must be unique across the discussion board; attempting to update one policy to have the same code as another must fail. This test ensures uniqueness is enforced during policy updates—an essential compliance and audit requirement.
 *
 * Steps:
 * 1. Create the first policy with a unique code ("CODE1").
 * 2. Create a second policy with a different code ("CODE2").
 * 3. Attempt to update the second policy’s code to "CODE1" (matching the first’s code).
 * 4. The update must fail due to a uniqueness constraint violation.
 */
export async function test_api_discussionBoard_contentPolicies_test_update_content_policy_with_duplicate_code(
  connection: api.IConnection,
) {
  // 1. Create the first unique policy
  const code1 = `CODE1_${RandomGenerator.alphaNumeric(8)}`;
  const createInput1: DiscussionBoardContentPolicies.ICreate = {
    code: code1,
    title: `Policy ${RandomGenerator.alphaNumeric(5)}`,
    description: RandomGenerator.paragraph()(),
    effective_from: new Date().toISOString(),
    effective_to: null,
    is_active: true,
  };
  const policy1 = await api.functional.discussionBoard.contentPolicies.post(connection, { body: createInput1 });
  typia.assert(policy1);

  // 2. Create the second unique policy
  const code2 = `CODE2_${RandomGenerator.alphaNumeric(8)}`;
  const createInput2: DiscussionBoardContentPolicies.ICreate = {
    code: code2,
    title: `Policy ${RandomGenerator.alphaNumeric(5)}`,
    description: RandomGenerator.paragraph()(),
    effective_from: new Date(Date.now() + 60000).toISOString(),
    effective_to: null,
    is_active: true,
  };
  const policy2 = await api.functional.discussionBoard.contentPolicies.post(connection, { body: createInput2 });
  typia.assert(policy2);

  // 3. Attempt to update policy2 to have the same code as policy1 -- should fail
  const updateInput: DiscussionBoardContentPolicies.IUpdate = {
    code: code1,
    title: policy2.title,
    description: policy2.description,
    effective_from: policy2.effective_from,
    effective_to: policy2.effective_to ?? null,
    is_active: policy2.is_active,
  };
  await TestValidator.error("Should reject duplicate code on update")(
    () => api.functional.discussionBoard.contentPolicies.putById(connection, {
      id: policy2.id,
      body: updateInput,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { DiscussionBoardContentPolicies } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardContentPolicies";

/**
 * Test updating a content policy with invalid data (business rule or schema violations).
 *
 * This test verifies the API correctly rejects updates that violate business rules or schema validation.
 * Specifically, it checks:
 * 1. Updating a content policy where expiration date precedes the effective date (business rule violation)
 * 2. Attempts to send invalid schema structures are NOT implemented (e.g., missing required fields or invalid types), as these are prevented by TypeScript type safety.
 *
 * Steps:
 * 1. Create a valid content policy
 * 2. Attempt to update with an expiration (effective_to) earlier than effective_from, expecting an error
 * 3. Any schema/type violations that can't be constructed with strict types are omitted per implementation rules
 */
export async function test_api_discussionBoard_contentPolicies_test_update_content_policy_with_invalid_status_or_time(
  connection: api.IConnection,
) {
  // 1. Create a valid content policy for update attempts
  const created = await api.functional.discussionBoard.contentPolicies.post(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(8),
      title: "Test Policy",
      description: "Sample content policy for test.",
      effective_from: new Date(Date.now() + 60 * 60 * 1000).toISOString(), // 1 hour from now
      effective_to: new Date(Date.now() + 3 * 60 * 60 * 1000).toISOString(), // 3 hours from now
      is_active: true,
    } satisfies DiscussionBoardContentPolicies.ICreate
  });
  typia.assert(created);

  // 2. Attempt to update with effective_to before effective_from
  await TestValidator.error("Reject update if expiration before effective_from")(() =>
    api.functional.discussionBoard.contentPolicies.putById(connection, {
      id: created.id,
      body: {
        code: created.code,
        title: created.title,
        description: created.description,
        effective_from: created.effective_from,
        effective_to: new Date(new Date(created.effective_from).getTime() - 10 * 60 * 1000).toISOString(), // 10 min before effective_from
        is_active: created.is_active,
      } satisfies DiscussionBoardContentPolicies.IUpdate,
    })
  );

  // 3. Negative cases requiring schema/type violation (e.g., missing title, invalid is_active type) are skipped as per implementation rules
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { DiscussionBoardContentPolicies } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardContentPolicies";

/**
 * Validate the soft-delete (archival) of a content policy by ID as an admin.
 *
 * This E2E test simulates the process for an admin user to delete (archive)
 * a content policy using the API endpoints. A newly created test policy is
 * used to ensure isolation and safety.
 *
 * Steps:
 * 1. Create a new content policy for deletion testing via POST /discussionBoard/contentPolicies.
 * 2. Soft-delete (archive) the policy using DELETE /discussionBoard/contentPolicies/{id}.
 * 3. Confirm that the returned policy is either marked inactive (is_active === false), or now has an effective_to date (indicates archived/expired status).
 * 4. (Audit log and explicit role-based admin enforcement are not asserted here due to API limitations.)
 */
export async function test_api_discussionBoard_contentPolicies_test_delete_content_policy_success(
  connection: api.IConnection,
) {
  // 1. Create a new content policy for deletion/archival test
  const creationInput = {
    code: `DELETE_TEST_${typia.random<string>().slice(0,8)}`,
    title: `DeleteTest-${RandomGenerator.alphabets(4)}`,
    description: "This is a test policy for delete/archival test.",
    effective_from: new Date().toISOString(),
    effective_to: null,
    is_active: true,
  } satisfies DiscussionBoardContentPolicies.ICreate;

  const createdPolicy = await api.functional.discussionBoard.contentPolicies.post(connection, { body: creationInput });
  typia.assert(createdPolicy);

  // 2. Soft-delete/archive the policy as admin
  const deletedPolicy = await api.functional.discussionBoard.contentPolicies.eraseById(connection, { id: createdPolicy.id });
  typia.assert(deletedPolicy);

  // 3. Confirm the policy is archived: is_active is false or effective_to is not null
  TestValidator.predicate("soft-delete sets inactive or expired status")(
    deletedPolicy.is_active === false || (typeof deletedPolicy.effective_to === "string" && !!deletedPolicy.effective_to)
  );

  // 4. (Optional) Audit/log validation and role enforcement are not testable here due to lack of relevant API endpoints.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
