 *
 * Test verifies:
 * 1. API returns an appropriate error (e.g., 404 Not Found or 400 Bad Request) for the invalid deletion request.
 * 2. No policy record is returned (i.e., not falsely reporting success).
 * 3. (If accessible) Audit logs appropriately note the failed deletion attempt (this may be validated outside this test if log access is not provided).
 *
 * Steps:
 * 1. Generate a random UUID that is extremely unlikely to exist in the database (not created in this suite).
 * 2. Attempt to delete content policy with this UUID using api.functional.discussionBoard.contentPolicies.eraseById.
 * 3. Validate that an error is thrown and not a successful deletion result.
 * 4. Optionally, if error object exposes relevant details, assert error type/message/status (within allowed E2E validation practices).
 *
 * Note: Since scenario does not expose an audit log API, audit compliance should be considered out-of-band, documented as a business requirement.
 */
export async function test_api_discussionBoard_contentPolicies_test_delete_content_policy_nonexistent_id(
  connection: api.IConnection,
) {
